import sys
sys.setrecursionlimit(2000)

def solve(observation):
    grid_data = observation['data']
    N = len(grid_data)

    # Deep copy grid to avoid modifying input
    grid = [row[:] for row in grid_data]

    # Directions for neighbors
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def check_2x2_violation(g):
        # Returns True if there is a monochromatic 2x2 block
        for r in range(N - 1):
            for c in range(N - 1):
                cells = [g[r][c], g[r+1][c], g[r][c+1], g[r+1][c+1]]
                if None not in cells:
                    if cells[0] == cells[1] == cells[2] == cells[3]:
                        return True
        return False

    def get_components(g, color):
        # Returns list of sets of coordinates for each connected component of 'color'
        # Only considers cells that ARE 'color'
        visited = set()
        components = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == color and (r, c) not in visited:
                    comp = set()
                    queue = [(r, c)]
                    visited.add((r, c))
                    comp.add((r, c))
                    while queue:
                        curr_r, curr_c = queue.pop(0)
                        for nr, nc in get_neighbors(curr_r, curr_c):
                            if g[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                comp.add((nr, nc))
                                queue.append((nr, nc))
                    components.append(comp)
        return components

    def can_connect_components(g, color, components):
        # Check if all components of 'color' can potentially be connected
        # They can be connected if there is a path of (color or None) between them.
        # If they are separated by the other color, they cannot connect.
        if len(components) <= 1:
            return True

        # We need to check if all components are in the same connected component 
        # of the graph where nodes are (cells with value == color OR value == None)

        # Let's build a graph of (color or None) cells
        # Actually, simpler: Pick one component, BFS through (color or None).
        # Check if all other component cells are reachable.

        start_comp = components[0]
        # Pick an arbitrary cell from start_comp
        start_cell = next(iter(start_comp))

        visited = set()
        queue = [start_cell]
        visited.add(start_cell)

        while queue:
            curr_r, curr_c = queue.pop(0)
            for nr, nc in get_neighbors(curr_r, curr_c):
                if (nr, nc) not in visited and g[nr][nc] != ('W' if color == 'B' else 'B'):
                    # Can traverse through same color or empty
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        # Check if all cells in all other components are visited
        for i in range(1, len(components)):
            for cell in components[i]:
                if cell not in visited:
                    return False
        return True

    def is_valid_state(g):
        # 1. Check 2x2 rule
        if check_2x2_violation(g):
            return False

        # 2. Check Black connectivity potential
        b_comps = get_components(g, 'B')
        if not can_connect_components(g, 'B', b_comps):
            return False

        # 3. Check White connectivity potential
        w_comps = get_components(g, 'W')
        if not can_connect_components(g, 'W', w_comps):
            return False

        return True

    def is_complete(g):
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    return False
        return True

    def get_empty_cells(g):
        cells = []
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    cells.append((r, c))
        return cells

    # Heuristic: MRV (Minimum Remaining Values) - though here domain is always 2.
    # Better heuristic: Most constrained cell (neighbors with fixed colors)
    def get_best_cell(g):
        best_cell = None
        max_fixed_neighbors = -1

        empty_cells = get_empty_cells(g)
        if not empty_cells:
            return None

        for r, c in empty_cells:
            fixed_count = 0
            for nr, nc in get_neighbors(r, c):
                if g[nr][nc] is not None:
                    fixed_count += 1
            if fixed_count > max_fixed_neighbors:
                max_fixed_neighbors = fixed_count
                best_cell = (r, c)
        return best_cell

    def search(g):
        if not is_valid_state(g):
            return None

        if is_complete(g):
            # Final check for strict connectivity (not just potential)
            # Although potential check with no None cells implies strict connectivity
            return [row[:] for row in g]

        r, c = get_best_cell(g)

        # Try 'B' then 'W'
        for color in ['B', 'W']:
            g[r][c] = color
            result = search(g)
            if result is not None:
                return result
            g[r][c] = None # Backtrack

        return None

    # Initial validation
    if not is_valid_state(grid):
        return "No Solution"

    solution = search(grid)

    if solution:
        return solution
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
