                            valid = False
                            for v2 in d2:
                                is_cons = (abs(v1 - v2) == 1)
                                if has_d and is_cons: valid = True; break
                                if not has_d and not is_cons: valid = True; break
                            if valid: new_d1.add(v1)

                        if new_d1 != d1:
                            domains[r][c] = new_d1
                            changed = True
                            if len(new_d1) == 0: return None

                        # Prune d2 based on d1
                        new_d2 = set()
                        for v2 in d2:
                            valid = False
                            for v1 in d1:
                                is_cons = (abs(v1 - v2) == 1)
                                if has_d and is_cons: valid = True; break
                                if not has_d and not is_cons: valid = True; break
                            if valid: new_d2.add(v2)

                        if new_d2 != d2:
                            domains[r][c+1] = new_d2
                            changed = True
                            if len(new_d2) == 0: return None

                    # Check Bottom Neighbor
                    if r + 1 < N:
                        has_d = has_dot(r, c, r+1, c)
                        d1 = domains[r][c]
                        d2 = domains[r+1][c]

                        # Prune d1 based on d2
                        new_d1 = set()
                        for v1 in d1:
                            valid = False
                            for v2 in d2:
                                is_cons = (abs(v1 - v2) == 1)
                                if has_d and is_cons: valid = True; break
                                if not has_d and not is_cons: valid = True; break
                            if valid: new_d1.add(v1)

                        if new_d1 != d1:
                            domains[r][c] = new_d1
                            changed = True
                            if len(new_d1) == 0: return None

                        # Prune d2 based on d1
                        new_d2 = set()
                        for v2 in d2:
                            valid = False
                            for v1 in d1:
                                is_cons = (abs(v1 - v2) == 1)
                                if has_d and is_cons: valid = True; break
                                if not has_d and not is_cons: valid = True; break
                            if valid: new_d2.add(v2)

                        if new_d2 != d2:
                            domains[r+1][c] = new_d2
                            changed = True
                            if len(new_d2) == 0: return None
        return domains

    # Backtracking Search
    def search(domains):
        # Check if solved
        is_solved = True
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            # Final validation (should be redundant if propagation is correct)
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        # MRV Heuristic: Pick cell with smallest domain > 1
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                size = len(domains[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best_cell = (r, c)

        if best_cell is None:
            # Should have been caught by is_solved, but safety check
            return None

        r, c = best_cell
        possible_values = list(domains[r][c])

        # Try values
        for val in possible_values:
            # Create copy of domains
            new_domains = [row[:] for row in domains] # Shallow copy of rows
            new_domains[r][c] = {val}

            # Propagate
            propagated = propagate(new_domains)
            if propagated is not None:
                result = search(propagated)
                if result is not None:
                    return result
        return None

    # Initial Propagation
    initial_domains = propagate(domains)
    if initial_domains is None:
        return "No Solution"

    solution = search(initial_domains)
    if solution:
        return solution
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
