def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0])

    # State: 0 = Unknown, 1 = Mine, 2 = Safe (Empty)
    # We initialize everything as Unknown, except where we deduce safety immediately (like around 0)
    # But actually, let's just track Mines (True) and Safe (False). None means Unknown.
    # Wait, the output requires 'F' for mines and None for non-mines.
    # Let's use a state grid: None (Unknown), 'M' (Mine), 'S' (Safe).

    state = [[None for _ in range(cols)] for _ in range(rows)]

    # Helper to get neighbors
    def get_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append((nr, nc))
        return neighs

    # Pre-calculate constraints
    # A constraint is (r, c, value, set_of_neighbors)
    constraints = []
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val is not None:
                constraints.append({'r': r, 'c': c, 'val': val, 'neighs': set(get_neighbors(r, c))})

    def get_constraint_info(con):
        # Returns (unknown_neighbors, known_mines_count)
        unknown = []
        known_mines = 0
        for nr, nc in con['neighs']:
            if state[nr][nc] == 'M':
                known_mines += 1
            elif state[nr][nc] is None:
                unknown.append((nr, nc))
        return unknown, known_mines

    def apply_logic():
        changed = True
        while changed:
            changed = False

            # 1. Basic Rules
            for con in constraints:
                unknown, known_mines = get_constraint_info(con)
                needed = con['val'] - known_mines

                # Rule: If needed == len(unknown), all unknown are mines
                if needed == len(unknown) and len(unknown) > 0:
                    for nr, nc in unknown:
                        if state[nr][nc] is None:
                            state[nr][nc] = 'M'
                            changed = True
                    continue # Move to next constraint as state changed

                # Rule: If needed == 0, all unknown are safe
                if needed == 0 and len(unknown) > 0:
                    for nr, nc in unknown:
                        if state[nr][nc] is None:
                            state[nr][nc] = 'S'
                            changed = True

            if changed: continue

            # 2. Set Subtraction / Pattern Matching
            # Compare every pair of constraints
            for i in range(len(constraints)):
                for j in range(i + 1, len(constraints)):
                    con1 = constraints[i]
                    con2 = constraints[j]

                    u1, m1 = get_constraint_info(con1)
                    u2, m2 = get_constraint_info(con2)

                    set1 = set(u1)
                    set2 = set(u2)

                    needed1 = con1['val'] - m1
                    needed2 = con2['val'] - m2

                    # Check if set1 is subset of set2
                    if set1.issubset(set2):
                        diff = set2 - set1
                        if len(diff) > 0:
                            # If needed1 == needed2, then diff must be safe
                            if needed1 == needed2:
                                for nr, nc in diff:
                                    if state[nr][nc] is None:
                                        state[nr][nc] = 'S'
                                        changed = True
                            # If needed2 == needed1 + len(diff), then diff must be mines
                            elif needed2 == needed1 + len(diff):
                                for nr, nc in diff:
                                    if state[nr][nc] is None:
                                        state[nr][nc] = 'M'
                                        changed = True

                    # Check if set2 is subset of set1
                    elif set2.issubset(set1):
                        diff = set1 - set2
                        if len(diff) > 0:
                            if needed2 == needed1:
                                for nr, nc in diff:
                                    if state[nr][nc] is None:
                                        state[nr][nc] = 'S'
                                        changed = True
                            elif needed1 == needed2 + len(diff):
                                for nr, nc in diff:
                                    if state[nr][nc] is None:
                                        state[nr][nc] = 'M'
                                        changed = True

            if changed: continue

    # Run logic first
    apply_logic()

    # Check if solved (all constraints satisfied and no unknowns relevant to constraints)
    # Actually, we just need to find all mines.
    # If there are still unknowns, we need backtracking.

    # Collect all unknown cells that are neighbors to any constraint
    # (Cells far away from numbers don't matter for the logic, but usually in these puzzles all cells are constrained or irrelevant)
    # However, to be safe, let's just find ANY unknown cell.

    def is_valid():
        for con in constraints:
            _, known_mines = get_constraint_info(con)
            if known_mines != con['val']:
                # Check if it's possible to satisfy
                unknown, _ = get_constraint_info(con)
                if known_mines > con['val']: return False
                if known_mines + len(unknown) < con['val']: return False
        return True

    def solve_recursive():
        # Find first unknown cell
        # Heuristic: Pick cell involved in most constraints or tightest constraint
        best_cell = None
        min_options = float('inf')

        # Simple heuristic: find unknown neighbor of a constraint with fewest unknowns
        for con in constraints:
            unknown, known_mines = get_constraint_info(con)
            needed = con['val'] - known_mines
            if 0 < needed < len(unknown):
                if len(unknown) < min_options:
                    min_options = len(unknown)
                    best_cell = unknown[0] # Just pick one

        if best_cell is None:
            # No constrained unknowns left? Check if any unknowns exist at all
            for r in range(rows):
                for c in range(cols):
                    if state[r][c] is None:
                        best_cell = (r, c)
                        break
                if best_cell: break

        if best_cell is None:
            return True # Solved

        r, c = best_cell

        # Try Mine
        state[r][c] = 'M'
        if is_valid():
            apply_logic()
            if solve_recursive():
                return True

        # Backtrack
        state[r][c] = None
        apply_logic() # Re-apply logic after undoing (though logic is deterministic based on state)

        # Try Safe
        state[r][c] = 'S'
        if is_valid():
            apply_logic()
            if solve_recursive():
                return True

        # Backtrack
        state[r][c] = None
        apply_logic()

        return False

    if not solve_recursive():
        return "No Solution"

    # Format output
    result = []
    for r in range(rows):
        row_res = []
        for c in range(cols):
            if state[r][c] == 'M':
                row_res.append('F')
            else:
                row_res.append(None)
        result.append(row_res)

    return result

