import sys
import collections

# Increase recursion depth to handle deeper search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Grid state: 0 = Unknown, 1 = White, 2 = Black
    grid = [[0 for _ in range(C)] for _ in range(R)]
    numbers = {}

    # Initialize grid with given numbers (which are always White)
