        for c in range(C):
            if data[r][c] is not None:
                grid[r][c] = 1
                numbers[(r, c)] = data[r][c]

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                yield nr, nc

    # Rule: No 2x2 block of Black cells.
    # If 3 cells in a 2x2 are Black, the 4th must be White.
    def check_2x2(g):
        changed = False
        for r in range(R - 1):
            for c in range(C - 1):
                cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                blacks = 0
                unknowns = []
                for cr, cc in cells:
                    if g[cr][cc] == 2:
                        blacks += 1
                    elif g[cr][cc] == 0:
                        unknowns.append((cr, cc))

                if blacks == 4:
                    return False  # Conflict
                if blacks == 3 and len(unknowns) == 1:
                    ur, uc = unknowns[0]
                    if g[ur][uc] != 1:
                        g[ur][uc] = 1
                        changed = True
        return changed if changed else None

    # Rule: Islands must match number size and contain exactly one number.
    def check_islands(g):
        changed = False
        visited = [[False] * C for _ in range(R)]

        for r in range(R):
            for c in range(C):
                if g[r][c] == 1 and not visited[r][c]:
                    comp = []
                    q = collections.deque([(r, c)])
                    visited[r][c] = True
                    num_val = None
                    num_count = 0

                    while q:
                        cr, cc = q.popleft()
                        comp.append((cr, cc))
                        if (cr, cc) in numbers:
                            num_count += 1
                            num_val = numbers[(cr, cc)]
                        for nr, nc in get_neighbors(cr, cc):
                            if g[nr][nc] == 1 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                    # Each island must have exactly one number
                    if num_count == 0:
                        return False  # Numberless island
                    if num_count > 1:
                        return False  # Multiple numbers in one island

                    if len(comp) > num_val:
                        return False  # Island too big

                    if len(comp) == num_val:
                        # Island is complete; all neighbors must be Black
                        for cr, cc in comp:
                            for nr, nc in get_neighbors(cr, cc):
                                if g[nr][nc] == 0:
                                    g[nr][nc] = 2
                                    changed = True
                    else:
                        # Island is too small; check if it can grow
                        can_grow = False
                        for cr, cc in comp:
                            for nr, nc in get_neighbors(cr, cc):
                                if g[nr][nc] == 0:
                                    can_grow = True
                                    break
                            if can_grow:
                                break
                        if not can_grow:
                            return False  # Island trapped and too small
        return changed if changed else None

    # Rule: All Black cells must be orthogonally connected.
    def check_black_conn(g):
        blacks = [(r, c) for r in range(R) for c in range(C) if g[r][c] == 2]
        if not blacks:
            return True

        visited = set()
        components = []
        for start in blacks:
            if start in visited:
                continue
            comp = set()
            q = collections.deque([start])
            visited.add(start)
            while q:
                cr, cc = q.popleft()
                comp.add((cr, cc))
                for nr, nc in get_neighbors(cr, cc):
                    if g[nr][nc] == 2 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            components.append(comp)

        if len(components) > 1:
            # If there are multiple black components, check if they are isolated.
            # A component is isolated if it has no Unknown neighbors to potentially connect through.
            for comp in components:
                has_unknown_neighbor = False
                for cr, cc in comp:
                    for nr, nc in get_neighbors(cr, cc):
                        if g[nr][nc] == 0:
                            has_unknown_neighbor = True
                            break
                    if has_unknown_neighbor:
                        break
                if not has_unknown_neighbor:
                    return False  # Isolated black component
        return True

    def propagate(g):
        while True:
            changed = False

            res = check_2x2(g)
            if res is False:
                return False
            if res is True:
                changed = True

            res = check_islands(g)
            if res is False:
                return False
            if res is True:
                changed = True

            if not check_black_conn(g):
                return False

            if not changed:
                break
        return True

    def search(g):
        if not propagate(g):
            return None

        # Check if grid is full
        complete = True
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    complete = False
                    break
            if not complete:
                break

        if complete:
            return g

        # Heuristic: Pick cell with highest constraint (adjacent to numbers or existing cells)
        best = None
        best_score = -1
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    score = 0
                    for nr, nc in get_neighbors(r, c):
                        if (nr, nc) in numbers:
                            score += 10
                        if g[nr][nc] == 2:
                            score += 5
                        if g[nr][nc] == 1:
                            score += 2
                    if score > best_score:
                        best_score = score
                        best = (r, c)

        if best is None:
            return None

        br, bc = best

        # Try White
        g[br][bc] = 1
        if search(g):
            return g
        g[br][bc] = 0

        # Try Black
        g[br][bc] = 2
        if search(g):
            return g
        g[br][bc] = 0

        return None

    res_grid = search(grid)
    if res_grid is None:
        return "No Solution"

    # Format output: 'B' for Black, None for White
    out = [[None for _ in range(C)] for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if res_grid[r][c] == 2:
                out[r][c] = 'B'
    return out

