        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    def has_2x2_black(g):
        for r in range(H-1):
            for c in range(W-1):
                if g[r][c] == 2 and g[r+1][c] == 2 and g[r][c+1] == 2 and g[r+1][c+1] == 2:
                    return True
        return False

    def get_white_component(g, start_r, start_c):
        if g[start_r][start_c] != 1:
            return set()
        visited = set()
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))
            for nr, nc in get_neighbors(r, c):
                if g[nr][nc] == 1:
                    stack.append((nr, nc))
        return visited

    def is_black_connected(g):
        black_cells = [(r,c) for r in range(H) for c in range(W) if g[r][c] == 2]
        if not black_cells:
            return True 
        start = black_cells[0]
        visited = set()
        stack = [start]
        while stack:
            r, c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))
            for nr, nc in get_neighbors(r, c):
                if g[nr][nc] == 2:
                    stack.append((nr, nc))
        return len(visited) == len(black_cells)

    def is_valid_partial(g):
        if has_2x2_black(g):
            return False

        visited = set()
        for r in range(H):
            for c in range(W):
                if g[r][c] == 1 and (r,c) not in visited:
                    comp = get_white_component(g, r, c)
                    visited.update(comp)

                    nums = [numbers[(cr, cc)] for (cr, cc) in comp if (cr, cc) in numbers]
                    if len(nums) > 1:
                        return False 

                    if len(nums) == 1:
                        target = nums[0]
                        if len(comp) > target:
                            return False 
                    elif len(nums) == 0:
                        # Pruning: If a white component has no number and is surrounded by black, it's invalid
                        surrounded = True
                        for (cr, cc) in comp:
                            for nr, nc in get_neighbors(cr, cc):
                                if g[nr][nc] != 2: 
                                    surrounded = False
                                    break
                            if not surrounded: break
                        if surrounded:
                            return False 

        # Pruning: Isolated black cell
        black_cells = []
        for r in range(H):
            for c in range(W):
                if g[r][c] == 2:
                    black_cells.append((r,c))

        if len(black_cells) > 1:
            for r, c in black_cells:
                has_black_nb = False
                has_unknown_nb = False
                for nr, nc in get_neighbors(r, c):
                    if g[nr][nc] == 2: has_black_nb = True
                    if g[nr][nc] == 0: has_unknown_nb = True
                if not has_black_nb and not has_unknown_nb:
                    return False 

        return True

    def solve_recursive(g):
        if not is_valid_partial(g):
            return None

        unknowns = []
        for r in range(H):
            for c in range(W):
                if g[r][c] == 0:
                    unknowns.append((r,c))

        if not unknowns:
            if not is_black_connected(g):
                return None

            visited = set()
            for r in range(H):
                for c in range(W):
                    if g[r][c] == 1 and (r,c) not in visited:
                        comp = get_white_component(g, r, c)
                        visited.update(comp)
                        nums = [numbers[(cr, cc)] for (cr, cc) in comp if (cr, cc) in numbers]
                        if len(nums) != 1: return None
                        if len(comp) != nums[0]: return None
            return g

        # MRV Heuristic
        best_cell = None
        best_score = -1

        for r, c in unknowns:
            score = 0
            for nr, nc in get_neighbors(r, c):
                if g[nr][nc] == 1:
                    score += 10 
                if (nr, nc) in numbers:
                    score += 5
            if score > best_score:
                best_score = score
                best_cell = (r, c)

        if best_cell is None:
            best_cell = unknowns[0]

        r, c = best_cell

        # Try White
        g1 = [row[:] for row in g]
        g1[r][c] = 1
        res = solve_recursive(g1)
        if res: return res

        # Try Black
        g2 = [row[:] for row in g]
        g2[r][c] = 2
        res = solve_recursive(g2)
        if res: return res

        return None

    # Initial Propagation: Neighbors of '1's are Black
    for (r,c), val in numbers.items():
        if val == 1:
            for nr, nc in get_neighbors(r, c):
                grid[nr][nc] = 2

    final_grid = solve_recursive(grid)

    if final_grid is None:
        return "No Solution"

    result = [[None]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if final_grid[r][c] == 2:
                result[r][c] = 'B'

    return result

