                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append((nr, nc))
        return neighs

    # Initialize sets: numbered cells are implicitly safe
    safe_init = set()
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                safe_init.add((r, c))
    mines_init = set()

    # Constraint Propagation Engine
    def propagate(m_set, s_set):
        changed = True
        while changed:
            changed = False

            # 1. Basic Rules (Saturation & Clearing)
            for r in range(rows):
                for c in range(cols):
                    val = data[r][c]
                    if val is None:
                        continue
                    neighs = get_neighbors(r, c)
                    u_neighs = [n for n in neighs if n not in m_set and n not in s_set]
                    k_mines = [n for n in neighs if n in m_set]
                    needed = val - len(k_mines)

                    # Contradiction checks
                    if needed < 0:
                        return None
                    if needed > len(u_neighs):
                        return None

                    # Rule: If needed == unknowns, all unknowns are mines
                    if needed == len(u_neighs) and len(u_neighs) > 0:
                        for n in u_neighs:
                            if n not in m_set:
                                m_set.add(n)
                                changed = True
                    # Rule: If needed == 0, all unknowns are safe
                    elif needed == 0 and len(u_neighs) > 0:
                        for n in u_neighs:
                            if n not in s_set:
                                s_set.add(n)
                                changed = True

            if changed:
                continue

            # 2. Set Subtraction / Overlap Logic (Human-like Deduction)
            # Collect active constraints
            constraints = []
            for r in range(rows):
                for c in range(cols):
                    val = data[r][c]
                    if val is None:
                        continue
                    neighs = get_neighbors(r, c)
                    u_neighs = set(n for n in neighs if n not in m_set and n not in s_set)
                    if not u_neighs:
                        continue
                    k_mines_count = sum(1 for n in neighs if n in m_set)
                    needed = val - k_mines_count
                    constraints.append({'unknowns': u_neighs, 'needed': needed})

            # Compare pairs of constraints
            for i in range(len(constraints)):
                for j in range(i + 1, len(constraints)):
                    c1 = constraints[i]
                    c2 = constraints[j]
                    s1, s2 = c1['unknowns'], c2['unknowns']
                    n1, n2 = c1['needed'], c2['needed']

                    # Case: s1 is subset of s2
                    if s1.issubset(s2):
                        diff = s2 - s1
                        diff_needed = n2 - n1
                        if diff_needed < 0:
                            return None # Contradiction
                        if diff_needed == 0:
                            # Remaining cells in s2 must be safe
                            for n in diff:
                                if n not in s_set:
                                    s_set.add(n)
                                    changed = True
                        elif diff_needed == len(diff):
                            # Remaining cells in s2 must be mines
                            for n in diff:
                                if n not in m_set:
                                    m_set.add(n)
                                    changed = True

                    # Case: s2 is subset of s1
                    elif s2.issubset(s1):
                        diff = s1 - s2
                        diff_needed = n1 - n2
                        if diff_needed < 0:
                            return None # Contradiction
                        if diff_needed == 0:
                            for n in diff:
                                if n not in s_set:
                                    s_set.add(n)
                                    changed = True
                        elif diff_needed == len(diff):
                            for n in diff:
                                if n not in m_set:
                                    m_set.add(n)
                                    changed = True
        return m_set, s_set

    # Backtracking Search with Heuristics
    def search(m_set, s_set):
        # Apply logic first
        res = propagate(m_set, s_set)
        if res is None:
            return None
        m_set, s_set = res

        # Check if solved (no unknowns left)
        all_cells = set((r, c) for r in range(rows) for c in range(cols))
        unknowns = all_cells - m_set - s_set

        if not unknowns:
            return m_set, s_set

        # Heuristic: Pick an unknown cell adjacent to a numbered cell (most constrained)
        guess_cell = None
        for r in range(rows):
            for c in range(cols):
                if data[r][c] is not None:
                    neighs = get_neighbors(r, c)
                    for n in neighs:
                        if n in unknowns:
                            guess_cell = n
                            break
                    if guess_cell:
                        break
            if guess_cell:
                break

        # Fallback if no numbered neighbors (isolated area)
        if not guess_cell:
            guess_cell = next(iter(unknowns))

        # Branch 1: Assume Mine
        res_mine = search(m_set | {guess_cell}, s_set.copy())
        if res_mine is not None:
            return res_mine

        # Branch 2: Assume Safe
        res_safe = search(m_set.copy(), s_set | {guess_cell})
        if res_safe is not None:
            return res_safe

        return None

    final_res = search(mines_init, safe_init)

    if final_res is None:
        return "No Solution"

    final_mines, _ = final_res
    result_grid = [[None for _ in range(cols)] for _ in range(rows)]
    for r, c in final_mines:
        result_grid[r][c] = 'F'

    return result_grid

