import sys
from collections import deque

sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # Initial grid setup
    grid = [row[:] for row in data]

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    # Propagate 2x2 rules: If 3 cells in a 2x2 are same color, 4th must be opposite.
    # Returns False if a 2x2 block becomes monochromatic (invalid).
    def propagate_2x2(grid):
        changed = True
        while changed:
            changed = False
            for r in range(N - 1):
                for c in range(N - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    vals = [grid[rr][cc] for rr, cc in cells]
                    b_count = vals.count('B')
                    w_count = vals.count('W')
                    none_count = vals.count(None)

                    if b_count == 4 or w_count == 4:
                        return False

                    if b_count == 3 and none_count == 1:
                        for rr, cc in cells:
                            if grid[rr][cc] is None:
                                grid[rr][cc] = 'W'
                                changed = True
                    elif w_count == 3 and none_count == 1:
                        for rr, cc in cells:
                            if grid[rr][cc] is None:
                                grid[rr][cc] = 'B'
                                changed = True
        return True

    # Check for isolated single cells of a color.
    # If a cell of color C has no C neighbors and no None neighbors, 
    # and there are other C cells, it's disconnected forever.
    def check_isolation(grid):
        total_b = sum(row.count('B') for row in grid)
        total_w = sum(row.count('W') for row in grid)

        for r in range(N):
            for c in range(N):
                val = grid[r][c]
                if val is None:
                    continue

                has_same = False
                has_unknown = False
                for nr, nc in get_neighbors(r, c):
                    nval = grid[nr][nc]
                    if nval == val:
                        has_same = True
                    elif nval is None:
                        has_unknown = True

                if not has_same and not has_unknown:
                    if val == 'B' and total_b > 1:
                        return False
                    if val == 'W' and total_w > 1:
                        return False
        return True

    # Check if all cells of 'color' can potentially be connected.
    # i.e., they are not separated by a wall of '!color'.
    def check_connectivity_potential(grid, color):
        total_count = 0
        start_node = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == color:
                    total_count += 1
                    if start_node is None:
                        start_node = (r, c)

        if total_count <= 1:
            return True

        # BFS through (color OR None) cells to see if all 'color' cells are reachable
        visited = set()
        queue = deque([start_node])
        visited.add(start_node)
        reached_color_count = 0

        while queue:
            r, c = queue.popleft()
            if grid[r][c] == color:
                reached_color_count += 1

            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited:
                    if grid[nr][nc] == color or grid[nr][nc] is None:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        return reached_color_count == total_count

    # Check full connectivity (for final solution validation)
    def is_fully_connected(grid, color):
        total_count = 0
        start_node = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == color:
                    total_count += 1
                    if start_node is None:
                        start_node = (r, c)

        if total_count == 0:
            return True

        visited = set()
        queue = deque([start_node])
        visited.add(start_node)

        while queue:
            r, c = queue.popleft()
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == total_count

    def solve_recursive(grid):
        # Work on a copy to allow propagation to fill cells without complex undo logic
        current_grid = [row[:] for row in grid]

        # 1. Propagate 2x2 rules
        if not propagate_2x2(current_grid):
            return None

        # 2. Check Isolation
        if not check_isolation(current_grid):
            return None

        # 3. Check Connectivity Potential (Pruning)
        if not check_connectivity_potential(current_grid, 'B'):
            return None
        if not check_connectivity_potential(current_grid, 'W'):
            return None

        # 4. Check if full
        is_full = True
        first_unknown = None
        for r in range(N):
            for c in range(N):
                if current_grid[r][c] is None:
                    is_full = False
                    if first_unknown is None:
                        first_unknown = (r, c)

        if is_full:
            if is_fully_connected(current_grid, 'B') and is_fully_connected(current_grid, 'W'):
                return current_grid
            else:
                return None

        # 5. Branch (Backtracking)
        r, c = first_unknown

        # Try B
        branch_b = [row[:] for row in current_grid]
        branch_b[r][c] = 'B'
        res = solve_recursive(branch_b)
        if res:
            return res

        # Try W
        branch_w = [row[:] for row in current_grid]
        branch_w[r][c] = 'W'
        res = solve_recursive(branch_w)
        if res:
            return res

        return None

    # Initial propagation and checks on the input grid
    if not propagate_2x2(grid):
        return "No Solution"
    if not check_isolation(grid):
        return "No Solution"
    if not check_connectivity_potential(grid, 'B'):
        return "No Solution"
    if not check_connectivity_potential(grid, 'W'):
        return "No Solution"

    result = solve_recursive(grid)
    return result

