def solve(observation):
    # Parse grid dimensions
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0])

    # Pre-calculate neighbors for all cells to optimize lookups
    neighbors_map = {}
    for r in range(rows):
        for c in range(cols):
            neighs = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighs.append((nr, nc))
            neighbors_map[(r, c)] = neighs

    # Initialize state
    # 'safe' contains cells known not to be mines (initially all numbered cells)
    # 'mines' contains cells known to be mines
    initial_safe = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is not None:
                initial_safe.add((r, c))
    initial_mines = set()

    # Constraint Propagation Function
    # Applies basic rules and set-subtraction logic until no more changes
    def propagate(current_mines, current_safe):
        mines = set(current_mines)
        safe = set(current_safe)

        changed = True
        while changed:
            changed = False
            constraints = [] # List of (set_of_unknown_neighbors, mines_needed)

            # 1. Analyze each numbered cell
            for r in range(rows):
                for c in range(cols):
                    val = grid[r][c]
                    if val is None: continue

                    neighs = neighbors_map[(r, c)]
                    unknown_neighbors = []
                    known_mines_count = 0

                    for nr, nc in neighs:
                        if (nr, nc) in mines:
                            known_mines_count += 1
                        elif (nr, nc) not in safe:
                            unknown_neighbors.append((nr, nc))

                    mines_needed = val - known_mines_count

                    # Contradiction Detection
                    if mines_needed < 0 or mines_needed > len(unknown_neighbors):
                        return mines, safe, False

                    # Rule 1: If mines_needed is 0, all unknowns are safe
                    if mines_needed == 0:
                        for u in unknown_neighbors:
                            if u not in safe:
                                safe.add(u)
                                changed = True
                    # Rule 2: If mines_needed equals unknown count, all unknowns are mines
                    elif mines_needed == len(unknown_neighbors):
                        for u in unknown_neighbors:
                            if u not in mines:
                                mines.add(u)
                                changed = True

                    # Store constraint for advanced logic
                    if unknown_neighbors:
                        constraints.append((set(unknown_neighbors), mines_needed))

            if changed: continue

            # 2. Advanced Logic: Set Subtraction (1-1, 1-2 patterns)
            # Compare pairs of constraints (U1, R1) and (U2, R2)
            found_adv = False
            n = len(constraints)
            for i in range(n):
                U1, R1 = constraints[i]
                for j in range(i + 1, n):
                    U2, R2 = constraints[j]

                    # Case: U1 is a subset of U2
                    if U1.issubset(U2):
                        diff = U2 - U1
                        needed_in_diff = R2 - R1
                        # If R2 == R1, then mines in diff must be 0 -> Safe
                        if needed_in_diff == 0:
                            for cell in diff:
                                if cell not in safe:
                                    safe.add(cell)
                                    found_adv = True
                        # If R2 - R1 == len(diff), then all in diff must be mines
                        elif needed_in_diff == len(diff):
                            for cell in diff:
                                if cell not in mines:
                                    mines.add(cell)
                                    found_adv = True

                    # Case: U2 is a subset of U1
                    elif U2.issubset(U1):
                        diff = U1 - U2
                        needed_in_diff = R1 - R2
                        if needed_in_diff == 0:
                            for cell in diff:
                                if cell not in safe:
                                    safe.add(cell)
                                    found_adv = True
                        elif needed_in_diff == len(diff):
                            for cell in diff:
                                if cell not in mines:
                                    mines.add(cell)
                                    found_adv = True

            if found_adv:
                changed = True

        return mines, safe, True

    # DFS with Propagation
    def dfs(mines, safe):
        # Apply logic first
        mines, safe, valid = propagate(mines, safe)

        if not valid:
            return None

        # Check if solution is complete
        is_complete = True
        for r in range(rows):
            for c in range(cols):
                if (r, c) not in safe and (r, c) not in mines:
                    is_complete = False
                    break
            if not is_complete: break

        if is_complete:
            return mines

        # Branching: Pick an unknown cell
        branch_cell = None
        for r in range(rows):
            for c in range(cols):
                if (r, c) not in safe and (r, c) not in mines:
                    branch_cell = (r, c)
                    break
            if branch_cell: break

        if not branch_cell:
            return None

        # Try assuming it's a mine
        res = dfs(mines | {branch_cell}, safe)
        if res is not None:
            return res

        # Try assuming it's safe
        res = dfs(mines, safe | {branch_cell})
        if res is not None:
            return res

        return None

    # Run solver
    final_mines = dfs(initial_mines, initial_safe)

    if final_mines is None:
        return "No Solution"

    # Format output
    res_grid = [[None for _ in range(cols)] for _ in range(rows)]
    for r, c in final_mines:
        res_grid[r][c] = 'F'

    return str(res_grid)

