    data = observation['data']
    adjacent_raw = observation['adjacent']

    N = len(data)

    # Convert adjacent midpoints to a set of integer coordinates (scaled by 2) to avoid float issues
    # (r, c+0.5) -> (2r, 2c+1)
    # (r+0.5, c) -> (2r+1, 2c)
    adjacent_set = set()
    for r, c in adjacent_raw:
