    # Precompute neighbors and their relationship (consecutive or not)
    # neighbors[r][c] = list of (nr, nc, is_consecutive)
    neighbors = {}
    for r in range(N):
        for c in range(N):
            neighbors[(r, c)] = []
            # Check 4 directions
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    # Calculate midpoint scaled by 2
                    mid_r = r * 2 + dr
                    mid_c = c * 2 + dc

                    is_consecutive = (mid_r, mid_c) in adjacent_set
                    neighbors[(r, c)].append((nr, nc, is_consecutive))

    # Initialize Domains
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Helper to check if a domain assignment is valid immediately
    def is_consistent(r, c, val):
        # Check row/col uniqueness against fixed values
        for i in range(N):
            if i != c and data[r][i] == val: return False
            if i != r and data[i][c] == val: return False
        return True

    # Constraint Propagation (AC-3 style + Latin Square)
    def propagate(domains):
        queue = set()
        # Initialize queue with all cells that have single values
        for r in range(N):
            for c in range(N):
                if len(domains[(r, c)]) == 1:
                    queue.add((r, c))

        while queue:
            r, c = queue.pop()
            val_set = domains[(r, c)]
            if not val_set: return False # Contradiction

            # 1. Propagate Neighbor Constraints (Consecutive/Non-consecutive)
            for nr, nc, is_consec in neighbors[(r, c)]:
                old_domain = domains[(nr, nc)]
                new_domain = set()

                if is_consec:
                    # Must be consecutive to some value in val_set
                    for v in old_domain:
                        for u in val_set:
                            if abs(v - u) == 1:
                                new_domain.add(v)
                                break
                else:
                    # Must NOT be consecutive to ANY value in val_set
                    for v in old_domain:
                        is_bad = False
                        for u in val_set:
                            if abs(v - u) == 1:
                                is_bad = True
                                break
                        if not is_bad:
                            new_domain.add(v)

                if new_domain != old_domain:
                    if not new_domain: return False
                    domains[(nr, nc)] = new_domain
                    if len(new_domain) == 1:
                        queue.add((nr, nc))

            # 2. Propagate Latin Square Constraints (Row/Col)
            # Since N is small (5), we can just scan rows and cols for singles
            # Row r
            row_vals = set()
            for k in range(N):
                if len(domains[(r, k)]) == 1:
                    row_vals.update(domains[(r, k)])

            for k in range(N):
                if k == c: continue
                old_d = domains[(r, k)]
                new_d = old_d - row_vals
                if new_d != old_d:
                    if not new_d: return False
                    domains[(r, k)] = new_d
                    if len(new_d) == 1:
                        queue.add((r, k))

            # Col c
            col_vals = set()
            for k in range(N):
                if len(domains[(k, c)]) == 1:
                    col_vals.update(domains[(k, c)])

            for k in range(N):
                if k == r: continue
                old_d = domains[(k, c)]
                new_d = old_d - col_vals
                if new_d != old_d:
                    if not new_d: return False
                    domains[(k, c)] = new_d
                    if len(new_d) == 1:
                        queue.add((k, c))

            # 3. Hidden Singles (Value appears only once in row/col domain)
            # Row r
            val_counts = {}
            for k in range(N):
                for v in domains[(r, k)]:
                    val_counts[v] = val_counts.get(v, 0) + 1

            for k in range(N):
                if len(domains[(r, k)]) > 1:
                    for v in list(domains[(r, k)]):
                        if val_counts.get(v, 0) == 1:
                            domains[(r, k)] = {v}
                            queue.add((r, k))
                            break # Domain reduced to 1, re-queue

            # Col c
            val_counts = {}
            for k in range(N):
                for v in domains[(k, c)]:
                    val_counts[v] = val_counts.get(v, 0) + 1

            for k in range(N):
                if len(domains[(k, c)]) > 1:
                    for v in list(domains[(k, c)]):
                        if val_counts.get(v, 0) == 1:
                            domains[(k, c)] = {v}
                            queue.add((k, c))
                            break

        return True

    # Backtracking Search
    def search(domains):
        # Check if solved
        if all(len(domains[(r, c)]) == 1 for r in range(N) for c in range(N)):
            return [[list(domains[(r, c)])[0] for c in range(N)] for r in range(N)]

        # MRV Heuristic: Pick cell with smallest domain > 1
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                l = len(domains[(r, c)])
                if 1 < l < min_len:
                    min_len = l
                    best_cell = (r, c)

        if best_cell is None:
            return None # Should have been caught by solved check

        r, c = best_cell
        possible_values = sorted(list(domains[(r, c)])) # Sort for determinism

        for val in possible_values:
            # Create copy of domains
            new_domains = {k: v.copy() for k, v in domains.items()}
            new_domains[(r, c)] = {val}

            # Propagate
            if propagate(new_domains):
                result = search(new_domains)
                if result:
                    return result

        return None

    # Initial Propagation
    if not propagate(domains):
        return "No Solution"

    result = search(domains)
    if result:
        return result
    return "No Solution"

