    col_targets = observation['col_sum']
    N = len(row_targets)
    M = len(col_targets)

    # Precompute all valid subsets for each row target
    # row_possibilities[r] will store a list of tuples, where each tuple contains column indices (0..M-1)
    # that sum up to row_targets[r]. The weight of column c is (c + 1).
    row_possibilities = []
    for r in range(N):
        target = row_targets[r]
        valid = []
        # Iterate through all subsets of columns using bitmask
        for mask in range(1 << M):
            s = 0
            cols = []
            for c in range(M):
                if mask & (1 << c):
                    s += (c + 1)
                    cols.append(c)
            if s == target:
                valid.append(tuple(cols))
        row_possibilities.append(valid)

    # Precompute all valid subsets for each column target
    # col_possibilities[c] will store a list of tuples, where each tuple contains row indices (0..N-1)
    # that sum up to col_targets[c]. The weight of row r is (r + 1).
    col_possibilities = []
    for c in range(M):
        target = col_targets[c]
        valid = []
        for mask in range(1 << N):
            s = 0
            rows = []
            for r in range(N):
                if mask & (1 << r):
                    s += (r + 1)
                    rows.append(r)
            if s == target:
                valid.append(tuple(rows))
        col_possibilities.append(valid)

    # Grid state: 'B' (Black), 'W' (White/None), '?' (Unknown)
    grid = [['?' for _ in range(M)] for _ in range(N)]

    # Current valid possibilities (filtered dynamically)
    curr_row_poss = [set(p) for p in row_possibilities]
    curr_col_poss = [set(p) for p in col_possibilities]

    def propagate():
        """
        Aggressively propagate constraints to deduce cell states.
        Mimics human logic: finding cells that MUST be black (intersection of all possibilities)
        or MUST be white (not in union of any possibility).
        """
        changed = True
        while changed:
            changed = False

            # 1. Deduce from Row Possibilities
            for r in range(N):
                if not curr_row_poss[r]:
                    return False # Contradiction

                # Convert tuples to sets for easier manipulation
                lists = [set(p) for p in curr_row_poss[r]]

                # Intersection: cells present in ALL valid configurations -> Must be Black
                must_black = lists[0].copy()
                # Union: cells present in AT LEAST ONE valid configuration -> Can be Black
                can_black = set()

                for s in lists:
                    must_black &= s
                    can_black |= s

                # Apply deductions to grid
                for c in range(M):
                    if grid[r][c] == '?':
                        if c in must_black:
                            grid[r][c] = 'B'
                            changed = True
                        elif c not in can_black:
                            grid[r][c] = 'W'
                            changed = True

            # 2. Deduce from Column Possibilities
            for c in range(M):
                if not curr_col_poss[c]:
                    return False # Contradiction

                lists = [set(p) for p in curr_col_poss[c]]
                must_black = lists[0].copy()
                can_black = set()

                for s in lists:
                    must_black &= s
                    can_black |= s

                for r in range(N):
                    if grid[r][c] == '?':
                        if r in must_black:
                            grid[r][c] = 'B'
                            changed = True
                        elif r not in can_black:
                            grid[r][c] = 'W'
                            changed = True

            # 3. Filter Possibilities based on current Grid state
            # Remove any configuration that conflicts with known 'B' or 'W' cells
            for r in range(N):
                new_poss = []
                for p in curr_row_poss[r]:
                    p_set = set(p)
                    valid = True
                    for c in range(M):
                        if grid[r][c] == 'B' and c not in p_set:
                            valid = False; break
                        if grid[r][c] == 'W' and c in p_set:
                            valid = False; break
                    if valid:
                        new_poss.append(p)
                if len(new_poss) != len(curr_row_poss[r]):
                    curr_row_poss[r] = set(new_poss)
                    changed = True # Possibilities reduced, may trigger further deductions

            for c in range(M):
                new_poss = []
                for p in curr_col_poss[c]:
                    p_set = set(p)
                    valid = True
                    for r in range(N):
                        if grid[r][c] == 'B' and r not in p_set:
                            valid = False; break
                        if grid[r][c] == 'W' and r in p_set:
                            valid = False; break
                    if valid:
                        new_poss.append(p)
                if len(new_poss) != len(curr_col_poss[c]):
                    curr_col_poss[c] = set(new_poss)
                    changed = True

        return True

    def backtrack():
        # First, run constraint propagation
        if not propagate():
            return False

        # Check if the grid is fully solved
        full = True
        for r in range(N):
            for c in range(M):
                if grid[r][c] == '?':
                    full = False
                    break
            if not full: break

        if full:
            return True

        # MRV Heuristic: Pick the row or column with the fewest remaining possibilities
        # This mimics human strategy of tackling the most constrained areas first
        min_count = float('inf')
        choice = None # ('row', r) or ('col', c)

        for r in range(N):
            cnt = len(curr_row_poss[r])
            if cnt < min_count:
                min_count = cnt
                choice = ('row', r)
        for c in range(M):
            cnt = len(curr_col_poss[c])
            if cnt < min_count:
                min_count = cnt
                choice = ('col', c)

        if min_count == 0:
            return False # Should have been caught by propagate

        # Save state for backtracking
        saved_grid = [row[:] for row in grid]
        saved_row_poss = [s.copy() for s in curr_row_poss]
        saved_col_poss = [s.copy() for s in curr_col_poss]

        if choice[0] == 'row':
            r_idx = choice[1]
            options = list(curr_row_poss[r_idx])
            for opt in options:
                # Restore state
                for r in range(N):
                    for c in range(M):
                        grid[r][c] = saved_grid[r][c]
                for r in range(N):
                    curr_row_poss[r] = saved_row_poss[r].copy()
                for c in range(M):
                    curr_col_poss[c] = saved_col_poss[c].copy()

                # Apply the chosen configuration for this row
                p_set = set(opt)
                valid = True
                for c in range(M):
                    if c in p_set:
                        if grid[r_idx][c] == 'W': valid = False; break
                        grid[r_idx][c] = 'B'
                    else:
                        if grid[r_idx][c] == 'B': valid = False; break
                        grid[r_idx][c] = 'W'

                if valid:
                    if backtrack():
                        return True
        else:
            c_idx = choice[1]
            options = list(curr_col_poss[c_idx])
            for opt in options:
                # Restore state
                for r in range(N):
                    for c in range(M):
                        grid[r][c] = saved_grid[r][c]
                for r in range(N):
                    curr_row_poss[r] = saved_row_poss[r].copy()
                for c in range(M):
                    curr_col_poss[c] = saved_col_poss[c].copy()

                # Apply the chosen configuration for this column
                p_set = set(opt)
                valid = True
                for r in range(N):
                    if r in p_set:
                        if grid[r][c_idx] == 'W': valid = False; break
                        grid[r][c_idx] = 'B'
                    else:
                        if grid[r][c_idx] == 'B': valid = False; break
                        grid[r][c_idx] = 'W'

                if valid:
                    if backtrack():
                        return True

        return False

    if backtrack():
        # Format output as list of lists with 'B' and None
        result = []
        for r in range(N):
            row_res = []
            for c in range(M):
                if grid[r][c] == 'B':
                    row_res.append('B')
                else:
                    row_res.append(None)
            result.append(row_res)
        return str(result)
    else:
        return "No Solution"

