            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    # Check if all cells of a specific color form a single connected component
    def is_connected(g, color):
        cells = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == color:
                    cells.append((r, c))

        if not cells:
            return True  # Vacuously true for empty set

        start = cells[0]
        visited = set([start])
        queue = [start]

        while queue:
            r, c = queue.pop(0)
            for nr, nc in get_neighbors(r, c):
                if g[nr][nc] == color and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == len(cells)

    # Find the next unassigned cell (row-major order)
    def get_next_cell(g):
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    return (r, c)
        return None

    # Recursive solver with constraint propagation
    def search(g):
        # Constraint Propagation Loop
        changed = True
        while changed:
            changed = False

            # 1. 2x2 Rule Propagation
            # If 3 cells in a 2x2 block are same color, the 4th must be opposite.
            # If 4 cells are same color, it's a conflict.
            for r in range(N - 1):
                for c in range(N - 1):
                    cells = [g[r][c], g[r][c+1], g[r+1][c], g[r+1][c+1]]
                    count_b = cells.count('B')
                    count_w = cells.count('W')
                    count_none = cells.count(None)

                    if count_none == 0:
                        if count_b == 4 or count_w == 4:
                            return None  # Conflict: Monochromatic 2x2
                    elif count_none == 1:
                        if count_b == 3:
                            # Set the None cell to 'W'
                            if g[r][c] is None: g[r][c] = 'W'
                            elif g[r][c+1] is None: g[r][c+1] = 'W'
                            elif g[r+1][c] is None: g[r+1][c] = 'W'
                            elif g[r+1][c+1] is None: g[r+1][c+1] = 'W'
                            changed = True
                        elif count_w == 3:
                            # Set the None cell to 'B'
                            if g[r][c] is None: g[r][c] = 'B'
                            elif g[r][c+1] is None: g[r][c+1] = 'B'
                            elif g[r+1][c] is None: g[r+1][c] = 'B'
                            elif g[r+1][c+1] is None: g[r+1][c+1] = 'B'
                            changed = True

            # 2. Connectivity/Degree Rule Propagation
            # If a cell has 3 neighbors of the opposite color, the 4th neighbor MUST be the same color
            # to prevent isolation (assuming the region size > 1, which is true given the clues).
            for r in range(N):
                for c in range(N):
                    if g[r][c] is not None:
                        color = g[r][c]
                        opp = 'W' if color == 'B' else 'B'
                        neighs = get_neighbors(r, c)
                        opp_count = 0
                        none_pos = None

                        for nr, nc in neighs:
                            if g[nr][nc] == opp:
                                opp_count += 1
                            elif g[nr][nc] is None:
                                none_pos = (nr, nc)

                        if opp_count == 3 and none_pos is not None:
                            nr, nc = none_pos
                            if g[nr][nc] is None:
                                g[nr][nc] = color
                                changed = True

        # Final check for 2x2 conflicts after propagation
        for r in range(N - 1):
            for c in range(N - 1):
                cells = [g[r][c], g[r][c+1], g[r+1][c], g[r+1][c+1]]
                if None not in cells:
                    if cells[0] == cells[1] == cells[2] == cells[3]:
                        return None

        # If grid is full, check global connectivity
        cell = get_next_cell(g)
        if cell is None:
            if is_connected(g, 'B') and is_connected(g, 'W'):
                return g
            return None

        r, c = cell

        # Heuristic: Try 'B' first (since we have B clues, maybe B is more constrained?)
        # Actually, order doesn't matter much with strong propagation.

        # Try assigning 'B'
        g_b = [row[:] for row in g]
        g_b[r][c] = 'B'
        res_b = search(g_b)
        if res_b:
            return res_b

        # Try assigning 'W'
        g_w = [row[:] for row in g]
        g_w[r][c] = 'W'
        res_w = search(g_w)
        if res_w:
            return res_w

        return None

    result = search(grid)
    if result:
        return result
    return "No Solution"

