        components = []
        for r in range(H):
            for c in range(W):
                if g[r][c] == 1 and not visited[r][c]:
                    comp = []
                    queue = collections.deque([(r, c)])
                    visited[r][c] = True
                    while queue:
                        cr, cc = queue.popleft()
                        comp.append((cr, cc))
                        for nr, nc in get_neighbors(cr, cc):
                            if g[nr][nc] == 1 and not visited[nr][nc]:
