    def is_solved(current_state):
        for r in range(rows):
            for c in range(cols):
                if current_state[r][c] == -1:
                    return False
        return True

    def solve_recursive(current_state):
        # First, run propagation to fill in obvious deductions
        if not propagate(current_state):
            return None

        if is_solved(current_state):
            return current_state

        # Heuristic: Find the unknown cell that is part of the most constrained clue
        # Or simply the first unknown cell for simplicity given small grid size
        # To be more efficient, let's pick a cell involved in a clue with tightest margin
        best_cell = None
        min_margin = float('inf')

        # Collect all unknown cells
        unknowns = []
        for r in range(rows):
            for c in range(cols):
                if current_state[r][c] == -1:
                    unknowns.append((r, c))

        if not unknowns:
            return current_state # Should be caught by is_solved, but safety check

        # Simple heuristic: pick first unknown
        # Better heuristic: pick unknown involved in a clue where (val - current_blacks) is small
        # But for 5x5, simple DFS with propagation is extremely fast.
        r, c = unknowns[0]

        # Try Black (1)
        # Create a copy for branching
        state_black = [row[:] for row in current_state]
        state_black[r][c] = 1
        res_black = solve_recursive(state_black)
        if res_black:
            return res_black

        # Try White (0)
        state_white = [row[:] for row in current_state]
        state_white[r][c] = 0
        res_white = solve_recursive(state_white)
        if res_white:
            return res_white

        return None

    final_state = solve_recursive(state)

    if final_state is None:
        return "No Solution"

    # Convert to output format: 'B' for 1, None for 0
    result_grid = []
    for r in range(rows):
        row_res = []
        for c in range(cols):
            if final_state[r][c] == 1:
                row_res.append('B')
            else:
                row_res.append(None)
        result_grid.append(row_res)

    return result_grid

