def solve(observation):
    # Parse grid dimensions
    grid = observation['data']
    N = len(grid)

    # Precompute valid cells for each row based on obstacles ('B')
    # initial_available[r] will contain a set of column indices c where grid[r][c] is not 'B'
    initial_available = []
    for r in range(N):
        s = set()
        for c in range(N):
            if grid[r][c] != 'B':
                s.add(c)
        initial_available.append(s)

    # Recursive solver with backtracking and constraint propagation
    # current_stars: list of (r, c) tuples representing placed stars
    # available_sets: list of sets, where available_sets[r] is the set of valid columns for row r
    def search(current_stars, available_sets):
        # Base case: All N rows have exactly 1 star
        if len(current_stars) == N:
            return current_stars

        # Identify rows that still need a star
        rows_with_stars = {r for r, c in current_stars}
        rows_needing_stars = [r for r in range(N) if r not in rows_with_stars]

        # MRV Heuristic (Minimum Remaining Values):
        # Pick the row with the fewest valid column options to minimize branching factor.
        best_row = -1
        min_options = N + 1

        for r in rows_needing_stars:
            count = len(available_sets[r])
            if count < min_options:
                min_options = count
                best_row = r
            # Pruning: If a row has no valid spots, this branch is dead
            if count == 0:
                return None 

        if best_row == -1:
            return None # Should not happen if logic is correct

        r = best_row
        # Iterate over a snapshot of candidates to avoid modification issues during iteration
        candidates = list(available_sets[r])

        # Try each candidate column for the selected row
        for c in candidates:
            # 1. Check Column Constraint: Is column c already used by an existing star?
            col_taken = False
            for sr, sc in current_stars:
                if sc == c:
                    col_taken = True
                    break
            if col_taken:
                continue

            # 2. Check Touching Constraint: Does (r, c) touch any existing star (including diagonally)?
            touches = False
            for sr, sc in current_stars:
                if abs(r - sr) <= 1 and abs(c - sc) <= 1:
                    touches = True
                    break
            if touches:
                continue

            # 3. Propagate Constraints (Forward Checking)
            # Create a copy of available_sets for the next recursion level
            new_available = [s.copy() for s in available_sets]

            # Remove c from all other rows (Column constraint propagation)
            for other_r in range(N):
                if other_r != r:
                    if c in new_available[other_r]:
                        new_available[other_r].remove(c)

            # Remove neighbors of (r, c) from all other rows (Touching constraint propagation)
            # Neighbors are cells (nr, nc) such that max(|r-nr|, |c-nc|) == 1
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if nr != r: # Only affect other rows
                            if nc in new_available[nr]:
                                new_available[nr].remove(nc)

            # Clear the set for the current row as it's now satisfied
            new_available[r] = set()

            # 4. Aggressive Pruning
            future_rows = set(rows_needing_stars) - {r}
            valid_branch = True

            # Check 4a: Domain wipeout - Any future row has no options?
            for fr in future_rows:
                if len(new_available[fr]) == 0:
                    valid_branch = False
                    break

            if valid_branch:
                # Check 4b: Hall's Condition (Simplified)
                # Every column that is NOT yet used must be available in at least one future row.
                # If a column is unused and not available in ANY future row, we can't place a star there,
                # violating the "1 star per column" rule.
                used_cols = {sc for sr, sc in current_stars} | {c}
                for col_idx in range(N):
                    if col_idx not in used_cols:
                        found_in_future = False
                        for fr in future_rows:
                            if col_idx in new_available[fr]:
                                found_in_future = True
                                break
                        if not found_in_future:
                            valid_branch = False
                            break

            # If branch is still valid, recurse
            if valid_branch:
                res = search(current_stars + [(r, c)], new_available)
                if res is not None:
                    return res

        return None

    # Start the search
    final_stars = search([], initial_available)

    if final_stars is None:
        return "No Solution"

    # Construct the result grid with 'S' for stars and None for empty cells
    result_grid = [[None for _ in range(N)] for _ in range(N)]
    for r, c in final_stars:
        result_grid[r][c] = 'S'

    return result_grid

