def solve(observation):
    grid = [row[:] for row in observation['data']]
    N = len(grid)
    HALF = N // 2

    def get_col(g, c):
        return [g[r][c] for r in range(N)]

    def is_valid(g):
        # Check rows
        for r in range(N):
            row = g[r]
            # Consecutive
            for c in range(N - 2):
                if row[c] and row[c+1] and row[c+2]:
                    if row[c] == row[c+1] == row[c+2]:
                        return False
            # Counts
            b_count = row.count('B')
            w_count = row.count('W')
            if b_count > HALF or w_count > HALF:
                return False

        # Check cols
        for c in range(N):
            col = get_col(g, c)
            for r in range(N - 2):
                if col[r] and col[r+1] and col[r+2]:
                    if col[r] == col[r+1] == col[r+2]:
                        return False
            b_count = col.count('B')
            w_count = col.count('W')
            if b_count > HALF or w_count > HALF:
                return False

        # Check uniqueness for completed rows/cols
        completed_rows = []
        for r in range(N):
            if None not in g[r]:
                completed_rows.append(tuple(g[r]))
        if len(completed_rows) != len(set(completed_rows)):
            return False

        completed_cols = []
        for c in range(N):
            col = get_col(g, c)
            if None not in col:
                completed_cols.append(tuple(col))
        if len(completed_cols) != len(set(completed_cols)):
            return False

        return True

    def propagate(g):
        changed = True
        while changed:
            changed = False

            # 1. Consecutive Rules (Rows)
            for r in range(N):
                row = g[r]
                for c in range(N - 1):
                    if row[c] and row[c+1] and row[c] == row[c+1]:
                        # Left
                        if c > 0 and row[c-1] is None:
                            g[r][c-1] = 'W' if row[c] == 'B' else 'B'
                            changed = True
                        # Right
                        if c + 2 < N and row[c+2] is None:
                            g[r][c+2] = 'W' if row[c] == 'B' else 'B'
                            changed = True
                for c in range(N - 2):
                    if row[c] and row[c+2] and row[c] == row[c+2]:
                        if row[c+1] is None:
                            g[r][c+1] = 'W' if row[c] == 'B' else 'B'
                            changed = True

            # 2. Count Rules (Rows)
            for r in range(N):
                row = g[r]
                b_count = row.count('B')
                w_count = row.count('W')
                if b_count == HALF:
                    for c in range(N):
                        if row[c] is None:
                            g[r][c] = 'W'
                            changed = True
                elif w_count == HALF:
                    for c in range(N):
                        if row[c] is None:
                            g[r][c] = 'B'
                            changed = True

            # 3. Consecutive Rules (Cols)
            for c in range(N):
                col = get_col(g, c)
                for r in range(N - 1):
                    if col[r] and col[r+1] and col[r] == col[r+1]:
                        if r > 0 and col[r-1] is None:
                            g[r-1][c] = 'W' if col[r] == 'B' else 'B'
                            changed = True
                        if r + 2 < N and col[r+2] is None:
                            g[r+2][c] = 'W' if col[r] == 'B' else 'B'
                            changed = True
                for r in range(N - 2):
                    if col[r] and col[r+2] and col[r] == col[r+2]:
                        if col[r+1] is None:
                            g[r+1][c] = 'W' if col[r] == 'B' else 'B'
                            changed = True

            # 4. Count Rules (Cols)
            for c in range(N):
                col = get_col(g, c)
                b_count = col.count('B')
                w_count = col.count('W')
                if b_count == HALF:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                elif w_count == HALF:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            # 5. Uniqueness Propagation
            # If row A is complete, and row B matches A except for one None, 
            # then that None must be the opposite of A's value to ensure uniqueness.
            for r1 in range(N):
                row1 = g[r1]
                if None in row1: continue # Row 1 must be complete

                for r2 in range(N):
                    if r1 == r2: continue
                    row2 = g[r2]
                    # Check if row2 matches row1 except for exactly one None
                    diff_count = 0
                    diff_idx = -1
                    possible = True
                    for c in range(N):
                        if row2[c] is None:
                            diff_count += 1
                            diff_idx = c
                        elif row2[c] != row1[c]:
                            possible = False
                            break

                    if possible and diff_count == 1:
                        # Force row2[diff_idx] to be opposite of row1[diff_idx]
                        val = 'W' if row1[diff_idx] == 'B' else 'B'
                        if g[r2][diff_idx] != val:
                            g[r2][diff_idx] = val
                            changed = True

            # Same for Cols
            for c1 in range(N):
                col1 = get_col(g, c1)
                if None in col1: continue

                for c2 in range(N):
                    if c1 == c2: continue
                    col2 = get_col(g, c2)

                    diff_count = 0
                    diff_idx = -1
                    possible = True
                    for r in range(N):
                        if col2[r] is None:
                            diff_count += 1
                            diff_idx = r
                        elif col2[r] != col1[r]:
                            possible = False
                            break

                    if possible and diff_count == 1:
                        val = 'W' if col1[diff_idx] == 'B' else 'B'
                        if g[diff_idx][c2] != val:
                            g[diff_idx][c2] = val
                            changed = True

        return g

    def search(g):
        # Propagate constraints first
        g = propagate(g)

        if not is_valid(g):
            return None

        # Check if solved
        is_solved = True
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            return g

        # Find first empty cell (could use MRV heuristic for larger grids)
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    # Try 'B'
                    g[r][c] = 'B'
                    res = search([row[:] for row in g])
                    if res: return res

                    # Try 'W'
                    g[r][c] = 'W'
                    res = search([row[:] for row in g])
                    if res: return res

                    # Backtrack
                    g[r][c] = None
                    return None
        return None

    result = search(grid)
    return result

