                if abs(c - prev_c) <= 1:
                    continue

            # Place star
            col_used[c] = True
            region_used[rid] = True
            solution[r] = c

            if dfs(r + 1):
                return True

            # Backtrack
            col_used[c] = False
            region_used[rid] = False
            solution[r] = -1

        return False

    if dfs(0):
