    N = len(grid_data)

    # Identify regions
    regions = {}
    max_rid = -1
    for r in range(N):
        for c in range(N):
            rid = grid_data[r][c]
            if rid > max_rid:
                max_rid = rid
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    num_regions = max_rid + 1

    # Precompute neighbors for each cell (8 directions)
    neighbors = {}
    for r in range(N):
        for c in range(N):
            nbs = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        nbs.append((nr, nc))
            neighbors[(r, c)] = nbs

    # State variables
    # grid: 0=Unknown, 1=Star, 2=Empty
    grid = [[0] * N for _ in range(N)]

    # Counts: stars needed
    r_rem = [2] * N
    c_rem = [2] * N
    reg_rem = [2] * num_regions

    # Counts: available cells (initially all cells are available)
    r_avail = [N] * N
    c_avail = [N] * N
    reg_avail = [len(regions[rid]) for rid in range(num_regions)]

    # Helper to save state for backtracking
    def save_state():
        return (
            [row[:] for row in grid],
            r_rem[:], c_rem[:], reg_rem[:],
            r_avail[:], c_avail[:], reg_avail[:]
        )

    # Helper to restore state
    def restore_state(snapshot):
        nonlocal grid, r_rem, c_rem, reg_rem, r_avail, c_avail, reg_avail
        grid, r_rem, c_rem, reg_rem, r_avail, c_avail, reg_avail = snapshot

    # Apply setting a cell to Star (1)
    def apply_star(r, c):
        grid[r][c] = 1
        rid = grid_data[r][c]
        r_rem[r] -= 1
        c_rem[c] -= 1
        reg_rem[rid] -= 1
        r_avail[r] -= 1
        c_avail[c] -= 1
        reg_avail[rid] -= 1

        # Block neighbors
        for nr, nc in neighbors[(r, c)]:
            if grid[nr][nc] == 0:
                grid[nr][nc] = 2
                nrid = grid_data[nr][nc]
                r_avail[nr] -= 1
                c_avail[nc] -= 1
                reg_avail[nrid] -= 1

    # Apply setting a cell to Empty (2)
    def apply_empty(r, c):
        grid[r][c] = 2
        rid = grid_data[r][c]
        r_avail[r] -= 1
        c_avail[c] -= 1
        reg_avail[rid] -= 1

    # Constraint Propagation
    def propagate():
        changed = True
        while changed:
            changed = False

            # Check Rows
            for r in range(N):
                if r_rem[r] == 0:
                    for c in range(N):
                        if grid[r][c] == 0:
                            apply_empty(r, c)
                            changed = True
                elif r_avail[r] == r_rem[r]:
                    for c in range(N):
                        if grid[r][c] == 0:
                            apply_star(r, c)
                            changed = True
                if r_rem[r] < 0 or r_avail[r] < r_rem[r]:
                    return False

            # Check Cols
            for c in range(N):
                if c_rem[c] == 0:
                    for r in range(N):
                        if grid[r][c] == 0:
                            apply_empty(r, c)
                            changed = True
                elif c_avail[c] == c_rem[c]:
                    for r in range(N):
                        if grid[r][c] == 0:
                            apply_star(r, c)
                            changed = True
                if c_rem[c] < 0 or c_avail[c] < c_rem[c]:
                    return False

            # Check Regions
            for rid in range(num_regions):
                if reg_rem[rid] == 0:
                    for r, c in regions[rid]:
                        if grid[r][c] == 0:
                            apply_empty(r, c)
                            changed = True
                elif reg_avail[rid] == reg_rem[rid]:
                    for r, c in regions[rid]:
                        if grid[r][c] == 0:
                            apply_star(r, c)
                            changed = True
                if reg_rem[rid] < 0 or reg_avail[rid] < reg_rem[rid]:
                    return False
        return True

    # Backtracking Search
    def search():
        if not propagate():
            return False

        # Find first unknown cell
        # Heuristic: Could pick cell with most constraints, but simple scan is fast for N=10
        r_pick, c_pick = -1, -1
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    r_pick, c_pick = r, c
                    break
            if r_pick != -1:
                break

        if r_pick == -1:
            return True  # Solved

        r, c = r_pick, c_pick
        rid = grid_data[r][c]

        # Try placing Star
        # Check basic constraints before branching
        if r_rem[r] > 0 and c_rem[c] > 0 and reg_rem[rid] > 0:
            # Check if any neighbor is already a star
            can_place = True
            for nr, nc in neighbors[(r, c)]:
                if grid[nr][nc] == 1:
                    can_place = False
                    break

            if can_place:
                snapshot = save_state()
                apply_star(r, c)
                if search():
                    return True
                restore_state(snapshot)

        # Try placing Empty
        snapshot = save_state()
        apply_empty(r, c)
        if search():
            return True
        restore_state(snapshot)

        return False

    if search():
        # Format output
        result = [[None] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 1:
                    result[r][c] = 'S'
        return result
    else:
        return "No Solution"

