    def propagate(domains):
        queue = []
        # Initialize queue with all cells that have single values or constraints
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) == 1:
                    queue.append((r, c))

        changed = True
        while changed:
            changed = False
            # We iterate all cells to check constraints, could be optimized but N=5 is small
            for r in range(N):
                for c in range(N):
                    current_domain = domains[r][c]
                    if not current_domain: return False # Contradiction

                    # 1. Latin Square Propagation (Row/Col uniqueness)
                    # If a cell has a single value, remove it from row/col peers
                    if len(current_domain) == 1:
                        val = next(iter(current_domain))
                        # Row peers
                        for cc in range(N):
                            if cc != c:
                                if val in domains[r][cc]:
                                    domains[r][cc].discard(val)
                                    if len(domains[r][cc]) == 0: return False
                                    changed = True
                        # Col peers
                        for rr in range(N):
                            if rr != r:
                                if val in domains[rr][c]:
                                    domains[rr][c].discard(val)
                                    if len(domains[rr][c]) == 0: return False
                                    changed = True

                    # 2. Consecutive Constraints
                    for nr, nc in must_consecutive[r][c]:
                        neighbor_domain = domains[nr][nc]
                        # If current cell is fixed to V, neighbor must be V-1 or V+1
                        if len(current_domain) == 1:
                            val = next(iter(current_domain))
                            allowed = {val - 1, val + 1}
                            allowed = {x for x in allowed if 1 <= x <= N}

                            before_size = len(neighbor_domain)
                            domains[nr][nc] = neighbor_domain.intersection(allowed)
                            if len(domains[nr][nc]) == 0: return False
                            if len(domains[nr][nc]) < before_size:
                                changed = True

                        # Reverse: If neighbor is fixed, constrain current
                        if len(neighbor_domain) == 1:
                            val = next(iter(neighbor_domain))
                            allowed = {val - 1, val + 1}
                            allowed = {x for x in allowed if 1 <= x <= N}

                            before_size = len(current_domain)
                            # We can't reassign current_domain directly here easily in loop, 
                            # but we can intersect. Note: domains[r][c] is a reference.
                            # Actually, let's just rely on the queue or next iteration for symmetry,
                            # but explicit intersection is safer.
                            new_domain = current_domain.intersection(allowed)
                            if len(new_domain) == 0: return False
                            if len(new_domain) < len(current_domain):
                                domains[r][c] = new_domain
                                changed = True

                    # 3. Non-Consecutive Constraints
                    for nr, nc in must_not_consecutive[r][c]:
                        neighbor_domain = domains[nr][nc]
                        # If current cell is fixed to V, neighbor cannot be V-1 or V+1
                        if len(current_domain) == 1:
                            val = next(iter(current_domain))
                            forbidden = {val - 1, val + 1}

                            before_size = len(neighbor_domain)
                            domains[nr][nc] = neighbor_domain - forbidden
                            if len(domains[nr][nc]) == 0: return False
                            if len(domains[nr][nc]) < before_size:
                                changed = True

                        # Reverse
                        if len(neighbor_domain) == 1:
                            val = next(iter(neighbor_domain))
                            forbidden = {val - 1, val + 1}

                            before_size = len(current_domain)
                            new_domain = current_domain - forbidden
                            if len(new_domain) == 0: return False
                            if len(new_domain) < len(current_domain):
                                domains[r][c] = new_domain
                                changed = True
        return True

    # Backtracking Search with MRV
    def search(domains):
        # Check if solved
        is_solved = True
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        # MRV Heuristic: Find cell with smallest domain > 1
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                size = len(domains[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best_cell = (r, c)

        if best_cell is None:
            return None # Should have been caught by is_solved or contradiction

        r, c = best_cell
        possible_values = list(domains[r][c])

        # Try values
        for val in possible_values:
            # Create deep copy of domains (shallow copy of sets is not enough, need new sets)
            # Optimization: Only copy affected parts? No, N=5 is tiny, full copy is fine.
            new_domains = [ [s.copy() for s in row] for row in domains ]
            new_domains[r][c] = {val}

            if propagate(new_domains):
                result = search(new_domains)
                if result:
                    return result

        return None

    if propagate(domains):
        solution = search(domains)
        if solution:
            return solution
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
