    for r, c in component:
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                if grid[nr][nc] == 0:
                    return False
    return True

def backtrack(grid):
    N = len(grid)

    # Find first unknown cell
    r_unknown, c_unknown = -1, -1
    for r in range(N):
        for c in range(N):
            if grid[r][c] == 0:
                r_unknown, c_unknown = r, c
                break
