        if not check_local_2x2(grid, r, c, val):
            continue

        grid[r][c] = val
        next_grid = copy.deepcopy(grid)

        if propagate(next_grid):
            res = backtrack(next_grid)
            if res:
                return res

        # Backtrack
        grid[r][c] = 0

    return None

def check_local_2x2(grid, r, c, val):
    N = len(grid)
    # Check 2x2 blocks that include (r, c)
    blocks = []
    if r > 0 and c > 0: blocks.append((r-1, c-1))
    if r > 0 and c < N-1: blocks.append((r-1, c))
    if r < N-1 and c > 0: blocks.append((r, c-1))
    if r < N-1 and c < N-1: blocks.append((r, c))

    for sr, sc in blocks:
        vals = []
        for dr in range(2):
