    # Check Black connectivity
    black_cells = [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 1]
    if not black_cells: return False # Must have black cells

    start = black_cells[0]
    visited = set([start])
    queue = [start]
    while queue:
        cr, cc = queue.pop(0)
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr+dr, cc+dc
            if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] == 1 and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))
    if len(visited) != len(black_cells): return False

    # Check White connectivity
    white_cells = [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 2]
    if not white_cells: return False # Must have white cells

    start = white_cells[0]
