    rows = len(data)
    cols = len(data[0])

    # State sets: mines and safe cells
    mines = set()
    safe = set()

    # Initialize safe with all numbered cells (clues cannot be mines)
    clues = {}
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]
                safe.add((r, c))

    def get_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append((nr, nc))
        return neighs

    def get_unknown_neighbors(clue_pos):
        r, c = clue_pos
        neighs = get_neighbors(r, c)
        return [n for n in neighs if n not in mines and n not in safe]

    def get_known_mines_count(clue_pos):
        r, c = clue_pos
        neighs = get_neighbors(r, c)
        return sum(1 for n in neighs if n in mines)

    # Propagation Loop: Apply logical deduction rules until no changes occur
    changed = True
    while changed:
        changed = False

        # 1. Basic Rules (Satisfied/Full)
        for (r, c), val in clues.items():
            unknown_neighs = get_unknown_neighbors((r, c))
            known_mines = get_known_mines_count((r, c))

            # Rule: If mines found == value, rest are safe
            if known_mines == val:
                for n in unknown_neighs:
                    if n not in safe:
                        safe.add(n)
                        changed = True

            # Rule: If mines found + unknowns == value, rest are mines
            elif known_mines + len(unknown_neighs) == val:
                for n in unknown_neighs:
                    if n not in mines:
                        mines.add(n)
                        changed = True

        # 2. Set Subtraction / Overlap Rules (Human-like pattern recognition)
        # Compare pairs of clues to deduce mines/safe cells based on set relationships
        clue_list = list(clues.keys())
        for i in range(len(clue_list)):
            for j in range(i + 1, len(clue_list)):
                c1, c2 = clue_list[i], clue_list[j]

                # Optimization: only check nearby clues (Manhattan distance <= 2 implies potential overlap)
                if abs(c1[0] - c2[0]) > 2 or abs(c1[1] - c2[1]) > 2:
                    continue

                u1 = set(get_unknown_neighbors(c1))
                u2 = set(get_unknown_neighbors(c2))

                if not u1 or not u2: continue

                v1 = clues[c1] - get_known_mines_count(c1)
                v2 = clues[c2] - get_known_mines_count(c2)

                # Case: u1 is a subset of u2
                if u1.issubset(u2):
                    # If both need same number of mines, the difference (u2 - u1) must be safe
                    if v1 == v2:
                        diff = u2 - u1
                        for n in diff:
                            if n not in safe:
                                safe.add(n)
                                changed = True
                    # If u2 needs more mines, the difference must contain the extra mines
                    elif v1 < v2:
                        diff = u2 - u1
                        needed = v2 - v1
                        if len(diff) == needed:
                            for n in diff:
                                if n not in mines:
                                    mines.add(n)
                                    changed = True
