                        diff = u1 - u2
                        for n in diff:
                            if n not in safe:
                                safe.add(n)
                                changed = True
                    elif v2 < v1:
                        diff = u1 - u2
                        needed = v1 - v2
                        if len(diff) == needed:
                            for n in diff:
                                if n not in mines:
                                    mines.add(n)
                                    changed = True

    # Check for remaining unknowns near clues that logic couldn't solve
    active_unknowns = set()
    for (r, c) in clues:
        active_unknowns.update(get_unknown_neighbors((r, c)))

    if active_unknowns:
        # Backtracking Search with Connected Components Decomposition
        # Build a graph where clues are nodes, connected if they share unknown neighbors
        adj = {c: [] for c in clues}
        clue_keys = list(clues.keys())
        for i in range(len(clue_keys)):
            for j in range(i+1, len(clue_keys)):
                c1, c2 = clue_keys[i], clue_keys[j]
                u1 = set(get_unknown_neighbors(c1))
                u2 = set(get_unknown_neighbors(c2))
                if u1 & u2:
                    adj[c1].append(c2)
                    adj[c2].append(c1)

        # Find connected components of clues
        visited_clues = set()
        components = []

        for c in clues:
            if c not in visited_clues:
                comp_clues = []
                stack = [c]
                visited_clues.add(c)
                while stack:
                    curr = stack.pop()
                    comp_clues.append(curr)
                    for neighbor in adj[curr]:
                        if neighbor not in visited_clues:
                            visited_clues.add(neighbor)
                            stack.append(neighbor)
                components.append(comp_clues)

        # Solve each component independently
        for comp_clues in components:
            comp_unknowns = set()
            for c in comp_clues:
                comp_unknowns.update(get_unknown_neighbors(c))

            if not comp_unknowns:
                continue

            unknown_list = list(comp_unknowns)
            solution_found = False

            # Heuristic: Sort unknowns by number of constraints (clues they touch) to fail fast
            def count_constraints(cell):
                count = 0
                for c in comp_clues:
                    if cell in get_neighbors(c[0], c[1]):
                        count += 1
                return count

            unknown_list.sort(key=count_constraints, reverse=True)

            def is_valid_state(local_mines, local_safe):
                for c in comp_clues:
                    r, cv = c
                    val = clues[c]
                    neighs = get_neighbors(r, c)

                    total_mines_so_far = 0
                    unknown_count = 0

                    for n in neighs:
                        if n in mines or n in local_mines:
                            total_mines_so_far += 1
                        elif n not in safe and n not in local_safe:
                            unknown_count += 1

                    # Pruning: Violation of constraints
                    if total_mines_so_far > val: return False
                    if total_mines_so_far + unknown_count < val: return False
                return True

            def backtrack(idx, local_mines, local_safe):
                nonlocal solution_found
                if solution_found: return

                if idx == len(unknown_list):
                    # Final check: exact satisfaction for all clues in component
                    for c in comp_clues:
                        r, cv = c
                        val = clues[c]
                        neighs = get_neighbors(r, c)
                        m_count = sum(1 for n in neighs if n in mines or n in local_mines)
                        if m_count != val:
                            return
                    # Solution found: update global state
                    mines.update(local_mines)
                    safe.update(local_safe)
                    solution_found = True
                    return

                cell = unknown_list[idx]

                # Try Mine
                local_mines.add(cell)
                if is_valid_state(local_mines, local_safe):
                    backtrack(idx + 1, local_mines, local_safe)
                local_mines.remove(cell)

                if solution_found: return

                # Try Safe
                local_safe.add(cell)
                if is_valid_state(local_mines, local_safe):
                    backtrack(idx + 1, local_mines, local_safe)
                local_safe.remove(cell)

            backtrack(0, set(), set())

    # Construct Output Grid
    result_grid = [[None for _ in range(cols)] for _ in range(rows)]
    for r, c in mines:
        result_grid[r][c] = 'F'

    return result_grid

