                if val >= 0:
                    numbered_cells[(r, c)] = val
            else:
                white_cells.add((r, c))

    def get_line(r, c, dr, dc):
        """Generator for cells in direction (dr, dc) from (r, c) until wall."""
        nr, nc = r + dr, c + dc
        while 0 <= nr < N and 0 <= nc < N:
            if (nr, nc) in black_cells:
                break
            yield (nr, nc)
            nr += dr
            nc += dc

    def compute_state(bulbs):
        """
        Computes lit cells and forbidden cells based on current bulbs.
        Returns (lit_set, forbidden_set, status)
        status: 'OK', 'CONFLICT'
        """
        lit = set()
        forbidden = set()

        # 1. Calculate illumination and check bulb-bulb conflict
        for (r, c) in bulbs:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                for nr, nc in get_line(r, c, dr, dc):
                    if (nr, nc) in bulbs:
                        return None, None, 'CONFLICT' # Two bulbs see each other
                    lit.add((nr, nc))

        # Cells that are lit cannot have a bulb (Rule 3)
        forbidden.update(lit)

        # 2. Check numbered clues
        for (r, c), val in numbered_cells.items():
            adj_bulbs = 0
            adj_white = []
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if (nr, nc) in bulbs:
                        adj_bulbs += 1
                    elif (nr, nc) in white_cells:
                        adj_white.append((nr, nc))

            if adj_bulbs > val:
                return None, None, 'CONFLICT' # Too many bulbs adjacent

            # If clue is satisfied, adjacent white cells cannot have bulbs
            if adj_bulbs == val:
                for wr, wc in adj_white:
                    if (wr, wc) not in bulbs:
                        forbidden.add((wr, wc))

        return lit, forbidden, 'OK'

    def propagate(bulbs):
        """
        Applies logical deductions until no more changes.
        Returns (new_bulbs_set, status)
        status: 'OK', 'CONFLICT', 'DEAD_END', 'SOLVED', 'PARTIAL'
        """
        current_bulbs = set(bulbs)
        changed = True

        while changed:
            changed = False
            lit, forbidden, status = compute_state(current_bulbs)
            if status == 'CONFLICT':
                return None, 'CONFLICT'

            # Deduction 1: Forced Bulbs from Clues
            # If a clue 'K' has 'K' available spots (bulbs + empty white), fill them.
            for (r, c), val in numbered_cells.items():
                adj_bulbs = 0
                adj_avail = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if (nr, nc) in current_bulbs:
                            adj_bulbs += 1
                        elif (nr, nc) in white_cells and (nr, nc) not in forbidden:
                            adj_avail.append((nr, nc))

                if adj_bulbs + len(adj_avail) == val:
                    for nr, nc in adj_avail:
                        if (nr, nc) not in current_bulbs:
                            current_bulbs.add((nr, nc))
                            changed = True

            # Deduction 2: Unique Illumination for Unlit Cells
            # If a white cell is unlit, and only one spot can light it, place bulb there.
            lit, forbidden, _ = compute_state(current_bulbs)
            unlit_white = [w for w in white_cells if w not in lit and w not in current_bulbs]

            if not unlit_white:
                # All white cells lit. Check if clues are satisfied.
                satisfied = True
                for (r, c), val in numbered_cells.items():
                    cnt = 0
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        if (r+dr, c+dc) in current_bulbs:
                            cnt += 1
                    if cnt != val:
                        satisfied = False
                        break
                if satisfied:
                    return current_bulbs, 'SOLVED'
                else:
                    # Clues not satisfied but board is full of light -> Dead End
                    return None, 'DEAD_END'

            found_force = False
            for ur, uc in unlit_white:
                cands = set()
                # Candidate: the cell itself
                if (ur, uc) not in forbidden:
                    cands.add((ur, uc))

                # Candidates: cells in row/col that can light (ur, uc)
                # Scan Left
                for dc in range(-1, -N-1, -1):
                    nc = uc + dc
                    if nc < 0 or (ur, nc) in black_cells: break
                    if (ur, nc) in white_cells and (ur, nc) not in forbidden and (ur, nc) not in current_bulbs:
                        cands.add((ur, nc))
                # Scan Right
                for dc in range(1, N):
                    nc = uc + dc
                    if nc >= N or (ur, nc) in black_cells: break
                    if (ur, nc) in white_cells and (ur, nc) not in forbidden and (ur, nc) not in current_bulbs:
                        cands.add((ur, nc))
                # Scan Up
                for dr in range(-1, -N-1, -1):
                    nr = ur + dr
                    if nr < 0 or (nr, uc) in black_cells: break
                    if (nr, uc) in white_cells and (nr, uc) not in forbidden and (nr, uc) not in current_bulbs:
                        cands.add((nr, uc))
                # Scan Down
                for dr in range(1, N):
                    nr = ur + dr
                    if nr >= N or (nr, uc) in black_cells: break
                    if (nr, uc) in white_cells and (nr, uc) not in forbidden and (nr, uc) not in current_bulbs:
                        cands.add((nr, uc))

                if len(cands) == 0:
                    return None, 'DEAD_END' # Cannot light this cell
                elif len(cands) == 1:
                    nr, nc = list(cands)[0]
                    if (nr, nc) not in current_bulbs:
                        current_bulbs.add((nr, nc))
                        changed = True
                        found_force = True

            # If we found a forced move, restart the while loop to propagate effects
            if not found_force:
                break

        # Final state check
        lit, forbidden, status = compute_state(current_bulbs)
        if status == 'CONFLICT': return None, 'CONFLICT'

        unlit_white = [w for w in white_cells if w not in lit and w not in current_bulbs]
        if not unlit_white:
             satisfied = True
             for (r, c), val in numbered_cells.items():
                cnt = sum(1 for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)] if (r+dr, c+dc) in current_bulbs)
                if cnt != val: satisfied = False; break
             if satisfied: return current_bulbs, 'SOLVED'

        return current_bulbs, 'PARTIAL'

    def dfs(bulbs):
        # 1. Propagate logic
        res_bulbs, status = propagate(bulbs)

        if status in ['CONFLICT', 'DEAD_END']:
            return None
        if status == 'SOLVED':
            return res_bulbs

        # 2. Branching
        # Pick an unlit white cell to try to light
        lit, forbidden, _ = compute_state(res_bulbs)
        unlit_white = [w for w in white_cells if w not in lit and w not in res_bulbs]

        if not unlit_white:
            return None # Should have been caught by SOLVED

        # Heuristic: Pick the first unlit cell (could optimize with min candidates)
        ur, uc = unlit_white[0]

        # Find all valid spots to light (ur, uc)
        cands = set()
        if (ur, uc) not in forbidden: cands.add((ur, uc))

        for dc in range(-1, -N-1, -1):
            nc = uc + dc
            if nc < 0 or (ur, nc) in black_cells: break
            if (ur, nc) in white_cells and (ur, nc) not in forbidden and (ur, nc) not in res_bulbs:
                cands.add((ur, nc))
        for dc in range(1, N):
            nc = uc + dc
            if nc >= N or (ur, nc) in black_cells: break
            if (ur, nc) in white_cells and (ur, nc) not in forbidden and (ur, nc) not in res_bulbs:
                cands.add((ur, nc))
        for dr in range(-1, -N-1, -1):
            nr = ur + dr
            if nr < 0 or (nr, uc) in black_cells: break
            if (nr, uc) in white_cells and (nr, uc) not in forbidden and (nr, uc) not in res_bulbs:
                cands.add((nr, uc))
        for dr in range(1, N):
            nr = ur + dr
            if nr >= N or (nr, uc) in black_cells: break
            if (nr, uc) in white_cells and (nr, uc) not in forbidden and (nr, uc) not in res_bulbs:
                cands.add((nr, uc))

        for br, bc in cands:
            new_bulbs = set(res_bulbs)
            new_bulbs.add((br, bc))
            res = dfs(new_bulbs)
            if res is not None:
                return res

        return None

    final_bulbs = dfs(set())

    if final_bulbs is None:
        return "No Solution"

    # Format Output
    res_grid = [[None for _ in range(N)] for _ in range(N)]
    for r, c in final_bulbs:
        res_grid[r][c] = 'B'
    return res_grid

