import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # Initial grid
    grid = [row[:] for row in data]

    # Propagate 2x2 rules: if 3 cells are same color, 4th must be opposite.
    # Also checks for 2x2 violation (4 same).
    def propagate(g_in):
        g = [row[:] for row in g_in]
        changed = True
        while changed:
            changed = False
            for r in range(N - 1):
                for c in range(N - 1):
                    cells = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
                    vals = [g[cr][cc] for cr, cc in cells]

                    if None in vals:
                        count_b = vals.count('B')
                        count_w = vals.count('W')

                        if count_b == 3:
                            for cr, cc in cells:
                                if g[cr][cc] is None:
                                    g[cr][cc] = 'W'
                                    changed = True
                        elif count_w == 3:
                            for cr, cc in cells:
                                if g[cr][cc] is None:
                                    g[cr][cc] = 'B'
                                    changed = True
            # Check for 2x2 violation
            for r in range(N - 1):
                for c in range(N - 1):
                    v = g[r][c]
                    if v is not None and v == g[r+1][c] == g[r][c+1] == g[r+1][c+1]:
                        return None
        return g

    # Check connectivity for a color.
    # Treats None as traversable (potential connection).
    # Returns False if fixed cells of 'color' are separated by the other color.
    def check_connectivity(g, color):
        targets = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == color:
                    targets.append((r, c))

        if not targets:
            return True

        start = targets[0]
        visited = set([start])
        queue = [start]

        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if (nr, nc) not in visited:
                        val = g[nr][nc]
                        if val == color or val is None:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

        for t in targets:
            if t not in visited:
                return False
        return True

    def search(g_in):
        # 1. Propagate
        g = propagate(g_in)
        if g is None:
            return False

        # 2. Check connectivity feasibility
        if not check_connectivity(g, 'B'):
            return False
        if not check_connectivity(g, 'W'):
            return False

        # 3. Find next empty cell
        empty = None
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    empty = (r, c)
                    break
            if empty:
                break

        if empty is None:
            return g

        r, c = empty

        # Try B
        g[r][c] = 'B'
        res = search(g)
        if res:
            return res

        # Try W
        g[r][c] = 'W'
        res = search(g)
        if res:
            return res

        return False

    result = search(grid)
    return result

