                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append((nr, nc))
        return neighs

    def propagate(current_state):
        changed = True
        while changed:
            changed = False

            # 1. Basic Rules (Saturation & Clearing)
            for r in range(rows):
                for c in range(cols):
                    val = data[r][c]
                    if val is None: continue

                    neighs = get_neighbors(r, c)
                    mines_count = sum(1 for nr, nc in neighs if current_state[nr][nc] == 'F')
                    unknown_count = sum(1 for nr, nc in neighs if current_state[nr][nc] == 'U')

                    needed = val - mines_count

                    # Rule: If remaining unknowns == needed mines, all are mines
                    if needed == unknown_count and unknown_count > 0:
                        for nr, nc in neighs:
                            if current_state[nr][nc] == 'U':
                                current_state[nr][nc] = 'F'
                                changed = True

                    # Rule: If needed mines == 0, all unknowns are safe
                    if needed == 0 and unknown_count > 0:
                        for nr, nc in neighs:
                            if current_state[nr][nc] == 'U':
                                current_state[nr][nc] = 'S'
                                changed = True

            # 2. Advanced Rule: Set Subtraction / Overlap (Human-like logic)
            # Collect all active clues with remaining unknowns
            clues = []
            for r in range(rows):
                for c in range(cols):
                    if data[r][c] is not None:
                        neighs = get_neighbors(r, c)
                        u_neighs = [n for n in neighs if current_state[n[0]][n[1]] == 'U']
                        f_neighs = [n for n in neighs if current_state[n[0]][n[1]] == 'F']
                        needed = data[r][c] - len(f_neighs)
                        if needed > 0 and len(u_neighs) > 0:
                            clues.append({'pos': (r, c), 'unknowns': set(u_neighs), 'needed': needed})

            # Compare pairs of clues to find subset relationships
            for i in range(len(clues)):
                for j in range(i + 1, len(clues)):
                    c1 = clues[i]
                    c2 = clues[j]

                    u1 = c1['unknowns']
                    u2 = c2['unknowns']
                    n1 = c1['needed']
                    n2 = c2['needed']

                    # Check if u1 is subset of u2
                    if u1.issubset(u2):
                        diff = u2 - u1
                        if len(diff) > 0:
                            # Logic: Mines(u2) = Mines(u1) + Mines(diff)
                            # n2 = n1 + Mines(diff) => Mines(diff) = n2 - n1
                            mines_in_diff = n2 - n1
                            if mines_in_diff == 0:
                                # All in diff are Safe
                                for nr, nc in diff:
                                    if current_state[nr][nc] == 'U':
                                        current_state[nr][nc] = 'S'
                                        changed = True
                            elif mines_in_diff == len(diff):
