                            elif mines_in_diff == len(diff):
                                for nr, nc in diff:
                                    if current_state[nr][nc] == 'U':
                                        current_state[nr][nc] = 'F'
                                        changed = True

        return current_state

    def is_consistent(current_state):
        for r in range(rows):
            for c in range(cols):
                val = data[r][c]
                if val is None: continue

                neighs = get_neighbors(r, c)
                mines_count = sum(1 for nr, nc in neighs if current_state[nr][nc] == 'F')
                unknown_count = sum(1 for nr, nc in neighs if current_state[nr][nc] == 'U')

                if mines_count > val: return False
                if mines_count + unknown_count < val: return False
        return True

    def solve_backtrack(current_state):
        # Aggressive constraint propagation
        current_state = propagate(current_state)

        if not is_consistent(current_state):
            return None

        # Check if solved (no 'U' left)
        has_unknown = False
        for r in range(rows):
            for c in range(cols):
                if current_state[r][c] == 'U':
                    has_unknown = True
                    break
            if has_unknown: break

        if not has_unknown:
            return current_state

        # Heuristic: Pick first unknown cell
        best_cell = None
        for r in range(rows):
            for c in range(cols):
                if current_state[r][c] == 'U':
                    best_cell = (r, c)
                    break
            if best_cell: break

        if not best_cell: return current_state

        r, c = best_cell

        # Try Mine ('F')
        new_state = [row[:] for row in current_state]
        new_state[r][c] = 'F'
        res = solve_backtrack(new_state)
        if res: return res

        # Try Safe ('S')
        new_state = [row[:] for row in current_state]
        new_state[r][c] = 'S'
        res = solve_backtrack(new_state)
        if res: return res

        return None

    final_state = solve_backtrack(state)

    if final_state is None:
        return "No Solution"

    # Format output: 'F' for mine, None for safe
    result_grid = []
    for r in range(rows):
        row_res = []
        for c in range(cols):
            if final_state[r][c] == 'F':
                row_res.append('F')
            else:
                row_res.append(None)
        result_grid.append(row_res)

    return result_grid

