    def get_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append((nr, nc))
        return neighs

    # Constraint Propagation Engine
    # Repeatedly applies logical deductions (Human-like solving techniques) 
    # until the grid stabilizes or a contradiction is found.
    def propagate(current_grid):
        changed = True
        while changed:
            changed = False
            for (r, c), val in numbers.items():
                neighs = get_neighbors(r, c)
                unknowns = []
                blacks_count = 0

                # Analyze current state of neighbors
                for nr, nc in neighs:
                    state = current_grid[nr][nc]
                    if state == -1:
                        unknowns.append((nr, nc))
                    elif state == 1:
                        blacks_count += 1

                # Deduction 1: If current blacks equal the number, remaining unknowns must be White
                # (Constraint satisfied, no more blacks allowed)
                if blacks_count == val:
                    for nr, nc in unknowns:
                        if current_grid[nr][nc] == -1:
                            current_grid[nr][nc] = 0
                            changed = True

                # Deduction 2: If current blacks + unknowns equal the number, all unknowns must be Black
                # (Must fill all remaining spots to reach the count)
                elif blacks_count + len(unknowns) == val:
                    for nr, nc in unknowns:
                        if current_grid[nr][nc] == -1:
                            current_grid[nr][nc] = 1
                            changed = True

                # Consistency Check: Fail if constraints are violated
                # 1. Too many blacks already placed
                # 2. Not enough space left to reach the required count
                elif blacks_count > val or (blacks_count + len(unknowns)) < val:
                    return False 
        return True

    # Backtracking Search with Heuristics
    def backtrack(current_grid):
        # 1. Propagate constraints to reduce search space before branching
        if not propagate(current_grid):
            return None

        # 2. Check for solution (no unknowns left)
        is_solved = True
        for r in range(rows):
            for c in range(cols):
                if current_grid[r][c] == -1:
                    is_solved = False
                    break
            if not is_solved:
                break

        if is_solved:
            # Final verification of all constraints to ensure validity
            for (r, c), val in numbers.items():
                neighs = get_neighbors(r, c)
                count = sum(1 for nr, nc in neighs if current_grid[nr][nc] == 1)
                if count != val:
                    return None
            return current_grid

        # 3. Heuristic Variable Selection (Most Constrained Variable)
        # Select the numbered cell with the fewest unknown neighbors to minimize branching factor
        best_constraint = None
        min_unknowns = float('inf')

        for (r, c), val in numbers.items():
            neighs = get_neighbors(r, c)
            unknowns_count = sum(1 for nr, nc in neighs if current_grid[nr][nc] == -1)

            # We prioritize constraints that are close to being resolved
            if 0 < unknowns_count < min_unknowns:
                min_unknowns = unknowns_count
                best_constraint = (r, c)

        # Determine the specific cell to branch on based on the best constraint
        if best_constraint is not None:
            r, c = best_constraint
            neighs = get_neighbors(r, c)
            for nr, nc in neighs:
                if current_grid[nr][nc] == -1:
                    r_guess, c_guess = nr, nc
