            found = False
            for r in range(rows):
                for c in range(cols):
                    if current_grid[r][c] == -1:
                        r_guess, c_guess = r, c
                        found = True
                        break
                if found: break

        # 4. Branching (Try Black then White)
        # Branch 1: Set cell to Black (1)
        new_grid_black = [row[:] for row in current_grid]
        new_grid_black[r_guess][c_guess] = 1
        res = backtrack(new_grid_black)
        if res is not None:
            return res

        # Branch 2: Set cell to White (0)
        new_grid_white = [row[:] for row in current_grid]
        new_grid_white[r_guess][c_guess] = 0
        res = backtrack(new_grid_white)
        if res is not None:
            return res

        return None

    # Execute Solver
    final_grid = backtrack(grid)

    if final_grid is None:
        return "No Solution"

    # Format Output: 'B' for Black, None for White as per requirements
    result = []
    for r in range(rows):
        row_data = []
        for c in range(cols):
            if final_grid[r][c] == 1:
                row_data.append('B')
            else:
                row_data.append(None)
        result.append(row_data)

    return result

