        """Calculate total bridges connected to island (r, c)."""
        count = 0
        for nr, nc in get_neighbors(r, c):
            key = tuple(sorted(((r, c), (nr, nc))))
            count += connections.get(key, 0)
        return count

    def is_connected():
        """Check if all islands are part of a single connected component."""
        if not islands: return True
        start = next(iter(islands))
        visited = {start}
        queue = [start]
        while queue:
            curr = queue.pop(0)
            for dr, dc in directions:
                nr, nc = curr[0] + dr, curr[1] + dc
                while 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) in islands:
                        key = tuple(sorted((curr, (nr, nc))))
                        if connections.get(key, 0) > 0:
                            if (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                        break
                    nr += dr
                    nc += dc
        return len(visited) == len(islands)

    def propagate_and_check(changes_stack):
        """
        Apply logical deductions to fill forced bridges.
        Returns False if a contradiction is found.
        Records changes in changes_stack for backtracking.
        """
        changed = True
        while changed:
            changed = False
            for (r, c), target in islands.items():
                current = get_current_count(r, c)
                remaining = target - current

                # Contradiction: Too many bridges
                if remaining < 0:
                    return False

                neighbors = get_neighbors(r, c)
                possible_dirs = []

                for nr, nc in neighbors:
                    key = tuple(sorted(((r, c), (nr, nc))))
                    curr_conn = connections.get(key, 0)

                    # Check if this direction can accept more bridges
                    if curr_conn < 2:
                        # Check if neighbor is full
                        neighbor_target = islands[(nr, nc)]
                        neighbor_current = get_current_count(nr, nc)
                        if neighbor_current < neighbor_target:
                            possible_dirs.append((nr, nc))

                num_possible = len(possible_dirs)

                # If island is satisfied, do nothing (implicitly blocks adding more)
                if remaining == 0:
                    continue

                # Contradiction: No places to put remaining bridges
                if num_possible == 0:
                    if remaining > 0:
                        return False
                    continue

                # Deduction 1: If remaining bridges == max possible (2 * num_possible), fill all with 2.
                # Example: Corner 4 (2 neighbors) -> needs 2 in each.
                if remaining == num_possible * 2:
                    for nr, nc in possible_dirs:
                        key = tuple(sorted(((r, c), (nr, nc))))
                        old_val = connections.get(key, 0)
                        if old_val < 2:
                            connections[key] = 2
                            changes_stack.append((key, old_val))
                            changed = True
                    continue

                # Deduction 2: If remaining bridges == num_possible, fill all with 1.
                # Example: Edge 3 (3 neighbors) -> needs 1 in each.
                if remaining == num_possible:
                    for nr, nc in possible_dirs:
                        key = tuple(sorted(((r, c), (nr, nc))))
                        old_val = connections.get(key, 0)
                        if old_val < 1:
                            connections[key] = 1
                            changes_stack.append((key, old_val))
                            changed = True
                    continue

        return True

    def solve_recursive():
        """Recursive backtracking solver with constraint propagation."""
        changes_stack = []

        # 1. Propagate constraints
        if not propagate_and_check(changes_stack):
            # Undo changes made in this frame
            for key, old_val in reversed(changes_stack):
                if old_val == 0:
                    if key in connections: del connections[key]
                else:
                    connections[key] = old_val
            return None

        # 2. Check if solved
        all_satisfied = True
        for (r, c), target in islands.items():
            if get_current_count(r, c) != target:
                all_satisfied = False
                break

        if all_satisfied:
            if is_connected():
                return dict(connections)
            else:
                # Satisfied numbers but not connected -> invalid
                for key, old_val in reversed(changes_stack):
                    if old_val == 0:
                        if key in connections: del connections[key]
                    else:
                        connections[key] = old_val
                return None

        # 3. Heuristic: Pick the most constrained island to branch on
        best_move = None
        min_options = float('inf')

        for (r, c), target in islands.items():
            current = get_current_count(r, c)
            if current < target:
                neighbors = get_neighbors(r, c)
                options = 0
                for nr, nc in neighbors:
                    key = tuple(sorted(((r, c), (nr, nc))))
                    curr_conn = connections.get(key, 0)
                    neighbor_target = islands[(nr, nc)]
                    neighbor_current = get_current_count(nr, nc)
                    if curr_conn < 2 and neighbor_current < neighbor_target:
                        options += 1

                if options < min_options:
                    min_options = options
                    best_move = (r, c)
                if min_options == 1: break # Found a very constrained move

        if best_move is None:
            # Should have been caught by all_satisfied or propagate
            for key, old_val in reversed(changes_stack):
                if old_val == 0:
                    if key in connections: del connections[key]
                else:
                    connections[key] = old_val
            return None

        r, c = best_move
        neighbors = get_neighbors(r, c)

        # Generate possible moves (add 1 bridge to a neighbor)
        moves = []
        for nr, nc in neighbors:
            key = tuple(sorted(((r, c), (nr, nc))))
            curr_conn = connections.get(key, 0)
            neighbor_target = islands[(nr, nc)]
            neighbor_current = get_current_count(nr, nc)

            if curr_conn < 2 and neighbor_current < neighbor_target:
                moves.append((key, curr_conn + 1))

        # Try moves
        for key, new_val in moves:
            old_val = connections.get(key, 0)
            connections[key] = new_val

            res = solve_recursive()
            if res is not None:
                return res

            # Backtrack
            if old_val == 0:
                if key in connections: del connections[key]
            else:
                connections[key] = old_val

        # If no moves worked, undo propagation changes and return None
        for key, old_val in reversed(changes_stack):
            if old_val == 0:
                if key in connections: del connections[key]
            else:
                connections[key] = old_val
        return None

    result = solve_recursive()
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
