import copy

def solve(observation):
    data = observation['data']
    if not data:
        return "No Solution"
    rows = len(data)
    cols = len(data[0])

    # Grid: -1 unknown, 0 white, 1 black
    grid = [[-1 for _ in range(cols)] for _ in range(rows)]

    # Store clues as (r, c) -> value
    clues = {}
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]

    def get_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append((nr, nc))
        return neighs

    def propagate(current_grid):
        # Returns True if consistent, False if contradiction found.
        # Modifies current_grid in place.
        changed = True
        while changed:
            changed = False
            for (r, c), val in clues.items():
                neighs = get_neighbors(r, c)
                blacks = 0
                unknowns = []
                for nr, nc in neighs:
                    cell_val = current_grid[nr][nc]
                    if cell_val == 1:
                        blacks += 1
                    elif cell_val == -1:
                        unknowns.append((nr, nc))

                # Rule 1: If blacks already equal value, rest must be white
                if blacks == val:
                    for ur, uc in unknowns:
                        if current_grid[ur][uc] == -1:
                            current_grid[ur][uc] = 0
                            changed = True
                # Rule 2: If blacks + unknowns equal value, rest must be black
                elif blacks + len(unknowns) == val:
                    for ur, uc in unknowns:
                        if current_grid[ur][uc] == -1:
                            current_grid[ur][uc] = 1
                            changed = True
                # Contradiction checks
                elif blacks > val:
                    return False
                elif blacks + len(unknowns) < val:
                    return False
        return True

    def is_solved(current_grid):
        for r in range(rows):
            for c in range(cols):
                if current_grid[r][c] == -1:
                    return False
        return True

    def get_best_guess(current_grid):
        # Heuristic: Find a clue that is most constrained (fewest unknowns relative to need)
        best_unknown_cell = None
        min_unknowns = float('inf')

        for (r, c), val in clues.items():
            neighs = get_neighbors(r, c)
            unknowns_count = 0
            blacks_count = 0
            unknown_coords = []

            for nr, nc in neighs:
                v = current_grid[nr][nc]
                if v == -1:
                    unknowns_count += 1
                    unknown_coords.append((nr, nc))
                elif v == 1:
                    blacks_count += 1

            needed = val - blacks_count

            # If 0 < needed < unknowns_count, this clue is a good candidate for branching
            if needed > 0 and unknowns_count > 0:
                if unknowns_count < min_unknowns:
                    min_unknowns = unknowns_count
                    best_unknown_cell = unknown_coords[0]

        if best_unknown_cell:
            return best_unknown_cell

        # Fallback: pick any unknown cell
        for r in range(rows):
            for c in range(cols):
                if current_grid[r][c] == -1:
                    return (r, c)
        return None

    def backtrack(current_grid):
        # 1. Propagate constraints
        if not propagate(current_grid):
            return None

        # 2. Check if solved
        if is_solved(current_grid):
            # Final validation
            for (r, c), val in clues.items():
                neighs = get_neighbors(r, c)
                count = sum(1 for nr, nc in neighs if current_grid[nr][nc] == 1)
                if count != val:
                    return None
            return current_grid

        # 3. Choose variable to assign
        guess_cell = get_best_guess(current_grid)
        if not guess_cell:
            return current_grid

        gr, gc = guess_cell

        # Try Black (1)
        grid_copy_1 = [row[:] for row in current_grid]
        grid_copy_1[gr][gc] = 1
        res = backtrack(grid_copy_1)
        if res:
            return res

        # Try White (0)
        grid_copy_0 = [row[:] for row in current_grid]
        grid_copy_0[gr][gc] = 0
        res = backtrack(grid_copy_0)
        if res:
            return res

        return None

    final_grid = backtrack(grid)

    if final_grid is None:
        return "No Solution"

    # Format output
    result = []
    for r in range(rows):
        row_res = []
        for c in range(cols):
            if final_grid[r][c] == 1:
                row_res.append('B')
            else:
                row_res.append(None)
        result.append(row_res)

    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
