OBSERVATION = {'data': [[None, None, 0, None, 1, None, None], [None, None, None, None, None, None, None], [2, None, None, None, None, None, 1], [None, None, None, None, None, None, None], [2, None, None, None, None, None, 0], [None, None, None, None, None, None, None], [None, None, 0, None, 0, None, None]]}

def solve(observation):
    data = observation['data']
    N = len(data)

    # Precompute walls and constraints
    # Walls are cells that are not None.
    # Constraints are walls with values 0-4. (-1 is a plain wall with no constraint).
    walls = set()
    constraints = {}

    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                walls.add((r, c))
                if val != -1:
                    constraints[(r, c)] = val

    # Helper: Get orthogonal neighbors (up, down, left, right)
    def get_adjacent(r, c):
        adj = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and (nr, nc) not in walls:
                adj.append((nr, nc))
        return adj

    # Helper: Get all cells visible from (r, c) in 4 directions (Line of Sight)
    # Stops at walls. Does not include (r, c) itself.
    def get_los(r, c):
        res = []
        # Up
        for i in range(r - 1, -1, -1):
            if (i, c) in walls: break
            res.append((i, c))
        # Down
        for i in range(r + 1, N):
            if (i, c) in walls: break
            res.append((i, c))
        # Left
        for j in range(c - 1, -1, -1):
            if (r, j) in walls: break
            res.append((r, j))
        # Right
        for j in range(c + 1, N):
            if (r, j) in walls: break
            res.append((r, j))
        return res

    # Recursive solver with constraint propagation
    def search(bulbs, invalid):
        changed = True
        while changed:
            changed = False

            # 1. Process Numbered Wall Constraints
            for (wr, wc), val in constraints.items():
                adj_bulbs = 0
                adj_avail = 0
                for nr, nc in get_adjacent(wr, wc):
                    if (nr, nc) in bulbs:
                        adj_bulbs += 1
                    elif (nr, nc) not in invalid:
                        adj_avail += 1

                # If too many bulbs adjacent, invalid state
                if adj_bulbs > val:
                    return None

                # If constraint satisfied, mark remaining neighbors as invalid (cannot be bulbs)
                if adj_bulbs == val:
                    for nr, nc in get_adjacent(wr, wc):
                        if (nr, nc) not in bulbs and (nr, nc) not in invalid:
                            invalid.add((nr, nc))
                            changed = True

                # If available spots equal remaining needed bulbs, place them
                if adj_avail == val and val > 0:
                    for nr, nc in get_adjacent(wr, wc):
                        if (nr, nc) not in bulbs and (nr, nc) not in invalid:
                            bulbs.add((nr, nc))
                            invalid.add((nr, nc))
                            # Mark line of sight as invalid (no other bulb can be there)
                            for vr, vc in get_los(nr, nc):
                                invalid.add((vr, vc))
                            changed = True

            # 2. Process Unlit White Cells (Human Logic: Every white cell must be lit)
            # Find a white cell that is not currently illuminated.
            unlit = None
            for r in range(N):
                for c in range(N):
                    if (r, c) not in walls:
                        # Check if covered by a bulb
                        covered = (r, c) in bulbs
                        if not covered:
                            for vr, vc in get_los(r, c):
                                if (vr, vc) in bulbs:
                                    covered = True
                                    break
                        if not covered:
                            unlit = (r, c)
                            break
                if unlit: break

            if unlit:
                ur, uc = unlit
                # Find all valid positions that can light this cell
                # Candidates: the cell itself, or any cell in its LOS
                cands = []
                if (ur, uc) not in invalid:
                    cands.append((ur, uc))
                for vr, vc in get_los(ur, uc):
                    if (vr, vc) not in invalid:
                        cands.append((vr, vc))

                # If no candidates, we cannot light this cell -> Dead end
                if not cands:
                    return None
                # If only one candidate, we MUST place a bulb there (Forced Move)
                if len(cands) == 1:
                    br, bc = cands[0]
                    bulbs.add((br, bc))
                    invalid.add((br, bc))
                    for vr, vc in get_los(br, bc):
                        invalid.add((vr, vc))
                    changed = True

        # Check if puzzle is solved
        # 1. All white cells must be illuminated
        solved = True
        for r in range(N):
            for c in range(N):
                if (r, c) not in walls:
                    covered = (r, c) in bulbs
                    if not covered:
                        for vr, vc in get_los(r, c):
                            if (vr, vc) in bulbs:
                                covered = True
                                break
                    if not covered:
                        solved = False
                        break
            if not solved: break

        if solved:
            # 2. Verify all constraints are exactly met (redundant check for safety)
            for (wr, wc), val in constraints.items():
                cnt = 0
                for nr, nc in get_adjacent(wr, wc):
                    if (nr, nc) in bulbs:
                        cnt += 1
                if cnt != val:
                    return None
            return bulbs

        # DFS Branching (Backtracking)
        # Heuristic: Pick an unlit cell with the fewest candidates (MRV)
        best_cell = None
        best_cands = None
        min_c = float('inf')

        for r in range(N):
            for c in range(N):
                if (r, c) not in walls:
                    covered = (r, c) in bulbs
                    if not covered:
                        for vr, vc in get_los(r, c):
                            if (vr, vc) in bulbs:
                                covered = True
                                break
                    if not covered:
                        cands = []
                        if (r, c) not in invalid:
                            cands.append((r, c))
                        for vr, vc in get_los(r, c):
                            if (vr, vc) not in invalid:
                                cands.append((vr, vc))

                        if len(cands) < min_c:
                            min_c = len(cands)
                            best_cell = (r, c)
                            best_cands = cands
                            if min_c == 1: break # Optimization
            if best_cell and min_c == 1: break

        if best_cell is None:
            # No unlit cells found, but constraints might not be met? 
            # (Should be caught by 'solved' check, but if not, return None)
            return None

        # Try placing a bulb in each candidate spot
        for br, bc in best_cands:
            nb = bulbs.copy()
            ni = invalid.copy()

            nb.add((br, bc))
            ni.add((br, bc))
            for vr, vc in get_los(br, bc):
                ni.add((vr, vc))

            res = search(nb, ni)
            if res is not None:
                return res

        return None

    # Initial State
    start_bulbs = set()
    start_invalid = set()

    # Pre-fill invalid spots from '0' constraints
    for (r, c), val in constraints.items():
        if val == 0:
            for nr, nc in get_adjacent(r, c):
                start_invalid.add((nr, nc))

    res_bulbs = search(start_bulbs, start_invalid)

    if res_bulbs is None:
        return "No Solution"

    # Format Output
    out = [[None]*N for _ in range(N)]
    for r, c in res_bulbs:
        out[r][c] = 'B'
    return out

