OBSERVATION = {'data': [[None, 1, None, None, None, None, 3], [2, None, None, 1, None, 2, None], [None, None, None, None, None, None, 3], [5, None, None, None, None, 3, None], [None, None, None, None, None, None, 2], [None, None, 1, None, None, 2, None], [4, None, None, 3, None, None, 2]]}

import sys

# Increase recursion depth to handle deeper search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    if not data:
        return "No Solution"

    rows = len(data)
    cols = len(data[0])

    # 1. Identify Islands
    islands = []
    island_map = {} # (r, c) -> index
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                island_map[(r, c)] = len(islands)
                islands.append({'r': r, 'c': c, 'val': data[r][c], 'id': len(islands)})

    num_islands = len(islands)
    if num_islands == 0:
        return {}

    # 2. Identify Edges (Potential Bridges)
    # An edge exists between two islands if they are in the same row/col 
    # and no other island is between them.
    edges = [] 
    # Edge structure: {'u': id1, 'v': id2, 'val': None}

    # Horizontal Edges
    for r in range(rows):
        row_islands = []
        for c in range(cols):
            if (r, c) in island_map:
                row_islands.append((c, island_map[(r, c)]))
        row_islands.sort()
        for i in range(len(row_islands) - 1):
            c1, id1 = row_islands[i]
            c2, id2 = row_islands[i+1]
            edges.append({'u': id1, 'v': id2, 'val': None})

    # Vertical Edges
    for c in range(cols):
        col_islands = []
        for r in range(rows):
            if (r, c) in island_map:
                col_islands.append((r, island_map[(r, c)]))
        col_islands.sort()
        for i in range(len(col_islands) - 1):
            r1, id1 = col_islands[i]
            r2, id2 = col_islands[i+1]
            edges.append({'u': id1, 'v': id2, 'val': None})

    num_edges = len(edges)

    # Adjacency list for islands: island_id -> list of edge_indices
    island_edges = [[] for _ in range(num_islands)]
    for i, e in enumerate(edges):
        island_edges[e['u']].append(i)
        island_edges[e['v']].append(i)

    # Initial max capacities (static constraints)
    # If an island has value 1, connected edges can be at most 1.
    initial_max_caps = [2] * num_edges
    for i, island in enumerate(islands):
        if island['val'] == 1:
            for e_idx in island_edges[i]:
                initial_max_caps[e_idx] = 1

    # Propagation Function (Constraint Propagation / Forward Checking)
    def propagate(edge_vals, max_caps):
        curr_vals = list(edge_vals)
        # max_caps is static, we use it as a base limit

        changed = True
        while changed:
            changed = False

            # Calculate remaining needs for all islands dynamically
            island_remaining = []
            for i, island in enumerate(islands):
                current_sum = 0
                for e_idx in island_edges[i]:
                    if curr_vals[e_idx] is not None:
                        current_sum += curr_vals[e_idx]
                rem = island['val'] - current_sum
                island_remaining.append(rem)
                if rem < 0:
                    return False, None

            # Check constraints and force moves
            for i, island in enumerate(islands):
                needed = island_remaining[i]
                unset_edges = [e_idx for e_idx in island_edges[i] if curr_vals[e_idx] is None]

                if not unset_edges:
                    if needed != 0:
                        return False, None
                    continue

                # Calculate max possible bridges from unset edges
                max_possible = 0
                effective_caps = {} 

                for e_idx in unset_edges:
                    u, v = edges[e_idx]['u'], edges[e_idx]['v']
                    other = v if u == i else u

                    # The capacity of an edge is limited by:
                    # 1. Static max (2, or 1 if neighbor is '1')
                    # 2. Current island's remaining need
                    # 3. Neighbor's remaining need
                    cap = min(max_caps[e_idx], needed, island_remaining[other])
                    effective_caps[e_idx] = cap
                    max_possible += cap

                # Pruning: If even taking max possible isn't enough
                if needed > max_possible:
                    return False, None

                # Force moves: If we MUST take all available capacity to satisfy need
                if needed == max_possible:
                    for e_idx in unset_edges:
                        cap = effective_caps[e_idx]
                        if curr_vals[e_idx] is None:
                            curr_vals[e_idx] = cap
                            changed = True

                # Force moves: If need is 0, all unset edges must be 0
                if needed == 0:
                    for e_idx in unset_edges:
                        if curr_vals[e_idx] is None:
                            curr_vals[e_idx] = 0
                            changed = True

        return True, curr_vals

    def check_connectivity(edge_vals):
        # Build graph of non-zero edges
        adj = [[] for _ in range(num_islands)]
        for i, e in enumerate(edges):
            if edge_vals[i] > 0:
                adj[e['u']].append(e['v'])
                adj[e['v']].append(e['u'])

        visited = set()
        stack = [0]
        visited.add(0)
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    stack.append(v)
        return len(visited) == num_islands

    def solve_recursive(edge_vals):
        # Propagate constraints
        success, prop_vals = propagate(edge_vals, initial_max_caps)
        if not success:
            return None

        # Check if solution is complete
        if all(v is not None for v in prop_vals):
            if check_connectivity(prop_vals):
                return prop_vals
            else:
                return None

        # Select next variable (edge) to branch on
        # Heuristic: Pick first unset edge
        best_edge_idx = -1
        for i, val in enumerate(prop_vals):
            if val is None:
                best_edge_idx = i
                break

        if best_edge_idx == -1:
            return None

        # Try values: 2, 1, 0 (descending order often finds solutions faster in bridge puzzles)
        limit = initial_max_caps[best_edge_idx]
        for val in range(limit, -1, -1):
            new_vals = list(prop_vals)
            new_vals[best_edge_idx] = val
            res = solve_recursive(new_vals)
            if res is not None:
                return res

        return None

    # Initial call
    initial_vals = [None] * num_edges
    final_vals = solve_recursive(initial_vals)

    if final_vals is None:
        return "No Solution"

    # Format output as dictionary {((r1, c1), (r2, c2)): count}
    ans = {}
    for i, e in enumerate(edges):
        if final_vals[i] > 0:
            u_id, v_id = e['u'], e['v']
            u_pos = (islands[u_id]['r'], islands[u_id]['c'])
            v_pos = (islands[v_id]['r'], islands[v_id]['c'])
            # Sort positions to ensure consistent key format
            if u_pos > v_pos:
                u_pos, v_pos = v_pos, u_pos
            ans[(u_pos, v_pos)] = final_vals[i]

    return ans

if __name__ == "__main__":
    print(solve(OBSERVATION))
