    # Coordinates are (row, col) floats.
    adj_set = set()
    for item in adj_list:
        adj_set.add((float(item[0]), float(item[1])))

    # Precompute neighbors and constraint types
    # neighbors[r][c] = list of (nr, nc, is_consecutive)
    neighbors = [[[] for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    # Midpoint
                    if dr != 0:
                        mid = (r + 0.5, c) if dr > 0 else (nr + 0.5, c)
                    else:
                        mid = (r, c + 0.5) if dc > 0 else (r, nc + 0.5)

                    is_consecutive = (mid in adj_set)
                    neighbors[r][c].append((nr, nc, is_consecutive))

    # Initialize domains and grid
    domains = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    grid = [[0]*N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                val = data[r][c]
                grid[r][c] = val
                domains[r][c] = {val}

    # AC-3 Propagation function
    # Returns False if inconsistency detected
    # Modifies grid and domains in place
    def ac3_full(grid, domains, initial_queue):
        queue = list(initial_queue)
        while queue:
            r, c = queue.pop(0)
            val = grid[r][c]

            # Check orthogonal neighbors (dots/no-dots)
            for nr, nc, is_consecutive in neighbors[r][c]:
                if grid[nr][nc] != 0:
                    n_val = grid[nr][nc]
                    if is_consecutive:
                        if abs(val - n_val) != 1: return False
                    else:
                        if abs(val - n_val) == 1: return False
                else:
                    # Reduce domain
                    old_len = len(domains[nr][nc])
                    if is_consecutive:
                        domains[nr][nc] = {v for v in domains[nr][nc] if abs(v - val) == 1}
                    else:
                        domains[nr][nc] = {v for v in domains[nr][nc] if abs(v - val) != 1}

                    if not domains[nr][nc]: return False
                    if len(domains[nr][nc]) == 1 and old_len > 1:
                        grid[nr][nc] = list(domains[nr][nc])[0]
                        queue.append((nr, nc))

            # Check row/col (Latin Square)
            # Row r
            for cc in range(N):
                if cc == c: continue
                if grid[r][cc] != 0:
                    if grid[r][cc] == val: return False
                else:
                    if val in domains[r][cc]:
                        domains[r][cc].remove(val)
                        if not domains[r][cc]: return False
                        if len(domains[r][cc]) == 1:
                            grid[r][cc] = list(domains[r][cc])[0]
                            queue.append((r, cc))
            # Col c
            for rr in range(N):
                if rr == r: continue
                if grid[rr][c] != 0:
                    if grid[rr][c] == val: return False
                else:
                    if val in domains[rr][c]:
                        domains[rr][c].remove(val)
                        if not domains[rr][c]: return False
                        if len(domains[rr][c]) == 1:
                            grid[rr][c] = list(domains[rr][c])[0]
                            queue.append((rr, c))
        return True

    # Initial propagation for pre-filled cells
    initial_queue = []
    for r in range(N):
        for c in range(N):
            if grid[r][c] != 0:
                initial_queue.append((r, c))

    if not ac3_full(grid, domains, initial_queue):
        return "No Solution"

    # Backtracking search with MRV
    def search(grid, domains):
        # Check solved
        is_solved = True
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            return grid

        # MRV: Minimum Remaining Values
        best_r, best_c = -1, -1
        min_size = N + 1
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    size = len(domains[r][c])
                    if size < min_size:
                        min_size = size
                        best_r, best_c = r, c

        if min_size == 0: return None

        r, c = best_r, best_c

        # Try values
        for val in sorted(list(domains[r][c])):
            new_grid = [row[:] for row in grid]
            new_domains = [ [d.copy() for d in row] for row in domains ]

            new_grid[r][c] = val
            new_domains[r][c] = {val}

            # Propagate from (r,c)
            if ac3_full(new_grid, new_domains, [(r, c)]):
                res = search(new_grid, new_domains)
                if res:
                    return res
        return None

    result = search(grid, domains)
    if result:
        return result
    return "No Solution"

