import sys

# Increase recursion depth just in case, though 7x7 is small
sys.setrecursionlimit(2000)

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']

    N = len(data)

    # Identify grid size from data
    if not data:
        return "No Solution"

    # Parse adjacent dots into a set of frozensets of coordinate pairs for O(1) lookup
    # Also build an adjacency list for quick access
    dot_pairs = set()
    adj_map = {} # (r, c) -> list of (nr, nc)

    for r in range(N):
        for c in range(N):
            adj_map[(r, c)] = []

    for pt in adjacent:
        r, c = pt
        # Determine orientation
        if r == int(r): # Horizontal dot: (r, c-0.5) and (r, c+0.5) -> cells (r, int(c-0.5)) and (r, int(c+0.5))
            # c is x.5. e.g., 3.5. Cells are (r, 3) and (r, 4)
            c1 = int(c - 0.5)
            c2 = int(c + 0.5)
            if 0 <= c1 < N and 0 <= c2 < N:
                p1 = (r, c1)
                p2 = (r, c2)
                dot_pairs.add(frozenset([p1, p2]))
                adj_map[p1].append(p2)
                adj_map[p2].append(p1)
        else: # Vertical dot: (r-0.5, c) and (r+0.5, c) -> cells (int(r-0.5), c) and (int(r+0.5), c)
            # r is y.5. e.g., 0.5. Cells are (0, c) and (1, c)
            r1 = int(r - 0.5)
            r2 = int(r + 0.5)
            if 0 <= r1 < N and 0 <= r2 < N:
                p1 = (r1, c)
                p2 = (r2, c)
                dot_pairs.add(frozenset([p1, p2]))
                adj_map[p1].append(p2)
                adj_map[p2].append(p1)

    # Initialize domains
    # domains[r][c] is a set of possible values
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Apply initial clues
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                domains[r][c] = {val}

    # Helper to get all orthogonal neighbors
    def get_neighbors(r, c):
        neighs = []
        if r > 0: neighs.append((r-1, c))
        if r < N-1: neighs.append((r+1, c))
        if c > 0: neighs.append((r, c-1))
        if c < N-1: neighs.append((r, c+1))
        return neighs

    # Constraint Propagation (AC-3 style logic but integrated into search for efficiency)
    # We will use a simple backtracking solver with forward checking and strong pruning

    def is_consistent(r, c, val, current_domains):
        # Check row and col uniqueness
        for k in range(N):
            if k != c:
                other_val_set = current_domains[r][k]
                if len(other_val_set) == 1 and val in other_val_set:
                    return False
            if k != r:
                other_val_set = current_domains[k][c]
                if len(other_val_set) == 1 and val in other_val_set:
                    return False

        # Check adjacency constraints
        neighbors = get_neighbors(r, c)
        for nr, nc in neighbors:
            is_dot = frozenset([(r, c), (nr, nc)]) in dot_pairs
            other_domain = current_domains[nr][nc]

            # If neighbor is fixed
            if len(other_domain) == 1:
                other_val = next(iter(other_domain))
                if is_dot:
                    if abs(val - other_val) != 1:
                        return False
                else:
                    if abs(val - other_val) == 1:
                        return False
            else:
                # If neighbor is not fixed, check if 'val' leaves any possibility for neighbor
                # This is a form of forward checking
                possible_for_neighbor = False
                for ov in other_domain:
                    if is_dot:
                        if abs(val - ov) == 1:
                            possible_for_neighbor = True
                            break
                    else:
                        if abs(val - ov) != 1:
                            possible_for_neighbor = True
                            break

                if not possible_for_neighbor:
                    return False

        return True

    def propagate(r, c, val, current_domains):
        # Returns a new domains state or None if contradiction
        # We modify a copy
        new_domains = [row[:] for row in current_domains]
        new_domains[r][c] = {val}

        queue = [(r, c)]

        while queue:
            curr_r, curr_c = queue.pop(0)
            curr_val_set = new_domains[curr_r][curr_c]
            if len(curr_val_set) != 1:
                continue # Should only process fixed cells
            curr_val = next(iter(curr_val_set))

            # Check all constraints involving (curr_r, curr_c)
            # 1. Row/Col
            for k in range(N):
                if k != curr_c:
                    # Row constraint
                    if curr_val in new_domains[curr_r][k]:
                        new_domains[curr_r][k].discard(curr_val)
                        if len(new_domains[curr_r][k]) == 0: return None
                        if len(new_domains[curr_r][k]) == 1:
                            queue.append((curr_r, k))

                if k != curr_r:
                    # Col constraint
                    if curr_val in new_domains[k][curr_c]:
                        new_domains[k][curr_c].discard(curr_val)
                        if len(new_domains[k][curr_c]) == 0: return None
                        if len(new_domains[k][curr_c]) == 1:
                            queue.append((k, curr_c))

            # 2. Adjacency
            neighbors = get_neighbors(curr_r, curr_c)
            for nr, nc in neighbors:
                is_dot = frozenset([(curr_r, curr_c), (nr, nc)]) in dot_pairs
                domain_nc = new_domains[nr][nc]

                to_remove = set()
                for v in domain_nc:
                    if is_dot:
                        if abs(v - curr_val) != 1:
                            to_remove.add(v)
                    else:
                        if abs(v - curr_val) == 1:
                            to_remove.add(v)

                if to_remove:
                    new_domains[nr][nc] -= to_remove
                    if len(new_domains[nr][nc]) == 0: return None
                    if len(new_domains[nr][nc]) == 1:
                        queue.append((nr, nc))

        return new_domains

    # Find cell with Minimum Remaining Values (MRV)
    def select_unassigned_variable(current_domains):
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(current_domains[r][c]) > 1:
                    if len(current_domains[r][c]) < min_len:
                        min_len = len(current_domains[r][c])
                        best_cell = (r, c)
        return best_cell

    def backtrack(current_domains):
        # Check if solved
        is_solved = True
        for r in range(N):
            for c in range(N):
                if len(current_domains[r][c]) != 1:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            return current_domains

        var = select_unassigned_variable(current_domains)
        if var is None:
            # All cells have 1 value, but we checked is_solved, so this shouldn't happen unless solved
            return current_domains

        r, c = var
        # Heuristic: try values that are most constrained? 
        # For now, just iterate sorted values
        possible_vals = sorted(list(current_domains[r][c]))

        for val in possible_vals:
            if is_consistent(r, c, val, current_domains):
                new_domains = propagate(r, c, val, current_domains)
                if new_domains is not None:
                    result = backtrack(new_domains)
                    if result is not None:
                        return result

        return None

    # Initial propagation for pre-filled cells
    # We can just call propagate for all pre-filled cells
    # But propagate expects a queue. Let's just start backtracking, 
    # but first run a global consistency check / initial propagation.

    # Actually, let's just create a queue of all fixed cells and run propagate logic once
    # Or simpler: just pass the initial domains to backtrack, 
    # but we need to ensure initial constraints are applied.
    # The `propagate` function handles a single assignment.
    # Let's do a loop to apply all initial clues.

    current_domains = domains
    fixed_cells = []
    for r in range(N):
        for c in range(N):
            if len(current_domains[r][c]) == 1:
                fixed_cells.append((r, c))

    # Apply all initial fixed cells
    # We need to be careful not to double propagate or conflict.
    # Since it's a valid puzzle, initial clues are consistent.
    # We can just call propagate sequentially.

    for r, c in fixed_cells:
        val = next(iter(current_domains[r][c]))
        # We need to update the domains in place or chain them
        # Let's just use the propagate function which returns new state
        # But propagate takes (r,c,val) and assumes that cell is being set NOW.
        # Since it's already set, we just need to propagate its effects.
        # Let's modify propagate slightly or just call it.
        # Actually, propagate sets new_domains[r][c] = {val}. It's already {val}.
        # So it works.
        current_domains = propagate(r, c, val, current_domains)
        if current_domains is None:
            return "No Solution"

    final_domains = backtrack(current_domains)

    if final_domains is None:
        return "No Solution"

    # Format output
    result_grid = []
    for r in range(N):
        row_vals = []
        for c in range(N):
            row_vals.append(next(iter(final_domains[r][c])))
        result_grid.append(row_vals)

    return result_grid

