def solve(observation):
    data = observation['data']
    N = len(data)

    # Grid representation:
    # None: White cell, unknown status (potential bulb)
    # -1: Black wall (no number)
    # 0..4: Black wall (with number)
    # 100: Bulb
    # -100: Invalid (White cell that cannot have a bulb, e.g., lit by another bulb or adjacent to 0)

    grid = [row[:] for row in data]

    def get_neighbors(r, c):
        res = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                res.append((nr, nc))
        return res

    def propagate(g):
        changed = True
        while changed:
            changed = False

            # 1. Process Numbered Walls (Constraint Propagation)
            for r in range(N):
                for c in range(N):
                    val = g[r][c]
                    if isinstance(val, int) and val >= 0:
                        bulbs = 0
                        available = []
                        for nr, nc in get_neighbors(r, c):
                            if g[nr][nc] == 100:
                                bulbs += 1
                            elif g[nr][nc] is None:
                                available.append((nr, nc))

                        if bulbs > val:
                            return False # Invalid state: Too many bulbs
                        if bulbs == val:
                            # Satisfied: Mark all other neighbors as invalid
                            for nr, nc in available:
                                g[nr][nc] = -100
                                changed = True
                        elif len(available) + bulbs == val:
                            # Forced: Place bulbs in all available neighbors
                            for nr, nc in available:
                                g[nr][nc] = 100
                                changed = True

            # 2. Process Bulbs (Line of Sight & Conflicts)
            bulbs_pos = [(r, c) for r in range(N) for c in range(N) if g[r][c] == 100]

            for br, bc in bulbs_pos:
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    r, c = br + dr, bc + dc
                    while 0 <= r < N and 0 <= c < N:
                        cell = g[r][c]
                        # Check for Wall or Bulb
                        if isinstance(cell, int) and cell >= -1:
                            if cell == 100:
                                return False # Conflict: Bulb sees Bulb
                            break # Hit Wall
                        if cell is None:
                            g[r][c] = -100 # Mark as lit/invalid
                            changed = True
                        # If -100, light passes through (it's an empty white cell)
                        r += dr
                        c += dc

            # 3. Process Unlit Cells (Coverage Rule)
            # Find cells that are still None (White, not lit, not invalid)
            # These MUST be lit by something.
            unlit_cells = [(r, c) for r in range(N) for c in range(N) if g[r][c] is None]

            for r, c in unlit_cells:
                candidates = []
                # Check Row Left
                for j in range(c-1, -1, -1):
                    cell = g[r][j]
                    if isinstance(cell, int) and cell >= -1: break
                    if cell is None: candidates.append((r, j))
                # Check Row Right
                for j in range(c+1, N):
                    cell = g[r][j]
                    if isinstance(cell, int) and cell >= -1: break
                    if cell is None: candidates.append((r, j))
                # Check Col Up
                for i in range(r-1, -1, -1):
                    cell = g[i][c]
                    if isinstance(cell, int) and cell >= -1: break
                    if cell is None: candidates.append((i, c))
                # Check Col Down
                for i in range(r+1, N):
                    cell = g[i][c]
                    if isinstance(cell, int) and cell >= -1: break
                    if cell is None: candidates.append((i, c))

                if len(candidates) == 0:
                    return False # Cannot light this cell -> Invalid
                if len(candidates) == 1:
                    pr, pc = candidates[0]
                    g[pr][pc] = 100
                    changed = True

        return True

    def is_solved(g):
        # Check all walls satisfied
        for r in range(N):
            for c in range(N):
                val = g[r][c]
                if isinstance(val, int) and val >= 0:
                    bulbs = 0
                    for nr, nc in get_neighbors(r, c):
                        if g[nr][nc] == 100:
                            bulbs += 1
                    if bulbs != val:
                        return False
        # Check all white cells lit (no None left)
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    return False
        return True

    def search(g):
        if not propagate(g):
            return None

        if is_solved(g):
            return g

        # Heuristic: Pick first None cell (could be optimized by picking most constrained)
        r, c = -1, -1
        for i in range(N):
            for j in range(N):
                if g[i][j] is None:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1: return None

        # Branch 1: Place Bulb
        g1 = [row[:] for row in g]
        g1[r][c] = 100
        res = search(g1)
        if res: return res

        # Branch 2: Mark Invalid (No Bulb)
        g2 = [row[:] for row in g]
        g2[r][c] = -100
        res = search(g2)
        if res: return res

        return None

    final_grid = search(grid)

    if final_grid is None:
        return "No Solution"

    result = [[None for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if final_grid[r][c] == 100:
                result[r][c] = 'B'
    return result

