                if g[r][c] and g[r+1][c] and g[r+2][c]:
                    if g[r][c] == g[r+1][c] == g[r+2][c]:
                        return False

        # 2. Counts do not exceed HALF
        for r in range(N):
            b = sum(1 for x in g[r] if x == 'B')
            w = sum(1 for x in g[r] if x == 'W')
            if b > HALF or w > HALF:
                return False
        for c in range(N):
            col = get_col(g, c)
            b = sum(1 for x in col if x == 'B')
            w = sum(1 for x in col if x == 'W')
            if b > HALF or w > HALF:
                return False

        # 3. Uniqueness (Full rows/cols must be unique)
        rows = [tuple(row) for row in g]
        full_rows = [r for r in rows if None not in r]
        if len(full_rows) != len(set(full_rows)):
            return False

        cols = [tuple(get_col(g, c)) for c in range(N)]
        full_cols = [c for c in cols if None not in c]
        if len(full_cols) != len(set(full_cols)):
            return False

        return True

    # Propagate constraints until fixpoint
    def propagate(g):
        changed = True
        while changed:
            changed = False

            # Rule 1: Triples (X X _ -> X X notX, etc.)
            # Rows
            for r in range(N):
                for c in range(N-2):
                    # Pattern B B _ or W W _
                    if g[r][c] and g[r][c+1] and not g[r][c+2]:
                        if g[r][c] == g[r][c+1]:
                            val = 'W' if g[r][c] == 'B' else 'B'
                            if g[r][c+2] != val:
                                g[r][c+2] = val
                                changed = True
                    # Pattern B _ B or W _ W
                    if g[r][c] and not g[r][c+1] and g[r][c+2]:
                        if g[r][c] == g[r][c+2]:
                            val = 'W' if g[r][c] == 'B' else 'B'
                            if g[r][c+1] != val:
                                g[r][c+1] = val
                                changed = True
                    # Pattern _ B B or _ W W
                    if not g[r][c] and g[r][c+1] and g[r][c+2]:
                        if g[r][c+1] == g[r][c+2]:
                            val = 'W' if g[r][c+1] == 'B' else 'B'
                            if g[r][c] != val:
                                g[r][c] = val
                                changed = True

            # Cols
            for c in range(N):
                for r in range(N-2):
                    if g[r][c] and g[r+1][c] and not g[r+2][c]:
                        if g[r][c] == g[r+1][c]:
                            val = 'W' if g[r][c] == 'B' else 'B'
                            if g[r+2][c] != val:
                                g[r+2][c] = val
                                changed = True
                    if g[r][c] and not g[r+1][c] and g[r+2][c]:
                        if g[r][c] == g[r+2][c]:
                            val = 'W' if g[r][c] == 'B' else 'B'
                            if g[r+1][c] != val:
                                g[r+1][c] = val
                                changed = True
                    if not g[r][c] and g[r+1][c] and g[r+2][c]:
                        if g[r+1][c] == g[r+2][c]:
                            val = 'W' if g[r+1][c] == 'B' else 'B'
                            if g[r][c] != val:
                                g[r][c] = val
                                changed = True

            # Rule 2: Counts (If count == HALF, rest are opposite)
            for r in range(N):
                b = sum(1 for x in g[r] if x == 'B')
                w = sum(1 for x in g[r] if x == 'W')
                if b == HALF:
                    for c in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                if w == HALF:
                    for c in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            for c in range(N):
                col = get_col(g, c)
                b = sum(1 for x in col if x == 'B')
                w = sum(1 for x in col if x == 'W')
                if b == HALF:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                if w == HALF:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            # Rule 3: Uniqueness
            # If Row A is full, and Row B has 1 empty cell, and Row B matches Row A elsewhere,
            # then Row B's empty cell must be different from Row A's corresponding cell.

            # Rows
            for r1 in range(N):
                row1 = g[r1]
                if None in row1: continue # r1 must be full
                for r2 in range(N):
                    if r1 == r2: continue
                    row2 = g[r2]
                    empty_indices = [c for c, val in enumerate(row2) if val is None]
                    if len(empty_indices) == 1:
                        k = empty_indices[0]
                        match = True
                        for c in range(N):
                            if c == k: continue
                            if row2[c] != row1[c]:
                                match = False
                                break
                        if match:
                            # Force opposite
                            val = 'W' if row1[k] == 'B' else 'B'
                            if g[r2][k] != val:
                                g[r2][k] = val
                                changed = True

            # Cols
            for c1 in range(N):
                col1 = get_col(g, c1)
                if None in col1: continue
                for c2 in range(N):
                    if c1 == c2: continue
                    col2 = get_col(g, c2)
                    empty_indices = [r for r, val in enumerate(col2) if val is None]
                    if len(empty_indices) == 1:
                        k = empty_indices[0]
                        match = True
                        for r in range(N):
                            if r == k: continue
                            if col2[r] != col1[r]:
                                match = False
                                break
                        if match:
                            val = 'W' if col1[k] == 'B' else 'B'
                            if g[k][c2] != val:
                                g[k][c2] = val
                                changed = True

        return is_valid_state(g)

    def solve_recursive(g):
        # Apply propagation
        if not propagate(g):
            return None

        # Check if solved
        is_full = True
        for r in range(N):
            if None in g[r]:
                is_full = False
                break

        if is_full:
            return g

        # Pick next empty cell (simple heuristic: first empty)
        r_pick, c_pick = -1, -1
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    r_pick, c_pick = r, c
                    break
            if r_pick != -1: break

        # Save state for backtracking
        g_snapshot = [row[:] for row in g]

        # Try 'B'
        g[r_pick][c_pick] = 'B'
        res = solve_recursive(g)
        if res:
            return res

        # Restore state
        for r in range(N):
            for c in range(N):
                g[r][c] = g_snapshot[r][c]

        # Try 'W'
        g[r_pick][c_pick] = 'W'
        res = solve_recursive(g)
        if res:
            return res

        return None

    result = solve_recursive(grid)
    return result

