        for i in range(len(cols_with_islands) - 1):
            c1, c2 = cols_with_islands[i], cols_with_islands[i+1]
            possible_bridges.append(((r, c1), (r, c2)))
    # Vertical bridges
    for c in range(cols):
        rows_with_islands = [r for r in range(rows) if grid[r][c] is not None]
        for i in range(len(rows_with_islands) - 1):
            r1, r2 = rows_with_islands[i], rows_with_islands[i+1]
            possible_bridges.append(((r1, c), (r2, c)))

    # Map each island to the indices of bridges connected to it
    island_to_bridges = { (r,c): [] for r,c,_ in islands }
    for idx, (p1, p2) in enumerate(possible_bridges):
        island_to_bridges[p1].append(idx)
        island_to_bridges[p2].append(idx)

    # Domains for each bridge: possible number of bridges (0, 1, 2)
    # Using a list of sets for constraint propagation
    domains = [ {0, 1, 2} for _ in range(len(possible_bridges)) ]

    def propagate(doms):
        """
        Applies constraint propagation rules.
        Returns False if a contradiction is found, True otherwise.
        Modifies doms in place.
        """
        changed = True
        while changed:
            changed = False
            for r, c, val in islands:
                b_indices = island_to_bridges[(r,c)]
                if not b_indices:
                    if val != 0: return False # Island needs bridges but has none
                    continue

                current_doms = [doms[i] for i in b_indices]

                # Check for empty domains (contradiction)
                for d in current_doms:
                    if not d: return False

                min_sum = sum(min(d) for d in current_doms)
                max_sum = sum(max(d) for d in current_doms)

                # Rule 1: Value must be within [min_sum, max_sum]
                if val < min_sum or val > max_sum:
                    return False

                # Rule 2: If val == max_sum, all bridges must take their maximum possible value
                if val == max_sum:
                    for i, b_idx in enumerate(b_indices):
                        d = current_doms[i]
                        m = max(d)
                        if doms[b_idx] != {m}:
                            doms[b_idx] = {m}
                            changed = True

                # Rule 3: If val == min_sum, all bridges must take their minimum possible value
                if val == min_sum:
                    for i, b_idx in enumerate(b_indices):
                        d = current_doms[i]
                        m = min(d)
                        if doms[b_idx] != {m}:
                            doms[b_idx] = {m}
                            changed = True

                # Rule 4: If island value is 1, no bridge can have 2 connections
                if val == 1:
                    for b_idx in b_indices:
                        if 2 in doms[b_idx]:
                            doms[b_idx].discard(2)
                            changed = True
                            if not doms[b_idx]: return False

        return True

    def is_complete(doms):
        """Checks if all domains are singletons."""
        for d in doms:
            if len(d) != 1:
                return False
        return True

    def check_connectivity(doms):
        """Checks if all islands are connected via bridges > 0."""
        adj = { (r,c): [] for r,c,_ in islands }
        for idx, d in enumerate(doms):
            val = list(d)[0]
            if val > 0:
                p1, p2 = possible_bridges[idx]
                adj[p1].append(p2)
                adj[p2].append(p1)

        if not islands: return True
        start = islands[0][:2]
        visited = set([start])
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
        return len(visited) == len(islands)

    def search(doms):
        """Backtracking search with constraint propagation."""
        if not propagate(doms):
            return None

        if is_complete(doms):
            if check_connectivity(doms):
                return doms
            else:
                return None

        # Heuristic: Pick the bridge with the smallest domain size > 1 (Most Constrained Variable)
        best_idx = -1
        min_size = 4

        for i, d in enumerate(doms):
            if len(d) > 1:
                if len(d) < min_size:
                    min_size = len(d)
                    best_idx = i

        if best_idx == -1:
            return None 

        # Try values in descending order (heuristic: more bridges often constrain faster)
        original_dom = doms[best_idx]
        for val in sorted(list(original_dom), reverse=True):
            new_doms = [d.copy() for d in doms]
            new_doms[best_idx] = {val}
            res = search(new_doms)
            if res:
                return res

        return None

    final_doms = search(domains)

    if final_doms is None:
        return "No Solution"

    result = {}
    for idx, d in enumerate(final_doms):
        val = list(d)[0]
        if val > 0:
            result[possible_bridges[idx]] = val

    return result

