    def propagate():
        while queue:
            r, c = queue.pop(0)
            if not domains[r][c]: return False # Domain wiped out
            val = list(domains[r][c])[0]

            # 1. Row/Col Constraints (Latin Square)
            for i in range(N):
                if i != c: # Same row
                    if val in domains[r][i]:
                        domains[r][i].discard(val)
                        if not domains[r][i]: return False
                        if len(domains[r][i]) == 1:
                            queue.append((r, i))
                if i != r: # Same col
                    if val in domains[i][c]:
                        domains[i][c].discard(val)
                        if not domains[i][c]: return False
                        if len(domains[i][c]) == 1:
