OBSERVATION = {'data': [[None, 2, None, 2, None, 5, None], [4, 5, 4, None, 6, 6, 3], [3, None, 5, None, 6, 6, None], [3, None, None, None, 5, 4, None], [3, None, 6, None, 5, 4, 4], [5, None, 6, None, 4, None, None], [None, 4, None, None, None, 3, 2]]}

def solve(observation):
    # Extract grid dimensions and data
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    # Internal representation: -1 = Unknown, 0 = White, 1 = Black
    grid = [[-1 for _ in range(cols)] for _ in range(rows)]

    # Store constraints: (row, col) -> target_value
    numbers = {}
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                numbers[(r, c)] = data[r][c]

    # Precompute neighbors for every cell (3x3 area centered at cell)
    neighbors_map = {}
    for r in range(rows):
        for c in range(cols):
            neighs = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighs.append((nr, nc))
            neighbors_map[(r, c)] = neighs

    def propagate(grid_state):
        """
        Applies logical deductions based on numbered cells (Constraint Propagation).
        Returns (success, modified_grid).
        If a contradiction is found, success is False.
        """
        changed = True
        while changed:
            changed = False
            for (r, c), target in numbers.items():
                neighs = neighbors_map[(r, c)]
                current_blacks = 0
                unknowns = []

                for nr, nc in neighs:
                    val = grid_state[nr][nc]
                    if val == 1:
                        current_blacks += 1
                    elif val == -1:
                        unknowns.append((nr, nc))

                needed = target - current_blacks

                # Pruning: Constraint violation (too many blacks or impossible to reach target)
                if needed < 0 or needed > len(unknowns):
                    return False, None

                # Deduction 1: If needed count equals unknown count, all unknowns must be Black
                if needed == len(unknowns) and needed > 0:
                    for nr, nc in unknowns:
                        if grid_state[nr][nc] == -1:
                            grid_state[nr][nc] = 1
                            changed = True

                # Deduction 2: If needed count is 0, all unknowns must be White
                elif needed == 0:
                    for nr, nc in unknowns:
                        if grid_state[nr][nc] == -1:
                            grid_state[nr][nc] = 0
                            changed = True
        return True, grid_state

    def is_complete(grid_state):
        for r in range(rows):
            for c in range(cols):
                if grid_state[r][c] == -1:
                    return False
        return True

    def is_valid_solution(grid_state):
        for (r, c), target in numbers.items():
            neighs = neighbors_map[(r, c)]
            count = sum(1 for nr, nc in neighs if grid_state[nr][nc] == 1)
            if count != target:
                return False
        return True

    def get_heuristic_cell(grid_state):
        """
        MRV Heuristic (Minimum Remaining Values):
        Selects an unknown cell adjacent to the most constrained numbered cell.
        """
        best_cell = None
        min_unknowns = float('inf')

        for (r, c), target in numbers.items():
            neighs = neighbors_map[(r, c)]
            unknown_cells = []
            for nr, nc in neighs:
                if grid_state[nr][nc] == -1:
                    unknown_cells.append((nr, nc))

            # Prioritize numbered cells with fewest unknown neighbors (tightest constraint)
            if 0 < len(unknown_cells) < min_unknowns:
                min_unknowns = len(unknown_cells)
                best_cell = unknown_cells[0]

        # Fallback: pick the first unknown cell in the grid
        if best_cell is None:
            for r in range(rows):
                for c in range(cols):
                    if grid_state[r][c] == -1:
                        return (r, c)
        return best_cell

    def backtrack(grid_state):
        # 1. Propagate constraints (Forward Checking)
        success, updated_grid = propagate(grid_state)
        if not success:
            return None

        # 2. Check if solved
        if is_complete(updated_grid):
            if is_valid_solution(updated_grid):
                return updated_grid
            return None

        # 3. Select variable using heuristic
        cell = get_heuristic_cell(updated_grid)
        if cell is None:
            return None

        r, c = cell

        # 4. Branch (Try Black then White)
        # Try Black (1)
        new_grid_black = [row[:] for row in updated_grid]
        new_grid_black[r][c] = 1
        res = backtrack(new_grid_black)
        if res:
            return res

        # Try White (0)
        new_grid_white = [row[:] for row in updated_grid]
        new_grid_white[r][c] = 0
        res = backtrack(new_grid_white)
        if res:
            return res

        return None

    # Start solving
    final_grid = backtrack(grid)

    if final_grid is None:
        return "No Solution"

    # Format output: 'B' for Black, None for White
    result_grid = []
    for r in range(rows):
        row_res = []
        for c in range(cols):
            if final_grid[r][c] == 1:
                row_res.append('B')
            else:
                row_res.append(None)
        result_grid.append(row_res)

    return str(result_grid)

