                if grid[i].count('W') != half: return False
                col = [grid[r][i] for r in range(N)]
                if col.count('B') != half: return False
                if col.count('W') != half: return False

            for i in range(N):
                for j in range(N - 2):
                    if grid[i][j] == grid[i][j+1] == grid[i][j+2]: return False
                    if grid[j][i] == grid[j+1][i] == grid[j+2][i]: return False

            rows = [tuple(r) for r in grid]
            if len(rows) != len(set(rows)): return False
            cols = [tuple([grid[r][c] for r in range(N)]) for c in range(N)]
            if len(cols) != len(set(cols)): return False
            return True

        def solve_bt(self, grid):
            if not self.propagate(grid):
                return None

            complete = True
            best_r, best_c = -1, -1
            max_score = -1

            for r in range(self.N):
                for c in range(self.N):
                    if grid[r][c] is None:
                        complete = False
                        filled_r = self.N - grid[r].count(None)
                        col_vals = [grid[k][c] for k in range(self.N)]
                        filled_c = self.N - col_vals.count(None)
                        score = filled_r + filled_c
                        if score > max_score:
                            max_score = score
                            best_r, best_c = r, c

            if complete:
                if self.is_valid_final(grid):
                    return grid
                else:
                    return None

            r, c = best_r, best_c

            grid_b = [row[:] for row in grid]
            grid_b[r][c] = 'B'
            res = self.solve_bt(grid_b)
            if res: return res

            grid_w = [row[:] for row in grid]
            grid_w[r][c] = 'W'
            res = self.solve_bt(grid_w)
            if res: return res

            return None

    solver = Solver(N)
    result = solver.solve_bt(grid)
    if result:
        return result
    return "No Solution"

