import sys

# Constants for cell states
UNKNOWN = 0
BLACK = 1
WHITE = -1

def solve(observation):
    grid_data = observation['data']
    rows = len(grid_data)
    cols = len(grid_data[0]) if rows > 0 else 0

    # State grid: 0=Unknown, 1=Black, -1=White
    state = [[UNKNOWN for _ in range(cols)] for _ in range(rows)]

    # Pre-calculate neighbors for every cell to speed up lookups
    # neighbors[r][c] is a list of (nr, nc) tuples
    neighbors = [[[] for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors[r][c].append((nr, nc))

    # List of constraints: (r, c, target_value)
    constraints = []
    for r in range(rows):
        for c in range(cols):
            val = grid_data[r][c]
            if val is not None:
                constraints.append((r, c, val))

    def get_constraint_stats(r, c, target):
        """Returns (current_black_count, unknown_count) for the neighborhood of (r,c)"""
        black_count = 0
        unknown_count = 0
        for nr, nc in neighbors[r][c]:
            s = state[nr][nc]
            if s == BLACK:
                black_count += 1
            elif s == UNKNOWN:
                unknown_count += 1
        return black_count, unknown_count

    def propagate():
        """Applies logical deduction rules until no more changes occur."""
        changed = True
        while changed:
            changed = False
            for r, c, target in constraints:
                black_count, unknown_count = get_constraint_stats(r, c, target)

                # Rule 1: If we have enough blacks, rest must be white
                if black_count == target:
                    for nr, nc in neighbors[r][c]:
                        if state[nr][nc] == UNKNOWN:
                            state[nr][nc] = WHITE
                            changed = True

                # Rule 2: If we need all remaining unknowns to be black to reach target
                elif black_count + unknown_count == target:
                    for nr, nc in neighbors[r][c]:
                        if state[nr][nc] == UNKNOWN:
                            state[nr][nc] = BLACK
                            changed = True
        return True

    def is_consistent():
        """Checks if current state violates any constraints."""
        for r, c, target in constraints:
            black_count, unknown_count = get_constraint_stats(r, c, target)
            # If we already have too many blacks, it's invalid
            if black_count > target:
                return False
            # If even with all unknowns being black we can't reach target, it's invalid
            if black_count + unknown_count < target:
                return False
        return True

    def solve_recursive():
        # 1. Propagate constraints
        propagate()

        # 2. Check consistency
        if not is_consistent():
            return False

        # 3. Check if solved (no unknowns left)
        # We only need to check cells that are part of any constraint neighborhood? 
        # Actually, the problem implies we need to color the whole grid or at least determine the state.
        # However, unnumbered cells far away might not be constrained. 
        # But usually in these puzzles, we just need a valid configuration.
        # Let's assume we need to fill everything or at least satisfy all numbers.
        # To be safe, let's look for any UNKNOWN cell.

        unknown_cells = []
        for r in range(rows):
            for c in range(cols):
                if state[r][c] == UNKNOWN:
                    unknown_cells.append((r, c))

        if not unknown_cells:
            return True # Solved

        # Heuristic: Pick the unknown cell that is part of the most "tight" constraints
        # A tight constraint is one where (target - current_black) is small.
        best_cell = None
        best_score = -1

        for r, c in unknown_cells:
            score = 0
            # Check all constraints that cover this cell
            # A constraint at (cr, cc) covers (r, c) if (r, c) is in neighbors[cr][cc]
            # Instead of iterating all constraints, we can iterate neighbors of (r,c) and check if they have numbers
            # Wait, the constraint is defined BY the number. So we look at neighbors of (r,c) to see if THEY are numbered cells?
            # No. The rule is: "Each numbered cell equals the count...".
            # So if cell (r,c) is in the 3x3 of a numbered cell (nr, nc), then (nr, nc) constrains (r,c).
            # So we look at neighbors of (r,c). If a neighbor (nr, nc) has a number, that number constrains (r,c).

            for nr, nc in neighbors[r][c]:
                val = grid_data[nr][nc]
                if val is not None:
                    # This neighbor imposes a constraint
                    b_count, u_count = get_constraint_stats(nr, nc, val)
                    needed = val - b_count
                    # Higher score if this cell is critical (needed is high relative to unknowns)
                    # Or simply count how many constraints touch it.
                    score += 1 
                    # Bonus for tight constraints
                    if needed == u_count: # Must be black
                        score += 10
                    if needed == 0: # Must be white
                        score += 10

            if score > best_score:
                best_score = score
                best_cell = (r, c)

        if best_cell is None:
            # Fallback to first unknown
            best_cell = unknown_cells[0]

        r, c = best_cell

        # Try Black
        state[r][c] = BLACK
        if solve_recursive():
            return True

        # Backtrack
        state[r][c] = WHITE
        if solve_recursive():
            return True

        # Backtrack
        state[r][c] = UNKNOWN
        return False

    if solve_recursive():
        # Format output
        result_grid = []
        for r in range(rows):
            row_res = []
            for c in range(cols):
                if state[r][c] == BLACK:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result_grid.append(row_res)
        return result_grid
    else:
        return "No Solution"

