def solve(observation):
    # Parse grid dimensions from the input data
    grid_data = observation['data']
    R = len(grid_data)
    C = len(grid_data[0])

    # State representation: 0 = White, 1 = Black, 2 = Unknown
    # Initialize all cells as Unknown (2)
    state = [[2 for _ in range(C)] for _ in range(R)]

    # Helper to get 3x3 neighborhood coordinates including the cell itself
    def get_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    neighs.append((nr, nc))
        return neighs

    # Pre-identify numbered cells and their target values
    numbered_cells = []
    for r in range(R):
        for c in range(C):
            if grid_data[r][c] is not None:
                numbered_cells.append((r, c, grid_data[r][c]))

    # Constraint Propagation Function (Human-like Deduction)
    # Applies logical rules until no more changes can be made (Fixed Point)
    # Returns False if a contradiction is found, True otherwise.
    # Modifies current_state in place.
    def propagate(current_state):
        changed = True
        while changed:
            changed = False
            for r, c, val in numbered_cells:
                neighs = get_neighbors(r, c)
                blacks = 0
                unknowns = 0
                # Count current blacks and unknowns in the neighborhood
                for nr, nc in neighs:
                    s = current_state[nr][nc]
                    if s == 1: blacks += 1
                    elif s == 2: unknowns += 1

                # Contradiction check 1: Too many blacks already placed
                if blacks > val: return False
                # Contradiction check 2: Not enough space left to reach the target value
                if blacks + unknowns < val: return False

                # Deduction Rule 1: If remaining unknowns MUST all be black to reach val
                # (Current Blacks + Unknowns == Target) -> All Unknowns become Black
                if blacks + unknowns == val:
                    for nr, nc in neighs:
                        if current_state[nr][nc] == 2:
                            current_state[nr][nc] = 1
                            changed = True

                # Deduction Rule 2: If we already have enough blacks, rest MUST be white
                # (Current Blacks == Target) -> All Unknowns become White
                if blacks == val:
                    for nr, nc in neighs:
                        if current_state[nr][nc] == 2:
                            current_state[nr][nc] = 0
                            changed = True
        return True

    # Check if grid is fully solved (no Unknowns left)
    def is_solved(current_state):
        for r in range(R):
            for c in range(C):
                if current_state[r][c] == 2:
                    return False
        return True

    # DFS Solver with Backtracking and Heuristics
    def solve_dfs(current_state):
        # Apply logic propagation first to prune search space
        if not propagate(current_state):
            return None

        if is_solved(current_state):
            return current_state

        # Heuristic: Choose the unknown cell that is part of the "tightest" constraint.
        # We look for a numbered cell with the minimum number of unknown neighbors (>0).
        # This mimics human strategy of solving the most constrained areas first.
        best_candidates = []
        min_unk = float('inf')

        for r, c, val in numbered_cells:
            neighs = get_neighbors(r, c)
            unk_locs = [ (nr, nc) for nr, nc in neighs if current_state[nr][nc] == 2 ]
            count = len(unk_locs)
            # We want tight constraints (small count) but must have unknowns to branch on
            if 0 < count < min_unk:
                min_unk = count
                best_candidates = unk_locs

        # Fallback: If no numbered cells have unknowns (e.g., isolated regions), pick any unknown
        if not best_candidates:
            for r in range(R):
                for c in range(C):
                    if current_state[r][c] == 2:
                        best_candidates = [(r, c)]
                        break
                if best_candidates: break

        if not best_candidates:
            return None 

        # Pick the first candidate from the tightest constraint group
        r_guess, c_guess = best_candidates[0]

        # Branch 1: Try Black (1)
        new_state_black = [row[:] for row in current_state]
        new_state_black[r_guess][c_guess] = 1
        res = solve_dfs(new_state_black)
        if res: return res

        # Branch 2: Try White (0)
        new_state_white = [row[:] for row in current_state]
        new_state_white[r_guess][c_guess] = 0
        res = solve_dfs(new_state_white)
        if res: return res

        return None

    final_state = solve_dfs(state)

    if final_state is None:
        return "No Solution"

    # Format output: 'B' for Black, None for White
    output_grid = []
    for r in range(R):
        row_out = []
        for c in range(C):
            if final_state[r][c] == 1:
                row_out.append('B')
            else:
                row_out.append(None)
        output_grid.append(row_out)

    return output_grid

