            # 1. Latin Square Constraints & Fixed Values
            for r in range(N):
                for c in range(N):
                    if grid[r][c] != 0:
                        val = grid[r][c]
                        # Row
                        for cc in range(N):
                            if cc != c and val in domains[r][cc]:
                                domains[r][cc].discard(val)
                                changed = True
                        # Col
                        for rr in range(N):
                            if rr != r and val in domains[rr][c]:
                                domains[rr][c].discard(val)
                                changed = True

                    # If domain becomes singleton, update grid
                    if grid[r][c] == 0 and len(domains[r][c]) == 1:
                        grid[r][c] = list(domains[r][c])[0]
                        changed = True

                    # If domain empty, failure
                    if len(domains[r][c]) == 0:
                        return False

            # 2. Adjacency Constraints (Dot / No Dot)
            for r in range(N):
                for c in range(N):
                    curr_domain = domains[r][c]
                    if len(curr_domain) == 0: return False

                    for nr, nc in neighbors[(r, c)]:
                        neighbor_domain = domains[nr][nc]
                        has_dot_between = is_constrained(r, c, nr, nc)

                        if has_dot_between:
                            # Must be consecutive
                            # D_neighbor must be subset of consecutive(D_curr)
                            allowed = get_consecutive_values(curr_domain)
                            new_neighbor_domain = neighbor_domain & allowed
                            if new_neighbor_domain != neighbor_domain:
                                domains[nr][nc] = new_neighbor_domain
                                changed = True

                            # Symmetric: D_curr must be subset of consecutive(D_neighbor)
                            allowed_curr = get_consecutive_values(neighbor_domain)
                            new_curr_domain = curr_domain & allowed_curr
                            if new_curr_domain != curr_domain:
                                domains[r][c] = new_curr_domain
                                curr_domain = new_curr_domain # Update local ref
                                changed = True
                        else:
                            # Must NOT be consecutive
                            # If curr is singleton {v}, neighbor cannot be v-1 or v+1
                            if len(curr_domain) == 1:
                                v = list(curr_domain)[0]
                                forbidden = {v-1, v+1}
                                new_neighbor_domain = neighbor_domain - forbidden
                                if new_neighbor_domain != neighbor_domain:
                                    domains[nr][nc] = new_neighbor_domain
                                    changed = True

                            # Symmetric
                            if len(neighbor_domain) == 1:
                                u = list(neighbor_domain)[0]
                                forbidden = {u-1, u+1}
                                new_curr_domain = curr_domain - forbidden
                                if new_curr_domain != curr_domain:
                                    domains[r][c] = new_curr_domain
                                    curr_domain = new_curr_domain
                                    changed = True

        return True

    def solve_recursive(domains, grid):
        # Check if solved
        if all(grid[r][c] != 0 for r in range(N) for c in range(N)):
            return grid

        # MRV Heuristic: Pick cell with smallest domain > 1
        min_size = N + 1
        best_cell = None

        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    size = len(domains[r][c])
                    if size < min_size:
                        min_size = size
                        best_cell = (r, c)
                    if size == 1: # Should have been caught by propagation, but safety check
                         pass 

        if best_cell is None:
            # If no empty cells but not returned above, something is wrong or it's solved
            if all(grid[r][c] != 0 for r in range(N) for c in range(N)):
                return grid
            return None # Stuck

        r, c = best_cell
        possible_values = sorted(list(domains[r][c])) # Sorting for determinism

        for val in possible_values:
            # Create copies for backtracking
            # Deep copy domains is expensive, but necessary for correctness without complex undo logic
            # Optimization: Only copy affected rows/cols? No, full copy is safer for N=9
            new_domains = [row[:] for row in domains] # Shallow copy of rows
            new_domains[r] = [s.copy() for s in domains[r]] # Deep copy of the specific row sets? 
            # Actually, list of sets. row[:] copies the list, but sets are references.
            # Need deep copy of sets.
            new_domains = [[s.copy() for s in row] for row in domains]

            new_grid = [row[:] for row in grid]

            # Assign
            new_grid[r][c] = val
            new_domains[r][c] = {val}

            # Propagate
            if propagate(new_domains, new_grid):
                result = solve_recursive(new_domains, new_grid)
                if result:
                    return result

        return None

    # Initial propagation
    if not propagate(domains, grid):
        return "No Solution"

    result_grid = solve_recursive(domains, grid)

    if result_grid:
        return result_grid
    else:
        return "No Solution"

