def solve(obs):
    data = obs['data']
    N = len(data)
    grid = [row[:] for row in data]

    def get_propagated_grid(g):
        new_g = [row[:] for row in g]
        changed = True
        while changed:
            changed = False
            for r in range(N - 1):
                for c in range(N - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    vals = [new_g[rr][cc] for rr, cc in cells]
                    if vals.count('B') == 4 or vals.count('W') == 4:
                        return None
                    if None in vals:
                        count_b = vals.count('B')
                        count_w = vals.count('W')
                        if count_b == 3:
                            for rr, cc in cells:
                                if new_g[rr][cc] is None:
                                    new_g[rr][cc] = 'W'
                                    changed = True
                        elif count_w == 3:
                            for rr, cc in cells:
                                if new_g[rr][cc] is None:
                                    new_g[rr][cc] = 'B'
                                    changed = True
        return new_g

    def check_2x2(g):
        for r in range(N - 1):
            for c in range(N - 1):
                v = g[r][c]
                if v is None: continue
                if g[r][c+1] == v and g[r+1][c] == v and g[r+1][c+1] == v:
                    return False
        return True

    def is_connected(g, color):
        cells = [(r, c) for r in range(N) for c in range(N) if g[r][c] == color]
        if not cells: return True
        start = cells[0]
        visited = set([start])
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and g[nr][nc] == color and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited) == len(cells)

    def is_potentially_connected(g, color):
        cells = [(r, c) for r in range(N) for c in range(N) if g[r][c] == color]
        if not cells: return True
        start = cells[0]
        visited = set([start])
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and (g[nr][nc] == color or g[nr][nc] is None) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return all((r, c) in visited for r, c in cells)

    def backtrack(g):
        g_prop = get_propagated_grid(g)
        if g_prop is None or not check_2x2(g_prop):
            return None
        if not is_potentially_connected(g_prop, 'B') or not is_potentially_connected(g_prop, 'W'):
            return None

        empty = None
        for r in range(N):
            for c in range(N):
                if g_prop[r][c] is None:
                    empty = (r, c)
                    break
            if empty: break

        if not empty:
            if is_connected(g_prop, 'B') and is_connected(g_prop, 'W'):
                return g_prop
            return None

        r, c = empty
        g_prop[r][c] = 'B'
        res = backtrack(g_prop)
        if res: return res

        g_prop[r][c] = 'W'
        res = backtrack(g_prop)
        if res: return res

        return None

    result = backtrack(grid)
    return result

