def solve(observation):
    # 1. Parse Input
    data = observation['data']
    N = len(data)

    # Convert adjacent list to a set of tuples for O(1) lookup
    # Coordinates are floats, so we keep them as is or map to integers if needed.
    # The prompt uses floats like 3.5.
    adjacent_set = set()
    for item in observation['adjacent']:
        # item is [row, col] e.g., [0, 3.5]
        adjacent_set.add((item[0], item[1]))

    # 2. Initialize Domains
    # domains[r][c] is a set of possible values
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Apply fixed values
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                domains[r][c] = {val}

    # 3. Constraint Propagation (AC-3 style / Fixed Point)
    def is_adjacent(r1, c1, r2, c2):
        # Check if there is a dot between (r1, c1) and (r2, c2)
        if r1 == r2:
            # Horizontal neighbor
            mid_col = (c1 + c2) / 2.0
            return (r1, mid_col) in adjacent_set
        elif c1 == c2:
            # Vertical neighbor
            mid_row = (r1 + r2) / 2.0
            return (mid_row, c1) in adjacent_set
        return False

    def propagate(domains):
        changed = True
        while changed:
            changed = False
            # Check all cells
            for r in range(N):
                for c in range(N):
                    domain = domains[r][c]
                    if len(domain) == 0:
                        return False # Contradiction
                    if len(domain) == 1:
                        val = next(iter(domain))
                        # Propagate to Row and Col (AllDiff)
                        for i in range(N):
                            if i != c:
                                if val in domains[r][i]:
                                    domains[r][i].discard(val)
                                    if len(domains[r][i]) == 0: return False
                                    changed = True
                            if i != r:
                                if val in domains[i][c]:
                                    domains[i][c].discard(val)
                                    if len(domains[i][c]) == 0: return False
                                    changed = True

                        # Propagate to Neighbors (Consecutive / Non-Consecutive)
                        neighbors = [
                            (r, c - 1), (r, c + 1),
                            (r - 1, c), (r + 1, c)
                        ]
                        for nr, nc in neighbors:
                            if 0 <= nr < N and 0 <= nc < N:
                                has_dot = is_adjacent(r, c, nr, nc)
                                neighbor_domain = domains[nr][nc]

                                if has_dot:
                                    # Must be consecutive: val-1 or val+1
                                    allowed = {val - 1, val + 1}
                                    # Intersect
                                    new_domain = neighbor_domain & allowed
                                    if len(new_domain) == 0: return False
                                    if new_domain != neighbor_domain:
                                        domains[nr][nc] = new_domain
                                        changed = True
                                else:
                                    # Must NOT be consecutive
                                    forbidden = {val - 1, val + 1}
                                    # Remove forbidden
                                    old_len = len(neighbor_domain)
                                    domains[nr][nc] -= forbidden
                                    if len(domains[nr][nc]) == 0: return False
                                    if len(domains[nr][nc]) < old_len:
                                        changed = True
            return True

    if not propagate(domains):
        return "No Solution"

    # 4. Backtracking Search with MRV Heuristic
    def get_unassigned_variable(domains):
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    if len(domains[r][c]) < min_size:
                        min_size = len(domains[r][c])
                        best_cell = (r, c)
        return best_cell

    def solve_recursive(domains):
        # Check if solved
        cell = get_unassigned_variable(domains)
        if cell is None:
            # Solved! Extract grid
            grid = [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]
            return grid

        r, c = cell
        possible_values = list(domains[r][c])

        # Try values
        for val in possible_values:
            # Create a deep copy of domains for this branch
            # Since N is small (9), copying list of sets is fast enough
            new_domains = [ [s.copy() for s in row] for row in domains ]
            new_domains[r][c] = {val}

            if propagate(new_domains):
                result = solve_recursive(new_domains)
                if result:
                    return result

        return None

    final_grid = solve_recursive(domains)
    if final_grid:
        return final_grid
    else:
        return "No Solution"

