def solve(observation):
    data = observation['data']
    N = len(data)

    # State grid:
    # '.' : White, unknown
    # 'B' : Bulb
    # 'X' : White, safe (cannot be bulb)
    # '#' : Black (block)
    state = [['.' for _ in range(N)] for _ in range(N)]
    constraints = [[None for _ in range(N)] for _ in range(N)]

    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is None:
                constraints[r][c] = None
            elif val == -1:
                constraints[r][c] = -1
                state[r][c] = '#'
            else:
                constraints[r][c] = val
                state[r][c] = '#'

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    def is_lit(r, c, grid):
        # Check Up
        for i in range(r-1, -1, -1):
            if grid[i][c] == '#': break
            if grid[i][c] == 'B': return True
        # Check Down
        for i in range(r+1, N):
            if grid[i][c] == '#': break
            if grid[i][c] == 'B': return True
        # Check Left
        for j in range(c-1, -1, -1):
            if grid[r][j] == '#': break
            if grid[r][j] == 'B': return True
        # Check Right
        for j in range(c+1, N):
            if grid[r][j] == '#': break
            if grid[r][j] == 'B': return True
        return False

    def mark_safe_line_status(r, c, grid):
        did_change = False
        # Up
        for i in range(r-1, -1, -1):
            if grid[i][c] == '#': break
            if grid[i][c] == 'B': return -1 # Conflict
            if grid[i][c] == '.': 
                grid[i][c] = 'X'
                did_change = True
        # Down
        for i in range(r+1, N):
            if grid[i][c] == '#': break
            if grid[i][c] == 'B': return -1
            if grid[i][c] == '.': 
                grid[i][c] = 'X'
                did_change = True
        # Left
        for j in range(c-1, -1, -1):
            if grid[r][j] == '#': break
            if grid[r][j] == 'B': return -1
            if grid[r][j] == '.': 
                grid[r][j] = 'X'
                did_change = True
        # Right
        for j in range(c+1, N):
            if grid[r][j] == '#': break
            if grid[r][j] == 'B': return -1
            if grid[r][j] == '.': 
                grid[r][j] = 'X'
                did_change = True
        return 1 if did_change else 0

    def propagate_final(grid):
        changed = True
        while changed:
            changed = False
            # 1. Constraints Logic
            for r in range(N):
                for c in range(N):
                    if constraints[r][c] is not None and constraints[r][c] >= 0:
                        target = constraints[r][c]
                        neighs = get_neighbors(r, c)
                        bulbs_count = 0
                        available_count = 0
                        available_cells = []
                        for nr, nc in neighs:
                            if grid[nr][nc] == 'B': bulbs_count += 1
                            elif grid[nr][nc] == '.':
                                available_count += 1
                                available_cells.append((nr, nc))

                        # If satisfied, mark rest as safe
                        if bulbs_count == target:
                            for nr, nc in available_cells:
                                grid[nr][nc] = 'X'
                                changed = True
                        # If forced, place bulbs
                        elif bulbs_count + available_count == target:
                            for nr, nc in available_cells:
                                grid[nr][nc] = 'B'
                                changed = True

            # 2. Bulb Propagation (Mark lines as Safe)
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 'B':
                        res = mark_safe_line_status(r, c, grid)
                        if res == -1: return False
                        if res == 1: changed = True
        return True

    def is_valid_final(grid):
        for r in range(N):
            for c in range(N):
                if constraints[r][c] is not None and constraints[r][c] >= 0:
                    target = constraints[r][c]
                    count = 0
                    for nr, nc in get_neighbors(r, c):
                        if grid[nr][nc] == 'B': count += 1
                    if count != target: return False

        for r in range(N):
            for c in range(N):
                if grid[r][c] != '#' and grid[r][c] != 'B':
                    if not is_lit(r, c, grid): return False
        return True

    def solve_recursive(grid):
        if not propagate_final(grid):
            return None

        # Find first unlit white cell (heuristic: most constrained cell to light)
        target_r, target_c = -1, -1
        for r in range(N):
            for c in range(N):
                if grid[r][c] != '#' and grid[r][c] != 'B':
                    if not is_lit(r, c, grid):
                        target_r, target_c = r, c
                        break
            if target_r != -1: break

        if target_r == -1:
            if is_valid_final(grid):
                return grid
            else:
                return None

        # Find candidates to light (target_r, target_c)
        candidates = []
        # Row candidates
        for j in range(N):
            if grid[target_r][j] == '.':
                blocked = False
                step = 1 if j > target_c else -1
                for k in range(target_c + step, j, step):
                    if grid[target_r][k] == '#':
                        blocked = True
                        break
                if not blocked:
                    candidates.append((target_r, j))
        # Col candidates
        for i in range(N):
            if grid[i][target_c] == '.':
                blocked = False
                step = 1 if i > target_r else -1
                for k in range(target_r + step, i, step):
                    if grid[k][target_c] == '#':
                        blocked = True
                        break
                if not blocked:
                    candidates.append((i, target_c))

        # Deduplicate candidates
        candidates = list(set(candidates))

        # Try candidates
        for cr, cc in candidates:
            # Save state
            saved = [row[:] for row in grid]

            # Place Bulb
            grid[cr][cc] = 'B'

            res = solve_recursive(grid)
            if res: return res

            # Restore state
            for r in range(N):
                for c in range(N):
                    grid[r][c] = saved[r][c]

        return None

    initial_state = [row[:] for row in state]
    result = solve_recursive(initial_state)

    if result:
        output = [[None for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if result[r][c] == 'B':
                    output[r][c] = 'B'
        return output
    else:
        return "No Solution"

