            if mn > 0:
                final_ans[pair] = mn
        return final_ans
    else:
        return "No Solution"

def search(islands, island_neighbors, bridges):
    bridges, valid = propagate(islands, island_neighbors, bridges)
    if not valid:
        return None

    all_fixed = True
    for pair, (mn, mx) in bridges.items():
        if mn != mx:
            all_fixed = False
            break

    if all_fixed:
        if is_connected(islands, bridges):
            return bridges
        else:
            return None

    branch_pair = None
    for pair, (mn, mx) in bridges.items():
        if mn != mx:
            branch_pair = pair
            break

    if branch_pair is None:
        return None

    mn, mx = bridges[branch_pair]

    bridges1 = copy.deepcopy(bridges)
    bridges1[branch_pair] = [mn, mn]
    res1 = search(islands, island_neighbors, bridges1)
    if res1:
        return res1

    if mx > mn:
        bridges2 = copy.deepcopy(bridges)
        bridges2[branch_pair] = [mn + 1, mx]
        res2 = search(islands, island_neighbors, bridges2)
        if res2:
            return res2

    return None

def propagate(islands, island_neighbors, bridges):
    changed = True
    while changed:
        changed = False
        for (r, c), val in islands.items():
            current_min_sum = 0
            current_max_sum = 0
            incident_pairs = []

            for nr, nc in island_neighbors[(r, c)]:
                pair = tuple(sorted(((r, c), (nr, nc))))
                mn, mx = bridges[pair]
                current_min_sum += mn
                current_max_sum += mx
                incident_pairs.append(pair)

            if current_min_sum > val or current_max_sum < val:
                return bridges, False

            for pair in incident_pairs:
                mn, mx = bridges[pair]

                max_from_others = current_max_sum - mx
                min_from_others = current_min_sum - mn

                new_mn = max(mn, val - max_from_others)
                new_mx = min(mx, val - min_from_others)

                if new_mn != mn or new_mx != mx:
                    bridges[pair] = [new_mn, new_mx]
                    changed = True
                    if new_mn > new_mx:
                        return bridges, False

    return bridges, True

def is_connected(islands, bridges):
    adj = {k: [] for k in islands}
    for pair, (mn, mx) in bridges.items():
        if mn > 0:
            (r1, c1), (r2, c2) = pair
            adj[(r1, c1)].append((r2, c2))
            adj[(r2, c2)].append((r1, c1))

    if not islands:
        return True

    start_node = next(iter(islands))
    visited = set([start_node])
    queue = [start_node]

    while queue:
        curr = queue.pop(0)
        for neighbor in adj[curr]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return len(visited) == len(islands)

