    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    # Build adjacency map for consecutive constraints
    # consecutive_neighbors[r][c] contains list of (nr, nc) that MUST be consecutive
    consecutive_neighbors = [[[] for _ in range(N)] for _ in range(N)]

    for pt in adjacent:
        r, c = pt
        # Determine if horizontal or vertical gap based on coordinates
        # Horizontal gap: (row, col+0.5) -> r is int, c is x.5
        # Vertical gap: (row+0.5, col) -> r is x.5, c is int

        if r == int(r): # Horizontal
            row_idx = int(r)
            col_idx = int(c - 0.5)
            if 0 <= row_idx < N and 0 <= col_idx < N - 1:
                u, v = (row_idx, col_idx), (row_idx, col_idx + 1)
                consecutive_neighbors[u[0]][u[1]].append(v)
                consecutive_neighbors[v[0]][v[1]].append(u)
        else: # Vertical
            row_idx = int(r - 0.5)
            col_idx = int(c)
            if 0 <= row_idx < N - 1 and 0 <= col_idx < N:
                u, v = (row_idx, col_idx), (row_idx + 1, col_idx)
                consecutive_neighbors[u[0]][u[1]].append(v)
                consecutive_neighbors[v[0]][v[1]].append(u)

    # Precompute all orthogonal neighbors for non-consecutive checks
    all_neighbors = [[[] for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    all_neighbors[r][c].append((nr, nc))

    # Constraint Propagation (AC-3 style)
    # Reduces domains based on Latin Square and Consecutive/Non-Consecutive rules
    def propagate(doms):
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if len(doms[r][c]) == 1:
                        val = next(iter(doms[r][c]))

                        # 1. Latin Square Constraints (Row/Col AllDifferent)
                        # Remove val from same row
                        for nc in range(N):
                            if nc != c:
                                if val in doms[r][nc]:
                                    doms[r][nc].discard(val)
                                    if len(doms[r][nc]) == 0: return False
                                    changed = True
                        # Remove val from same col
                        for nr in range(N):
                            if nr != r:
                                if val in doms[nr][c]:
                                    doms[nr][c].discard(val)
                                    if len(doms[nr][c]) == 0: return False
                                    changed = True

                        # 2. Adjacency Constraints
                        for nr, nc in all_neighbors[r][c]:
                            is_consec = (nr, nc) in consecutive_neighbors[r][c]
                            if is_consec:
                                # Must be val-1 or val+1
                                allowed = {val - 1, val + 1}
                                old_len = len(doms[nr][nc])
                                doms[nr][nc] &= allowed
                                if len(doms[nr][nc]) == 0: return False
                                if len(doms[nr][nc]) < old_len:
                                    changed = True
                            else:
                                # Must NOT be val-1 or val+1
                                forbidden = {val - 1, val + 1}
                                old_len = len(doms[nr][nc])
                                doms[nr][nc] -= forbidden
                                if len(doms[nr][nc]) == 0: return False
                                if len(doms[nr][nc]) < old_len:
                                    changed = True
        return True

    # Initial propagation to reduce search space
    if not propagate(domains):
        return "No Solution"

    # Backtracking Search with Minimum Remaining Values (MRV) Heuristic
    def solve_recursive(doms):
        # Check if solved
        is_solved = True
        best_cell = None
        min_size = N + 1

        for r in range(N):
            for c in range(N):
                size = len(doms[r][c])
                if size == 0: return False # Dead end
                if size > 1:
                    is_solved = False
                    if size < min_size:
                        min_size = size
                        best_cell = (r, c)

        if is_solved:
            return doms # Return the solved state

        r, c = best_cell
        possible = list(doms[r][c])

        for val in possible:
            # Create new state (deep copy of domains)
            new_doms = [ [s.copy() for s in row] for row in doms ]
            new_doms[r][c] = {val}

            # Propagate constraints after assignment
            if propagate(new_doms):
                res = solve_recursive(new_doms)
                if res:
                    return res
        return False

    result_doms = solve_recursive(domains)

    if result_doms:
        grid = [[next(iter(result_doms[r][c])) for c in range(N)] for r in range(N)]
        return grid
    else:
        return "No Solution"

