import itertools

def solve(observation):
    # Parse clues from observation
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']
    H = len(row_clues)
    W = len(col_clues)

    # Helper to generate all valid binary lines for a given length and clue list
    # This mimics the human step of "listing possible configurations"
    def generate_lines(length, clues):
        if not clues:
            return [tuple([0]*length)]

        valid = []
        # Brute force all 2^length combinations (efficient for small N like 5)
        for bits in itertools.product([0, 1], repeat=length):
            runs = []
            count = 0
            for b in bits:
                if b == 1:
                    count += 1
                else:
                    if count > 0:
                        runs.append(count)
                        count = 0
            if count > 0:
                runs.append(count)

            if runs == clues:
                valid.append(bits)
        return valid

    # Precompute valid lines for all rows and columns
    # We use sets for efficient intersection/filtering
    initial_row_sets = [set(generate_lines(W, clues)) for clues in row_clues]
    initial_col_sets = [set(generate_lines(H, clues)) for clues in col_clues]

    # Grid state: None (unknown), 0 (white), 1 (black)
    initial_grid = [[None for _ in range(W)] for _ in range(H)]

    def propagate(row_sets, col_sets, grid):
        """
        Applies constraint propagation (human-like deduction).
        Filters valid lines based on current grid knowledge.
        Updates grid cells that are determined (same in all valid lines).
        Returns (Success, row_sets, col_sets).
        """
        changed = True
        while changed:
            changed = False

            # Process Rows
            for r in range(H):
                if not row_sets[r]:
                    return False, None, None # Contradiction

                known_row = grid[r]
                # Filter lines consistent with current grid
                new_set = set()
                for line in row_sets[r]:
                    consistent = True
                    for c in range(W):
                        if known_row[c] is not None and known_row[c] != line[c]:
                            consistent = False
                            break
                    if consistent:
                        new_set.add(line)

                if not new_set:
                    return False, None, None

                row_sets[r] = new_set

                # Deduce cell values (Intersection of all valid lines)
                # If a cell is 1 in ALL valid lines, it must be 1.
                # If a cell is 0 in ALL valid lines, it must be 0.
                for c in range(W):
                    if known_row[c] is None:
                        vals = [line[c] for line in new_set]
                        if all(v == 1 for v in vals):
                            grid[r][c] = 1
                            changed = True
                        elif all(v == 0 for v in vals):
                            grid[r][c] = 0
                            changed = True

            # Process Columns
            for c in range(W):
                if not col_sets[c]:
                    return False, None, None

                known_col = [grid[r][c] for r in range(H)]
                new_set = set()
                for line in col_sets[c]:
                    consistent = True
                    for r in range(H):
                        if known_col[r] is not None and known_col[r] != line[r]:
                            consistent = False
                            break
                    if consistent:
                        new_set.add(line)

                if not new_set:
                    return False, None, None

                col_sets[c] = new_set

                # Deduce cell values
                for r in range(H):
                    if grid[r][c] is None:
                        vals = [line[r] for line in new_set]
                        if all(v == 1 for v in vals):
                            grid[r][c] = 1
                            changed = True
                        elif all(v == 0 for v in vals):
                            grid[r][c] = 0
                            changed = True

        return True, row_sets, col_sets

    def is_solved(grid):
        for r in range(H):
            for c in range(W):
                if grid[r][c] is None:
                    return False
        return True

    def search(row_sets, col_sets, grid):
        # 1. Propagate constraints (Deduction phase)
        success, row_sets, col_sets = propagate(row_sets, col_sets, grid)
        if not success:
            return None

        # 2. Check if solved
        if is_solved(grid):
            return [row[:] for row in grid]

        # 3. Branching (Guessing phase)
        # Pick the first unknown cell
        for r in range(H):
            for c in range(W):
                if grid[r][c] is None:
                    # Try Black (1)
                    grid[r][c] = 1
                    # Copy state for recursion to allow backtracking
                    rs_copy = [s.copy() for s in row_sets]
                    cs_copy = [s.copy() for s in col_sets]
                    grid_copy = [row[:] for row in grid]

                    res = search(rs_copy, cs_copy, grid_copy)
                    if res:
                        return res

                    # Try White (0)
                    grid[r][c] = 0
                    rs_copy = [s.copy() for s in row_sets]
                    cs_copy = [s.copy() for s in col_sets]
                    grid_copy = [row[:] for row in grid]

                    res = search(rs_copy, cs_copy, grid_copy)
                    if res:
                        return res

                    # Backtrack
                    return None

        return None

    # Initialize search
    rs_start = [s.copy() for s in initial_row_sets]
    cs_start = [s.copy() for s in initial_col_sets]
    grid_start = [row[:] for row in initial_grid]

    result = search(rs_start, cs_start, grid_start)

    if result is None:
        return "No Solution"

    # Format output as requested: 'B' for black, None for non-black
    final_output = []
    for r in range(H):
        row_out = []
        for c in range(W):
            if result[r][c] == 1:
                row_out.append('B')
            else:
                row_out.append(None)
        final_output.append(row_out)

    return final_output

