import sys
import copy

# Increase recursion depth just in case, though 10x10 is small.
sys.setrecursionlimit(2000)

def get_valid_lines(length, clues):
    """
    Generates all valid binary lines (1 for black, 0 for white) of given length
    that satisfy the clues.
    """
    if not clues:
        return [[0] * length]

    # Calculate minimum length required
    min_len = sum(clues) + len(clues) - 1
    if min_len > length:
        return []

    results = []

    def backtrack(current_line, clue_idx, current_pos):
        if clue_idx == len(clues):
            # Fill the rest with 0s
            line = current_line + [0] * (length - current_pos)
            results.append(line)
            return

        clue = clues[clue_idx]
        # Calculate max start position for this block
        # We need space for remaining clues: sum(clues[clue_idx+1:]) + len(clues[clue_idx+1:])
        remaining_space_needed = 0
        if clue_idx < len(clues) - 1:
            remaining_space_needed = sum(clues[clue_idx+1:]) + (len(clues) - 1 - clue_idx)

        max_start = length - remaining_space_needed - clue

        for start in range(current_pos, max_start + 1):
            # Place block
            new_line = current_line + [0] * (start - current_pos) + [1] * clue
            # Add separator if not last clue
            next_pos = start + clue
            if clue_idx < len(clues) - 1:
                next_pos += 1 # Separator
                # We handle the separator in the next iteration's padding or explicitly here?
                # Actually, simpler to just pass next_pos and let next iteration pad with 0s.
                # But we must ensure at least one 0 between blocks.
                # So we pass start + clue + 1 as the minimum current_pos for next call.
                backtrack(new_line, clue_idx + 1, start + clue + 1)
            else:
                backtrack(new_line, clue_idx + 1, start + clue)

    backtrack([], 0, 0)
    return results

class NonogramSolver:
    def __init__(self, row_clues, col_clues):
        self.rows = len(row_clues)
        self.cols = len(col_clues)
        self.row_clues = row_clues
        self.col_clues = col_clues

        # Grid: -1 unknown, 0 white, 1 black
        self.grid = [[-1] * self.cols for _ in range(self.rows)]

        # Precompute all valid lines
        self.row_possibilities = [get_valid_lines(self.cols, clue) for clue in row_clues]
        self.col_possibilities = [get_valid_lines(self.rows, clue) for clue in col_clues]

    def is_consistent(self, line, possibilities):
        """Check if a line (row or col) is consistent with at least one possibility."""
        for poss in possibilities:
            match = True
            for i, val in enumerate(line):
                if val != -1 and val != poss[i]:
                    match = False
                    break
            if match:
                return True
        return False

    def propagate(self):
        """
        Applies logical deduction to fill the grid.
        Returns True if any change was made, False otherwise.
        Returns None if a contradiction is found.
        """
        changed = False

        # Process Rows
        for r in range(self.rows):
            # Filter possibilities based on current grid row
            current_row = self.grid[r]
            valid_poss = []
            for poss in self.row_possibilities[r]:
                is_valid = True
                for c in range(self.cols):
                    if current_row[c] != -1 and current_row[c] != poss[c]:
                        is_valid = False
                        break
                if is_valid:
                    valid_poss.append(poss)

            if not valid_poss:
                return None # Contradiction

            self.row_possibilities[r] = valid_poss

            # Deduce fixed cells
            if len(valid_poss) == 1:
                # Row is solved
                for c in range(self.cols):
                    if self.grid[r][c] == -1:
                        self.grid[r][c] = valid_poss[0][c]
                        changed = True
            else:
                # Intersection logic
                for c in range(self.cols):
                    if self.grid[r][c] == -1:
                        # Check if all possibilities agree
                        val = valid_poss[0][c]
                        all_same = True
                        for poss in valid_poss[1:]:
                            if poss[c] != val:
                                all_same = False
                                break
                        if all_same:
                            self.grid[r][c] = val
                            changed = True

        # Process Columns
        for c in range(self.cols):
            current_col = [self.grid[r][c] for r in range(self.rows)]
            valid_poss = []
            for poss in self.col_possibilities[c]:
                is_valid = True
                for r in range(self.rows):
                    if current_col[r] != -1 and current_col[r] != poss[r]:
                        is_valid = False
                        break
                if is_valid:
                    valid_poss.append(poss)

            if not valid_poss:
                return None # Contradiction

            self.col_possibilities[c] = valid_poss

            # Deduce fixed cells
            if len(valid_poss) == 1:
                for r in range(self.rows):
                    if self.grid[r][c] == -1:
                        self.grid[r][c] = valid_poss[0][r]
                        changed = True
            else:
                for r in range(self.rows):
                    if self.grid[r][c] == -1:
                        val = valid_poss[0][r]
                        all_same = True
                        for poss in valid_poss[1:]:
                            if poss[r] != val:
                                all_same = False
                                break
                        if all_same:
                            self.grid[r][c] = val
                            changed = True

        return changed

    def solve(self):
        # Initial propagation
        while True:
            res = self.propagate()
            if res is None:
                return False # Contradiction
            if not res:
                break # No more changes

        # Check if solved
        is_full = True
        for r in range(self.rows):
            for c in range(self.cols):
                if self.grid[r][c] == -1:
                    is_full = False
                    break
            if not is_full:
                break

        if is_full:
            return True

        # Backtracking
        # Heuristic: Pick cell with most constrained possibilities?
        # Or just first unknown.
        # Let's pick the row with fewest possibilities to branch on.

        best_r, best_c = -1, -1
        min_poss = float('inf')

        # Find an unknown cell
        for r in range(self.rows):
            for c in range(self.cols):
                if self.grid[r][c] == -1:
                    # Estimate branching factor
                    # Count valid row possibilities and col possibilities
                    # This is a simple heuristic
                    score = len(self.row_possibilities[r]) + len(self.col_possibilities[c])
                    if score < min_poss:
                        min_poss = score
                        best_r, best_c = r, c

        if best_r == -1:
            return False # Should not happen if is_full is false

        r, c = best_r, best_c

        # Save state
        saved_grid = copy.deepcopy(self.grid)
        saved_row_poss = copy.deepcopy(self.row_possibilities)
        saved_col_poss = copy.deepcopy(self.col_possibilities)

        # Try Black (1)
        self.grid[r][c] = 1
        if self.solve():
            return True

        # Restore state
        self.grid = saved_grid
        self.row_possibilities = saved_row_poss
        self.col_possibilities = saved_col_poss

        # Try White (0)
        self.grid[r][c] = 0
        if self.solve():
            return True

        # Restore state again for caller (though we return False)
        self.grid = saved_grid
        self.row_possibilities = saved_row_poss
        self.col_possibilities = saved_col_poss

        return False

    def get_solution_grid(self):
        # Convert 0/1 to None/'B'
        result = []
        for r in range(self.rows):
            row_res = []
            for c in range(self.cols):
                if self.grid[r][c] == 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result.append(row_res)
        return result

def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']

    solver = NonogramSolver(row_clues, col_clues)
    if solver.solve():
        return solver.get_solution_grid()
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
