def solve(observation):
    """
    Generalized solver for the grid puzzle.
    Uses constraint propagation and backtracking with pruning.
    Weights are assumed to be 1-based indices (1, 2, ..., N) based on puzzle constraints.
    """
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    R = len(row_targets)
    C = len(col_targets)

    # Weights are 1, 2, ..., N. 
    # Inferred because 0-based weights (0,1,2,3) would make row target 7 impossible (max sum 6).
    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # Precompute all valid bitmasks for each row and column
    # A row mask bit 'c' is 1 if cell (r, c) is Black.
    # A col mask bit 'r' is 1 if cell (r, c) is Black.

    def get_valid_masks(weights, target, length):
        valid = []
        for mask in range(1 << length):
            s = 0
            for i in range(length):
                if (mask >> i) & 1:
                    s += weights[i]
            if s == target:
                valid.append(mask)
        return valid

    # row_options[r] contains list of valid masks for row r
    row_options = [get_valid_masks(col_weights, row_targets[r], C) for r in range(R)]
    # col_options[c] contains list of valid masks for col c
    col_options = [get_valid_masks(row_weights, col_targets[c], R) for c in range(C)]

    # Grid state: None (unknown), 0 (White), 1 (Black)
    grid = [[None for _ in range(C)] for _ in range(R)]

    # Constraint Propagation
    # Repeatedly filter options based on current grid state and find forced cells
    changed = True
    while changed:
        changed = False

        # 1. Filter row options based on current grid
        for r in range(R):
            new_options = []
            for mask in row_options[r]:
                consistent = True
                for c in range(C):
                    cell_val = (mask >> c) & 1
                    if grid[r][c] is not None and grid[r][c] != cell_val:
                        consistent = False
                        break
                if consistent:
                    new_options.append(mask)
            if len(new_options) != len(row_options[r]):
                row_options[r] = new_options
                changed = True

        # 2. Filter col options based on current grid
        for c in range(C):
            new_options = []
            for mask in col_options[c]:
                consistent = True
                for r in range(R):
                    cell_val = (mask >> r) & 1
                    if grid[r][c] is not None and grid[r][c] != cell_val:
                        consistent = False
                        break
                if consistent:
                    new_options.append(mask)
            if len(new_options) != len(col_options[c]):
                col_options[c] = new_options
                changed = True

        # 3. Deduce forced cells from remaining options
        # If a bit is 1 in all options for a row, that cell must be Black
        for r in range(R):
            if not row_options[r]: return "No Solution" # Contradiction
            common_mask = row_options[r][0]
            union_mask = row_options[r][0]
            for mask in row_options[r][1:]:
                common_mask &= mask
                union_mask |= mask

            for c in range(C):
                bit = 1 << c
                # If bit is set in all masks
                if (common_mask & bit):
                    if grid[r][c] != 1:
                        grid[r][c] = 1
                        changed = True
                # If bit is unset in all masks (i.e., not in union)
                elif not (union_mask & bit):
                    if grid[r][c] != 0:
                        grid[r][c] = 0
                        changed = True

        # Same for columns
        for c in range(C):
            if not col_options[c]: return "No Solution"
            common_mask = col_options[c][0]
            union_mask = col_options[c][0]
            for mask in col_options[c][1:]:
                common_mask &= mask
                union_mask |= mask

            for r in range(R):
                bit = 1 << r
                if (common_mask & bit):
                    if grid[r][c] != 1:
                        grid[r][c] = 1
                        changed = True
                elif not (union_mask & bit):
                    if grid[r][c] != 0:
                        grid[r][c] = 0
                        changed = True

    # Check if solved
    solved = all(grid[r][c] is not None for r in range(R) for c in range(C))
    if solved:
        # Verify solution
        for r in range(R):
            s = sum(col_weights[c] for c in range(C) if grid[r][c] == 1)
            if s != row_targets[r]: return "No Solution"
        for c in range(C):
            s = sum(row_weights[r] for r in range(R) if grid[r][c] == 1)
            if s != col_targets[c]: return "No Solution"

        # Format output
        result = []
        for r in range(R):
            row_data = ['B' if grid[r][c] == 1 else None for c in range(C)]
            result.append(row_data)
        return result

    # Backtracking Search with Pruning
    # We fill row by row.
    # To optimize, we could pick the row with fewest options (MRV), but row-by-row is simpler for reconstruction.
    # Let's use a simple DFS that respects the 'grid' state fixed by propagation.

    solution_path = None

    def dfs(r, current_col_sums):
        nonlocal solution_path
        if solution_path is not None: return

        if r == R:
            if all(current_col_sums[c] == col_targets[c] for c in range(C)):
                solution_path = [] # Will be filled by successful path
            return

        # Pruning: Check column constraints
        for c in range(C):
            if current_col_sums[c] > col_targets[c]:
                return
            # Check if remaining rows can possibly reach target
            max_remaining = sum(row_weights[k] for k in range(r, R))
            if current_col_sums[c] + max_remaining < col_targets[c]:
                return

        # Try valid masks for row r
        for mask in row_options[r]:
            # Check consistency with fixed grid cells in this row
            consistent = True
            for c in range(C):
                if grid[r][c] is not None:
                    bit_val = (mask >> c) & 1
                    if bit_val != grid[r][c]:
                        consistent = False
                        break
            if not consistent:
                continue

            # Calculate new col sums
            new_col_sums = list(current_col_sums)
            for c in range(C):
                if (mask >> c) & 1:
                    new_col_sums[c] += row_weights[r]

            # Recurse
            dfs(r + 1, new_col_sums)

            if solution_path is not None:
                solution_path = solution_path + [mask] # Build path on unwind? No, easier to pass path
                return

    # Redo DFS with path passing to avoid global state issues
    def dfs_path(r, current_col_sums, path):
        nonlocal solution_path
        if solution_path is not None: return

        if r == R:
            if all(current_col_sums[c] == col_targets[c] for c in range(C)):
                solution_path = path
            return

        for c in range(C):
            if current_col_sums[c] > col_targets[c]: return
            max_remaining = sum(row_weights[k] for k in range(r, R))
            if current_col_sums[c] + max_remaining < col_targets[c]: return

        for mask in row_options[r]:
            consistent = True
            for c in range(C):
                if grid[r][c] is not None:
                    if ((mask >> c) & 1) != grid[r][c]:
                        consistent = False
                        break
            if not consistent: continue

            new_col_sums = list(current_col_sums)
            for c in range(C):
                if (mask >> c) & 1:
                    new_col_sums[c] += row_weights[r]

            dfs_path(r + 1, new_col_sums, path + [mask])
            if solution_path is not None: return

    dfs_path(0, [0] * C, [])

    if solution_path is None:
        return "No Solution"

    # Convert path to grid
    result = []
    for r in range(R):
        mask = solution_path[r]
        row_data = ['B' if (mask >> c) & 1 else None for c in range(C)]
        result.append(row_data)

    return result

