OBSERVATION = {'data': [[None, None, None, 1, None], [2, None, 1, 1, None], [2, None, 2, None, None], [1, 2, 0, 2, None], [None, 3, 3, 3, None]]}

import sys
sys.setrecursionlimit(5000)

class SlitherlinkSolver:
    def __init__(self, clues):
        self.rows = len(clues)
        self.cols = len(clues[0])
        self.clues = clues
        # h_edges: (rows+1) x cols. Connects (r, c) and (r, c+1)
        # v_edges: rows x (cols+1). Connects (r, c) and (r+1, c)
        self.h_rows, self.h_cols = self.rows + 1, self.cols
        self.v_rows, self.v_cols = self.rows, self.cols + 1
        # State: 0=Unknown, 1=Line, 2=NoLine
        self.h_state = [[0]*self.h_cols for _ in range(self.h_rows)]
        self.v_state = [[0]*self.v_cols for _ in range(self.v_rows)]

    def get_h(self, r, c):
        if 0 <= r < self.h_rows and 0 <= c < self.h_cols: return self.h_state[r][c]
        return -1
    def get_v(self, r, c):
        if 0 <= r < self.v_rows and 0 <= c < self.v_cols: return self.v_state[r][c]
        return -1
    def set_h(self, r, c, v):
        if 0 <= r < self.h_rows and 0 <= c < self.h_cols:
            if self.h_state[r][c] != 0 and self.h_state[r][c] != v: return False
            self.h_state[r][c] = v
            return True
        return False
    def set_v(self, r, c, v):
        if 0 <= r < self.v_rows and 0 <= c < self.v_cols:
            if self.v_state[r][c] != 0 and self.v_state[r][c] != v: return False
            self.v_state[r][c] = v
            return True
        return False

    def get_cell_edges(self, r, c):
        # Top, Bottom, Left, Right
        return [('h', r, c), ('h', r+1, c), ('v', r, c), ('v', r, c+1)]

    def get_vertex_edges(self, r, c):
        edges = []
        if r > 0: edges.append(('v', r-1, c))
        if r < self.rows: edges.append(('v', r, c))
        if c > 0: edges.append(('h', r, c-1))
        if c < self.cols: edges.append(('h', r, c))
        return edges

    def propagate(self):
        changed = True
        while changed:
            changed = False
            # 1. Clue Constraints
            for r in range(self.rows):
                for c in range(self.cols):
                    clue = self.clues[r][c]
                    if clue is None: continue
                    edges = self.get_cell_edges(r, c)
                    lines = sum(1 for t,e_r,e_c in edges if (self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)) == 1)
                    unknowns = sum(1 for t,e_r,e_c in edges if (self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)) == 0)

                    if lines > clue: return False
                    if lines == clue:
                        for t,e_r,e_c in edges:
                            val = self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)
                            if val == 0:
                                if t=='h': self.set_h(e_r,e_c, 2)
                                else: self.set_v(e_r,e_c, 2)
                                changed = True
                    if lines + unknowns == clue:
                        for t,e_r,e_c in edges:
                            val = self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)
                            if val == 0:
                                if t=='h': self.set_h(e_r,e_c, 1)
                                else: self.set_v(e_r,e_c, 1)
                                changed = True

            # 2. Vertex Constraints (Degree must be 0 or 2)
            for r in range(self.h_rows):
                for c in range(self.v_cols):
                    edges = self.get_vertex_edges(r, c)
                    lines = sum(1 for t,e_r,e_c in edges if (self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)) == 1)
                    nols = sum(1 for t,e_r,e_c in edges if (self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)) == 2)
                    unknowns = len(edges) - lines - nols

                    if lines > 2: return False
                    if unknowns == 0 and lines == 1: return False # Degree 1 invalid

                    if lines == 2:
                        for t,e_r,e_c in edges:
                            val = self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)
                            if val == 0:
                                if t=='h': self.set_h(e_r,e_c, 2)
                                else: self.set_v(e_r,e_c, 2)
                                changed = True
                    if nols >= 3: # If 3 are NoLine, last must be NoLine (degree 0)
                        for t,e_r,e_c in edges:
