                                else: self.set_v(e_r,e_c, 1)
                                changed = True

            # 3. Loop Prevention (Union-Find to detect sub-loops)
            parent = list(range(self.h_rows * self.v_cols))
            def find(i):
                if parent[i] != i: parent[i] = find(parent[i])
                return parent[i]
            def union(i, j):
                pi, pj = find(i), find(j)
                if pi != pj: parent[pi] = pj; return True
                return False

            segments = []
            for r in range(self.h_rows):
                for c in range(self.h_cols):
                    if self.h_state[r][c] == 1: segments.append((r*self.v_cols+c, r*self.v_cols+c+1))
            for r in range(self.v_rows):
                for c in range(self.v_cols):
                    if self.v_state[r][c] == 1: segments.append((r*self.v_cols+c, (r+1)*self.v_cols+c))

            has_cycle = False
            temp_parent = list(range(self.h_rows * self.v_cols))
            def t_find(i):
                if temp_parent[i] != i: temp_parent[i] = t_find(temp_parent[i])
                return temp_parent[i]
            def t_union(i, j):
                pi, pj = t_find(i), t_find(j)
                if pi != pj: temp_parent[pi] = pj; return True
                return False

            for u, v in segments:
                if t_find(u) == t_find(v): has_cycle = True
                else: t_union(u, v)

            if has_cycle and not self.is_solved(): return False

        return True

    def is_solved(self):
        # Check clues
        for r in range(self.rows):
            for c in range(self.cols):
                clue = self.clues[r][c]
                if clue is None: continue
                edges = self.get_cell_edges(r, c)
                lines = sum(1 for t,e_r,e_c in edges if (self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)) == 1)
                unknowns = sum(1 for t,e_r,e_c in edges if (self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)) == 0)
                if unknowns > 0 or lines != clue: return False

        # Check all edges determined
        for r in range(self.h_rows):
            for c in range(self.h_cols):
                if self.h_state[r][c] == 0: return False
        for r in range(self.v_rows):
            for c in range(self.v_cols):
                if self.v_state[r][c] == 0: return False

        # Check connectivity (single loop)
        parent = list(range(self.h_rows * self.v_cols))
        def find(i):
            if parent[i] != i: parent[i] = find(parent[i])
            return parent[i]
        def union(i, j):
            pi, pj = find(i), find(j)
            if pi != pj: parent[pi] = pj

        count_lines = 0
        for r in range(self.h_rows):
            for c in range(self.h_cols):
                if self.h_state[r][c] == 1:
                    union(r*self.v_cols+c, r*self.v_cols+c+1)
                    count_lines += 1
        for r in range(self.v_rows):
            for c in range(self.v_cols):
                if self.v_state[r][c] == 1:
                    union(r*self.v_cols+c, (r+1)*self.v_cols+c)
                    count_lines += 1

        if count_lines == 0: return False

        root = -1
        for r in range(self.h_rows):
            for c in range(self.h_cols):
                if self.h_state[r][c] == 1:
                    root = find(r*self.v_cols+c)
                    break
            if root != -1: break
        if root == -1:
            for r in range(self.v_rows):
                for c in range(self.v_cols):
                    if self.v_state[r][c] == 1:
                        root = find(r*self.v_cols+c)
                        break
                if root != -1: break

        for r in range(self.h_rows):
            for c in range(self.h_cols):
                if self.h_state[r][c] == 1:
                    if find(r*self.v_cols+c) != root or find(r*self.v_cols+c+1) != root: return False
        for r in range(self.v_rows):
            for c in range(self.v_cols):
                if self.v_state[r][c] == 1:
                    if find(r*self.v_cols+c) != root or find((r+1)*self.v_cols+c) != root: return False

        return True

    def solve_dfs(self):
        if not self.propagate(): return None
        if self.is_solved(): return self.get_solution()

        # Heuristic: MRV on clues (Minimum Remaining Values)
        best_edge = None
        min_unk = 100
        for r in range(self.rows):
            for c in range(self.cols):
                if self.clues[r][c] is None: continue
                edges = self.get_cell_edges(r, c)
                unk = sum(1 for t,e_r,e_c in edges if (self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)) == 0)
                if 0 < unk < min_unk:
                    min_unk = unk
                    for t,e_r,e_c in edges:
                        if (self.get_h(e_r,e_c) if t=='h' else self.get_v(e_r,e_c)) == 0:
                            best_edge = (t, e_r, e_c)
                            break

        if not best_edge:
            for r in range(self.h_rows):
                for c in range(self.h_cols):
                    if self.h_state[r][c] == 0: best_edge = ('h', r, c); break
                if best_edge: break
            if not best_edge:
                for r in range(self.v_rows):
                    for c in range(self.v_cols):
                        if self.v_state[r][c] == 0: best_edge = ('v', r, c); break
                    if best_edge: break

        if not best_edge: return None

        t, er, ec = best_edge
        saved_h = [x[:] for x in self.h_state]
        saved_v = [x[:] for x in self.v_state]

        # Try Line (1)
        if t == 'h': self.h_state[er][ec] = 1
        else: self.v_state[er][ec] = 1
        res = self.solve_dfs()
        if res: return res

        self.h_state = saved_h
        self.v_state = saved_v

        # Try NoLine (2)
        if t == 'h': self.h_state[er][ec] = 2
        else: self.v_state[er][ec] = 2
        res = self.solve_dfs()
        if res: return res

        return None

    def get_solution(self):
        adj = {}
        for r in range(self.h_rows):
            for c in range(self.h_cols):
                if self.h_state[r][c] == 1:
                    u, v = (r,c), (r,c+1)
                    adj.setdefault(u, []).append(v)
                    adj.setdefault(v, []).append(u)
        for r in range(self.v_rows):
            for c in range(self.v_cols):
                if self.v_state[r][c] == 1:
                    u, v = (r,c), (r+1,c)
                    adj.setdefault(u, []).append(v)
                    adj.setdefault(v, []).append(u)
        if not adj: return []
        start = next(iter(adj))
        path = [start]
        curr, prev = start, None
        while True:
            nxt = None
            for n in adj[curr]:
                if n != prev: nxt = n; break
            if nxt is None: break
            path.append(nxt)
            prev, curr = curr, nxt
            if curr == start: break
        return path

def solve(observation):
    solver = SlitherlinkSolver(observation['data'])
    sol = solver.solve_dfs()
    return sol if sol else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
