import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    """
    Generalized Sudoku Solver using Constraint Satisfaction Problem (CSP) techniques.
    Implements human-like logic: Constraint Propagation (Naked/Hidden Singles) and 
    Backtracking with Minimum Remaining Values (MRV) heuristic.
    """
    data = observation['data']
    unit_str = observation['unit']

    # Parse unit dimensions (e.g., '3x3' -> 3, 3; '3' -> 3, 3)
    if 'x' in unit_str:
        r_unit, c_unit = map(int, unit_str.split('x'))
    else:
        r_unit = c_unit = int(unit_str)

    rows = len(data)
    cols = len(data[0]) if rows > 0 else 0
    N = rows  # Assuming square grid N x N with values 1..N

    # Precompute Units (Rows, Columns, Boxes)
    all_units = []

    # Row units
    for r in range(rows):
        all_units.append([(r, c) for c in range(cols)])

    # Column units
    for c in range(cols):
        all_units.append([(r, c) for r in range(rows)])

    # Box units
    num_box_rows = rows // r_unit
    num_box_cols = cols // c_unit
    for br in range(num_box_rows):
        for bc in range(num_box_cols):
            box = []
            for dr in range(r_unit):
                for dc in range(c_unit):
                    box.append((br * r_unit + dr, bc * c_unit + dc))
            all_units.append(box)

    # Map each cell to the list of units it belongs to
    cell_units = { (r, c): [] for r in range(rows) for c in range(cols) }
    for unit in all_units:
        for cell in unit:
            cell_units[cell].append(unit)

    # Map each cell to its set of peers (cells in same row, col, or box)
    all_peers = { (r, c): set() for r in range(rows) for c in range(cols) }
    for r in range(rows):
        for c in range(cols):
            peers = set()
            for unit in cell_units[(r, c)]:
                for cell in unit:
                    if cell != (r, c):
                        peers.add(cell)
            all_peers[(r, c)] = peers

    # Initialize possibilities for each cell (1..N)
    possibilities = { (r, c): set(range(1, N + 1)) for r in range(rows) for c in range(cols) }

    # --- Constraint Propagation Functions ---

    def assign(r, c, value, poss):
        """
        Assign a value to a cell and eliminate it from peers.
        Returns False if a contradiction is detected.
        """
        if value not in poss[(r, c)]:
            return False  # Value already eliminated

        # Eliminate all other values from this cell
        for val in list(poss[(r, c)]):
            if val != value:
                if not eliminate(r, c, val, poss):
                    return False
        return True

    def eliminate(r, c, value, poss):
        """
        Eliminate a value from a cell's possibilities.
        Triggers propagation: Naked Singles and Hidden Singles.
        Returns False if a contradiction is detected.
        """
        if value not in poss[(r, c)]:
            return True  # Already eliminated

        poss[(r, c)].remove(value)

        # 1. Naked Single: If only 1 value remains, assign it (propagate to peers)
        if len(poss[(r, c)]) == 0:
            return False  # Contradiction: No values left
        elif len(poss[(r, c)]) == 1:
            val = next(iter(poss[(r, c)]))
            for pr, pc in all_peers[(r, c)]:
                if not eliminate(pr, pc, val, poss):
                    return False

        # 2. Hidden Single: Check units for the eliminated value
        # If 'value' can only go in one place in a unit, assign it there.
        # If 'value' has no place in a unit, contradiction.
        for unit in cell_units[(r, c)]:
            places = [cell for cell in unit if value in poss[cell]]
            if len(places) == 0:
                return False  # Contradiction: Value has nowhere to go in this unit
            elif len(places) == 1:
                # Hidden Single found
                if not assign(places[0][0], places[0][1], value, poss):
                    return False
        return True

    # --- Initial Assignment of Given Values ---
    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is not None:
                if not assign(r, c, val, possibilities):
                    return "No Solution"

    # --- Search with Heuristics ---

    def search(poss):
        """
        Depth-first search with MRV (Minimum Remaining Values) heuristic.
        """
        # Check if solved (all cells have 1 possibility)
        if all(len(poss[(r, c)]) == 1 for r in range(rows) for c in range(cols)):
            return [[next(iter(poss[(r, c)])) for c in range(cols)] for r in range(rows)]

        # Check for contradictions (any cell has 0 possibilities)
        if any(len(poss[(r, c)]) == 0 for r in range(rows) for c in range(cols)):
            return None

        # Heuristic: MRV - Choose the unsolved cell with the fewest possibilities
        min_len = N + 1
        best_cell = None
        for r in range(rows):
            for c in range(cols):
                l = len(poss[(r, c)])
                if 1 < l < min_len:
                    min_len = l
                    best_cell = (r, c)

        if best_cell is None:
            return None  # Should not happen if checks above pass

        br, bc = best_cell

        # Try values in sorted order (deterministic)
        # Optimization: Least Constraining Value could be used here, but sorting is sufficient for standard puzzles
        for val in sorted(poss[(br, bc)]):
            new_poss = {k: v.copy() for k, v in poss.items()}
            if assign(br, bc, val, new_poss):
                res = search(new_poss)
                if res:
                    return res
        return None

    result = search(possibilities)
    return result if result else "No Solution"

