                       self.get_h(r, c) != 1 and self.get_v(r, c) != 1:
                        opts.append(('L', 'U'))
                    if self.get_h(r, c-1) != 0 and self.get_v(r, c) != 0 and \
                       self.get_h(r, c) != 1 and self.get_v(r-1, c) != 1:
                        opts.append(('L', 'D'))
                    if self.get_h(r, c) != 0 and self.get_v(r-1, c) != 0 and \
                       self.get_h(r, c-1) != 1 and self.get_v(r, c) != 1:
                        opts.append(('R', 'U'))
                    if self.get_h(r, c) != 0 and self.get_v(r, c) != 0 and \
                       self.get_h(r, c-1) != 1 and self.get_v(r-1, c) != 1:
                        opts.append(('R', 'D'))

                    if len(opts) == 0: return False
                    if len(opts) == 1:
                        op = opts[0]
                        if op[0] == 'L':
                            if self.get_h(r, c-1) == 2:
                                if not self.set_h(r, c-1, 1): return False
                                changed = True
                            if self.get_h(r, c) == 2:
                                if not self.set_h(r, c, 0): return False
                                changed = True
                        else:
                            if self.get_h(r, c) == 2:
                                if not self.set_h(r, c, 1): return False
                                changed = True
                            if self.get_h(r, c-1) == 2:
                                if not self.set_h(r, c-1, 0): return False
                                changed = True

                        if op[1] == 'U':
                            if self.get_v(r-1, c) == 2:
                                if not self.set_v(r-1, c, 1): return False
                                changed = True
                            if self.get_v(r, c) == 2:
                                if not self.set_v(r, c, 0): return False
                                changed = True
                        else:
                            if self.get_v(r, c) == 2:
                                if not self.set_v(r, c, 1): return False
                                changed = True
                            if self.get_v(r-1, c) == 2:
                                if not self.set_v(r-1, c, 0): return False
                                changed = True

                        d1 = (0, -1) if op[0]=='L' else (0, 1)
                        d2 = (-1, 0) if op[1]=='U' else (1, 0)
                        if not self.apply_length_b(r, c, k, d1, d2): return False
                        changed = True

        return True

    def apply_length_w(self, r, c, k, orientation):
        if orientation == 'H':
            if c-1 >= 0 and c-2 >= 0:
                if not self.set_h(r, c-2, 0): return False
            if c+1 < self.C and c+2 < self.C:
                if not self.set_h(r, c+1, 0): return False
        elif orientation == 'V':
            if r-1 >= 0 and r-2 >= 0:
                if not self.set_v(r-2, c, 0): return False
            if r+1 < self.R and r+2 < self.R:
                if not self.set_v(r+1, c, 0): return False
        return True

    def apply_length_b(self, r, c, k, d1, d2):
        if k == 2:
            nr1, nc1 = r + d1[0], c + d1[1]
            nnr1, nnc1 = nr1 + d1[0], nc1 + d1[1]
            if 0 <= nnr1 < self.R and 0 <= nnc1 < self.C:
                if d1[0] == 0:
                    if not self.set_h(nr1, min(nc1, nnc1), 0): return False
                else:
                    if not self.set_v(min(nr1, nnr1), nc1, 0): return False

            nr2, nc2 = r + d2[0], c + d2[1]
            nnr2, nnc2 = nr2 + d2[0], nc2 + d2[1]
            if 0 <= nnr2 < self.R and 0 <= nnc2 < self.C:
                if d2[0] == 0:
                    if not self.set_h(nr2, min(nc2, nnc2), 0): return False
                else:
                    if not self.set_v(min(nr2, nnr2), nc2, 0): return False
        return True

    def is_valid_final(self):
        for (r, c) in self.clues:
            if self.degree(r, c) != 2:
                return False

        start = None
        for r in range(self.R):
            for c in range(self.C):
                if self.degree(r, c) == 2:
                    start = (r, c)
                    break
            if start: break

        if not start: return False

        path = []
        curr = start
        prev = None
        while True:
            path.append(curr)
            r, c = curr
            neighbors = []
            if self.get_h(r, c-1) == 1: neighbors.append((r, c-1))
            if self.get_h(r, c) == 1: neighbors.append((r, c+1))
            if self.get_v(r-1, c) == 1: neighbors.append((r-1, c))
            if self.get_v(r, c) == 1: neighbors.append((r+1, c))

            nxt = None
            for n in neighbors:
                if n != prev:
                    nxt = n
                    break

            if nxt == start:
                break
            if nxt is None:
                return False
            prev = curr
            curr = nxt

        for (r, c) in self.clues:
            if (r, c) not in path:
                return False

        total_on = 0
        for r in range(self.R):
            for c in range(self.C-1):
                if self.H[r][c] == 1: total_on += 1
        for r in range(self.R-1):
            for c in range(self.C):
                if self.V[r][c] == 1: total_on += 1

        if total_on != len(path):
            return False

        return True

    def get_path(self):
        start = None
        for r in range(self.R):
            for c in range(self.C):
                if self.degree(r, c) == 2:
                    start = (r, c)
                    break
            if start: break
        if not start: return []

        path = [start]
        curr = start
        prev = None
        while True:
            r, c = curr
            neighbors = []
            if self.get_h(r, c-1) == 1: neighbors.append((r, c-1))
            if self.get_h(r, c) == 1: neighbors.append((r, c+1))
            if self.get_v(r-1, c) == 1: neighbors.append((r-1, c))
            if self.get_v(r, c) == 1: neighbors.append((r+1, c))

            nxt = None
            for n in neighbors:
                if n != prev:
                    nxt = n
                    break
            if nxt == start:
                path.append(start)
                break
            prev = curr
            curr = nxt
        return path

    def search(self):
        if not self.propagate():
            return None

        for r in range(self.R):
            for c in range(self.C-1):
                if self.H[r][c] == 2:
                    sH = [x[:] for x in self.H]
                    sV = [x[:] for x in self.V]
                    self.H[r][c] = 1
                    res = self.search()
                    if res: return res
                    self.H = sH
                    self.V = sV

                    self.H[r][c] = 0
                    res = self.search()
                    if res: return res
                    return None

        for r in range(self.R-1):
            for c in range(self.C):
                if self.V[r][c] == 2:
                    sH = [x[:] for x in self.H]
                    sV = [x[:] for x in self.V]
                    self.V[r][c] = 1
                    res = self.search()
                    if res: return res
                    self.H = sH
                    self.V = sV

                    self.V[r][c] = 0
                    res = self.search()
                    if res: return res
                    return None

        if self.is_valid_final():
            return self.get_path()
        return None

def solve(obs):
    solver = Solver(obs['data'])
    path = solver.search()
    if path:
        return str(path)
    return "No Solution"

