            r1, r2 = grid[c1[0]][c1[1]], grid[c2[0]][c2[1]]
            if r1 == rid and r2 == rid:
                return 0 # Internal
            return 1 # Crossing

        candidates.sort(key=sort_key)

        if not candidates:
