def solve(observation):
    # Parse input
    grid = [row[:] for row in observation['data']]
    unit_str = observation['unit']

    # Determine grid size and subgrid dimensions
    N = len(grid)
    if 'x' in unit_str:
        box_h, box_w = map(int, unit_str.split('x'))
    else:
        box_h = box_w = int(unit_str)

    # Initialize possibilities for each cell
    # possibilities[r][c] is a set of valid numbers
    possibilities = [[set(range(1, N + 1)) if grid[r][c] is None else set() for c in range(N)] for r in range(N)]

    # Helper to get box coordinates
    def get_box_start(r, c):
        return (r // box_h) * box_h, (c // box_w) * box_w

    # Initial constraint propagation based on given numbers
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                val = grid[r][c]
                # Remove this value from row, col, and box possibilities
                for k in range(N):
                    possibilities[r][k].discard(val)
                    possibilities[k][c].discard(val)

                br, bc = get_box_start(r, c)
                for dr in range(box_h):
                    for dc in range(box_w):
                        possibilities[br + dr][bc + dc].discard(val)
                possibilities[r][c] = set() # Empty set for fixed cells

    def is_solved():
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    return False
        return True

    def propagate():
        # Returns True if any change was made
        changed = True
        while changed:
            changed = False

            # 1. Naked Singles: If a cell has only 1 possibility, fill it
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is None and len(possibilities[r][c]) == 1:
                        val = possibilities[r][c].pop()
                        grid[r][c] = val
                        changed = True

                        # Update peers
                        for k in range(N):
                            possibilities[r][k].discard(val)
                            possibilities[k][c].discard(val)

                        br, bc = get_box_start(r, c)
                        for dr in range(box_h):
                            for dc in range(box_w):
                                possibilities[br + dr][bc + dc].discard(val)

            if changed: continue

            # 2. Hidden Singles: If a value can only go in one cell in a unit
            # Check Rows
            for r in range(N):
                counts = {}
                for c in range(N):
                    if grid[r][c] is None:
                        for val in possibilities[r][c]:
                            counts.setdefault(val, []).append(c)
                for val, cols in counts.items():
                    if len(cols) == 1:
                        c = cols[0]
                        grid[r][c] = val
                        possibilities[r][c] = set()
                        changed = True
                        # Update peers
                        for k in range(N):
                            if k != c: possibilities[r][k].discard(val)
                            possibilities[k][c].discard(val)
                        br, bc = get_box_start(r, c)
                        for dr in range(box_h):
                            for dc in range(box_w):
                                if not (br + dr == r and bc + dc == c):
                                    possibilities[br + dr][bc + dc].discard(val)

            if changed: continue

            # Check Cols
            for c in range(N):
                counts = {}
                for r in range(N):
                    if grid[r][c] is None:
                        for val in possibilities[r][c]:
                            counts.setdefault(val, []).append(r)
                for val, rows in counts.items():
                    if len(rows) == 1:
                        r = rows[0]
                        grid[r][c] = val
                        possibilities[r][c] = set()
                        changed = True
                        # Update peers
                        for k in range(N):
                            if k != r: possibilities[k][c].discard(val)
                            possibilities[r][k].discard(val)
                        br, bc = get_box_start(r, c)
                        for dr in range(box_h):
                            for dc in range(box_w):
                                if not (br + dr == r and bc + dc == c):
                                    possibilities[br + dr][bc + dc].discard(val)

            if changed: continue

            # Check Boxes
            for br in range(0, N, box_h):
                for bc in range(0, N, box_w):
                    counts = {}
                    for dr in range(box_h):
                        for dc in range(box_w):
                            r, c = br + dr, bc + dc
                            if grid[r][c] is None:
                                for val in possibilities[r][c]:
                                    counts.setdefault(val, []).append((r, c))
                    for val, cells in counts.items():
                        if len(cells) == 1:
                            r, c = cells[0]
                            grid[r][c] = val
                            possibilities[r][c] = set()
                            changed = True
                            # Update peers
                            for k in range(N):
                                possibilities[r][k].discard(val)
                                possibilities[k][c].discard(val)
                            for dr in range(box_h):
                                for dc in range(box_w):
                                    possibilities[br + dr][bc + dc].discard(val)

            if changed: continue

        return changed

    # Run initial propagation
    propagate()

    if is_solved():
        return grid

    # Backtracking with MRV (Minimum Remaining Values)
    # Find the empty cell with the fewest possibilities
    min_possibilities = N + 1
    best_cell = None

    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
