                # If has_path(u, v) is true, adding edge creates cycle.
                # We check validity in is_valid_state (subcycles).
                # So we can just try.

                edges[best_edge] = 1
                node_degree[u] += 1
                node_degree[v] += 1

                changes = propagate()
                if is_valid_state():
                    sol = backtrack(best_idx + 1)
                    if sol: return sol
                undo_propagate(changes)

                edges[best_edge] = 0
                node_degree[u] -= 1
                node_degree[v] -= 1

        # Try Absent
        unknown_u = sum(1 for n in get_neighbors(u[0], u[1]) if edges[get_edge_key(u, n)] == 0)
        unknown_v = sum(1 for n in get_neighbors(v[0], v[1]) if edges[get_edge_key(v, n)] == 0)

        skip_absent = False
        if node_degree[u] + unknown_u - 1 < 2 and (u in clues or node_degree[u] > 0): skip_absent = True
        if node_degree[v] + unknown_v - 1 < 2 and (v in clues or node_degree[v] > 0): skip_absent = True

        if not skip_absent:
            edges[best_edge] = 2
            changes = propagate()
            if is_valid_state():
                sol = backtrack(best_idx + 1)
                if sol: return sol
            undo_propagate(changes)
            edges[best_edge] = 0

        return None

    # Initial propagation
    changes = propagate()
    if not is_valid_state():
        return "No Solution"

    sol = backtrack(0)
    if sol:
        return sol
    return "No Solution"

