import sys

# Increase recursion depth to handle deep paths in larger grids if necessary
sys.setrecursionlimit(5000)

def solve(obs):
    # Parse the grid from observation
    grid = obs['data']
    if not grid:
        return "No Solution"

    R = len(grid)
    C = len(grid[0])

    # Identify all clues and store them in a map for O(1) access
    clues = []
    clue_map = {} 
    for r in range(R):
        for c in range(C):
            val = grid[r][c]
            if val:
                # val is like 'W3' or 'B5'
                type_char = val[0] 
                k = int(val[1:])
                clues.append((r, c))
                clue_map[(r, c)] = (type_char, k)

    if not clues:
        # If no clues, any loop is valid? But problem implies clues exist.
        # Return a minimal loop or indicate no solution based on strict rules.
        # Assuming at least one clue is required to define the loop.
        return "No Solution"

    # Directions: Up, Down, Left, Right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                yield (nr, nc), (dr, dc)

    # Check if p_prev -> p_curr -> p_next is a straight line
    def is_straight(p_prev, p_curr, p_next):
        v1 = (p_curr[0] - p_prev[0], p_curr[1] - p_prev[1])
        v2 = (p_next[0] - p_curr[0], p_next[1] - p_curr[1])
        return v1 == v2

    # Check if p_prev -> p_curr -> p_next is a turn
    def is_turn(p_prev, p_curr, p_next):
        return not is_straight(p_prev, p_curr, p_next)

    # Verify the number constraint for a completed cycle
    def check_number_constraints(cycle):
        n = len(cycle)
        # Map node to index for O(1) lookup
        node_idx = {node: i for i, node in enumerate(cycle)}

        for (r, c), (ctype, k) in clue_map.items():
            if (r, c) not in node_idx:
                return False 

            idx = node_idx[(r, c)]
            prev_node = cycle[(idx - 1) % n]
            next_node = cycle[(idx + 1) % n]
            curr_node = (r, c)

            # 1. Check Straight/Turn consistency
            if ctype == 'W':
                if not is_straight(prev_node, curr_node, next_node):
                    return False
            else: # 'B'
                if not is_turn(prev_node, curr_node, next_node):
                    return False

            # 2. Check Number constraint (sum of segment lengths)
            def get_segment_length(start_node, direction_node):
                length = 0
                curr = start_node
                nxt = direction_node

                while True:
                    length += 1
                    # Find neighbors of nxt in the cycle
                    n_idx = node_idx[nxt]
                    n_prev = cycle[(n_idx - 1) % n]
                    n_next = cycle[(n_idx + 1) % n]

                    # Identify the 'other' neighbor (the one that is not curr)
                    other = n_prev if n_prev != curr else n_next

                    # If nxt is a turn, the segment ends here
                    if is_turn(curr, nxt, other):
                        break

                    # Otherwise, continue straight
                    curr = nxt
                    nxt = other

                return length

            len1 = get_segment_length(curr_node, next_node)
            len2 = get_segment_length(curr_node, prev_node)

            if len1 + len2 != k:
                return False

        return True

    start_node = clues[0]
    start_r, start_c = start_node
    found_solution = None

    # We try to build a path starting from start_node.
    # Since it's a cycle, we pick a first neighbor and try to close the loop back to start_node.

    # Get valid first steps
    first_steps = []
    for nb, d in get_neighbors(start_r, start_c):
        first_steps.append(nb)

    # DFS function
    def dfs(curr, path, visited):
        nonlocal found_solution
        if found_solution:
            return

        # Try to close the loop if curr is adjacent to start_node
        # We check adjacency explicitly
        for nb, d in get_neighbors(curr[0], curr[1]):
            if nb == start_node:
                # Potential cycle closure
                # Minimum cycle length in grid is 4
                if len(path) < 4:
                    continue

                # Check constraint at start_node (since we are closing the loop)
                # The loop would be ... -> curr -> start_node -> path[1] -> ...
                p_prev = curr
                p_curr = start_node
                p_next = path[1]

                valid_close = True
                if start_node in clue_map:
                    ctype, _ = clue_map[start_node]
                    if ctype == 'W':
                        if not is_straight(p_prev, p_curr, p_next):
                            valid_close = False
                    else:
                        if not is_turn(p_prev, p_curr, p_next):
                            valid_close = False

                if valid_close:
                    # Check if all clues are visited
                    all_visited = True
                    for cl in clues:
                        if cl not in visited:
                            all_visited = False
                            break

                    if all_visited:
                        # Check number constraints
                        if check_number_constraints(path):
                            found_solution = list(path)
                            return
            elif nb not in visited:
                # Continue path
                # Check constraint at curr (if curr is a clue)
                # We are moving curr -> nb. Previous was path[-2].
                valid_move = True
                if curr in clue_map:
                    ctype, _ = clue_map[curr]
                    p_prev = path[-2]
                    p_curr = curr
                    p_next = nb

                    if ctype == 'W':
                        if not is_straight(p_prev, p_curr, p_next):
                            valid_move = False
                    else: # 'B'
                        if not is_turn(p_prev, p_curr, p_next):
                            valid_move = False

                if valid_move:
                    visited.add(nb)
                    path.append(nb)
                    dfs(nb, path, visited)
                    if found_solution:
                        return
                    path.pop()
                    visited.remove(nb)

    # Try each possible first step
    for first_nb in first_steps:
        path = [start_node, first_nb]
        visited = {start_node, first_nb}
        dfs(first_nb, path, visited)
        if found_solution:
            break

    if found_solution:
        # Return the closed loop (append start node at the end)
        return found_solution + [found_solution[0]]
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
