import sys
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    H = len(data)
    W = len(data[0])

    # h[r][c] is horizontal edge between (r, c) and (r, c+1). r in 0..H, c in 0..W-1
    # v[r][c] is vertical edge between (r, c) and (r+1, c). r in 0..H-1, c in 0..W
    # State: 0=Unknown, 1=Line, -1=No Line
    h = [[0] * W for _ in range(H + 1)]
    v = [[0] * (W + 1) for _ in range(H)]

    parent = list(range((H + 1) * (W + 1)))
    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    def idx(r, c):
        return r * (W + 1) + c

    def get_cell_edges(r, c):
        return [('h', r, c), ('h', r + 1, c), ('v', r, c), ('v', r, c + 1)]

    def get_vertex_edges(r, c):
        edges = []
        if r > 0: edges.append(('v', r - 1, c))
        if r < H: edges.append(('v', r, c))
        if c > 0: edges.append(('h', r, c - 1))
        if c < W: edges.append(('h', r, c))
        return edges

    def get_state():
        return ([row[:] for row in h], [row[:] for row in v], parent[:])

    def set_state(state):
        nonlocal h, v, parent
        h, v, parent = state[0], state[1], state[2]

    def propagate():
        changed = True
        while changed:
            changed = False
            # Clue constraints
            for r in range(H):
                for c in range(W):
                    clue = data[r][c]
                    if clue is None: continue
                    edges = get_cell_edges(r, c)
                    lines = 0
                    unknowns = 0
                    for typ, er, ec in edges:
                        val = h[er][ec] if typ=='h' else v[er][ec]
                        if val == 1: lines += 1
                        elif val == 0: unknowns += 1

                    if lines > clue: return False
                    if lines + unknowns < clue: return False

                    if lines == clue:
                        for typ, er, ec in edges:
                            val = h[er][ec] if typ=='h' else v[er][ec]
                            if val == 0:
                                if typ=='h': h[er][ec] = -1
                                else: v[er][ec] = -1
                                changed = True
                    elif lines + unknowns == clue:
                        for typ, er, ec in edges:
                            val = h[er][ec] if typ=='h' else v[er][ec]
                            if val == 0:
                                u = idx(er, ec)
                                v_idx = idx(er + (0 if typ=='h' else 1), ec + (1 if typ=='h' else 0))
                                if find(u) == find(v_idx):
                                    return False
                                if typ=='h': h[er][ec] = 1
                                else: v[er][ec] = 1
                                union(u, v_idx)
                                changed = True

            # Vertex constraints
            for r in range(H + 1):
                for c in range(W + 1):
                    edges = get_vertex_edges(r, c)
                    lines = 0
                    unknowns = 0
                    no_lines = 0
                    for typ, er, ec in edges:
                        val = h[er][ec] if typ=='h' else v[er][ec]
                        if val == 1: lines += 1
                        elif val == 0: unknowns += 1
                        elif val == -1: no_lines += 1

                    if lines > 2: return False
                    if lines == 2:
                        for typ, er, ec in edges:
                            val = h[er][ec] if typ=='h' else v[er][ec]
                            if val == 0:
                                if typ=='h': h[er][ec] = -1
                                else: v[er][ec] = -1
                                changed = True
                    elif lines == 1 and unknowns == 1:
                        for typ, er, ec in edges:
                            val = h[er][ec] if typ=='h' else v[er][ec]
                            if val == 0:
                                u = idx(er, ec)
                                v_idx = idx(er + (0 if typ=='h' else 1), ec + (1 if typ=='h' else 0))
                                if find(u) == find(v_idx): return False
                                if typ=='h': h[er][ec] = 1
                                else: v[er][ec] = 1
                                union(u, v_idx)
                                changed = True
                    elif lines == 0 and no_lines == 3:
                        for typ, er, ec in edges:
                            val = h[er][ec] if typ=='h' else v[er][ec]
                            if val == 0:
                                if typ=='h': h[er][ec] = -1
                                else: v[er][ec] = -1
                                changed = True
        return True

    def count_unknowns():
        cnt = 0
        for r in range(H + 1):
            for c in range(W):
                if h[r][c] == 0: cnt += 1
        for r in range(H):
            for c in range(W + 1):
                if v[r][c] == 0: cnt += 1
        return cnt

    def search():
        if not propagate(): return None

        rem = count_unknowns()
        if rem == 0:
            edges_list = []
            for r in range(H + 1):
                for c in range(W):
                    if h[r][c] == 1: edges_list.append(('h', r, c))
            for r in range(H):
                for c in range(W + 1):
                    if v[r][c] == 1: edges_list.append(('v', r, c))

            if not edges_list: return None

            start = None
            for r in range(H + 1):
                for c in range(W + 1):
                    deg = 0
                    for typ, er, ec in get_vertex_edges(r, c):
                        if (h[er][ec] if typ=='h' else v[er][ec]) == 1: deg += 1
                    if deg == 2:
                        start = (r, c)
                        break
                if start: break

            if not start: return None

            visited = set()
            curr = start
            path = [curr]
            while True:
                found_next = False
                for typ, er, ec in get_vertex_edges(curr[0], curr[1]):
                    if (h[er][ec] if typ=='h' else v[er][ec]) == 1:
                        eid = (typ, er, ec)
                        if eid in visited: continue
                        visited.add(eid)
                        if typ == 'h':
                            nxt = (er, ec + 1) if ec == curr[1] else (er, ec)
                        else:
                            nxt = (er + 1, ec) if er == curr[0] else (er, ec)
                        curr = nxt
                        path.append(curr)
                        found_next = True
                        break
                if not found_next: break
                if curr == start: break

            if len(visited) != len(edges_list): return None
            return path

        best = None
        min_u = 100
        for r in range(H):
            for c in range(W):
                if data[r][c] is not None:
                    edges = get_cell_edges(r, c)
                    u_count = 0
                    first_unknown = None
                    for typ, er, ec in edges:
                        val = h[er][ec] if typ=='h' else v[er][ec]
                        if val == 0:
                            u_count += 1
                            if not first_unknown: first_unknown = (typ, er, ec)
                    if 0 < u_count < min_u:
                        min_u = u_count
                        best = first_unknown
                        if min_u == 1: break
            if best and min_u == 1: break

        if not best:
            for r in range(H + 1):
                for c in range(W):
                    if h[r][c] == 0:
                        best = ('h', r, c)
                        break
                if best: break
            if not best:
                for r in range(H):
                    for c in range(W + 1):
                        if v[r][c] == 0:
                            best = ('v', r, c)
                            break
                    if best: break

        if not best: return None

        typ, er, ec = best
        saved = get_state()

        u = idx(er, ec)
        v_idx = idx(er + (0 if typ=='h' else 1), ec + (1 if typ=='h' else 0))
        is_cycle = (find(u) == find(v_idx))

        if not is_cycle or (is_cycle and rem == 1):
            if typ == 'h': h[er][ec] = 1
            else: v[er][ec] = 1
            if not is_cycle: union(u, v_idx)

            res = search()
            if res: return res
            set_state(saved)

        if typ == 'h': h[er][ec] = -1
        else: v[er][ec] = -1

        res = search()
        if res: return res

        set_state(saved)
        return None

    res = search()
    if res:
        return res
    return "No Solution"

