                                return False

                    elif clue == 'W':
                        # Must go straight: 2 collinear active edges
                        # Turn at least once in prev or next step

                        if len(active) > 2: return False
                        if len(active) == 2:
                            if (active[0] + 2) % 4 != active[1]: # Perpendicular
                                return False # Invalid for W

                            # Check "Turn prev/next"
                            # If Vertical (0, 2)
                            if active[0] in [0, 2]:
                                # Check Up neighbor (r-1, c) and Down neighbor (r+1, c)
                                # If (r-1, c) has Up active (from r-2), then (r+1, c) cannot have Down active (to r+2)
                                # And vice versa.
                                # Actually, simpler: If (r-1, c) is straight (Up/Down active), then (r+1, c) must turn.
                                # But we don't know if (r-1, c) is straight yet.
                                # We check: If Edge(r-2, c)-(r-1, c) is Active AND Edge(r+1, c)-(r+2, c) is Active -> Fail.
                                pass 

                        elif len(active) == 1:
                            d1 = active[0]
                            opp = (d1 + 2) % 4
                            # Must be collinear, so opp must be active.
                            if self.edges[r][c][opp] == 2: return False
                            if self.edges[r][c][opp] == 0:
                                if not self.set_edge(r, c, opp, 1): return False
                                changed = True
                            # Perpendiculars must be inactive
                            for pd in [ (d1+1)%4, (d1+3)%4 ]:
                                if self.edges[r][c][pd] == 1: return False
                                if self.edges[r][c][pd] == 0:
                                    if not self.set_edge(r, c, pd, 2): return False
                                    changed = True

                        elif len(active) == 0:
                            if len(possible) == 2:
                                # Must be collinear
                                if (possible[0] + 2) % 4 == possible[1]:
                                    for d in possible:
                                        if not self.set_edge(r, c, d, 1): return False
                                    changed = True
                                elif len(possible) == 2:
                                    # Only perpendicular left? Impossible for W.
                                    return False

            # 2. Degree Constraints
            for r in range(self.H):
                for c in range(self.W):
                    deg = self.deg[r][c]
                    if deg > 2: return False
                    if deg == 2:
                        # All unknowns must be inactive
                        for d in range(4):
                            if self.edges[r][c][d] == 0:
                                if not self.set_edge(r, c, d, 2): return False
                                changed = True
                    elif deg == 1:
                        # If only 1 unknown left, it must be active
                        unknowns = [d for d in range(4) if self.edges[r][c][d] == 0]
                        if len(unknowns) == 1:
                            if not self.set_edge(r, c, unknowns[0], 1): return False
                            changed = True
                        elif len(unknowns) == 0:
                            # Degree 1 and no unknowns -> Dead end (unless it's the only edge? No, loop needs 2)
                            # But non-clue nodes can be degree 0.
                            # If degree 1, it MUST become 2.
                            # So if no unknowns, fail.
                            # Wait, is it possible for a node to be degree 1 temporarily? Yes.
                            # But if no unknowns left, it's stuck at 1. Fail.
                            # Unless the node is not part of the loop?
                            # But if deg=1, it IS part of the loop.
                            return False

            # 3. Small Loop Detection (Union Find)
            # If adding an edge connects two nodes already in same component, it's a cycle.
            # We check this in set_edge? No, set_edge just unions.
            # We need to check if a cycle is formed that doesn't include all clues.
            # But we don't know the final set of edges.
            # Heuristic: If a cycle is formed, and the number of active edges in that component == number of nodes in that component,
            # and it doesn't include all clues, then it's a small loop -> Fail.

            # Let's count components and edges/nodes
            comp_nodes = {}
            comp_edges = {}
            for r in range(self.H):
                for c in range(self.W):
                    if self.deg[r][c] > 0:
                        root = self.find(self.get_node(r, c))
                        comp_nodes.setdefault(root, 0)
                        comp_nodes[root] += 1

            # Count edges per component
            # Each active edge is counted twice in deg sum.
            # So sum(deg)/2 = num_edges.
            comp_deg_sum = {}
            for r in range(self.H):
                for c in range(self.W):
                    if self.deg[r][c] > 0:
                        root = self.find(self.get_node(r, c))
                        comp_deg_sum.setdefault(root, 0)
                        comp_deg_sum[root] += self.deg[r][c]

            for root in comp_nodes:
                num_nodes = comp_nodes[root]
                num_edges = comp_deg_sum[root] // 2
                if num_edges == num_nodes: # Cycle
                    # Check if this component has all clues
                    has_all_clues = True
                    total_clues = 0
                    comp_clues = 0
                    for r in range(self.H):
                        for c in range(self.W):
                            if self.grid[r][c] is not None:
                                total_clues += 1
                                if self.find(self.get_node(r, c)) == root:
                                    comp_clues += 1
                    if comp_clues < total_clues:
                        return False # Small loop not covering all clues

            # 4. White Circle "Turn Prev/Next" Rule
            for r in range(self.H):
                for c in range(self.W):
                    if self.grid[r][c] == 'W':
                        # Check if Vertical
                        if self.edges[r][c][0] == 1 and self.edges[r][c][2] == 1:
                            # Vertical. Check neighbors.
                            # Up neighbor (r-1, c). If it has Up edge (from r-2), then Down neighbor (r+1, c) cannot have Down edge (to r+2).
                            if r-1 >= 0 and r+1 < self.H:
                                up_has_up = (r-2 >= 0 and self.edges[r-1][c][0] == 1)
                                down_has_down = (r+2 < self.H and self.edges[r+1][c][2] == 1)
                                if up_has_up and down_has_down:
                                    return False
                                # Propagate: If up_has_up, then down_has_down must be False (Inactive)
                                if up_has_up and r+2 < self.H:
                                    if self.edges[r+1][c][2] == 0:
                                        if not self.set_edge(r+1, c, 2, 2): return False
                                        changed = True
                                if down_has_down and r-2 >= 0:
                                    if self.edges[r-1][c][0] == 0:
                                        if not self.set_edge(r-1, c, 0, 2): return False
                                        changed = True
                        # Check if Horizontal
                        elif self.edges[r][c][1] == 1 and self.edges[r][c][3] == 1:
                            if c-1 >= 0 and c+1 < self.W:
                                left_has_left = (c-2 >= 0 and self.edges[r][c-1][3] == 1)
                                right_has_right = (c+2 < self.W and self.edges[r][c+1][1] == 1)
                                if left_has_left and right_has_right:
                                    return False
                                if left_has_left and c+2 < self.W:
                                    if self.edges[r][c+1][1] == 0:
                                        if not self.set_edge(r, c+1, 1, 2): return False
                                        changed = True
                                if right_has_right and c-2 >= 0:
                                    if self.edges[r][c-1][3] == 0:
                                        if not self.set_edge(r, c-1, 3, 2): return False
                                        changed = True

        return True

    def is_solved(self):
        # 1. All clues must be visited (degree 2)
        for r in range(self.H):
            for c in range(self.W):
                if self.grid[r][c] is not None:
                    if self.deg[r][c] != 2:
                        return False

        # 2. Single loop covering all clues
        # Check connectivity of all active nodes
        active_nodes = []
        for r in range(self.H):
            for c in range(self.W):
                if self.deg[r][c] > 0:
                    active_nodes.append((r, c))

        if not active_nodes:
            return False # No loop

        # Check if all active nodes are in one component
        root = self.find(self.get_node(active_nodes[0][0], active_nodes[0][1]))
        for r, c in active_nodes[1:]:
            if self.find(self.get_node(r, c)) != root:
                return False # Disconnected

        # Check if it's a single cycle (num_edges == num_nodes)
        # Since degree is 2 for all active nodes (if any degree 1, propagate would have failed or caught it)
        # Wait, propagate ensures degree <= 2.
        # Are there any degree 1 nodes?
        for r, c in active_nodes:
            if self.deg[r][c] != 2:
                return False # Loose ends

        # Check if all clues are in this component
        for r in range(self.H):
            for c in range(self.W):
                if self.grid[r][c] is not None:
                    if self.find(self.get_node(r, c)) != root:
                        return False

        return True

    def solve(self):
        if not self.propagate():
            return None

        if self.is_solved():
            return self.get_path()

        # Find unknown edge to branch
        # Heuristic: Prefer edges near clues
        best_edge = None
        best_score = -1

        for r in range(self.H):
            for c in range(self.W):
                for d in range(4):
                    if self.edges[r][c][d] == 0:
                        score = 0
                        if self.grid[r][c] is not None: score += 10
                        nr, nc = r, c
                        if d == 0: nr -= 1
                        elif d == 1: nc += 1
                        elif d == 2: nr += 1
                        elif d == 3: nc -= 1
                        if 0 <= nr < self.H and 0 <= nc < self.W:
                            if self.grid[nr][nc] is not None: score += 10
                        if score > best_score:
                            best_score = score
                            best_edge = (r, c, d)

        if best_edge is None:
            return None # No unknowns but not solved?

        r, c, d = best_edge

        # Try Active
        saved_state = self.save_state()
        if self.set_edge(r, c, d, 1):
            if self.propagate():
                res = self.solve()
                if res: return res
        self.restore_state(saved_state)

        # Try Inactive
        saved_state = self.save_state()
        if self.set_edge(r, c, d, 2):
            if self.propagate():
                res = self.solve()
                if res: return res
        self.restore_state(saved_state)

        return None

    def save_state(self):
        return {
            'edges': copy.deepcopy(self.edges),
            'deg': copy.deepcopy(self.deg),
            'parent': copy.deepcopy(self.parent),
            'active_edges_count': self.active_edges_count
        }

    def restore_state(self, state):
        self.edges = state['edges']
        self.deg = state['deg']
        self.parent = state['parent']
        self.active_edges_count = state['active_edges_count']

    def get_path(self):
        # Find a start node (clue)
        start = None
        for r in range(self.H):
            for c in range(self.W):
                if self.grid[r][c] is not None:
                    start = (r, c)
                    break
            if start: break

        if not start:
            # No clues? Just find any active node
            for r in range(self.H):
                for c in range(self.W):
                    if self.deg[r][c] > 0:
                        start = (r, c)
                        break
                if start: break

        if not start:
            return []

        path = [start]
        curr = start
        prev = None

        while True:
            r, c = curr
            # Find next neighbor
            next_node = None
            for d in range(4):
                if self.edges[r][c][d] == 1:
                    nr, nc = r, c
                    if d == 0: nr -= 1
                    elif d == 1: nc += 1
                    elif d == 2: nr += 1
                    elif d == 3: nc -= 1

                    if (nr, nc) != prev:
                        next_node = (nr, nc)
                        break

            if next_node is None:
                break # Should not happen in a loop

            if next_node == start:
                path.append(start)
                break

            path.append(next_node)
            prev = curr
            curr = next_node

        return path

def solve(observation):
    grid = observation['data']
    solver = MasyuSolver(grid)
    path = solver.solve()
    if path:
        return path
    return "No Solution"

