            curr = start_node
            prev = None
            while True:
                r, c = curr
                neighbors = []
                if r > 0 and state.get_v(r-1, c) == 1: neighbors.append((r-1, c))
                if r < state.R - 1 and state.get_v(r, c) == 1: neighbors.append((r+1, c))
                if c > 0 and state.get_h(r, c-1) == 1: neighbors.append((r, c-1))
                if c < state.C - 1 and state.get_h(r, c) == 1: neighbors.append((r, c+1))

                next_node = None
                for n in neighbors:
                    if n != prev:
                        next_node = n
                        break

                if next_node is None:
                    break
                if next_node == start_node:
                    path.append(next_node)
                    break
                path.append(next_node)
                prev = curr
                curr = next_node

            if not path or path[0] != path[-1]:
                return None

            path_set = set(path[:-1])
            for r in range(state.R):
                for c in range(state.C):
                    if data[r][c] is not None:
                        if (r, c) not in path_set:
                            return None

            node_idx = {node: i for i, node in enumerate(path[:-1])}

            for r in range(state.R):
                for c in range(state.C):
                    if data[r][c] == 'W':
                        if (r, c) not in node_idx: return None
                        idx = node_idx[(r, c)]
                        prev_node = path[idx - 1]
                        next_node = path[(idx + 1) % len(path[:-1])]

                        def is_turn_at(node, p_prev, p_next):
                            nr, nc = node
                            pr, pc = p_prev
                            nxr, nxc = p_next
                            v1 = (nr - pr, nc - pc)
                            v2 = (nxr - nr, nxc - nc)
                            return v1[0]*v2[0] + v1[1]*v2[1] == 0

                        prev_is_turn = is_turn_at(prev_node, path[(idx - 2) % len(path[:-1])], (r, c))
                        next_is_turn = is_turn_at(next_node, (r, c), path[(idx + 2) % len(path[:-1])])

                        if not (prev_is_turn or next_is_turn):
                            return None

            for r in range(state.R):
                for c in range(state.C):
                    if data[r][c] == 'B':
                        if (r, c) not in node_idx: return None
                        idx = node_idx[(r, c)]
                        prev_node = path[idx - 1]
                        next_node = path[(idx + 1) % len(path[:-1])]

                        def is_straight_at(node, p_prev, p_next):
                            nr, nc = node
                            pr, pc = p_prev
                            nxr, nxc = p_next
                            v1 = (nr - pr, nc - pc)
                            v2 = (nxr - nr, nxc - nc)
                            return v1[0]*v2[0] + v1[1]*v2[1] != 0

                        if not is_straight_at(prev_node, path[(idx - 2) % len(path[:-1])], (r, c)):
                            return None
                        if not is_straight_at(next_node, (r, c), path[(idx + 2) % len(path[:-1])]):
                            return None

            return path

        typ, r, c = unk

        # Try ON
        new_state = state.copy()
        if typ == 'h':
            new_state.set_h(r, c, 1)
        else:
            new_state.set_v(r, c, 1)

        propagated = propagate(new_state)
        if propagated is not None:
            res = search(propagated)
            if res is not None:
                return res

        # Try OFF
        new_state = state.copy()
        if typ == 'h':
            new_state.set_h(r, c, 0)
        else:
            new_state.set_v(r, c, 0)

        propagated = propagate(new_state)
        if propagated is not None:
            res = search(propagated)
            if res is not None:
                return res

        return None

    result_path = search(current_state)
    if result_path is None:
        return "No Solution"
    else:
        return result_path

