import sys

# Increase recursion depth to handle deep search if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0])

    # H: Horizontal edges. Dimensions: (rows+1) x cols
    # V: Vertical edges. Dimensions: rows x (cols+1)
    # -1: Unknown, 0: Empty, 1: Line
    H = [[-1] * cols for _ in range(rows + 1)]
    V = [[-1] * (cols + 1) for _ in range(rows)]

    clues = data

    def get_cell_edges(r, c):
        # Returns list of (type, r, c) for edges surrounding cell (r, c)
        return [
            ('H', r, c),       # Top
            ('H', r+1, c),     # Bottom
            ('V', r, c),       # Left
            ('V', r, c+1)      # Right
        ]

    def get_dot_edges(r, c):
        # Returns list of (type, r, c) for edges incident to dot (r, c)
        edges = []
        if r > 0: edges.append(('V', r-1, c)) # Top
        if r < rows: edges.append(('V', r, c)) # Bottom
        if c > 0: edges.append(('H', r, c-1)) # Left
        if c < cols: edges.append(('H', r, c)) # Right
        return edges

    def propagate(state_H, state_V):
        # Returns (success, changed)
        changed = True
        while changed:
            changed = False

            # 1. Clue Constraints
            for r in range(rows):
                for c in range(cols):
                    clue = clues[r][c]
                    if clue is None: continue

                    edges = get_cell_edges(r, c)
                    known_lines = 0
                    unknown_count = 0
                    unknown_edges = []

                    for typ, rr, cc in edges:
                        val = state_H[rr][cc] if typ == 'H' else state_V[rr][cc]
                        if val == 1: known_lines += 1
                        elif val == -1: 
                            unknown_count += 1
                            unknown_edges.append((typ, rr, cc))

                    if known_lines > clue: return False, False
                    if known_lines == clue:
                        for typ, rr, cc in unknown_edges:
                            if typ == 'H' and state_H[rr][cc] == -1:
                                state_H[rr][cc] = 0
                                changed = True
                            elif typ == 'V' and state_V[rr][cc] == -1:
                                state_V[rr][cc] = 0
                                changed = True
                    elif known_lines + unknown_count == clue:
                        for typ, rr, cc in unknown_edges:
                            if typ == 'H' and state_H[rr][cc] == -1:
                                state_H[rr][cc] = 1
                                changed = True
                            elif typ == 'V' and state_V[rr][cc] == -1:
                                state_V[rr][cc] = 1
                                changed = True

            # 2. Vertex Constraints (Degree 0 or 2)
            for r in range(rows + 1):
                for c in range(cols + 1):
                    edges = get_dot_edges(r, c)
                    known_lines = 0
                    unknown_count = 0
                    unknown_edges = []

                    for typ, rr, cc in edges:
                        val = state_H[rr][cc] if typ == 'H' else state_V[rr][cc]
                        if val == 1: known_lines += 1
                        elif val == -1:
                            unknown_count += 1
                            unknown_edges.append((typ, rr, cc))

                    if known_lines > 2: return False, False

                    if known_lines == 2:
                        for typ, rr, cc in unknown_edges:
                            if typ == 'H' and state_H[rr][cc] == -1:
                                state_H[rr][cc] = 0
                                changed = True
                            elif typ == 'V' and state_V[rr][cc] == -1:
                                state_V[rr][cc] = 0
                                changed = True
                    elif known_lines == 1 and unknown_count == 1:
                        typ, rr, cc = unknown_edges[0]
                        if typ == 'H' and state_H[rr][cc] == -1:
                            state_H[rr][cc] = 1
                            changed = True
                        elif typ == 'V' and state_V[rr][cc] == -1:
                            state_V[rr][cc] = 1
                            changed = True
        return True, True

    def forms_loop(state_H, state_V):
        # Checks if the current set of lines forms any cycle.
        # Returns True if a cycle exists.
        parent = list(range((rows + 1) * (cols + 1)))
        def find(i):
            path = []
            while parent[i] != i:
                path.append(i)
                i = parent[i]
            for node in path: parent[node] = i
            return i

        def union(i, j):
            ri, rj = find(i), find(j)
            if ri == rj: return False
            parent[ri] = rj
            return True

        for r in range(rows + 1):
            for c in range(cols):
                if state_H[r][c] == 1:
                    u = r * (cols + 1) + c
                    v = r * (cols + 1) + c + 1
                    if not union(u, v): return True

        for r in range(rows):
            for c in range(cols + 1):
                if state_V[r][c] == 1:
                    u = r * (cols + 1) + c
                    v = (r + 1) * (cols + 1) + c
                    if not union(u, v): return True
        return False

    def is_valid_solution(state_H, state_V):
        # Check clues
        for r in range(rows):
            for c in range(cols):
                clue = clues[r][c]
                if clue is None: continue
                edges = get_cell_edges(r, c)
                count = 0
                for typ, rr, cc in edges:
                    val = state_H[rr][cc] if typ == 'H' else state_V[rr][cc]
                    if val == 1: count += 1
                if count != clue: return False

        # Check single loop connectivity
        parent = list(range((rows + 1) * (cols + 1)))
        def find(i):
            if parent[i] != i: parent[i] = find(parent[i])
            return parent[i]
        def union(i, j):
            ri, rj = find(i), find(j)
            if ri != rj: parent[ri] = rj

        line_count = 0
        for r in range(rows + 1):
            for c in range(cols):
                if state_H[r][c] == 1:
                    u = r * (cols + 1) + c
                    v = r * (cols + 1) + c + 1
                    union(u, v)
                    line_count += 1
        for r in range(rows):
            for c in range(cols + 1):
                if state_V[r][c] == 1:
                    u = r * (cols + 1) + c
                    v = (r + 1) * (cols + 1) + c
                    union(u, v)
                    line_count += 1

        if line_count == 0: return False

        roots = set()
        for r in range(rows + 1):
            for c in range(cols):
                if state_H[r][c] == 1:
                    roots.add(find(r * (cols + 1) + c))
        for r in range(rows):
            for c in range(cols + 1):
                if state_V[r][c] == 1:
                    roots.add(find(r * (cols + 1) + c))

        return len(roots) == 1

    def solve_recursive(state_H, state_V):
        success, _ = propagate(state_H, state_V)
        if not success: return None

        # Check for unknowns
        has_unknown = False
        for r in range(rows + 1):
            for c in range(cols):
                if state_H[r][c] == -1: has_unknown = True; break
            if has_unknown: break
        if not has_unknown:
            for r in range(rows):
                for c in range(cols + 1):
                    if state_V[r][c] == -1: has_unknown = True; break
                if has_unknown: break

        if not has_unknown:
            if is_valid_solution(state_H, state_V):
                return (state_H, state_V)
            return None

        # Heuristic: Pick first unknown
        fr, fc, ftyp = -1, -1, ''
        for r in range(rows + 1):
            for c in range(cols):
                if state_H[r][c] == -1:
                    fr, fc, ftyp = r, c, 'H'
                    break
            if ftyp: break
        if not ftyp:
            for r in range(rows):
                for c in range(cols + 1):
                    if state_V[r][c] == -1:
                        fr, fc, ftyp = r, c, 'V'
                        break
                if ftyp: break

        # Try 1
        H1 = [row[:] for row in state_H]
        V1 = [row[:] for row in state_V]
        if ftyp == 'H': H1[fr][fc] = 1
        else: V1[fr][fc] = 1

        # Prune if small loop formed and not a solution
        if forms_loop(H1, V1):
            if is_valid_solution(H1, V1):
                res = solve_recursive(H1, V1)
                if res: return res
        else:
            res = solve_recursive(H1, V1)
            if res: return res

        # Try 0
        H0 = [row[:] for row in state_H]
        V0 = [row[:] for row in state_V]
        if ftyp == 'H': H0[fr][fc] = 0
        else: V0[fr][fc] = 0

        res = solve_recursive(H0, V0)
        if res: return res

        return None

    res = solve_recursive(H, V)

    if res:
        final_H, final_V = res
        # Find start dot
        start_dot = None
        for r in range(rows + 1):
            for c in range(cols + 1):
                deg = 0
                if r > 0 and final_V[r-1][c] == 1: deg += 1
                if r < rows and final_V[r][c] == 1: deg += 1
                if c > 0 and final_H[r][c-1] == 1: deg += 1
                if c < cols and final_H[r][c] == 1: deg += 1
                if deg == 2:
                    start_dot = (r, c)
                    break
            if start_dot: break

        if not start_dot:
            return "No Solution"

        path = []
        curr = start_dot
        prev = None
        steps = 0
        max_steps = (rows + 1) * (cols + 1) + 5

        while steps < max_steps:
            path.append(curr)
            r, c = curr
            neighbors = []
            if r > 0 and final_V[r-1][c] == 1: neighbors.append((r-1, c))
            if r < rows and final_V[r][c] == 1: neighbors.append((r+1, c))
            if c > 0 and final_H[r][c-1] == 1: neighbors.append((r, c-1))
            if c < cols and final_H[r][c] == 1: neighbors.append((r, c+1))

            next_node = None
            for n in neighbors:
                if n != prev:
                    next_node = n
                    break

            if next_node is None:
                break
            if next_node == start_dot:
                path.append(start_dot)
                break

            prev = curr
            curr = next_node
            steps += 1

        return path
    else:
        return "No Solution"

