import copy

def solve(observation):
    tree_grid = observation['tree']
    row_counts = observation['row_tent_counts']
    col_counts = observation['col_tent_counts']
    R = len(tree_grid)
    C = len(tree_grid[0])

    # Initialize grid: 'T' for tree, None for empty
    grid = [[None for _ in range(C)] for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                grid[r][c] = 'T'

    # Pre-calculate tree neighbors for each cell to speed up checks
    # tree_neighbors[r][c] = list of (tr, tc) adjacent to (r, c)
    tree_neighbors = [[[] for _ in range(C)] for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'T': continue
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 'T':
                    tree_neighbors[r][c].append((nr, nc))

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C:
                neighs.append((nr, nc))
        return neighs

    def get_all_neighbors(r, c):
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < R and 0 <= nc < C:
                    neighs.append((nr, nc))
        return neighs

    def is_valid_placement(grid, r, c, val):
        # Check tent touching rule
        if val == 't':
            for nr, nc in get_all_neighbors(r, c):
                if grid[nr][nc] == 't':
                    return False
            # Check if tent is adjacent to at least one tree (Standard Rule)
            # Note: Prompt says "adjacent to exactly one", but standard puzzles allow multiple adjacency 
            # as long as pairing is 1-to-1. However, if a cell has 0 tree neighbors, it can't be a tent.
            has_tree = False
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == 'T':
                    has_tree = True
                    break
            if not has_tree:
                return False
        return True

    def check_counts(grid):
        for r in range(R):
            t_count = sum(1 for c in range(C) if grid[r][c] == 't')
            if t_count > row_counts[r]: return False
        for c in range(C):
            t_count = sum(1 for r in range(R) if grid[r][c] == 't')
            if t_count > col_counts[c]: return False
        return True

    def check_tree_potential(grid):
        # Every tree must have at least one adjacent cell that is either 't' or None (potential tent)
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 'T':
                    has_potential = False
                    for nr, nc in get_neighbors(r, c):
                        if grid[nr][nc] in ['t', None]:
                            has_potential = True
                            break
                    if not has_potential:
                        return False
        return True

    def is_complete(grid):
        for r in range(R):
            for c in range(C):
                if grid[r][c] is None:
                    return False
        return True

    def check_final_validity(grid):
        # 1. Counts
        for r in range(R):
            if sum(1 for c in range(C) if grid[r][c] == 't') != row_counts[r]:
                return False
        for c in range(C):
            if sum(1 for r in range(R) if grid[r][c] == 't') != col_counts[c]:
                return False

        # 2. Bipartite Matching (Tree <-> Tent)
        trees = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == 'T']
        tents = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == 't']

        if len(trees) != len(tents):
            return False

        # Simple DFS for matching
        match = {} # tent -> tree
        def can_match(tree_idx, used_tents):
            if tree_idx == len(trees):
                return True
            tr, tc = trees[tree_idx]
            for tent_r, tent_c in tents:
                if (tent_r, tent_c) in used_tents:
                    continue
                # Check adjacency
                if abs(tr - tent_r) + abs(tc - tent_c) == 1:
                    used_tents.add((tent_r, tent_c))
                    if can_match(tree_idx + 1, used_tents):
                        return True
                    used_tents.remove((tent_r, tent_c))
            return False

        return can_match(0, set())

    def propagate(grid):
        changed = True
        while changed:
            changed = False
            # Rule 1: Row/Col Completion
            for r in range(R):
                current = sum(1 for c in range(C) if grid[r][c] == 't')
                needed = row_counts[r]
                if current == needed:
                    for c in range(C):
                        if grid[r][c] is None:
                            grid[r][c] = 'g'
                            changed = True
                else:
                    unknowns = [c for c in range(C) if grid[r][c] is None]
                    if len(unknowns) == needed - current:
                        for c in unknowns:
                            grid[r][c] = 't'
                            changed = True

            for c in range(C):
                current = sum(1 for r in range(R) if grid[r][c] == 't')
                needed = col_counts[c]
                if current == needed:
                    for r in range(R):
                        if grid[r][c] is None:
                            grid[r][c] = 'g'
                            changed = True
                else:
                    unknowns = [r for r in range(R) if grid[r][c] is None]
                    if len(unknowns) == needed - current:
                        for r in unknowns:
                            grid[r][c] = 't'
                            changed = True

            # Rule 2: Tree Satisfaction (Unique Spot)
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 'T':
                        # Check if already satisfied
                        satisfied = False
                        for nr, nc in get_neighbors(r, c):
                            if grid[nr][nc] == 't':
                                satisfied = True
                                break
                        if not satisfied:
                            spots = [ (nr, nc) for nr, nc in get_neighbors(r, c) if grid[nr][nc] is None ]
                            if len(spots) == 1:
                                sr, sc = spots[0]
                                grid[sr][sc] = 't'
                                changed = True

            # Rule 3: Tent Exclusion (Grass around tents)
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 't':
                        for nr, nc in get_all_neighbors(r, c):
                            if grid[nr][nc] is None:
                                grid[nr][nc] = 'g'
                                changed = True
                            elif grid[nr][nc] == 't':
                                return False # Conflict
            if not check_counts(grid) or not check_tree_potential(grid):
                return False
        return True

    def backtrack(grid):
        if not propagate(grid):
            return None

        if is_complete(grid):
            if check_final_validity(grid):
                return grid
            else:
                return None

        # Find first unknown
        for r in range(R):
            for c in range(C):
                if grid[r][c] is None:
                    # Try Tent
                    if is_valid_placement(grid, r, c, 't'):
                        grid[r][c] = 't'
                        res = backtrack(grid)
                        if res: return res
                        grid[r][c] = None

                    # Try Grass
                    grid[r][c] = 'g'
                    res = backtrack(grid)
                    if res: return res
                    grid[r][c] = None

                    return None # No solution from this state
        return None

    final_grid = backtrack(grid)
    if final_grid is None:
        return "No Solution"

    # Format output
    result = [[None for _ in range(C)] for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if final_grid[r][c] == 't':
                result[r][c] = 't'
    return result

