    N = len(grid)

    # Group cells by region ID
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    region_ids = sorted(regions.keys())
