        for c in range(N):
            # Right neighbor
            if c + 1 < N:
                all_dominoes.append(((r, c), (r, c + 1)))
            # Down neighbor
            if r + 1 < N:
                all_dominoes.append(((r, c), (r + 1, c)))

    # For each domino, precompute which regions it contributes to
    # contribution[domino_index] = {region_id: count}
    domino_contributions = []
    for d in all_dominoes:
        contrib = {}
        for cell in d:
            rid = grid[cell[0]][cell[1]]
            contrib[rid] = contrib.get(rid, 0) + 1
        domino_contributions.append(contrib)

    # Precompute neighbors for each cell (for forbidden mask)
    cell_neighbors = {}
    for r in range(N):
        for c in range(N):
            neighbors = []
            if r > 0: neighbors.append((r - 1, c))
            if r < N - 1: neighbors.append((r + 1, c))
            if c > 0: neighbors.append((r, c - 1))
            if c < N - 1: neighbors.append((r, c + 1))
            cell_neighbors[(r, c)] = neighbors

    # Backtracking solver
    # State: 
    #   region_counts: dict {rid: count}
    #   forbidden: set of cells that cannot be used (shaded or adjacent to shaded)
    #   solution: list of domino indices

    # Initial state
    initial_counts = {rid: 0 for rid in region_ids}
    initial_forbidden = set()

    # Heuristic: Order regions? 
    # We will dynamically pick the region with count < 2.

    def get_valid_dominoes_for_region(rid, current_counts, forbidden):
        # We need to add cells to 'rid' to reach count 2.
        # needed = 2 - current_counts[rid]
        # If needed == 2: can pick internal (contrib 2) or crossing (contrib 1)
        # If needed == 1: must pick crossing (contrib 1)

        needed = 2 - current_counts[rid]
        valid = []

        for i, d in enumerate(all_dominoes):
            contrib = domino_contributions[i]
            c_rid = contrib.get(rid, 0)

            if c_rid == 0:
                continue # Domino doesn't touch this region

            if c_rid > needed:
                continue # Adds too many cells to this region

            # Check if cells are free
            valid_d = True
            for cell in d:
                if cell in forbidden:
                    valid_d = False
                    break

            if valid_d:
                valid.append(i)

        return valid

    def backtrack(current_counts, forbidden, solution_indices):
        # Check if solved
        if all(current_counts[rid] == 2 for rid in region_ids):
            return solution_indices

        # Select a region to satisfy (heuristic: first unsatisfied)
        # Better heuristic: region with fewest options?
        # For simplicity, pick first unsatisfied.
        target_rid = None
        for rid in region_ids:
            if current_counts[rid] < 2:
                target_rid = rid
                break

        if target_rid is None:
            return None # Should not happen if check above passes

        # Get candidate dominoes that can help target_rid
        candidates = get_valid_dominoes_for_region(target_rid, current_counts, forbidden)

        # To reduce symmetry when needed=2 and we pick crossing dominoes:
        # If we pick a crossing domino, we will recurse and pick another.
        # This might lead to (D1, D2) and (D2, D1).
        # We can enforce an order on domino indices if we want, but let's try without first.
        # Given the small size, it should be fine.

        for d_idx in candidates:
            d = all_dominoes[d_idx]
            contrib = domino_contributions[d_idx]

            # Update counts
            new_counts = current_counts.copy()
            for rid, c in contrib.items():
                new_counts[rid] = new_counts.get(rid, 0) + c

            # Update forbidden
            # Forbidden = old_forbidden U cells(d) U neighbors(cells(d))
            # Note: cells(d) are already checked to be not in forbidden.
            new_forbidden = forbidden.copy()
            for cell in d:
                new_forbidden.add(cell)
                for nb in cell_neighbors[cell]:
                    new_forbidden.add(nb)

            res = backtrack(new_counts, new_forbidden, solution_indices + [d_idx])
            if res is not None:
                return res

        return None

    solution_indices = backtrack(initial_counts, initial_forbidden, [])

    if solution_indices is None:
        return "No Solution"

    # Construct output grid
    out_grid = [[None for _ in range(N)] for _ in range(N)]
    for idx in solution_indices:
        d = all_dominoes[idx]
        for r, c in d:
            out_grid[r][c] = 'S'

    return out_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
