import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(20000)

OBSERVATION = {'data': [
    [3, None, None, None, None, None, 3],
    [1, 2, 1, None, 1, 2, None],
    [2, 3, None, 2, None, None, 2],
    [3, None, None, 2, None, None, None],
    [None, 2, None, None, 3, None, 2],
    [None, None, None, 3, None, None, 3],
    [None, 2, None, 3, 2, 2, None]
]}

class SlitherlinkSolver:
    def __init__(self, clues):
        self.H_cells = len(clues)
        self.W_cells = len(clues[0])
        self.H_dots = self.H_cells + 1
        self.W_dots = self.W_cells + 1
        self.clues = clues

        # Edge states: 0=Unknown, 1=Line, 2=Cross
        # Horizontal edges: H_dots rows, W_cells cols
        self.h_edges = [[0] * self.W_cells for _ in range(self.H_dots)]
        # Vertical edges: H_cells rows, W_dots cols
        self.v_edges = [[0] * self.W_dots for _ in range(self.H_cells)]

    def get_dot_id(self, r, c):
        return r * self.W_dots + c

    def get_cell_edges(self, r, c):
        # Returns list of (is_horizontal, row, col) for edges surrounding cell (r,c)
        return [
            (True, r, c),       # Top
            (True, r+1, c),     # Bottom
            (False, r, c),      # Left
            (False, r, c+1)     # Right
        ]

    def get_dot_edges(self, r, c):
        # Returns list of (is_horizontal, row, col) for edges connected to dot (r,c)
        edges = []
        if r > 0: edges.append((True, r-1, c))       # Top
        if r < self.H_dots - 1: edges.append((True, r, c)) # Bottom
        if c > 0: edges.append((False, r, c-1))      # Left
        if c < self.W_dots - 1: edges.append((False, r, c)) # Right
        return edges

    def set_edge(self, r, c, is_h, val):
        # val: 1 (Line), 2 (Cross)
        if is_h:
            if self.h_edges[r][c] != 0 and self.h_edges[r][c] != val:
                return False # Contradiction
            self.h_edges[r][c] = val
        else:
            if self.v_edges[r][c] != 0 and self.v_edges[r][c] != val:
                return False
            self.v_edges[r][c] = val
        return True

    def propagate(self):
        changed = True
        while changed:
            changed = False

            # 1. Clue Constraints
            for r in range(self.H_cells):
                for c in range(self.W_cells):
                    clue = self.clues[r][c]
                    if clue is None: continue
                    edges = self.get_cell_edges(r, c)
                    lines = 0
                    unknowns = 0
                    for is_h, er, ec in edges:
                        val = self.h_edges[er][ec] if is_h else self.v_edges[er][ec]
                        if val == 1: lines += 1
                        elif val == 0: unknowns += 1

                    if lines == clue:
                        # All unknowns must be Cross
                        for is_h, er, ec in edges:
                            if (is_h and self.h_edges[er][ec] == 0) or (not is_h and self.v_edges[er][ec] == 0):
                                self.set_edge(er, ec, is_h, 2)
                                changed = True
                    elif lines + unknowns == clue:
                        # All unknowns must be Line
                        for is_h, er, ec in edges:
                            if (is_h and self.h_edges[er][ec] == 0) or (not is_h and self.v_edges[er][ec] == 0):
                                self.set_edge(er, ec, is_h, 1)
                                changed = True

            # 2. Dot Constraints (Degree must be 0 or 2)
            for r in range(self.H_dots):
                for c in range(self.W_dots):
                    edges = self.get_dot_edges(r, c)
                    lines = 0
                    unknowns = 0
                    for is_h, er, ec in edges:
                        val = self.h_edges[er][ec] if is_h else self.v_edges[er][ec]
                        if val == 1: lines += 1
                        elif val == 0: unknowns += 1

                    if lines == 2:
                        # All unknowns must be Cross
                        for is_h, er, ec in edges:
                            if (is_h and self.h_edges[er][ec] == 0) or (not is_h and self.v_edges[er][ec] == 0):
                                self.set_edge(er, ec, is_h, 2)
                                changed = True
                    elif lines == 1 and unknowns == 1:
                        # The single unknown must be Line to reach degree 2
                        for is_h, er, ec in edges:
                            if (is_h and self.h_edges[er][ec] == 0) or (not is_h and self.v_edges[er][ec] == 0):
                                self.set_edge(er, ec, is_h, 1)
                                changed = True
                    elif lines == 0 and unknowns == 1:
                        # The single unknown must be Cross to stay at degree 0
                        for is_h, er, ec in edges:
                            if (is_h and self.h_edges[er][ec] == 0) or (not is_h and self.v_edges[er][ec] == 0):
                                self.set_edge(er, ec, is_h, 2)
                                changed = True

            # 3. Cycle Prevention (Sub-loop detection)
            # If adding a line creates a cycle, it must be the FINAL solution loop.
            # Otherwise, it's a sub-loop and the edge must be Cross.

            # Build DSU for current Lines
            parent = list(range(self.H_dots * self.W_dots))
            def find(p, i):
                path = []
                while p[i] != i:
                    path.append(i)
                    i = p[i]
                for node in path: p[node] = i
                return i

            for r in range(self.H_dots):
                for c in range(self.W_cells):
                    if self.h_edges[r][c] == 1:
                        u, v = self.get_dot_id(r, c), self.get_dot_id(r, c+1)
                        ru, rv = find(parent, u), find(parent, v)
                        if ru != rv: parent[ru] = rv
            for r in range(self.H_cells):
                for c in range(self.W_dots):
                    if self.v_edges[r][c] == 1:
                        u, v = self.get_dot_id(r, c), self.get_dot_id(r+1, c)
                        ru, rv = find(parent, u), find(parent, v)
                        if ru != rv: parent[ru] = rv

            # Check unknowns: if setting to Line connects two nodes in same component -> Cycle
            for r in range(self.H_dots):
                for c in range(self.W_cells):
                    if self.h_edges[r][c] == 0:
                        u, v = self.get_dot_id(r, c), self.get_dot_id(r, c+1)
                        if find(parent, u) == find(parent, v):
                            if not self.is_valid_full_solution(r, c, True):
                                self.h_edges[r][c] = 2
                                changed = True
            for r in range(self.H_cells):
                for c in range(self.W_dots):
                    if self.v_edges[r][c] == 0:
                        u, v = self.get_dot_id(r, c), self.get_dot_id(r+1, c)
                        if find(parent, u) == find(parent, v):
                            if not self.is_valid_full_solution(r, c, False):
                                self.v_edges[r][c] = 2
                                changed = True

    def is_valid_full_solution(self, r, c, is_h):
        # Check if adding this line (and assuming all other unknowns are Cross) creates a valid solution
        # 1. All clues must be satisfied exactly
        for cr in range(self.H_cells):
            for cc in range(self.W_cells):
                clue = self.clues[cr][cc]
                if clue is None: continue
                count = 0
                edges = self.get_cell_edges(cr, cc)
                for is_h_edge, er, ec in edges:
                    val = 0
                    if is_h_edge: val = self.h_edges[er][ec]
                    else: val = self.v_edges[er][ec]

                    # Override for the hypothetical line
                    if is_h_edge and er == r and ec == c and is_h: val = 1
                    if not is_h_edge and er == r and ec == c and not is_h: val = 1

                    if val == 1: count += 1
                if count != clue: return False

        # 2. All dots must have degree 0 or 2
        for dr in range(self.H_dots):
            for dc in range(self.W_dots):
                deg = 0
                edges = self.get_dot_edges(dr, dc)
                for is_h_edge, er, ec in edges:
                    val = 0
                    if is_h_edge: val = self.h_edges[er][ec]
                    else: val = self.v_edges[er][ec]

                    if is_h_edge and er == r and ec == c and is_h: val = 1
                    if not is_h_edge and er == r and ec == c and not is_h: val = 1

                    if val == 1: deg += 1
                if deg != 0 and deg != 2: return False

        return True

    def solve(self):
        self.propagate()
        if not self.is_consistent(): return None
        if self.is_solved(): return self.extract_solution()

        # Backtracking: Pick first unknown edge
        for r in range(self.H_dots):
            for c in range(self.W_cells):
                if self.h_edges[r][c] == 0:
                    saved_h = [x[:] for x in self.h_edges]
                    saved_v = [x[:] for x in self.v_edges]

                    # Try Line
                    self.h_edges[r][c] = 1
                    res = self.solve()
                    if res: return res

                    # Restore
                    self.h_edges = saved_h
                    self.v_edges = saved_v

                    # Try Cross
                    self.h_edges[r][c] = 2
                    res = self.solve()
                    if res: return res
                    return None

        for r in range(self.H_cells):
            for c in range(self.W_dots):
                if self.v_edges[r][c] == 0:
                    saved_h = [x[:] for x in self.h_edges]
                    saved_v = [x[:] for x in self.v_edges]

                    self.v_edges[r][c] = 1
                    res = self.solve()
                    if res: return res

                    self.h_edges = saved_h
                    self.v_edges = saved_v

                    self.v_edges[r][c] = 2
                    res = self.solve()
                    if res: return res
                    return None
        return None

    def is_consistent(self):
        # Check for immediate contradictions
        for r in range(self.H_cells):
            for c in range(self.W_cells):
                clue = self.clues[r][c]
                if clue is None: continue
                lines = 0
                for is_h, er, ec in self.get_cell_edges(r, c):
                    if (self.h_edges[er][ec] if is_h else self.v_edges[er][ec]) == 1: lines += 1
                if lines > clue: return False
        return True

    def is_solved(self):
        # Check if all edges are determined
        for r in range(self.H_dots):
            for c in range(self.W_cells):
                if self.h_edges[r][c] == 0: return False
        for r in range(self.H_cells):
            for c in range(self.W_dots):
                if self.v_edges[r][c] == 0: return False
        return True

    def extract_solution(self):
        # Find a starting dot with a line
        start = None
        for r in range(self.H_dots):
            for c in range(self.W_dots):
                for is_h, er, ec in self.get_dot_edges(r, c):
                    if (self.h_edges[er][ec] if is_h else self.v_edges[er][ec]) == 1:
                        start = (r, c)
                        break
                if start: break
            if start: break
        if not start: return []

        path = [start]
        curr = start
        prev = None
        while True:
            r, c = curr
            next_node = None
            for is_h, er, ec in self.get_dot_edges(r, c):
                if (self.h_edges[er][ec] if is_h else self.v_edges[er][ec]) == 1:
                    if is_h:
                        # Horizontal edge connects (er, ec) and (er, ec+1)
                        neighbor = (er, ec+1) if (er, ec) == (r, c) else (er, ec)
                    else:
                        # Vertical edge connects (er, ec) and (er+1, ec)
                        neighbor = (er+1, ec) if (er, ec) == (r, c) else (er, ec)

                    if neighbor != prev:
                        next_node = neighbor
                        break
            if next_node == start:
                path.append(start)
                break
            if next_node is None: break
            path.append(next_node)
            prev = curr
            curr = next_node
        return path

def solve(observation):
    solver = SlitherlinkSolver(observation['data'])
    path = solver.solve()
    return str(path) if path else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
