def solve(observation):
    grid = observation['data']
    N = len(grid)

    # Map cells to regions
    cell_to_region = {}
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            cell_to_region[(r, c)] = rid
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    # Precompute neighbors for each cell
    neighbors = {}
    for r in range(N):
        for c in range(N):
            neighs = []
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighs.append((nr, nc))
            neighbors[(r, c)] = neighs

    # Identify forced dominoes for regions of size 2
    # If a region has exactly 2 cells, they MUST be shaded (to satisfy "exactly 2 shaded cells").
    # And they must form a domino (since every shaded cell belongs to a domino).
    forced_dominoes = []
    initial_shaded = set()
    initial_blocked = set()
    region_counts = {rid: 0 for rid in regions}

    # Sort regions by size to process small ones first (heuristic)
    sorted_rids = sorted(regions.keys(), key=lambda rid: len(regions[rid]))

    for rid in sorted_rids:
        cells = regions[rid]
        if len(cells) == 2:
            c1, c2 = cells
            # Check if they are adjacent
            if c2 in neighbors[c1]:
                forced_dominoes.append((c1, c2))
            else:
                # Should not happen in a valid puzzle if rules hold
                return "No Solution"

    # Apply forced dominoes
    for c1, c2 in forced_dominoes:
        initial_shaded.add(c1)
        initial_shaded.add(c2)
        region_counts[cell_to_region[c1]] += 1 # Both in same region
        # Block neighbors
        for c in [c1, c2]:
            for n in neighbors[c]:
                if n not in initial_shaded:
                    initial_blocked.add(n)

    # If any region is full, block its remaining cells
    for rid, count in region_counts.items():
        if count == 2:
            for c in regions[rid]:
                if c not in initial_shaded:
                    initial_blocked.add(c)

    # Backtracking solver
    # State: shaded (set), blocked (set), region_counts (dict)
    # We need to fill all regions to count 2.

    target_count = 2
    all_rids = list(regions.keys())

    def get_valid_dominoes_for_region(rid, shaded, blocked, counts):
        # Find a cell in rid that is not shaded and not blocked
        # Try to pair it with a neighbor to form a domino
        candidates = []
        needed = target_count - counts[rid]

        # If region is full, no dominoes needed
        if needed <= 0:
            return []

        # Heuristic: pick a cell in rid that is available
        available_cells = [c for c in regions[rid] if c not in shaded and c not in blocked]

        if not available_cells:
            # If we need cells but none available, this path is dead
            return []

        # Try to form dominoes involving these cells
        # We only need to consider dominoes that add at least 1 cell to rid
        # Since we iterate cells in rid, any domino {c, n} adds 1 (if n not in rid) or 2 (if n in rid)

        seen_dominoes = set()
        for c in available_cells:
            for n in neighbors[c]:
                if n in shaded or n in blocked:
                    continue

                # Form domino
                d_cells = tuple(sorted([c, n]))
                if d_cells in seen_dominoes:
                    continue
                seen_dominoes.add(d_cells)

                r1 = cell_to_region[c]
                r2 = cell_to_region[n]

                # Check region constraints
                # If r1 == r2, we add 2 to r1
                # If r1 != r2, we add 1 to r1 and 1 to r2

                valid = True
                if r1 == r2:
                    if counts[r1] + 2 > target_count:
                        valid = False
                else:
                    if counts[r1] + 1 > target_count:
                        valid = False
                    if counts[r2] + 1 > target_count:
                        valid = False

                if valid:
                    candidates.append((c, n))

        return candidates

    def backtrack(shaded, blocked, counts):
        # Check if solved
        if all(counts[rid] == target_count for rid in all_rids):
            return shaded

        # Pick a region to fill
        # Heuristic: Pick region with smallest (target - count) > 0, and fewest available cells?
        # Or just first incomplete region
        incomplete_regions = [rid for rid in all_rids if counts[rid] < target_count]
        if not incomplete_regions:
            return None # Should be caught by check above

        # Sort by remaining need (prefer regions needing 1 cell? or 2?)
        # Actually, prefer regions with fewest options
        best_rid = None
        min_options = float('inf')

        for rid in incomplete_regions:
            opts = get_valid_dominoes_for_region(rid, shaded, blocked, counts)
            if len(opts) < min_options:
                min_options = len(opts)
                best_rid = rid
            if min_options == 0:
                break # Prune early

        if min_options == 0:
            return None

        # Try candidates for best_rid
        candidates = get_valid_dominoes_for_region(best_rid, shaded, blocked, counts)

        # Sort candidates? Maybe by whether they fill the region completely
        # Prefer dominoes that are internal to the region (add 2) if needed=2
        needed = target_count - counts[best_rid]
        if needed == 2:
            # Prefer internal dominoes
            candidates.sort(key=lambda d: (0 if cell_to_region[d[0]] == cell_to_region[d[1]] else 1))

        for c1, c2 in candidates:
            d_cells = {c1, c2}
            r1 = cell_to_region[c1]
            r2 = cell_to_region[c2]

            # Apply move
            new_shaded = shaded | d_cells
            new_blocked = set(blocked)
            new_counts = counts.copy()

            # Update counts
            new_counts[r1] += 1
            if r1 != r2:
                new_counts[r2] += 1

            # Update blocked
            for c in d_cells:
                for n in neighbors[c]:
                    if n not in new_shaded:
                        new_blocked.add(n)

            # If any region is full, block remaining cells
            for rid in all_rids:
                if new_counts[rid] == target_count:
                    for cell in regions[rid]:
                        if cell not in new_shaded:
                            new_blocked.add(cell)

            res = backtrack(new_shaded, new_blocked, new_counts)
            if res is not None:
                return res

        return None

    final_shaded = backtrack(initial_shaded, initial_blocked, region_counts)

    if final_shaded is None:
        return "No Solution"

    # Construct output grid
    result_grid = [[None for _ in range(N)] for _ in range(N)]
    for r, c in final_shaded:
        result_grid[r][c] = 'S'

    return result_grid

