        [None, 'T', None, None, 'T', None, None, None],
        [None, None, None, 'T', None, None, None, 'T'],
        [None, None, None, None, None, None, 'T', None],
        [None, None, 'T', None, None, 'T', None, 'T'],
        [None, None, None, None, None, None, None, None]
    ],
    'row_tent_counts': [2, 1, 1, 3, 0, 3, 1, 1],
    'col_tent_counts': [1, 2, 1, 2, 0, 2, 0, 4]
}

def solve(observation):
    # Constants for grid states
    EMPTY = 0
    TREE = 1
    TENT = 2
    GRASS = 3

    rows = len(observation['tree'])
    cols = len(observation['tree'][0])

    # Initialize grid
    grid = [[EMPTY for _ in range(cols)] for _ in range(rows)]
    tree_positions = []

    for r in range(rows):
        for c in range(cols):
            if observation['tree'][r][c] == 'T':
                grid[r][c] = TREE
                tree_positions.append((r, c))

    row_targets = observation['row_tent_counts']
    col_targets = observation['col_tent_counts']

    # Helper to get orthogonal neighbors
    def get_orth_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                yield nr, nc

    # Helper to get 8-way neighbors
    def get_all_neighbors(r, c):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    yield nr, nc

    def count_tents_row(r):
        return sum(1 for c in range(cols) if grid[r][c] == TENT)

    def count_tents_col(c):
        return sum(1 for r in range(rows) if grid[r][c] == TENT)

    def count_empty_row(r):
        return sum(1 for c in range(cols) if grid[r][c] == EMPTY)

    def count_empty_col(c):
        return sum(1 for r in range(rows) if grid[r][c] == EMPTY)

    def is_valid_tent_spot(r, c):
        # A tent must be adjacent to at least one tree to be potentially valid
        # (Though strictly, it must be paired 1-to-1, but for placement validity, adjacency is key)
        for nr, nc in get_orth_neighbors(r, c):
            if grid[nr][nc] == TREE:
                return True
        return False

    def propagate():
        changed = True
        while changed:
            changed = False

            # Rule 1: Mark cells not adjacent to any tree as GRASS (Optimization)
            # Actually, strictly speaking, a tent MUST be adjacent to a tree. 
            # So any EMPTY cell not orthogonally adjacent to a TREE can be marked GRASS.
            for r in range(rows):
                for c in range(cols):
                    if grid[r][c] == EMPTY:
                        if not is_valid_tent_spot(r, c):
                            grid[r][c] = GRASS
                            changed = True

            # Rule 2: Row/Col Count Fulfillment -> Mark rest as GRASS
            for r in range(rows):
                if count_tents_row(r) == row_targets[r]:
                    for c in range(cols):
                        if grid[r][c] == EMPTY:
                            grid[r][c] = GRASS
                            changed = True

            for c in range(cols):
                if count_tents_col(c) == col_targets[c]:
                    for r in range(rows):
                        if grid[r][c] == EMPTY:
                            grid[r][c] = GRASS
                            changed = True

            # Rule 3: Row/Col Forced Placement -> Mark rest as TENT
            for r in range(rows):
                needed = row_targets[r] - count_tents_row(r)
                empty_count = count_empty_row(r)
                if needed == empty_count and needed > 0:
                    for c in range(cols):
                        if grid[r][c] == EMPTY:
                            grid[r][c] = TENT
                            changed = True

            for c in range(cols):
                needed = col_targets[c] - count_tents_col(c)
                empty_count = count_empty_col(c)
                if needed == empty_count and needed > 0:
                    for r in range(rows):
                        if grid[r][c] == EMPTY:
                            grid[r][c] = TENT
                            changed = True

            # Rule 4: Tree Needs Tent -> If only 1 empty neighbor, place TENT
            for tr, tc in tree_positions:
                # Check if this tree already has a tent
                has_tent = False
                for nr, nc in get_orth_neighbors(tr, tc):
                    if grid[nr][nc] == TENT:
                        has_tent = True
                        break

                if not has_tent:
                    empty_neighbors = []
                    for nr, nc in get_orth_neighbors(tr, tc):
                        if grid[nr][nc] == EMPTY:
                            # Check if placing here violates row/col counts
                            if count_tents_row(nr) < row_targets[nr] and count_tents_col(nc) < col_targets[nc]:
                                empty_neighbors.append((nr, nc))

                    if len(empty_neighbors) == 1:
                        nr, nc = empty_neighbors[0]
                        grid[nr][nc] = TENT
                        changed = True

            # Rule 5: Tent Separation -> If TENT, mark 8-neighbors as GRASS
            for r in range(rows):
                for c in range(cols):
                    if grid[r][c] == TENT:
                        for nr, nc in get_all_neighbors(r, c):
                            if grid[nr][nc] == EMPTY:
                                grid[nr][nc] = GRASS
                                changed = True

            # Consistency Check
            for r in range(rows):
                if count_tents_row(r) > row_targets[r]: return False
            for c in range(cols):
                if count_tents_col(c) > col_targets[c]: return False

            # Check if any tree is blocked (no empty neighbors and no tent)
            for tr, tc in tree_positions:
                has_tent = False
                has_empty = False
                for nr, nc in get_orth_neighbors(tr, tc):
                    if grid[nr][nc] == TENT: has_tent = True
                    if grid[nr][nc] == EMPTY: has_empty = True
                if not has_tent and not has_empty:
                    return False # Tree cannot be satisfied

        return True

    def is_solved():
        # Check counts
        for r in range(rows):
            if count_tents_row(r) != row_targets[r]: return False
        for c in range(cols):
            if count_tents_col(c) != col_targets[c]: return False

        # Check every tree has a tent
        # Note: The rules say 1-to-1 pairing. 
        # If counts match total trees, and every tree has a tent, and tents don't touch, 
        # a valid matching usually exists (Hall's Marriage Theorem conditions are typically met in these puzzles if local constraints are satisfied).
        # However, to be strict, we should check if a matching exists.
        # Given the small size and constraints, if counts match and every tree has a neighbor tent, it's likely solved.
        # But let's do a quick bipartite check to be safe? 
        # Actually, standard solvers often just check "Every tree has a tent" + "Counts match".
        # Let's stick to: Counts match + Every tree has at least one tent neighbor.
        # Wait, "Each tent is orthogonally adjacent to exactly one tree" is a rule?
        # Rule 1: "Each tent must be orthogonally adjacent to its paired tree." -> This is strict.
        # My current logic allows a tent to be adjacent to multiple trees. I need to enforce this.

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == TENT:
                    adj_trees = 0
                    for nr, nc in get_orth_neighbors(r, c):
                        if grid[nr][nc] == TREE:
                            adj_trees += 1
                    if adj_trees != 1:
                        return False # A tent must touch exactly one tree

        for tr, tc in tree_positions:
            has_tent = False
            for nr, nc in get_orth_neighbors(tr, tc):
                if grid[nr][nc] == TENT:
                    has_tent = True
                    break
            if not has_tent:
                return False

        return True

    def solve_dfs():
        if not propagate():
            return False

        if is_solved():
            return True

        # Heuristic: Pick a tree that doesn't have a tent yet and has few options
        best_tree = None
        min_options = 100

        for tr, tc in tree_positions:
            has_tent = False
            for nr, nc in get_orth_neighbors(tr, tc):
                if grid[nr][nc] == TENT:
                    has_tent = True
                    break

            if not has_tent:
                options = []
                for nr, nc in get_orth_neighbors(tr, tc):
                    if grid[nr][nc] == EMPTY:
                        # Check validity
                        if count_tents_row(nr) < row_targets[nr] and count_tents_col(nc) < col_targets[nc]:
                            options.append((nr, nc))
                if len(options) < min_options:
                    min_options = len(options)
                    best_tree = (tr, tc)
                if min_options == 0: return False # Stuck

        if best_tree is None:
            # All trees have tents, but maybe counts aren't met? 
            # Or maybe is_solved failed due to the "exactly one tree" rule?
            # If we are here, propagate didn't finish it.
            # Try picking an empty cell?
            # Actually, if all trees have tents, and counts match, we are done.
            # If counts don't match, we have extra tents needed? 
            # But #Tents = #Trees. So if all trees have tents, counts MUST match if valid.
            # So if best_tree is None, we should be solved.
            return is_solved()

        tr, tc = best_tree
        # Get options for this tree
        options = []
        for nr, nc in get_orth_neighbors(tr, tc):
            if grid[nr][nc] == EMPTY:
                if count_tents_row(nr) < row_targets[nr] and count_tents_col(nc) < col_targets[nc]:
                    options.append((nr, nc))

        # Try placing a tent for this tree
        for r, c in options:
            # Save state
            # Since grid is mutable, we need to be careful. 
            # Deep copy is expensive. Let's just modify and revert.
            # But propagate modifies many cells. 
            # Simple backtracking with snapshot is safer for correctness, though slower.
            # Given 8x8, snapshot is fine.

            snapshot = [row[:] for row in grid]

            grid[r][c] = TENT
            # Apply immediate separation
            for nr, nc in get_all_neighbors(r, c):
                if grid[nr][nc] == EMPTY:
                    grid[nr][nc] = GRASS

            if solve_dfs():
                return True

            # Restore
            for i in range(rows):
                for j in range(cols):
                    grid[i][j] = snapshot[i][j]

        return False

    if solve_dfs():
        # Format output
        result_grid = [[None for _ in range(cols)] for _ in range(rows)]
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == TENT:
                    result_grid[r][c] = 't'
        return result_grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
