import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # State representation
    # edges: set of normalized edges ((r1, c1), (r2, c2))
    # degrees: 2D list of degrees for each dot
    # forbidden: set of normalized edges that cannot be used

    edges = set()
    degrees = [[0] * N for _ in range(N)]
    forbidden = set()

    def norm_edge(p1, p2):
        if p1 < p2:
            return (p1, p2)
        return (p2, p1)

    def get_neighbors(r, c):
        neighs = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                neighs.append((nr, nc))
        return neighs

    # Union-Find to check connectivity and cycles
    def get_uf_state(current_edges):
        parent = list(range(N * N))
        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]
        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        for (r1, c1), (r2, c2) in current_edges:
            union(r1 * N + c1, r2 * N + c2)
        return parent

    def is_valid_state(current_edges, current_degrees, current_forbidden):
        # 1. Check degrees <= 2
        for r in range(N):
            for c in range(N):
                if current_degrees[r][c] > 2:
                    return False

        # 2. Check Clue Constraints
        for r in range(N):
            for c in range(N):
                clue = data[r][c]
                if clue is None:
                    continue

                # Get active neighbors
                active_neighs = []
                for nr, nc in get_neighbors(r, c):
                    if norm_edge((r, c), (nr, nc)) in current_edges:
                        active_neighs.append((nr, nc))

                deg = len(active_neighs)

                if clue == 'B':
                    # Black: Turn at circle, straight before and after.
                    if deg == 2:
                        # Check perpendicularity
                        v1 = (active_neighs[0][0] - r, active_neighs[0][1] - c)
                        v2 = (active_neighs[1][0] - r, active_neighs[1][1] - c)
                        if v1[0] * v2[0] + v1[1] * v2[1] != 0:
                            return False # Not perpendicular

                        # Check straight extensions
                        for nr, nc in active_neighs:
                            dr, dc = nr - r, nc - c
                            nnr, nnc = nr + dr, nc + dc
                            if 0 <= nnr < N and 0 <= nnc < N:
                                if norm_edge((nr, nc), (nnr, nnc)) not in current_edges:
                                    return False
                            else:
                                return False # Out of bounds
                    elif deg == 1:
                        # Check straight extension for the single existing neighbor
                        nr, nc = active_neighs[0]
                        dr, dc = nr - r, nc - c
                        nnr, nnc = nr + dr, nc + dc
                        if 0 <= nnr < N and 0 <= nnc < N:
                            e_ext = norm_edge((nr, nc), (nnr, nnc))
                            if e_ext in current_forbidden:
                                return False
                        else:
                            return False

                elif clue == 'W':
                    # White: Straight through, turn at least once in prev/next step.
                    if deg == 2:
                        # Check collinearity
                        v1 = (active_neighs[0][0] - r, active_neighs[0][1] - c)
                        v2 = (active_neighs[1][0] - r, active_neighs[1][1] - c)
                        if v1[0] * v2[1] - v1[1] * v2[0] != 0:
                            return False # Not collinear

                        # Check turn condition (not straight on both sides)
                        straight_sides = 0
                        for nr, nc in active_neighs:
                            dr, dc = nr - r, nc - c
                            nnr, nnc = nr + dr, nc + dc
                            if 0 <= nnr < N and 0 <= nnc < N:
                                if norm_edge((nr, nc), (nnr, nnc)) in current_edges:
                                    straight_sides += 1
                        if straight_sides == 2:
                            return False # Went straight on both sides

        # 3. Check for small loops (sub-cycles)
        # If a component is a cycle (all nodes deg 2), it must be the ONLY component and cover all clues.
        parent = get_uf_state(current_edges)
        components = {}
        for r in range(N):
            for c in range(N):
                if current_degrees[r][c] > 0:
                    root = parent[r * N + c]
                    if root not in components:
                        components[root] = []
                    components[root].append((r, c))

        cycle_components = 0
        for root, nodes in components.items():
            is_cycle = all(current_degrees[r][c] == 2 for r, c in nodes)
            if is_cycle:
                cycle_components += 1
                # Check if covers all clues
                all_clues_covered = True
                for r in range(N):
                    for c in range(N):
                        if data[r][c] is not None:
                            if (r, c) not in nodes:
                                all_clues_covered = False
                                break
                    if not all_clues_covered: break

                if not all_clues_covered:
                    return False # Small loop not covering all clues

                # If there are other components with edges, it's invalid (disconnected loop)
                # But wait, 'components' only contains nodes with deg > 0.
                # So if cycle_components == 1 and len(components) == 1, it's a valid full loop.
                # If cycle_components == 1 and len(components) > 1, it's a loop + paths -> Invalid.

        if cycle_components > 0 and len(components) > 1:
            return False
        if cycle_components > 1:
