                        best_node = (r, c)
                        min_opts = opts

        if best_node is None:
            return None

        r, c = best_node
        valid_edges = []
        for nr, nc in get_neighbors(r, c):
            e = norm_edge((r,c), (nr,nc))
            if e not in current_forbidden and e not in current_edges:
                valid_edges.append(e)

        for e in valid_edges:
            new_edges = set(current_edges)
            new_edges.add(e)
            new_degrees = [row[:] for row in current_degrees]
            new_degrees[e[0][0]][e[0][1]] += 1
            new_degrees[e[1][0]][e[1][1]] += 1
            new_forbidden = set(current_forbidden)

            res = search(new_edges, new_degrees, new_forbidden)
            if res:
                return res

            current_forbidden.add(e)

        return None

    # Initial solve
    return search(edges, degrees, forbidden)

