    # Mimics human deduction: finding cells that MUST be black or MUST be white
    # based on the intersection/union of all remaining valid candidates.
    # Modifies r_cands, c_cands, grid in place.
    # Returns False if contradiction found, True otherwise.
    def propagate(r_cands, c_cands, grid):
        while True:
            changed = False

            # Propagate Rows
            for r in range(H):
                if not r_cands[r]:
                    return False # Contradiction: No valid candidates for row r

                # Intersection of all candidates -> Cells that MUST be Black
                must_black = r_cands[r][0]
                for mask in r_cands[r][1:]:
                    must_black &= mask

                # Union of all candidates -> Cells that CAN be Black
                can_black = 0
                for mask in r_cands[r]:
                    can_black |= mask

                # Cells that MUST be White (not in any candidate)
                must_white = ((1 << W) - 1) ^ can_black

                # Apply Must Black
                for c in range(W):
                    if (must_black >> c) & 1:
                        if grid[r][c] is None:
