                                    new_c_list.append(m)
                            c_cands[c] = new_c_list
                        elif grid[r][c] == 0:
                            return False # Contradiction

                # Apply Must White
                for c in range(W):
                    if (must_white >> c) & 1:
                        if grid[r][c] is None:
                            grid[r][c] = 0
                            changed = True
                            # Filter col candidates for c: keep only masks with bit r unset
                            new_c_list = []
                            for m in c_cands[c]:
