            if not changed:
                break

        return True

    # Search function with Backtracking and MRV Heuristic
    def search(r_cands, c_cands, grid):
        # 1. Propagate constraints aggressively
        if not propagate(r_cands, c_cands, grid):
            return None

        # 2. Check if solved
        is_solved = True
        for r in range(H):
            for c in range(W):
                if grid[r][c] is None:
                    is_solved = False
                    break
            if not is_solved:
                break

        if is_solved:
            return grid

        # 3. MRV Heuristic: Pick row or col with fewest valid candidates (>1)
        # This minimizes the branching factor.
        min_options = float('inf')
        best_idx = -1
        is_row_choice = True

        for r in range(H):
            count = len(r_cands[r])
            if 1 < count < min_options:
                min_options = count
                best_idx = r
                is_row_choice = True

        for c in range(W):
            count = len(c_cands[c])
            if 1 < count < min_options:
                min_options = count
                best_idx = c
                is_row_choice = False

        # If no variable with >1 options found, but not solved, then we are stuck
        if min_options == float('inf'):
            return None

        # 4. Branch
        if is_row_choice:
            r = best_idx
            # Snapshot state for backtracking
            snap_r_cands = [list(lst) for lst in r_cands]
            snap_c_cands = [list(lst) for lst in c_cands]
            snap_grid = [row[:] for row in grid]

            for mask in snap_r_cands[r]:
                # Restore state for this branch
                new_r_cands = [list(lst) for lst in snap_r_cands]
                new_c_cands = [list(lst) for lst in snap_c_cands]
                new_grid = [row[:] for row in snap_grid]

                # Force this mask for row r
                new_r_cands[r] = [mask]

                # Update grid based on mask
                conflict = False
                for c in range(W):
                    val = 1 if (mask >> c) & 1 else 0
                    if new_grid[r][c] is not None and new_grid[r][c] != val:
                        conflict = True
                        break
                    new_grid[r][c] = val

                if not conflict:
                    res = search(new_r_cands, new_c_cands, new_grid)
                    if res is not None:
                        return res
            return None

        else:
            c = best_idx
            snap_r_cands = [list(lst) for lst in r_cands]
            snap_c_cands = [list(lst) for lst in c_cands]
            snap_grid = [row[:] for row in grid]

            for mask in snap_c_cands[c]:
                new_r_cands = [list(lst) for lst in snap_r_cands]
                new_c_cands = [list(lst) for lst in snap_c_cands]
                new_grid = [row[:] for row in snap_grid]

                new_c_cands[c] = [mask]

                conflict = False
                for r in range(H):
                    val = 1 if (mask >> r) & 1 else 0
                    if new_grid[r][c] is not None and new_grid[r][c] != val:
                        conflict = True
                        break
                    new_grid[r][c] = val

                if not conflict:
                    res = search(new_r_cands, new_c_cands, new_grid)
                    if res is not None:
                        return res
            return None

    # Start Search
    start_r_cands = [list(lst) for lst in row_candidates]
    start_c_cands = [list(lst) for lst in col_candidates]
    start_grid = [row[:] for row in initial_grid]

    final_grid = search(start_r_cands, start_c_cands, start_grid)

    if final_grid:
        return final_grid
    else:
        return "No Solution"

