    # A mask is an integer where bit j is 1 if the cell is Black ('B')

    def get_valid_masks(target, weights):
        # Find all subsets of indices such that sum(weights[indices]) == target
        n = len(weights)
        valid_masks = []
        # Iterate all subsets (2^n)
        for r in range(1 << n):
            current_sum = 0
            for i in range(n):
                if (r >> i) & 1:
                    current_sum += weights[i]
            if current_sum == target:
                # Convert subset bitmask 'r' to a grid mask
                # Bit i in 'r' corresponds to index i in 'weights'
                # We want a mask where bit 'i' is set if bit 'i' is set in 'r'
                # Since weights are 0..N-1, the indices align with bit positions.
                valid_masks.append(r)
        return valid_masks

    # Row options: list of masks (length C bits). Bit c corresponds to column c.
    # Sum of col_weights[c] for set bits must equal row_targets[r]
    row_options = []
    for r in range(R):
        row_options.append(get_valid_masks(row_targets[r], col_weights))

    # Col options: list of masks (length R bits). Bit r corresponds to row r.
    # Sum of row_weights[r] for set bits must equal col_targets[c]
    col_options = []
    for c in range(C):
