    # Grid state: -1 (Unknown), 0 (White/None), 1 (Black)
    grid = [[-1 for _ in range(C)] for _ in range(R)]

    # Mutable state for solver
    current_row_options = [list(opts) for opts in row_options]
    current_col_options = [list(opts) for opts in col_options]

    def propagate():
        """
        Aggressive constraint propagation.
        Returns False if a contradiction is found.
        Returns True if propagation stabilizes (even if not fully solved).
        """
        changed = True
        while changed:
            changed = False

            # 1. Process Rows
            for r in range(R):
                if not current_row_options[r]:
                    return False # Contradiction: No valid options left

                # Intersection: bits set in ALL options MUST be 1 (Black)
                # Union: bits set in ANY option COULD be 1. Bits in NONE MUST be 0 (White)

                all_mask = 0xFF # Assuming max 8 bits, effectively (1<<C) - 1
                any_mask = 0

                # Calculate intersection and union of all valid masks for this row
                # Initialize all_mask with the first option to be safe, or all 1s
                if current_row_options[r]:
