                    # If bit is 1 in intersection, cell must be Black
                    if (all_mask & bit_val):
                        if grid[r][c] != 1:
                            grid[r][c] = 1
                            changed = True

                    # If bit is 0 in union, cell must be White
                    if not (any_mask & bit_val):
                        if grid[r][c] != 0:
                            grid[r][c] = 0
                            changed = True

            # 2. Process Columns
            for c in range(C):
                if not current_col_options[c]:
                    return False

                all_mask = 0xFF
                any_mask = 0

                if current_col_options[c]:
                    all_mask = current_col_options[c][0]
                    for mask in current_col_options[c][1:]:
                        all_mask &= mask

                    for mask in current_col_options[c]:
                        any_mask |= mask

                for r in range(R):
                    bit_val = 1 << r

                    if (all_mask & bit_val):
