                            grid[r][c] = 1
                            changed = True
                    if not (any_mask & bit_val):
                        if grid[r][c] != 0:
                            grid[r][c] = 0
                            changed = True

            # 3. Filter options based on current grid state
            # Remove any mask that conflicts with known grid cells
            for r in range(R):
                new_opts = []
                for mask in current_row_options[r]:
                    valid = True
                    for c in range(C):
                        cell_val = grid[r][c]
                        is_black = (mask >> c) & 1
                        # Conflict: Grid says Black, Mask says White
                        if cell_val == 1 and not is_black:
                            valid = False; break
                        # Conflict: Grid says White, Mask says Black
                        if cell_val == 0 and is_black:
                            valid = False; break
                    if valid:
                        new_opts.append(mask)

                if len(new_opts) != len(current_row_options[r]):
                    current_row_options[r] = new_opts
                    changed = True # Options reduced, may trigger new deductions

            for c in range(C):
                new_opts = []
                for mask in current_col_options[c]:
                    valid = True
                    for r in range(R):
                        cell_val = grid[r][c]
                        is_black = (mask >> r) & 1
                        if cell_val == 1 and not is_black:
                            valid = False; break
                        if cell_val == 0 and is_black:
                            valid = False; break
                    if valid:
                        new_opts.append(mask)
                if len(new_opts) != len(current_col_options[c]):
                    current_col_options[c] = new_opts
                    changed = True

        return True

    def solve_recursive():
        # Run propagation first
        if not propagate():
            return False

        # Check if solved (no unknowns)
        solved = True
        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    solved = False
                    break
            if not solved: break

        if solved:
            return True

        # Heuristic: Minimum Remaining Values (MRV)
        # Pick the row or column with the fewest valid options to branch on
        best_len = float('inf')
        best_type = None 
        best_idx = -1

        for r in range(R):
            l = len(current_row_options[r])
            if l < best_len:
