            if l < best_len:
                best_len = l
                best_type = 'col'
                best_idx = c

        # Save state for backtracking
        # Deep copy is necessary because lists are mutable
        saved_row_opts = [list(x) for x in current_row_options]
        saved_col_opts = [list(x) for x in current_col_options]
        saved_grid = [list(row) for row in grid]

        if best_type == 'row':
            r = best_idx
