            for mask in current_row_options[r]:
                # Temporarily apply this mask to the grid
                # We only set unknown cells to avoid overwriting confirmed cells (though they should match)
                # Actually, we can just force the grid to match the mask for this row
                # and let propagation handle the rest.

                # Snapshot grid for this specific branch to restore easily? 
                # No, we rely on the outer saved state.

                # Apply mask to grid
                for c in range(C):
                    val = 1 if (mask >> c) & 1 else 0
                    if grid[r][c] == -1:
                        grid[r][c] = val
