                for i in range(R): current_row_options[i] = list(saved_row_opts[i])
                for i in range(C): current_col_options[i] = list(saved_col_opts[i])
                for i in range(R): grid[i] = list(saved_grid[i])

            return False

        else: # best_type == 'col'
            c = best_idx
            for mask in current_col_options[c]:
                for r in range(R):
                    val = 1 if (mask >> r) & 1 else 0
                    if grid[r][c] == -1:
                        grid[r][c] = val

                current_col_options[c] = [mask]

                if solve_recursive():
                    return True

                # Backtrack
                for i in range(R): current_row_options[i] = list(saved_row_opts[i])
                for i in range(C): current_col_options[i] = list(saved_col_opts[i])
                for i in range(R): grid[i] = list(saved_grid[i])

            return False

    if solve_recursive():
        # Format output as list of lists with 'B' and None
        res = []
        for r in range(R):
