import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # Identify clues
    clues = []
    for r in range(N):
        for c in range(N):
            if data[r][c] in ('W', 'B'):
                clues.append((r, c))

    # State class to hold grid status
    class State:
        def __init__(self, H, V, degree, parent):
            self.H = [row[:] for row in H]
            self.V = [row[:] for row in V]
            self.degree = [row[:] for row in degree]
            self.parent = parent[:]
            self.N = N

        def copy(self):
            return State(self.H, self.V, self.degree, self.parent)

        def find(self, i):
            path = []
            while self.parent[i] != i:
                path.append(i)
                i = self.parent[i]
            for node in path:
                self.parent[node] = i
            return i

        def union(self, i, j):
            pi, pj = self.find(i), self.find(j)
            if pi != pj:
                self.parent[pi] = pj
                return True
            return False

    def get_h(state, r, c):
        if c < 0 or c >= state.N - 1: return -1
        return state.H[r][c]

    def get_v(state, r, c):
        if r < 0 or r >= state.N - 1: return -1
        return state.V[r][c]

    def set_h(state, r, c, val):
        if c < 0 or c >= state.N - 1: return True
        if state.H[r][c] == -val and val != 0: return False
        if state.H[r][c] == val: return True
        state.H[r][c] = val
        if val == 1:
            state.degree[r][c] += 1
            state.degree[r][c+1] += 1
            state.union(r * state.N + c, r * state.N + c + 1)
        return True

    def set_v(state, r, c, val):
        if r < 0 or r >= state.N - 1: return True
        if state.V[r][c] == -val and val != 0: return False
        if state.V[r][c] == val: return True
        state.V[r][c] = val
        if val == 1:
            state.degree[r][c] += 1
            state.degree[r+1][c] += 1
            state.union(r * state.N + c, (r + 1) * state.N + c)
        return True

    def propagate(state):
        changed = True
        while changed:
            changed = False
            # Check degree contradictions
            for r in range(state.N):
                for c in range(state.N):
                    if state.degree[r][c] > 2:
                        return None

            # 1. Degree Rules
            for r in range(state.N):
                for c in range(state.N):
                    d = state.degree[r][c]
                    unknown = 0
                    if c > 0 and get_h(state, r, c-1) == 0: unknown += 1
                    if c < state.N-1 and get_h(state, r, c) == 0: unknown += 1
                    if r > 0 and get_v(state, r-1, c) == 0: unknown += 1
                    if r < state.N-1 and get_v(state, r, c) == 0: unknown += 1

                    is_clue = data[r][c] in ('W', 'B')

                    if d == 2:
                        if c > 0 and get_h(state, r, c-1) == 0:
                            if not set_h(state, r, c-1, -1): return None
                            changed = True
                        if c < state.N-1 and get_h(state, r, c) == 0:
                            if not set_h(state, r, c, -1): return None
                            changed = True
                        if r > 0 and get_v(state, r-1, c) == 0:
                            if not set_v(state, r-1, c, -1): return None
                            changed = True
                        if r < state.N-1 and get_v(state, r, c) == 0:
                            if not set_v(state, r, c, -1): return None
                            changed = True
