                                if not set_h(state, r, c-1, 1): return None
                                changed = True
                            elif c < state.N-1 and get_h(state, r, c) == 0:
                                if not set_h(state, r, c, 1): return None
                                changed = True
                            elif r > 0 and get_v(state, r-1, c) == 0:
                                if not set_v(state, r-1, c, 1): return None
                                changed = True
                            elif r < state.N-1 and get_v(state, r, c) == 0:
                                if not set_v(state, r, c, 1): return None
                                changed = True
                        elif unknown == 0:
                            return None # Degree 1 with no options -> Invalid
                    elif d == 0:
                        if unknown == 1 and not is_clue:
                            if c > 0 and get_h(state, r, c-1) == 0:
                                if not set_h(state, r, c-1, -1): return None
                                changed = True
                            elif c < state.N-1 and get_h(state, r, c) == 0:
                                if not set_h(state, r, c, -1): return None
                                changed = True
                            elif r > 0 and get_v(state, r-1, c) == 0:
                                if not set_v(state, r-1, c, -1): return None
                                changed = True
                            elif r < state.N-1 and get_v(state, r, c) == 0:
                                if not set_v(state, r, c, -1): return None
                                changed = True

            # 2. Clue Rules
            for r, c in clues:
                clue_type = data[r][c]
                used_dirs = []
                if r > 0 and get_v(state, r-1, c) == 1: used_dirs.append('N')
                if r < state.N-1 and get_v(state, r, c) == 1: used_dirs.append('S')
                if c > 0 and get_h(state, r, c-1) == 1: used_dirs.append('W')
                if c < state.N-1 and get_h(state, r, c) == 1: used_dirs.append('E')

                if clue_type == 'B':
                    if len(used_dirs) == 1:
                        d = used_dirs[0]
                        # Opposite must be unused
                        if d == 'N' and r < state.N-1 and get_v(state, r, c) == 0:
                            if not set_v(state, r, c, -1): return None
                            changed = True
                        if d == 'S' and r > 0 and get_v(state, r-1, c) == 0:
                            if not set_v(state, r-1, c, -1): return None
                            changed = True
                        if d == 'W' and c < state.N-1 and get_h(state, r, c) == 0:
                            if not set_h(state, r, c, -1): return None
                            changed = True
                        if d == 'E' and c > 0 and get_h(state, r, c-1) == 0:
                            if not set_h(state, r, c-1, -1): return None
                            changed = True

                        # Extension rule
                        if d == 'N':
                            if r > 1 and get_v(state, r-2, c) == 0:
                                if not set_v(state, r-2, c, 1): return None
                                changed = True
                            e_unused = (c < state.N-1 and get_h(state, r, c) == -1)
                            w_unused = (c > 0 and get_h(state, r, c-1) == -1)
                            if e_unused and not w_unused:
                                if c > 0 and get_h(state, r, c-1) == 0:
                                    if not set_h(state, r, c-1, 1): return None
                                    changed = True
                            if w_unused and not e_unused:
                                if c < state.N-1 and get_h(state, r, c) == 0:
                                    if not set_h(state, r, c, 1): return None
                                    changed = True
                            if c < state.N-1 and get_h(state, r, c) == 1:
                                if c < state.N-2 and get_h(state, r, c+1) == 0:
                                    if not set_h(state, r, c+1, 1): return None
                                    changed = True
                            if c > 0 and get_h(state, r, c-1) == 1:
                                if c > 1 and get_h(state, r, c-2) == 0:
                                    if not set_h(state, r, c-2, 1): return None
                                    changed = True
                    elif len(used_dirs) == 2:
                        if ('N' in used_dirs and 'S' in used_dirs) or ('W' in used_dirs and 'E' in used_dirs):
                            return None
                        if 'N' in used_dirs:
                            if r > 1 and get_v(state, r-2, c) == 0:
                                if not set_v(state, r-2, c, 1): return None
                                changed = True
                        if 'S' in used_dirs:
                            if r < state.N-2 and get_v(state, r+1, c) == 0:
                                if not set_v(state, r+1, c, 1): return None
                                changed = True
                        if 'W' in used_dirs:
                            if c > 1 and get_h(state, r, c-2) == 0:
                                if not set_h(state, r, c-2, 1): return None
                                changed = True
                        if 'E' in used_dirs:
                            if c < state.N-2 and get_h(state, r, c+1) == 0:
                                if not set_h(state, r, c+1, 1): return None
                                changed = True

                elif clue_type == 'W':
                    if len(used_dirs) == 1:
                        d = used_dirs[0]
                        if d == 'N':
                            if r < state.N-1 and get_v(state, r, c) == 0:
                                if not set_v(state, r, c, 1): return None
                                changed = True
                            if c < state.N-1 and get_h(state, r, c) == 0:
                                if not set_h(state, r, c, -1): return None
                                changed = True
                            if c > 0 and get_h(state, r, c-1) == 0:
                                if not set_h(state, r, c-1, -1): return None
                                changed = True
                        elif d == 'S':
                            if r > 0 and get_v(state, r-1, c) == 0:
                                if not set_v(state, r-1, c, 1): return None
                                changed = True
                            if c < state.N-1 and get_h(state, r, c) == 0:
                                if not set_h(state, r, c, -1): return None
                                changed = True
                            if c > 0 and get_h(state, r, c-1) == 0:
                                if not set_h(state, r, c-1, -1): return None
                                changed = True
                        elif d == 'W':
                            if c < state.N-1 and get_h(state, r, c) == 0:
                                if not set_h(state, r, c, 1): return None
                                changed = True
                            if r > 0 and get_v(state, r-1, c) == 0:
                                if not set_v(state, r-1, c, -1): return None
                                changed = True
                            if r < state.N-1 and get_v(state, r, c) == 0:
                                if not set_v(state, r, c, -1): return None
                                changed = True
                        elif d == 'E':
                            if c > 0 and get_h(state, r, c-1) == 0:
                                if not set_h(state, r, c-1, 1): return None
                                changed = True
                            if r > 0 and get_v(state, r-1, c) == 0:
                                if not set_v(state, r-1, c, -1): return None
                                changed = True
                            if r < state.N-1 and get_v(state, r, c) == 0:
                                if not set_v(state, r, c, -1): return None
                                changed = True
                    elif len(used_dirs) == 2:
                        if ('N' in used_dirs and 'S' in used_dirs):
                            if c < state.N-1 and get_h(state, r, c) == 0:
                                if not set_h(state, r, c, -1): return None
                                changed = True
                            if c > 0 and get_h(state, r, c-1) == 0:
                                if not set_h(state, r, c-1, -1): return None
                                changed = True
                        elif ('W' in used_dirs and 'E' in used_dirs):
                            if r > 0 and get_v(state, r-1, c) == 0:
                                if not set_v(state, r-1, c, -1): return None
                                changed = True
                            if r < state.N-1 and get_v(state, r, c) == 0:
                                if not set_v(state, r, c, -1): return None
                                changed = True
                        else:
                            return None

            # 3. Sub-loop detection
            # Re-build UF for current state
            for i in range(state.N * state.N): state.parent[i] = i
            for r in range(state.N):
                for c in range(state.N-1):
                    if state.H[r][c] == 1:
                        state.union(r * state.N + c, r * state.N + c + 1)
            for r in range(state.N-1):
                for c in range(state.N):
                    if state.V[r][c] == 1:
                        state.union(r * state.N + c, (r + 1) * state.N + c)

            components = {}
            for i in range(state.N * state.N):
                if state.degree[i // state.N][i % state.N] > 0:
                    root = state.find(i)
                    if root not in components: components[root] = []
                    components[root].append(i)

            for root, nodes in components.items():
                is_cycle = True
                clues_count = 0
                for node in nodes:
                    r, c = node // state.N, node % state.N
                    if state.degree[r][c] != 2: is_cycle = False
                    if data[r][c] in ('W', 'B'): clues_count += 1
                if is_cycle and clues_count < len(clues):
                    return None

            # 4. White Turn Constraint
            for r, c in clues:
                if data[r][c] == 'W':
                    if c > 0 and c < state.N-1 and get_h(state, r, c-1) == 1 and get_h(state, r, c) == 1:
                        left_s = (c > 1 and get_h(state, r, c-2) == 1)
                        right_s = (c < state.N-2 and get_h(state, r, c+1) == 1)
                        if left_s and right_s: return None
                        if left_s and not right_s:
                            if c < state.N-2 and get_h(state, r, c+1) == 0:
                                if not set_h(state, r, c+1, -1): return None
                                changed = True
                        if right_s and not left_s:
                            if c > 1 and get_h(state, r, c-2) == 0:
                                if not set_h(state, r, c-2, -1): return None
                                changed = True
                    if r > 0 and r < state.N-1 and get_v(state, r-1, c) == 1 and get_v(state, r, c) == 1:
                        up_s = (r > 1 and get_v(state, r-2, c) == 1)
                        down_s = (r < state.N-2 and get_v(state, r+1, c) == 1)
                        if up_s and down_s: return None
                        if up_s and not down_s:
                            if r < state.N-2 and get_v(state, r+1, c) == 0:
                                if not set_v(state, r+1, c, -1): return None
                                changed = True
                        if down_s and not up_s:
                            if r > 1 and get_v(state, r-2, c) == 0:
                                if not set_v(state, r-2, c, -1): return None
                                changed = True
        return state

    def solve_state(state):
        state = propagate(state)
        if state is None:
            return None

        # Find unknown edge
        unk = None
        for r in range(state.N):
            for c in range(state.N-1):
                if state.H[r][c] == 0:
                    unk = ('H', r, c)
                    break
            if unk: break
        if not unk:
            for r in range(state.N-1):
                for c in range(state.N):
                    if state.V[r][c] == 0:
                        unk = ('V', r, c)
                        break
                if unk: break

        if unk is None:
            # Check solution validity
            for r, c in clues:
                if state.degree[r][c] != 2: return None

            # Check connectivity
            r0, c0 = clues[0]
            root = state.find(r0 * state.N + c0)
            for r, c in clues:
                if state.find(r * state.N + c) != root: return None

            # Check degrees
            for r in range(state.N):
                for c in range(state.N):
                    if state.degree[r][c] not in (0, 2): return None

            # Reconstruct path
            path = [clues[0]]
            curr = clues[0]
            prev = None
            while True:
                r, c = curr
                neighs = []
                if c > 0 and get_h(state, r, c-1) == 1: neighs.append((r, c-1))
                if c < state.N-1 and get_h(state, r, c) == 1: neighs.append((r, c+1))
                if r > 0 and get_v(state, r-1, c) == 1: neighs.append((r-1, c))
                if r < state.N-1 and get_v(state, r, c) == 1: neighs.append((r+1, c))
                nxt = None
                for n in neighs:
                    if n != prev:
                        nxt = n
                        break
                if nxt == clues[0]:
                    path.append(clues[0])
                    break
                if nxt is None: break
                path.append(nxt)
                prev = curr
                curr = nxt
            return path

        typ, r, c = unk

        # Try Used
        new_state = state.copy()
        if typ == 'H':
            if new_state.H[r][c] == 0:
                new_state.H[r][c] = 1
                new_state.degree[r][c] += 1
                new_state.degree[r][c+1] += 1
                new_state.union(r * new_state.N + c, r * new_state.N + c + 1)
        else:
            if new_state.V[r][c] == 0:
                new_state.V[r][c] = 1
                new_state.degree[r][c] += 1
                new_state.degree[r+1][c] += 1
                new_state.union(r * new_state.N + c, (r + 1) * new_state.N + c)

        res = solve_state(new_state)
        if res: return res

        # Try Unused
        new_state2 = state.copy()
        if typ == 'H':
            new_state2.H[r][c] = -1
        else:
            new_state2.V[r][c] = -1
        res = solve_state(new_state2)
        if res: return res

        return None

    # Initial State
    init_H = [[0] * (N - 1) for _ in range(N)]
    init_V = [[0] * N for _ in range(N - 1)]
    init_degree = [[0] * N for _ in range(N)]
    init_parent = list(range(N * N))
    init_state = State(init_H, init_V, init_degree, init_parent)

    result = solve_state(init_state)
    return result

if __name__ == "__main__":
    OBSERVATION = {'data': [[None, None, 'W', None, None, None, 'W', None], ['W', None, None, None, 'W', None, None, 'W'], ['B', None, None, None, None, None, None, None], [None, None, None, None, 'W', None, None, 'B'], [None, 'W', None, 'B', None, None, None, None], [None, None, None, None, 'W', 'W', None, None], [None, None, None, 'B', 'W', None, None, 'W'], ['B', None, None, None, None, None, 'W', None]]}
