import sys
import copy

# Increase recursion depth to handle deeper search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Grid: 0=Unknown, 1=White, 2=Black
    initial_grid = [[0]*C for _ in range(R)]
    clues = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                clues[(r,c)] = data[r][c]
                initial_grid[r][c] = 1 # Clues are white

    def get_neighbors(r, c):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C:
                yield nr, nc

    def get_white_components(g):
        visited = set()
        components = []
        for r in range(R):
            for c in range(C):
                if g[r][c] == 1 and (r,c) not in visited:
                    comp = set()
                    queue = [(r,c)]
                    visited.add((r,c))
                    has_clue = False
                    clue_val = -1
                    while queue:
                        curr_r, curr_c = queue.pop(0)
                        comp.add((curr_r, curr_c))
                        if (curr_r, curr_c) in clues:
                            has_clue = True
                            clue_val = clues[(curr_r, curr_c)]
                        for nr, nc in get_neighbors(curr_r, curr_c):
                            if g[nr][nc] == 1 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                    components.append((comp, clue_val if has_clue else None))
        return components

    def get_black_components(g):
        visited = set()
        components = []
        for r in range(R):
            for c in range(C):
                if g[r][c] == 2 and (r,c) not in visited:
                    comp = set()
                    queue = [(r,c)]
                    visited.add((r,c))
                    while queue:
                        curr_r, curr_c = queue.pop(0)
                        comp.add((curr_r, curr_c))
                        for nr, nc in get_neighbors(curr_r, curr_c):
                            if g[nr][nc] == 2 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                    components.append(comp)
        return components

    def propagate(g):
        # Returns True if consistent, False if contradiction
        # Modifies g in place
        changed = True
        while changed:
            changed = False

            # 1. Neighbors of '1' are Black
            for (r, c), val in clues.items():
                if val == 1:
                    for nr, nc in get_neighbors(r, c):
                        if g[nr][nc] == 0:
                            g[nr][nc] = 2
                            changed = True
                        elif g[nr][nc] == 1:
                            return False # Contradiction

            # 2. Analyze White Components
            components = get_white_components(g)

            # Map cell to component index
            cell_to_comp = {}
            for i, (comp, _) in enumerate(components):
                for r, c in comp:
                    cell_to_comp[(r,c)] = i

            for comp, clue_val in components:
                # Rule: Each white island must have exactly one clue
                if clue_val is None:
                    return False 

                # Rule: Size must match clue
                if len(comp) > clue_val:
                    return False 

                # Rule: If completed, neighbors are Black
                if len(comp) == clue_val:
                    for r, c in comp:
                        for nr, nc in get_neighbors(r, c):
                            if g[nr][nc] == 0:
                                g[nr][nc] = 2
                                changed = True
                            elif g[nr][nc] == 1:
                                return False # Islands touching

                # Rule: Reachability (Starvation)
                if len(comp) < clue_val:
                    reachable = set()
                    queue = list(comp)
                    visited_reach = set(comp)
                    while queue:
                        r, c = queue.pop(0)
                        for nr, nc in get_neighbors(r, c):
                            if (nr, nc) not in visited_reach:
                                if g[nr][nc] == 0: 
                                    reachable.add((nr, nc))
                                    visited_reach.add((nr, nc))
                                    queue.append((nr, nc))

                    needed = clue_val - len(comp)
                    if len(reachable) < needed:
                        return False 

                    if len(reachable) == needed:
                        for r, c in reachable:
                            if g[r][c] == 0:
                                g[r][c] = 1
                                changed = True

            # 3. 2x2 Rule
            for r in range(R-1):
                for c in range(C-1):
                    cells = [(r,c), (r+1,c), (r,c+1), (r+1,c+1)]
                    blacks = [p for p in cells if g[p[0]][p[1]] == 2]
                    unknowns = [p for p in cells if g[p[0]][p[1]] == 0]
                    if len(blacks) == 3 and len(unknowns) == 1:
                        ur, uc = unknowns[0]
                        if g[ur][uc] == 0:
                            g[ur][uc] = 1
                            changed = True
                        elif g[ur][uc] == 2:
                            return False 

            # 4. Island Separation (Merge Prevention)
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 0:
                        neighbor_comps = set()
                        for nr, nc in get_neighbors(r, c):
                            if g[nr][nc] == 1:
                                if (nr, nc) in cell_to_comp:
                                    neighbor_comps.add(cell_to_comp[(nr, nc)])

                        if len(neighbor_comps) >= 2:
                            total_size = 1 
                            total_clues = 0
                            for idx in neighbor_comps:
                                comp, cval = components[idx]
                                total_size += len(comp)
                                if cval is not None:
                                    total_clues += 1

                            if total_clues > 1:
                                g[r][c] = 2
                                changed = True
                            elif total_clues == 1:
                                target_size = -1
                                for idx in neighbor_comps:
                                    _, cval = components[idx]
                                    if cval is not None:
                                        target_size = cval
                                if total_size > target_size:
                                    g[r][c] = 2
                                    changed = True

            # 5. Black Connectivity (Stream Growth)
            black_comps = get_black_components(g)
            if len(black_comps) > 1:
                for comp in black_comps:
                    unknown_neighbors = set()
                    for r, c in comp:
                        for nr, nc in get_neighbors(r, c):
                            if g[nr][nc] == 0:
                                unknown_neighbors.add((nr, nc))

                    if len(unknown_neighbors) == 0:
                        return False 

                    if len(unknown_neighbors) == 1:
                        nr, nc = list(unknown_neighbors)[0]
                        if g[nr][nc] == 0:
                            g[nr][nc] = 2
                            changed = True
                        elif g[nr][nc] == 1:
                            return False 

        return True

    def is_valid_final(g):
        # 1. No 2x2 Black
        for r in range(R-1):
            for c in range(C-1):
                if g[r][c] == 2 and g[r+1][c] == 2 and g[r][c+1] == 2 and g[r+1][c+1] == 2:
                    return False

        # 2. Black Connectivity
        black_comps = get_black_components(g)
        if len(black_comps) > 1:
            total_black = sum(1 for r in range(R) for c in range(C) if g[r][c] == 2)
            if total_black > 0:
                return False

        # 3. White Islands
        components = get_white_components(g)
        for comp, clue_val in components:
            if clue_val is None: return False
            if len(comp) != clue_val: return False

        return True

    def search_deep(g):
        if not propagate(g):
            return None

        unknowns = [(r,c) for r in range(R) for c in range(C) if g[r][c] == 0]
        if not unknowns:
            if is_valid_final(g):
                return g
            return None

        best_cell = max(unknowns, key=lambda p: sum(1 for nr, nc in get_neighbors(p[0], p[1]) if g[nr][nc] != 0))
        r, c = best_cell

        # Try White
        g1 = [row[:] for row in g]
        g1[r][c] = 1
        res = search_deep(g1)
        if res: return res

        # Try Black
        g2 = [row[:] for row in g]
        g2[r][c] = 2
        res = search_deep(g2)
        if res: return res

        return None

    final_grid = search_deep(initial_grid)

    if final_grid is None:
        return "No Solution"

    result = []
    for r in range(R):
        row_res = []
        for c in range(C):
            if final_grid[r][c] == 2:
                row_res.append('B')
            else:
                row_res.append(None)
        result.append(row_res)

    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))
