def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Grid: -1 Unknown, 0 White, 1 Black
    grid = [[-1 for _ in range(C)] for _ in range(R)]
    numbers = {}

    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                grid[r][c] = 0 # White
