    def get_neighbors(r, c):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C:
                yield nr, nc

    def get_connected_white(r, c, current_grid):
        visited = set()
        stack = [(r,c)]
        visited.add((r,c))
        while stack:
            curr_r, curr_c = stack.pop()
            for nr, nc in get_neighbors(curr_r, curr_c):
                if (nr, nc) not in visited and current_grid[nr][nc] == 0:
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        return visited

    def get_connected_black(current_grid):
        visited_global = set()
        components = []
        for r in range(R):
            for c in range(C):
                if current_grid[r][c] == 1 and (r,c) not in visited_global:
                    comp = set()
                    stack = [(r,c)]
                    visited_global.add((r,c))
                    comp.add((r,c))
                    while stack:
                        curr_r, curr_c = stack.pop()
                        for nr, nc in get_neighbors(curr_r, curr_c):
                            if (nr, nc) not in visited_global and current_grid[nr][nc] == 1:
                                visited_global.add((nr, nc))
                                comp.add((nr, nc))
                                stack.append((nr, nc))
                    components.append(comp)
        return components

    def propagate(current_grid):
        changed = True
        while changed:
            changed = False

            # 1. Consistency: Numbers must be White
            for (r,c), val in numbers.items():
                if current_grid[r][c] == 1: 
                    return False

            # 2. '1' neighbors must be Black
            for (r,c), val in numbers.items():
                if val == 1:
                    for nr, nc in get_neighbors(r,c):
                        if current_grid[nr][nc] == -1:
                            current_grid[nr][nc] = 1
                            changed = True
                        elif current_grid[nr][nc] == 0:
                            return False # Neighbor is white, but island size is 1

            # 3. Island Logic
            visited_white = set()
            for r in range(R):
                for c in range(C):
                    if current_grid[r][c] == 0 and (r,c) not in visited_white:
                        comp = get_connected_white(r, c, current_grid)
                        visited_white.update(comp)

                        nums_in_comp = [k for k in numbers if k in comp]

                        if len(nums_in_comp) > 1:
                            return False # Merged islands

                        if len(nums_in_comp) == 1:
                            num_val = numbers[nums_in_comp[0]]
                            if len(comp) > num_val:
                                return False
                            if len(comp) == num_val:
                                for cr, cc in comp:
