                                        if current_grid[nr][nc] == -1:
                                            current_grid[nr][nc] = 1
                                            changed = True
                                        elif current_grid[nr][nc] == 0:
                                            # Should be in comp if connected
                                            pass
                        else: # len(nums_in_comp) == 0
                            # Unnumbered white component.
                            # Check if it is trapped (surrounded by Black/Edge)
                            trapped = True
                            for cr, cc in comp:
                                for nr, nc in get_neighbors(cr, cc):
                                    if current_grid[nr][nc] == -1:
                                        trapped = False
                                        break
                                if not trapped: break
                            if trapped:
                                return False # Formed an unnumbered island

            # 4. No 2x2 Black
            for r in range(R-1):
                for c in range(C-1):
                    block = [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]
                    blacks = [p for p in block if current_grid[p[0]][p[1]] == 1]
                    unknowns = [p for p in block if current_grid[p[0]][p[1]] == -1]
                    if len(blacks) == 3 and len(unknowns) == 1:
                        ur, uc = unknowns[0]
                        current_grid[ur][uc] = 0
                        changed = True
                    if len(blacks) == 4:
                        return False

            # 5. Reachability Deduction
            # If an UNKNOWN cell cannot reach any number via (White + Unknown), it must be Black.
            for r in range(R):
                for c in range(C):
                    if current_grid[r][c] == -1:
                        q = [(r,c)]
                        vis = set([(r,c)])
                        reachable = False
                        while q:
                            cr, cc = q.pop(0)
                            if (cr, cc) in numbers:
                                reachable = True
                                break
                            for nr, nc in get_neighbors(cr, cc):
                                if (nr, nc) not in vis and current_grid[nr][nc] != 1:
                                    vis.add((nr, nc))
                                    q.append((nr, nc))

                        if not reachable:
                            current_grid[r][c] = 1
                            changed = True

            # 6. Black Connectivity Pruning
            # If a Black component is isolated (no unknown neighbors) and there are other Black components, fail.
            black_comps = get_connected_black(current_grid)
            if len(black_comps) > 1:
                for comp in black_comps:
                    has_unknown_neighbor = False
                    for cr, cc in comp:
                        for nr, nc in get_neighbors(cr, cc):
                            if current_grid[nr][nc] == -1:
                                has_unknown_neighbor = True
                                break
                        if has_unknown_neighbor: break

                    if not has_unknown_neighbor:
                        # Isolated component
                        return False

        return True

    def solve_recursive(current_grid):
        # Find first unknown
        r_unknown, c_unknown = -1, -1
        for r in range(R):
            for c in range(C):
                if current_grid[r][c] == -1:
                    r_unknown, c_unknown = r, c
                    break
            if r_unknown != -1: break

        if r_unknown == -1:
            # Grid full. Final check: Black connectivity
            comps = get_connected_black(current_grid)
            if len(comps) > 1:
                return None
            return current_grid

        # Heuristic: Try White (0) then Black (1)
        # Try White
        grid_white = [row[:] for row in current_grid]
        grid_white[r_unknown][c_unknown] = 0
        if propagate(grid_white):
            res = solve_recursive(grid_white)
            if res is not None: return res

        # Try Black
        grid_black = [row[:] for row in current_grid]
        grid_black[r_unknown][c_unknown] = 1
        if propagate(grid_black):
            res = solve_recursive(grid_black)
            if res is not None: return res

        return None

    if not propagate(grid):
        return "No Solution"

    final_grid = solve_recursive(grid)

    if final_grid is None:
        return "No Solution"

    out_grid = []
    for r in range(R):
        row_out = []
        for c in range(C):
            if final_grid[r][c] == 1:
                row_out.append('B')
            else:
                row_out.append(None)
        out_grid.append(row_out)

    return out_grid

