                            grid[ur][uc] = 1
                            changed = True

            # Rule: Separation. Unknown cell between two different islands must be black.
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 0:
                        roots = set()
                        for nr, nc in get_neighbors(r, c):
                            if grid[nr][nc] == 1 and (nr, nc) in comp_map:
                                roots.add(comp_map[(nr, nc)])
                        if len(roots) > 1:
                            grid[r][c] = 2
                            changed = True

            # Pruning: Black isolation check
            # If a black cell is surrounded by White/Border (no Black/Unknown neighbors)
            # and there are other black cells, it's permanently isolated.
            total_black = sum(1 for r in range(R) for c in range(C) if grid[r][c] == 2)
            if total_black > 1:
                for r in range(R):
                    for c in range(C):
                        if grid[r][c] == 2:
                            has_conn = False
                            for nr, nc in get_neighbors(r, c):
                                if grid[nr][nc] != 1: # Is Black or Unknown
                                    has_conn = True
                                    break
                            if not has_conn:
                                return False

        return True

    # Backtracking search
    def backtrack():
        if not propagate():
            return None
        if not check_2x2():
            return None

        unknowns = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == 0]
        if not unknowns:
            if check_black_connectivity():
                return [row[:] for row in grid]
            return None

        # Heuristic: Pick cell with most known neighbors (MRV-like)
        best = None
        best_score = -1
        for r, c in unknowns:
            score = 0
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] != 0: score += 1
            if score > best_score:
                best_score = score
                best = (r, c)

        if best is None: best = unknowns[0]
        br, bc = best

        saved = [row[:] for row in grid]

        # Try White
        grid[br][bc] = 1
        # Quick validity check for White placement
        comps = get_components()
        valid = True
        for cells, nums in comps:
            if (br, bc) in cells:
                if len(nums) > 1: valid = False
                if len(nums) == 1 and len(cells) > nums[0][2]: valid = False
                break
        if valid:
            res = backtrack()
            if res: return res

        # Restore
        grid = [row[:] for row in saved]

        # Try Black
        grid[br][bc] = 2
        res = backtrack()
        if res: return res

        return None

    res_grid = backtrack()
    if res_grid:
        out = []
        for r in range(R):
            row_out = []
            for c in range(C):
                if res_grid[r][c] == 2:
                    row_out.append('B')
                else:
                    row_out.append(None)
            out.append(row_out)
        return out
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
