import sys
sys.setrecursionlimit(5000)

def solve(observation):
    grid = observation['data']
    H = len(grid)
    W = len(grid[0])

    # Directions: N, S, W, E
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbor(r, c, d):
        nr, nc = r + DIRS[d][0], c + DIRS[d][1]
        if 0 <= nr < H and 0 <= nc < W:
            return (nr, nc)
        return None

    class State:
        def __init__(self):
            self.edges_on = set()
            self.edges_off = set()
            self.degree = [[0]*W for _ in range(H)]
            self.white_constraints = [] 

        def copy(self):
            new_state = State()
            new_state.edges_on = set(self.edges_on)
            new_state.edges_off = set(self.edges_off)
            new_state.degree = [row[:] for row in self.degree]
            new_state.white_constraints = list(self.white_constraints)
            return new_state

        def _norm_edge(self, r1, c1, r2, c2):
            if (r1, c1) > (r2, c2):
                return (r2, c2), (r1, c1)
            return (r1, c1), (r2, c2)

        def add_edge(self, r1, c1, r2, c2):
            e = self._norm_edge(r1, c1, r2, c2)
            if e in self.edges_off: return False
            if e in self.edges_on: return True

            self.edges_on.add(e)
            self.degree[r1][c1] += 1
            self.degree[r2][c2] += 1

            if self.degree[r1][c1] > 2 or self.degree[r2][c2] > 2:
                return False
            return True

        def forbid_edge(self, r1, c1, r2, c2):
            e = self._norm_edge(r1, c1, r2, c2)
            if e in self.edges_on: return False
            if e not in self.edges_off:
                self.edges_off.add(e)
                return True
            return False

        def is_edge_on(self, r1, c1, r2, c2):
            return self._norm_edge(r1, c1, r2, c2) in self.edges_on

        def is_edge_off(self, r1, c1, r2, c2):
            return self._norm_edge(r1, c1, r2, c2) in self.edges_off

    def get_clues():
        clues = []
        for r in range(H):
            for c in range(W):
                if grid[r][c] in ('W', 'B'):
                    clues.append((r, c, grid[r][c]))
        return clues

    def get_configs(r, c, ctype):
        configs = []
        if ctype == 'B':
            # 4 turns: NE, NW, SE, SW (dirs: 0:N, 1:S, 2:W, 3:E)
            pairs = [(0, 3), (0, 2), (1, 3), (1, 2)]
            for d1, d2 in pairs:
                n1 = get_neighbor(r, c, d1)
                n2 = get_neighbor(r, c, d2)
                if n1 and n2:
                    configs.append((d1, d2))
        else: # 'W'
            # 2 straight: NS, EW
            pairs = [(0, 1), (2, 3)]
            for d1, d2 in pairs:
                n1 = get_neighbor(r, c, d1)
                n2 = get_neighbor(r, c, d2)
                if n1 and n2:
                    configs.append((d1, d2))
        return configs

    final_path = None

    def is_valid_cycle(state):
        if not state.edges_on: return False
        adj = {}
        nodes = set()
        for (u, v) in state.edges_on:
            nodes.add(u); nodes.add(v)
            adj.setdefault(u, []).append(v)
            adj.setdefault(v, []).append(u)

        for node in nodes:
            if len(adj.get(node, [])) != 2: return False

        start = next(iter(nodes))
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node in visited: continue
            visited.add(node)
            for nb in adj[node]:
                if nb not in visited: stack.append(nb)

        if len(visited) != len(nodes): return False

        for r in range(H):
            for c in range(W):
                if grid[r][c] in ('W', 'B'):
                    if (r, c) not in nodes: return False
        return True

    def has_small_cycle(state):
        adj = {}
        nodes = set()
        for (u, v) in state.edges_on:
            nodes.add(u); nodes.add(v)
            adj.setdefault(u, []).append(v)
            adj.setdefault(v, []).append(u)

        visited_global = set()
        for start in nodes:
            if start in visited_global: continue
            component_nodes = set()
            stack = [start]
            while stack:
                node = stack.pop()
                if node in component_nodes: continue
                component_nodes.add(node)
                visited_global.add(node)
                for nb in adj[node]:
                    if nb not in component_nodes: stack.append(nb)

            all_deg2 = all(len(adj[node]) == 2 for node in component_nodes)
            if all_deg2:
                for r in range(H):
                    for c in range(W):
                        if grid[r][c] in ('W', 'B'):
                            if (r, c) not in component_nodes:
                                return True
        return False

    def propagate(state):
        changed = True
        while changed:
            changed = False
            for r in range(H):
                for c in range(W):
                    if state.degree[r][c] == 2:
                        for d in range(4):
                            nb = get_neighbor(r, c, d)
                            if nb and not state.is_edge_on(r, c, nb[0], nb[1]):
                                if state.forbid_edge(r, c, nb[0], nb[1]): changed = True
                    elif state.degree[r][c] > 2: return False

            for r in range(H):
                for c in range(W):
                    if grid[r][c] == 'B' and state.degree[r][c] == 2:
                        neighbors = []
                        for d in range(4):
                            nb = get_neighbor(r, c, d)
                            if nb and state.is_edge_on(r, c, nb[0], nb[1]):
                                neighbors.append((d, nb))
                        if len(neighbors) == 2:
                            d1, nb1 = neighbors[0]
                            d2, nb2 = neighbors[1]
                            if (d1 + d2 == 1) or (d1 + d2 == 5): return False # Parallel
                            for d, nb in neighbors:
                                nnb = get_neighbor(nb[0], nb[1], d)
                                if nnb:
                                    if state.is_edge_off(nb[0], nb[1], nnb[0], nnb[1]): return False
                                    if not state.is_edge_on(nb[0], nb[1], nnb[0], nnb[1]):
                                        if state.add_edge(nb[0], nb[1], nnb[0], nnb[1]): changed = True
                                        else: return False
                                else: return False

            new_constraints = []
            for wc in state.white_constraints:
                wr, wc_c, config, edge1, edge2 = wc
                e1_on = state.is_edge_on(*edge1[0], *edge1[1])
                e2_on = state.is_edge_on(*edge2[0], *edge2[1])
                if e1_on and e2_on: return False
                if e1_on:
                    if state.forbid_edge(*edge2[0], *edge2[1]): changed = True
                elif e2_on:
                    if state.forbid_edge(*edge1[0], *edge1[1]): changed = True
                else:
                    new_constraints.append(wc)
            state.white_constraints = new_constraints

            if has_small_cycle(state): return False
        return True

    def solve_clues(state, idx, clues):
        nonlocal final_path
        if final_path: return True
        if idx == len(clues):
            return solve_completion(state)

        r, c, ctype = clues[idx]
        if state.degree[r][c] == 2:
            return solve_clues(state, idx + 1, clues)

        for config in get_configs(r, c, ctype):
            d1, d2 = config
            nb1, nb2 = get_neighbor(r, c, d1), get_neighbor(r, c, d2)
            if state.is_edge_off(r, c, nb1[0], nb1[1]) or state.is_edge_off(r, c, nb2[0], nb2[1]):
                continue

            saved = state.copy()
            if not state.add_edge(r, c, nb1[0], nb1[1]): continue
            if not state.add_edge(r, c, nb2[0], nb2[1]):
                state = saved; continue

            if ctype == 'W':
                n2 = get_neighbor(nb1[0], nb1[1], d1)
                s2 = get_neighbor(nb2[0], nb2[1], d2)
                if n2 and s2:
                    e1 = ((nb1[0], nb1[1]), (n2[0], n2[1]))
                    e2 = ((nb2[0], nb2[1]), (s2[0], s2[1]))
                    if e1[0] > e1[1]: e1 = (e1[1], e1[0])
                    if e2[0] > e2[1]: e2 = (e2[1], e2[0])
                    state.white_constraints.append((r, c, config, e1, e2))

            if propagate(state):
                if solve_clues(state, idx + 1, clues): return True
            state = saved
        return False

    def solve_completion(state):
        nonlocal final_path
        deg1 = [(r, c) for r in range(H) for c in range(W) if state.degree[r][c] == 1]
        if not deg1:
            if is_valid_cycle(state):
                start = None
                for r in range(H):
                    for c in range(W):
                        if grid[r][c] in ('W', 'B'):
                            start = (r, c); break
                    if start: break
                if not start: return True
                path = [start]
                curr, prev = start, None
                adj = {}
                for (u, v) in state.edges_on:
                    adj.setdefault(u, []).append(v)
                    adj.setdefault(v, []).append(u)
                while True:
                    nxt = next((nb for nb in adj[curr] if nb != prev), None)
                    if nxt == start:
                        path.append(start); break
                    path.append(nxt)
                    prev, curr = curr, nxt
                final_path = path
                return True
            return False

        best = min(deg1, key=lambda n: sum(1 for d in range(4) if get_neighbor(n[0], n[1], d) and not state.is_edge_off(n[0], n[1], *get_neighbor(n[0], n[1], d)) and state.degree[get_neighbor(n[0], n[1], d)[0]][get_neighbor(n[0], n[1], d)[1]] < 2))
        r, c = best
        for d in range(4):
            nb = get_neighbor(r, c, d)
            if nb and not state.is_edge_off(r, c, nb[0], nb[1]) and state.degree[nb[0]][nb[1]] < 2:
                saved = state.copy()
                if state.add_edge(r, c, nb[0], nb[1]):
                    if propagate(state):
                        if solve_completion(state): return True
                state = saved
        return False

    clues = get_clues()
    clues.sort(key=lambda x: 0 if x[2] == 'W' else 1)
    solve_clues(State(), 0, clues)
    return final_path if final_path else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
