import sys
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    H = len(data)
    W = len(data[0])

    clues = {}
    for r in range(H):
        for c in range(W):
            if data[r][c]:
                clues[(r, c)] = data[r][c]

    solver = MasyuSolver(H, W, clues)
    if solver.solve():
        return solver.get_path()
    return "No Solution"

class MasyuSolver:
    def __init__(self, H, W, clues):
        self.H = H
        self.W = W
        self.clues = clues
        self.total_clues = len(clues)

        # State
        self.edges = set() # Set of normalized edges ((r1,c1), (r2,c2))
        self.forbidden = set()
        self.degrees = {}
        for r in range(H):
            for c in range(W):
                self.degrees[(r, c)] = 0

        # Union-Find for connectivity
        self.parent = {}
        self.clue_counts = {} # Root -> count of clues in component
        for r in range(H):
            for c in range(W):
                self.parent[(r, c)] = (r, c)
                self.clue_counts[(r, c)] = 1 if (r, c) in clues else 0

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        ru, rv = self.find(u), self.find(v)
        if ru != rv:
            self.parent[ru] = rv
            self.clue_counts[rv] += self.clue_counts[ru]
            return True
        return False

    def get_neighbors(self, r, c):
        res = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < self.H and 0 <= nc < self.W:
                res.append(((nr, nc), (dr, dc)))
        return res

    def normalize_edge(self, u, v):
        if u > v: u, v = v, u
        return (u, v)

    def add_edge(self, u, v):
        edge = self.normalize_edge(u, v)
        if edge in self.forbidden:
            return False
        if edge in self.edges:
            return True

        # Check cycle
        if self.find(u) == self.find(v):
            # Cycle formed. Must be the final solution containing all clues.
            root = self.find(u)
            if self.clue_counts[root] < self.total_clues:
                return False # Sub-loop
            # If all clues are in, we still need to check if it's a valid loop (White turns)
            # But we can't check White turns fully until degrees are 2 everywhere in loop.
            # However, if we close the loop, we assume we are done.
            # We will verify validity at the end.

        self.edges.add(edge)
        self.degrees[u] += 1
        self.degrees[v] += 1

        if self.degrees[u] > 2 or self.degrees[v] > 2:
            return False

        if self.find(u) != self.find(v):
            self.union(u, v)

        return True

    def forbid_edge(self, u, v):
        edge = self.normalize_edge(u, v)
        if edge in self.edges:
            return False
        if edge in self.forbidden:
            return True
        self.forbidden.add(edge)
        return True

    def propagate(self):
        changed = True
        while changed:
            changed = False
            # 1. Degree constraints
            for r in range(self.H):
                for c in range(self.W):
                    u = (r, c)
                    deg = self.degrees[u]
                    if deg > 2: return False

                    neighbors = self.get_neighbors(r, c)
                    available = []
                    for v, _ in neighbors:
                        if self.normalize_edge(u, v) not in self.edges and self.normalize_edge(u, v) not in self.forbidden:
                            available.append(v)

                    # If degree 2, forbid rest
                    if deg == 2:
                        for v in available:
                            if self.forbid_edge(u, v): changed = True

                    # If clue and deg + available == 2, force rest
                    if u in self.clues:
                        if deg + len(available) == 2:
                            for v in available:
                                if self.add_edge(u, v): changed = True
                                else: return False
                    # If not clue, we don't force degree 2 necessarily, but if deg=0 and available=0, it's unused (ok)
                    # But if deg=1 and available=0, contradiction (unless it's not in loop? No, if deg=1 it's in loop)
                    # Wait, if a node is in the loop (deg > 0), it must reach deg 2.
                    if deg > 0 and deg + len(available) < 2:
                        return False

            # 2. Clue specific constraints
            for (r, c), ctype in self.clues.items():
                u = (r, c)
                deg = self.degrees[u]
                neighbors = self.get_neighbors(r, c)

                # Map direction to neighbor
                dir_map = {}
                for v, (dr, dc) in neighbors:
                    dir_map[(dr, dc)] = v

                used_dirs = []
                for v, (dr, dc) in neighbors:
                    if self.normalize_edge(u, v) in self.edges:
                        used_dirs.append((dr, dc))

                if ctype == 'W':
                    # Must go straight
                    if deg == 1:
                        d = used_dirs[0]
                        opp = (-d[0], -d[1])
                        # Force opposite
                        if opp in dir_map:
                            v_opp = dir_map[opp]
                            if self.add_edge(u, v_opp): changed = True
                            else: return False
                        # Forbid perp
                        for dd in [(-1,0), (1,0), (0,-1), (0,1)]:
                            if dd != d and dd != opp and dd in dir_map:
                                if self.forbid_edge(u, dir_map[dd]): changed = True
                    elif deg == 2:
                        # Check collinear
                        d1, d2 = used_dirs
                        if d1[0] != -d2[0] or d1[1] != -d2[1]:
                            return False # Not straight

                elif ctype == 'B':
                    # Must turn
                    if deg == 1:
                        d = used_dirs[0]
                        opp = (-d[0], -d[1])
                        # Forbid opposite (cannot go straight)
                        if opp in dir_map:
                            if self.forbid_edge(u, dir_map[opp]): changed = True
                    elif deg == 2:
                        # Check perpendicular
                        d1, d2 = used_dirs
                        if d1[0] == -d2[0] and d1[1] == -d2[1]:
                            return False # Collinear, not turn
                        if d1[0] == d2[0] and d1[1] == d2[1]:
                             return False # Same edge? impossible

                        # Force extensions
                        # Neighbor in d1 must extend straight
                        v1 = dir_map[d1]
                        # v1 must connect to v1 + d1
                        v1_next = (v1[0] + d1[0], v1[1] + d1[1])
                        if 0 <= v1_next[0] < self.H and 0 <= v1_next[1] < self.W:
                            if self.add_edge(v1, v1_next): changed = True
                            else: return False
                            # Also v1 cannot turn, so forbid perp at v1 relative to u-v1
                            # u-v1 is direction -d1 from v1.
                            # So v1 must connect to v1+d1.
                            # Forbid perp at v1
                            for dd in [(-1,0), (1,0), (0,-1), (0,1)]:
                                if dd != d1 and dd != (-d1[0], -d1[1]):
                                    v1_neighbor = (v1[0] + dd[0], v1[1] + dd[1])
                                    if 0 <= v1_neighbor[0] < self.H and 0 <= v1_neighbor[1] < self.W:
                                        if self.forbid_edge(v1, v1_neighbor): changed = True

                        # Neighbor in d2 must extend straight
                        v2 = dir_map[d2]
                        v2_next = (v2[0] + d2[0], v2[1] + d2[1])
                        if 0 <= v2_next[0] < self.H and 0 <= v2_next[1] < self.W:
                            if self.add_edge(v2, v2_next): changed = True
                            else: return False
                            for dd in [(-1,0), (1,0), (0,-1), (0,1)]:
                                if dd != d2 and dd != (-d2[0], -d2[1]):
                                    v2_neighbor = (v2[0] + dd[0], v2[1] + dd[1])
                                    if 0 <= v2_neighbor[0] < self.H and 0 <= v2_neighbor[1] < self.W:
                                        if self.forbid_edge(v2, v2_neighbor): changed = True

            # 3. White Turn Condition Check (Pruning)
            # If W is satisfied, check if neighbors are forced straight
            for (r, c), ctype in self.clues.items():
                if ctype == 'W' and self.degrees[(r,c)] == 2:
                    u = (r, c)
                    neighbors = self.get_neighbors(r, c)
                    used_vs = []
                    for v, _ in neighbors:
                        if self.normalize_edge(u, v) in self.edges:
                            used_vs.append(v)
                    # Check if both neighbors are forced straight
                    # A neighbor v is forced straight if deg(v)==2 and edges are collinear with u-v
                    turn_possible = False
                    for v in used_vs:
                        if self.degrees[v] == 2:
                            # Check if v is a turn
                            v_neighbors = self.get_neighbors(v[0], v[1])
                            v_edges = []
                            for vn, _ in v_neighbors:
                                if self.normalize_edge(v, vn) in self.edges:
                                    v_edges.append(vn)
                            # Check if v_edges are perp
                            if len(v_edges) == 2:
                                dx1 = v_edges[0][0] - v[0]
                                dy1 = v_edges[0][1] - v[1]
                                dx2 = v_edges[1][0] - v[0]
                                dy2 = v_edges[1][1] - v[1]
                                if dx1*dx2 + dy1*dy2 == 0: # Perp
                                    turn_possible = True
                                    break
                        elif self.degrees[v] < 2:
                            # Not determined yet, so turn is possible
                            turn_possible = True
                            break

                    if not turn_possible:
                        # Both neighbors are straight (or will be), so W condition fails
                        # But wait, if neighbor deg < 2, it might turn later.
                        # So we only fail if neighbor deg == 2 and is straight.
                        # Let's refine:
                        all_straight = True
                        for v in used_vs:
                            is_straight = False
                            if self.degrees[v] == 2:
                                v_neighbors = self.get_neighbors(v[0], v[1])
                                v_edges = []
                                for vn, _ in v_neighbors:
                                    if self.normalize_edge(v, vn) in self.edges:
                                        v_edges.append(vn)
                                if len(v_edges) == 2:
                                    dx1 = v_edges[0][0] - v[0]
                                    dy1 = v_edges[0][1] - v[1]
                                    dx2 = v_edges[1][0] - v[0]
                                    dy2 = v_edges[1][1] - v[1]
                                    if dx1*dx2 + dy1*dy2 == 0: # Perp
                                        is_straight = False
                                    else:
                                        is_straight = True
                            if not is_straight:
                                all_straight = False
                                break
                        if all_straight:
                            return False

        return True

    def search(self):
        if not self.propagate():
            return False

        # Check if solved
        # All clues deg 2, single component, valid white turns
        all_clues_deg2 = True
        for u in self.clues:
            if self.degrees[u] != 2:
                all_clues_deg2 = False
                break

        if all_clues_deg2:
            # Check connectivity
            roots = set()
            for u in self.clues:
                roots.add(self.find(u))
            if len(roots) == 1:
                # Check white turns
                if self.check_white_turns():
                    return True
                # If white turns fail, we might need to backtrack, but propagation should have caught it?
                # Propagation only catches if neighbors are forced straight.
                # Here neighbors might be deg 2 but we didn't check?
                # Actually propagate checks it.
                # So if we are here, it should be valid.
                return True

        # Heuristic: Pick a clue with deg < 2 or a node near clues
        # Or just pick any node with deg < 2 and available edges
        # Better: Pick a clue that is not satisfied
        target = None
        for u in self.clues:
            if self.degrees[u] < 2:
                target = u
                break

        if target is None:
            # All clues satisfied, but maybe not connected?
            # Pick any node with deg < 2
            for r in range(self.H):
                for c in range(self.W):
                    if self.degrees[(r,c)] < 2:
                        # Check available
                        neighbors = self.get_neighbors(r, c)
                        for v, _ in neighbors:
                            if self.normalize_edge((r,c), v) not in self.edges and self.normalize_edge((r,c), v) not in self.forbidden:
                                target = (r, c)
                                break
                        if target: break
                if target: break

        if target is None:
            return False # No moves left, not solved

        r, c = target
        neighbors = self.get_neighbors(r, c)
        # Sort neighbors?
        for v, _ in neighbors:
            edge = self.normalize_edge(target, v)
            if edge not in self.edges and edge not in self.forbidden:
                # Try add
                # Save state
                old_edges = self.edges.copy()
                old_forbidden = self.forbidden.copy()
                old_degrees = self.degrees.copy()
                old_parent = self.parent.copy()
                old_clue_counts = self.clue_counts.copy()

                if self.add_edge(target, v):
                    if self.search():
                        return True

                # Backtrack
                self.edges = old_edges
                self.forbidden = old_forbidden
                self.degrees = old_degrees
                self.parent = old_parent
                self.clue_counts = old_clue_counts

        return False

    def check_white_turns(self):
        for (r, c), ctype in self.clues.items():
            if ctype == 'W':
                u = (r, c)
                neighbors = self.get_neighbors(r, c)
                used_vs = []
                for v, _ in neighbors:
                    if self.normalize_edge(u, v) in self.edges:
                        used_vs.append(v)
                if len(used_vs) != 2: return False

                turn_found = False
                for v in used_vs:
                    if self.degrees[v] == 2:
                        v_neighbors = self.get_neighbors(v[0], v[1])
                        v_edges = []
                        for vn, _ in v_neighbors:
                            if self.normalize_edge(v, vn) in self.edges:
                                v_edges.append(vn)
                        if len(v_edges) == 2:
                            dx1 = v_edges[0][0] - v[0]
                            dy1 = v_edges[0][1] - v[1]
                            dx2 = v_edges[1][0] - v[0]
                            dy2 = v_edges[1][1] - v[1]
                            if dx1*dx2 + dy1*dy2 == 0:
                                turn_found = True
                                break
                if not turn_found:
                    return False
        return True

    def solve(self):
        return self.search()

    def get_path(self):
        # Reconstruct path from edges
        # Find a start node (any clue)
        start = list(self.clues.keys())[0]
        path = [start]
        curr = start
        prev = None
        while True:
            neighbors = self.get_neighbors(curr[0], curr[1])
            next_node = None
            for v, _ in neighbors:
                if self.normalize_edge(curr, v) in self.edges:
                    if v != prev:
                        next_node = v
                        break
            if next_node is None:
                break
            path.append(next_node)
            prev = curr
            curr = next_node
            if curr == start:
                break
        return path

if __name__ == "__main__":
    print(solve(OBSERVATION))
