    # We fill row by row to ensure 1 star per row automatically.
    # But we need to ensure 1 star per col and region.
    # MRV Heuristic: Pick the row with the fewest valid candidates?
    # Actually, filling row by row is simple and efficient for N=6.

    solution = None

    def backtrack(row_idx, placed_stars):
        nonlocal solution
        if solution is not None:
            return True

        if row_idx == N:
            solution = list(placed_stars)
            return True

        # Try all columns in the current row
        # Optimization: Check candidates validity first
        candidates = []
        for c in range(N):
            if is_valid_placement(row_idx, c, placed_stars):
                candidates.append(c)

        # If no candidates, backtrack
        if not candidates:
            return False

        for c in candidates:
            placed_stars.append((row_idx, c))
            if backtrack(row_idx + 1, placed_stars):
                return True
            placed_stars.pop()

        return False

    backtrack(0, [])

    if solution is None:
        return "No Solution"

    # Format output as grid with 'S' and None
    # The prompt asks for "same-sized grid using 'S' for star cells and None for non-star cells."
    # But also says "returning the final string answer".
    # I will return a string representation of the grid.

    output_grid = [[None for _ in range(N)] for _ in range(N)]
    for r, c in solution:
