        r_float = float(parts[0].strip())
        c = int(parts[1].strip())
        r1 = int(r_float - 0.5)
        r2 = int(r_float + 0.5)
        if op == 'v':
            constraints.append(((r1, c), (r2, c), '>'))
        elif op == '^':
            constraints.append(((r1, c), (r2, c), '<'))

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # 1. Apply Binary Constraints (Inequalities) - Arc Consistency
            for (r1, c1), (r2, c2), op in constraints:
                d1 = domains[r1][c1]
                d2 = domains[r2][c2]

                new_d1 = set()
                new_d2 = set()

                if op == '<':
                    for x in d1:
                        if any(y > x for y in d2):
                            new_d1.add(x)
                    for y in d2:
