import ast
import copy

def solve(observation):
    # Parse the observation into internal structures
    data = observation['data']
    h_raw = observation.get('horizontal', {})
    v_raw = observation.get('vertical', {})

    N = len(data)
    # Grid representation: 0 = Empty, 1 = Black ('B'), -1 = White ('W')
    grid = [[0] * N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val == 'B':
                grid[r][c] = 1
            elif val == 'W':
                grid[r][c] = -1

    # Parse constraints
    # h_cons[(r, c)] stores relation between (r, c) and (r, c+1)
    # 1 means same color, -1 means different color
    h_cons = {}
    for k, v in h_raw.items():
        t = ast.literal_eval(k)
        r, c_float = t
        c = int(c_float - 0.5)
        # Map '=' to 1 (same), 'x' to -1 (diff)
        relation = 1 if v == '=' else -1
        h_cons[(r, c)] = relation

    # v_cons[(r, c)] stores relation between (r, c) and (r+1, c)
    v_cons = {}
    for k, v in v_raw.items():
        t = ast.literal_eval(k)
        r_float, c = t
        r = int(r_float - 0.5)
        relation = 1 if v == '=' else -1
        v_cons[(r, c)] = relation

    # Check if current grid state is valid (no contradictions)
    def is_valid(g):
        limit = N // 2
        # Check counts
        for r in range(N):
            b_count = sum(1 for c in range(N) if g[r][c] == 1)
            w_count = sum(1 for c in range(N) if g[r][c] == -1)
            if b_count > limit or w_count > limit:
                return False
        for c in range(N):
            b_count = sum(1 for r in range(N) if g[r][c] == 1)
            w_count = sum(1 for r in range(N) if g[r][c] == -1)
            if b_count > limit or w_count > limit:
                return False

        # Check triples
        for r in range(N):
            for c in range(N - 2):
                if g[r][c] != 0 and g[r][c] == g[r][c+1] == g[r][c+2]:
                    return False
        for c in range(N):
            for r in range(N - 2):
                if g[r][c] != 0 and g[r][c] == g[r+1][c] == g[r+2][c]:
                    return False

        # Check explicit constraints (only if both cells are filled)
        for (r, c), rel in h_cons.items():
            if g[r][c] != 0 and g[r][c+1] != 0:
                if rel == 1 and g[r][c] != g[r][c+1]:
                    return False
                if rel == -1 and g[r][c] == g[r][c+1]:
                    return False
        for (r, c), rel in v_cons.items():
            if g[r][c] != 0 and g[r+1][c] != 0:
                if rel == 1 and g[r][c] != g[r+1][c]:
                    return False
                if rel == -1 and g[r][c] == g[r+1][c]:
                    return False

        return True

    # Propagate constraints until no more changes or contradiction found
    def propagate(g):
        changed = True
        while changed:
            changed = False

            # 1. Apply explicit constraints
            for (r, c), rel in h_cons.items():
                if g[r][c] != 0 and g[r][c+1] == 0:
                    g[r][c+1] = g[r][c] * rel
                    changed = True
                elif g[r][c+1] != 0 and g[r][c] == 0:
                    g[r][c] = g[r][c+1] * rel
                    changed = True

            for (r, c), rel in v_cons.items():
                if g[r][c] != 0 and g[r+1][c] == 0:
                    g[r+1][c] = g[r][c] * rel
                    changed = True
                elif g[r+1][c] != 0 and g[r][c] == 0:
                    g[r][c] = g[r+1][c] * rel
                    changed = True

            # 2. Apply Count Rule (Balance)
            for r in range(N):
                b_count = sum(1 for c in range(N) if g[r][c] == 1)
                w_count = sum(1 for c in range(N) if g[r][c] == -1)
                if b_count == N // 2:
                    for c in range(N):
                        if g[r][c] == 0:
                            g[r][c] = -1
                            changed = True
                if w_count == N // 2:
                    for c in range(N):
                        if g[r][c] == 0:
                            g[r][c] = 1
                            changed = True

            for c in range(N):
                b_count = sum(1 for r in range(N) if g[r][c] == 1)
                w_count = sum(1 for r in range(N) if g[r][c] == -1)
                if b_count == N // 2:
                    for r in range(N):
                        if g[r][c] == 0:
                            g[r][c] = -1
                            changed = True
                if w_count == N // 2:
                    for r in range(N):
                        if g[r][c] == 0:
                            g[r][c] = 1
                            changed = True

            # 3. Apply No-Triples Rule
            # Horizontal
            for r in range(N):
                for c in range(N - 2):
                    # Pattern X X ? -> ? must be !X
                    if g[r][c] != 0 and g[r][c] == g[r][c+1]:
                        if g[r][c+2] == 0:
                            g[r][c+2] = -g[r][c]
                            changed = True
                    # Pattern ? X X -> ? must be !X
                    if g[r][c+1] != 0 and g[r][c+1] == g[r][c+2]:
                        if g[r][c] == 0:
                            g[r][c] = -g[r][c+1]
                            changed = True
                    # Pattern X ? X -> ? must be !X
                    if g[r][c] != 0 and g[r][c] == g[r][c+2]:
                        if g[r][c+1] == 0:
                            g[r][c+1] = -g[r][c]
                            changed = True
            # Vertical
            for c in range(N):
                for r in range(N - 2):
                    if g[r][c] != 0 and g[r][c] == g[r+1][c]:
                        if g[r+2][c] == 0:
                            g[r+2][c] = -g[r][c]
                            changed = True
                    if g[r+1][c] != 0 and g[r+1][c] == g[r+2][c]:
                        if g[r][c] == 0:
                            g[r][c] = -g[r+1][c]
                            changed = True
                    if g[r][c] != 0 and g[r][c] == g[r+2][c]:
                        if g[r+1][c] == 0:
                            g[r+1][c] = -g[r][c]
                            changed = True

            # Check for contradictions after propagation step
            if not is_valid(g):
                return False

        return True

    # DFS Backtracking Search
    def search(g):
        # First, propagate all logical deductions
        if not propagate(g):
            return None

        # Check if grid is full
        is_full = True
        for r in range(N):
            for c in range(N):
                if g[r][c] == 0:
                    is_full = False
                    break
            if not is_full:
                break

        if is_full:
            return g

        # Heuristic: Pick first empty cell (could be optimized with MRV)
        for r in range(N):
            for c in range(N):
                if g[r][c] == 0:
                    # Try Black (1)
                    g[r][c] = 1
                    res = search(copy.deepcopy(g))
                    if res:
                        return res

                    # Try White (-1)
                    g[r][c] = -1
                    res = search(copy.deepcopy(g))
                    if res:
                        return res

                    # Backtrack
                    return None
        return None

    # Run solver
    final_grid = search(grid)

    if final_grid is None:
        return "No Solution"

    # Convert internal representation back to 'B'/'W'
    result = []
    for r in range(N):
        row_str = []
        for c in range(N):
            row_str.append('B' if final_grid[r][c] == 1 else 'W')
        result.append(row_str)

    return result

