    def is_valid(r, c, val):
        for j in range(N):
            if j != c and grid[r][j] == val: return False
        for i in range(N):
            if i != r and grid[i][c] == val: return False

        if (r, c - 1) in h_cons:
            op = h_cons[(r, c - 1)]
            left = grid[r][c - 1]
            if left is not None:
                if op == '<' and not (left < val): return False
                if op == '>' and not (left > val): return False
        if (r, c) in h_cons:
            op = h_cons[(r, c)]
            right = grid[r][c + 1]
            if right is not None:
                if op == '<' and not (val < right): return False
                if op == '>' and not (val > right): return False

        if (r - 1, c) in v_cons:
            op = v_cons[(r - 1, c)]
            top = grid[r - 1][c]
            if top is not None:
