import sys

# Increase recursion depth to handle deep search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # Grid states
    UNKNOWN = 0
    WHITE = 1
    BLACK = 2

    # Initialize grid
    # 0: Unknown, 1: White, 2: Black
    grid = [[UNKNOWN for _ in range(N)] for _ in range(N)]
    clues = []

    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                grid[r][c] = WHITE
                clues.append((r, c, val))

    # Precompute directions
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_visible_counts(r, c, current_grid):
        # Returns (white_count, unknown_cells_list)
        # The clue cell itself is white and counted.
        w_count = 1
        unknowns = []

        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N:
                cell = current_grid[nr][nc]
                if cell == BLACK:
                    break # Blocked
                elif cell == WHITE:
                    w_count += 1
                elif cell == UNKNOWN:
                    unknowns.append((nr, nc))
                nr += dr
                nc += dc
        return w_count, unknowns

    def check_connectivity(current_grid):
        # Count white cells and check if they are all connected
        start_node = None
        total_white = 0
        for r in range(N):
            for c in range(N):
                if current_grid[r][c] == WHITE:
                    total_white += 1
                    if start_node is None:
                        start_node = (r, c)

        if total_white == 0:
            return True 

        # BFS
        queue = [start_node]
        visited = set([start_node])
        idx = 0
        while idx < len(queue):
            cr, cc = queue[idx]
            idx += 1
            for dr, dc in DIRS:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if current_grid[nr][nc] == WHITE and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        return len(visited) == total_white

    def propagate(current_grid):
        changed = True
        while changed:
            changed = False

            # 1. Clue Logic
            for r, c, val in clues:
                w_count, unknowns = get_visible_counts(r, c, current_grid)

                if w_count > val:
                    return False # Contradiction: Too many white cells visible

                if w_count + len(unknowns) < val:
                    return False # Impossible: Not enough cells to reach count

                if w_count == val:
                    # All unknowns in view must be BLACK
                    for ur, uc in unknowns:
                        if current_grid[ur][uc] == UNKNOWN:
                            current_grid[ur][uc] = BLACK
                            changed = True

                elif w_count + len(unknowns) == val:
                    # All unknowns in view must be WHITE
                    for ur, uc in unknowns:
                        if current_grid[ur][uc] == UNKNOWN:
                            current_grid[ur][uc] = WHITE
                            changed = True

            # 2. Black Cell Isolation Logic
            # If a cell is BLACK, orthogonal neighbors must be WHITE
            for r in range(N):
                for c in range(N):
                    if current_grid[r][c] == BLACK:
                        for dr, dc in DIRS:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if current_grid[nr][nc] == BLACK:
                                    return False # Adjacent black cells violation
                                elif current_grid[nr][nc] == UNKNOWN:
                                    current_grid[nr][nc] = WHITE
                                    changed = True
        return True

    def search(current_grid):
        # Propagate constraints
        if not propagate(current_grid):
            return None

        # Find next unknown cell
        unknown_pos = None
        # Heuristic: Simple row-major scan. 
        # For better performance, one could pick a cell involved in the most constrained clue.
        for r in range(N):
            for c in range(N):
                if current_grid[r][c] == UNKNOWN:
                    unknown_pos = (r, c)
                    break
            if unknown_pos:
                break

        if not unknown_pos:
            # Solved state: No unknowns left.
            # Propagate ensures clues are satisfied (w_count == val) if it returned True.
            # We just need to check connectivity.
            if check_connectivity(current_grid):
                return current_grid
            else:
                return None

        r, c = unknown_pos

        # Try BLACK first (Heuristic: Black cells are sparse and restrictive)
        # Check if valid to place BLACK here (neighbors not BLACK) - Propagate handles this, 
        # but we can prune early.
        can_be_black = True
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                if current_grid[nr][nc] == BLACK:
                    can_be_black = False
                    break

        if can_be_black:
            new_grid = [row[:] for row in current_grid]
            new_grid[r][c] = BLACK
            res = search(new_grid)
            if res:
                return res

        # Try WHITE
        new_grid = [row[:] for row in current_grid]
        new_grid[r][c] = WHITE
        res = search(new_grid)
        if res:
            return res

        return None

    final_grid = search(grid)

    if final_grid:
        output = []
        for r in range(N):
            row_out = []
            for c in range(N):
                if final_grid[r][c] == BLACK:
                    row_out.append('B')
                elif data[r][c] is not None:
                    row_out.append(data[r][c])
                else:
                    row_out.append(None)
            output.append(row_out)
        return output
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

