OBSERVATION = {'data': [[None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None], [1, None, None, None, None], [5, None, None, None, None]], 'horizontal': {'(0, 0.5)': '<', '(0, 1.5)': '<', '(2, 1.5)': '<', '(2, 3.5)': '>', '(4, 3.5)': '>'}, 'vertical': {'(0.5, 1)': '^', '(1.5, 0)': '^', '(1.5, 4)': '^', '(2.5, 2)': '^', '(3.5, 3)': '^'}}

import copy

def solve(observation):
    data = observation['data']
    N = len(data)

    # Parse constraints from string keys to integer coordinates
    # Horizontal: (r, c+0.5) -> relation between (r,c) and (r,c+1)
    h_constraints = {} 
    for key, val in observation['horizontal'].items():
        parts = key.strip('()').split(',')
        r = int(float(parts[0].strip()))
        c_float = float(parts[1].strip())
        c = int(c_float - 0.5)
        h_constraints[(r, c)] = val

    # Vertical: (r+0.5, c) -> relation between (r,c) and (r+1,c)
    v_constraints = {} 
    for key, val in observation['vertical'].items():
        parts = key.strip('()').split(',')
        r_float = float(parts[0].strip())
        c = int(float(parts[1].strip()))
        r = int(r_float - 0.5)
        v_constraints[(r, c)] = val

    # Initialize domains for each cell
    domains = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]

    # Apply givens
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    def check_ineq(val1, val2, op):
        # val1 is top/left, val2 is bottom/right
        if op == '<': return val1 < val2
        if op == '>': return val1 > val2
        if op == '^': return val1 < val2 # Point up means top is smaller
        if op == 'v': return val1 > val2 # Point down means bottom is smaller
        return True

    def get_peers(r, c):
        peers = []
        for i in range(N):
            if i != c: peers.append((r, i))
            if i != r: peers.append((i, c))
        return peers

    def propagate(domains):
        # Constraint Propagation (AC-3 style + Hidden Singles)
        changed = True
        while changed:
            changed = False

            # 1. Unit Propagation (Naked Singles)
            # If a cell has 1 value, remove it from peers
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        for pr, pc in get_peers(r, c):
                            if val in domains[pr][pc]:
                                domains[pr][pc].discard(val)
                                if len(domains[pr][pc]) == 0: return False
                                changed = True

            # 2. Inequality Propagation (Arc Consistency)
            # Filter domains based on inequality constraints
            for (r, c), op in h_constraints.items():
                d1 = domains[r][c]
                d2 = domains[r][c+1]

                # Filter d1: keep x if exists y in d2 s.t. x op y
                new_d1 = {x for x in d1 if any(check_ineq(x, y, op) for y in d2)}
                if new_d1 != d1:
                    domains[r][c] = new_d1
                    if len(new_d1) == 0: return False
                    changed = True

                # Filter d2: keep y if exists x in (updated) d1 s.t. x op y
                new_d2 = {y for y in d2 if any(check_ineq(x, y, op) for x in domains[r][c])}
                if new_d2 != d2:
                    domains[r][c+1] = new_d2
                    if len(new_d2) == 0: return False
                    changed = True

            for (r, c), op in v_constraints.items():
                d1 = domains[r][c]
                d2 = domains[r+1][c]

                new_d1 = {x for x in d1 if any(check_ineq(x, y, op) for y in d2)}
                if new_d1 != d1:
                    domains[r][c] = new_d1
                    if len(new_d1) == 0: return False
                    changed = True

                new_d2 = {y for y in d2 if any(check_ineq(x, y, op) for x in domains[r][c])}
                if new_d2 != d2:
                    domains[r+1][c] = new_d2
                    if len(new_d2) == 0: return False
                    changed = True

            # 3. Hidden Singles
            # If a value can only go in one cell in a row/col, place it
            for r in range(N):
                val_counts = {v: [] for v in range(1, N+1)}
                for c in range(N):
                    for v in domains[r][c]:
                        val_counts[v].append(c)
                for v, positions in val_counts.items():
                    if len(positions) == 1:
                        c = positions[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {v}
                            changed = True
                            if len(domains[r][c]) == 0: return False

            for c in range(N):
                val_counts = {v: [] for v in range(1, N+1)}
                for r in range(N):
                    for v in domains[r][c]:
                        val_counts[v].append(r)
                for v, positions in val_counts.items():
                    if len(positions) == 1:
                        r = positions[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {v}
                            changed = True
                            if len(domains[r][c]) == 0: return False

        return True

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    def solve_recursive(domains):
        # Find unsolved cell with Minimum Remaining Values (MRV)
        min_len = N + 1
        min_cell = None
        is_solved = True

        for r in range(N):
            for c in range(N):
                d_len = len(domains[r][c])
                if d_len == 0: return None # Failure
                if d_len > 1:
                    is_solved = False
                    if d_len < min_len:
                        min_len = d_len
                        min_cell = (r, c)

        if is_solved:
            # Construct solution grid
            sol = [[0]*N for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    sol[r][c] = next(iter(domains[r][c]))
            return sol

        r, c = min_cell
        # Try values in sorted order (deterministic)
        for val in sorted(list(domains[r][c])):
            new_domains = copy.deepcopy(domains)
            new_domains[r][c] = {val}

            # Propagate constraints after assignment
            if propagate(new_domains):
                result = solve_recursive(new_domains)
                if result:
                    return result

        return None

    final_sol = solve_recursive(domains)
    return final_sol if final_sol else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
