import sys

# Increase recursion depth for deep backtracking if necessary
sys.setrecursionlimit(5000)

OBSERVATION = {'data': [[1, 5, 3, 4, 1], [5, 3, 5, 3, 1], [3, 5, 4, 1, 5], [5, 1, 2, 3, 4], [2, 1, 1, 1, 3]]}

WHITE = 1
BLACK = 2
UNKNOWN = 0

def solve(obs):
    data = obs['data']
    N = len(data)
    # State grid: 0=Unknown, 1=White, 2=Black
    state = [[UNKNOWN] * N for _ in range(N)]

    # Precompute groups for fast access
    # row_groups[r][val] = [c1, c2, ...]
    # col_groups[c][val] = [r1, r2, ...]
    row_groups = [{} for _ in range(N)]
    col_groups = [{} for _ in range(N)]

    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val not in row_groups[r]:
                row_groups[r][val] = []
            row_groups[r][val].append(c)

            if val not in col_groups[c]:
                col_groups[c][val] = []
            col_groups[c][val].append(r)

    if backtrack(state, data, N, row_groups, col_groups):
        # Convert state to output format
        res = []
        for r in range(N):
            row_res = []
            for c in range(N):
                if state[r][c] == BLACK:
                    row_res.append('B')
                else:
                    row_res.append(None)
            res.append(row_res)
        return res
    return "No Solution"

def backtrack(state, data, N, row_groups, col_groups):
    # Propagate constraints
    # propagate returns True if consistent, False if contradiction found
    # It modifies state in place
    if not propagate(state, data, N, row_groups, col_groups):
        return False

    # Check if grid is full
    unknowns = []
    for r in range(N):
        for c in range(N):
            if state[r][c] == UNKNOWN:
                unknowns.append((r, c))

    if not unknowns:
        # Final connectivity check (strict)
        return check_connectivity_strict(state, N)

    # Heuristic: Pick an unknown cell
    # Prefer cells that are part of groups with conflicts or large segments
    # For simplicity, pick first unknown. 
    # Optimization: Pick one with most neighbors or in a dense group.
    r, c = unknowns[0]

    # Try Black
    state[r][c] = BLACK
    if backtrack(state, data, N, row_groups, col_groups):
        return True
    state[r][c] = UNKNOWN # Undo

    # Try White
    state[r][c] = WHITE
    if backtrack(state, data, N, row_groups, col_groups):
        return True
    state[r][c] = UNKNOWN # Undo

    return False

def propagate(state, data, N, row_groups, col_groups):
    changed = True
    while changed:
        changed = False

        # 1. Adjacency Rule: If Black, neighbors must be White
        for r in range(N):
            for c in range(N):
                if state[r][c] == BLACK:
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < N and 0 <= nc < N:
                            if state[nr][nc] == UNKNOWN:
                                state[nr][nc] = WHITE
                                changed = True
                            elif state[nr][nc] == BLACK:
                                return False # Adjacency violation (Black touches Black)

        # 2. Uniqueness & Group Logic
        # Check Rows
        for r in range(N):
            for val, cols in row_groups[r].items():
                valid, group_changed = process_group(state, r, cols, True, N)
                if not valid: return False
                if group_changed: changed = True

        # Check Cols
        for c in range(N):
            for val, rows in col_groups[c].items():
                valid, group_changed = process_group(state, c, rows, False, N)
                if not valid: return False
                if group_changed: changed = True

        # 3. Connectivity Check (Relaxed)
        # If White cells are separated by Black cells such that no Unknown path exists, Fail
        if not check_connectivity_relaxed(state, N):
            return False

    return True

def process_group(state, fixed_idx, variable_idxs, is_row, N):
    # fixed_idx is r if is_row else c
    # variable_idxs are the other coordinates (cols if row, rows if col)
    cells = []
    for idx in variable_idxs:
        if is_row:
            cells.append((fixed_idx, idx))
        else:
            cells.append((idx, fixed_idx))

    whites = [cell for cell in cells if state[cell[0]][cell[1]] == WHITE]
    unknowns = [cell for cell in cells if state[cell[0]][cell[1]] == UNKNOWN]

    changed = False

    # Rule: At most one White in the group
    if len(whites) > 1:
        return False, False

    if len(whites) == 1:
        # All unknowns must be Black
        for cell in unknowns:
            if state[cell[0]][cell[1]] != BLACK:
                state[cell[0]][cell[1]] = BLACK
                changed = True
        return True, changed

    if len(whites) == 0:
        # Analyze contiguous segments of unknowns
        # Sort unknowns by the variable index
        variable_indices = [idx for idx in variable_idxs if state[fixed_idx if is_row else idx][idx if is_row else fixed_idx] == UNKNOWN]
        variable_indices.sort()

        segments = []
        if variable_indices:
            current_seg = [variable_indices[0]]
            for i in range(1, len(variable_indices)):
                if variable_indices[i] == variable_indices[i-1] + 1:
                    current_seg.append(variable_indices[i])
                else:
                    segments.append(current_seg)
                    current_seg = [variable_indices[i]]
            segments.append(current_seg)

        large_segments = [s for s in segments if len(s) >= 2]

        if len(large_segments) > 1:
            # Need > 1 White to avoid Black-Black adjacency in multiple segments
            # But allowed Whites <= 1. Contradiction.
            return False, False

        if len(large_segments) == 1:
            S = large_segments[0]
            # All unknowns NOT in S must be Black
            for idx in variable_indices:
                if idx not in S:
                    r, c = (fixed_idx, idx) if is_row else (idx, fixed_idx)
                    if state[r][c] != BLACK:
                        state[r][c] = BLACK
                        changed = True

            # Specific logic for the large segment
            if len(S) == 3:
                # Must be B, W, B
                # Middle is White
                mid_idx = S[1]
                r, c = (fixed_idx, mid_idx) if is_row else (mid_idx, fixed_idx)
                if state[r][c] != WHITE:
                    state[r][c] = WHITE
                    changed = True
                # Ends are Black
                for end_idx in [S[0], S[2]]:
                    r, c = (fixed_idx, end_idx) if is_row else (end_idx, fixed_idx)
                    if state[r][c] != BLACK:
                        state[r][c] = BLACK
                        changed = True
            # If len(S) == 2, we know one is W and one is B, but don't know which. No force.

    return True, changed

def check_connectivity_relaxed(state, N):
    # Check if all WHITE cells are in the same component of (WHITE + UNKNOWN) graph
    white_cells = []
    for r in range(N):
        for c in range(N):
            if state[r][c] == WHITE:
                white_cells.append((r, c))

    if not white_cells:
        return True

    start = white_cells[0]
    visited = set()
    queue = [start]
    visited.add(start)

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                if (nr, nc) not in visited:
                    # Can traverse White or Unknown
                    if state[nr][nc] == WHITE or state[nr][nc] == UNKNOWN:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

    # Check if all white cells were visited
    for wc in white_cells:
        if wc not in visited:
            return False
    return True

def check_connectivity_strict(state, N):
    # Check if all WHITE cells form a single connected component (ignoring UNKNOWN, but there are none)
    white_cells = []
    for r in range(N):
        for c in range(N):
            if state[r][c] == WHITE:
                white_cells.append((r, c))

    if not white_cells:
        return True # Technically valid? Rules say "All unshaded...". If 0 unshaded, vacuously true? 
                    # But usually puzzles have at least one.

    start = white_cells[0]
    visited = set()
    queue = [start]
    visited.add(start)

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                if (nr, nc) not in visited and state[nr][nc] == WHITE:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return len(visited) == len(white_cells)

