import sys

# Increase recursion depth to handle deeper search trees if necessary
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # Board state: -1 = Unknown, 0 = White (None in output), 1 = Black ('B' in output)
    board = [[-1] * N for _ in range(N)]

    # Helper to find cells with same value in row/col (peers)
    def get_peers(r, c, val):
        peers = []
        for k in range(N):
            if k != c and data[r][k] == val:
                peers.append((r, k))
            if k != r and data[k][c] == val:
                peers.append((k, c))
        return peers

    # Constraint propagation
    # changes: list of (r, c, val) to apply
    def propagate(changes):
        queue = list(changes)
        while queue:
            r, c, val = queue.pop(0)

            # Check for contradiction with existing state
            if board[r][c] != -1 and board[r][c] != val:
                return False

            board[r][c] = val

            if val == 1:  # Cell is Black
                # Rule 3: Orthogonal neighbors must be White
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if board[nr][nc] == 1:  # Adjacent Black found -> Invalid
                            return False
                        if board[nr][nc] == -1:
                            queue.append((nr, nc, 0))
            else:  # Cell is White
                # Rule 1 & 2: Peers with same number must be Black
                val_num = data[r][c]
                peers = get_peers(r, c, val_num)
                for pr, pc in peers:
                    if board[pr][pc] == 0:  # Duplicate White found -> Invalid
                        return False
                    if board[pr][pc] == -1:
                        queue.append((pr, pc, 1))
        return True

    # Check if all White cells form a single connected group (Rule 4)
    def is_connected():
        start = None
        count_white = 0
        for r in range(N):
            for c in range(N):
                if board[r][c] == 0:
                    count_white += 1
                    if start is None:
                        start = (r, c)

        if count_white == 0:
            return True  # Vacuously true

        visited = set()
        queue = [start]
        visited.add(start)

        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and board[nr][nc] == 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == count_white

    # Backtracking search with pruning
    def solve_recursive():
        # Find first unknown cell (simple heuristic, could be optimized with MRV)
        r_unknown, c_unknown = -1, -1
        for r in range(N):
            for c in range(N):
                if board[r][c] == -1:
                    r_unknown, c_unknown = r, c
                    break
            if r_unknown != -1:
                break

        # Base case: all cells assigned
        if r_unknown == -1:
            return is_connected()

        r, c = r_unknown, c_unknown

        # Try assigning White (0)
        val_num = data[r][c]
        can_be_white = True
        # Check if any peer is already White (pruning)
        for k in range(N):
            if k != c and board[r][k] == 0 and data[r][k] == val_num:
                can_be_white = False
                break
            if k != r and board[k][c] == 0 and data[k][c] == val_num:
                can_be_white = False
                break

        if can_be_white:
            snapshot = [row[:] for row in board]
            if propagate([(r, c, 0)]):
                if solve_recursive():
                    return True
            # Backtrack: restore board
            for i in range(N):
                for j in range(N):
                    board[i][j] = snapshot[i][j]

        # Try assigning Black (1)
        can_be_black = True
        # Check if any neighbor is already Black (pruning)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and board[nr][nc] == 1:
                can_be_black = False
                break

        if can_be_black:
            snapshot = [row[:] for row in board]
            if propagate([(r, c, 1)]):
                if solve_recursive():
                    return True
            # Backtrack: restore board
            for i in range(N):
                for j in range(N):
                    board[i][j] = snapshot[i][j]

        return False

    if solve_recursive():
        # Format output: 'B' for Black, None for White
        result_grid = []
        for r in range(N):
            row_res = []
            for c in range(N):
                if board[r][c] == 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result_grid.append(row_res)
        return result_grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
