        c = int(float(parts[1])) # 1.5 -> 1
        h_constraints[(r, c)] = v

    # v_constraints[(r, c)] = 'v' means data[r][c] > data[r+1][c]
    v_constraints = {}
    for k, v in observation['vertical'].items():
        parts = k.strip('()').split(', ')
        r = int(float(parts[0])) # 0.5 -> 0
        c = int(parts[1])
        v_constraints[(r, c)] = v

    # Initialize domains and grid
    # grid[r][c] stores the assigned value or None
    grid = [row[:] for row in data]

    # Pre-calculate neighbors for efficient checking
    # For each cell, store list of (neighbor_r, neighbor_c, op) where op is relative to current
    # e.g. if current > neighbor, op is '>'
    neighbors = [[[] for _ in range(N)] for _ in range(N)]

    for (r, c), op in h_constraints.items():
        # Constraint between (r, c) and (r, c+1)
        if op == '>':
            neighbors[r][c].append((r, c+1, '>')) # current > neighbor
            neighbors[r][c+1].append((r, c, '<')) # current < neighbor
        else: # '<'
            neighbors[r][c].append((r, c+1, '<'))
            neighbors[r][c+1].append((r, c, '>'))

    for (r, c), op in v_constraints.items():
        # Constraint between (r, c) and (r+1, c)
        if op == 'v': # Top > Bottom
            neighbors[r][c].append((r+1, c, '>'))
            neighbors[r+1][c].append((r, c, '<'))
        else: # '^' -> Top < Bottom
            neighbors[r][c].append((r+1, c, '<'))
            neighbors[r+1][c].append((r, c, '>'))

    def is_valid(r, c, val):
        # Check row
        for j in range(N):
            if j != c and grid[r][j] == val:
                return False
        # Check col
        for i in range(N):
            if i != r and grid[i][c] == val:
                return False
        # Check inequalities with assigned neighbors
        for nr, nc, op in neighbors[r][c]:
            nval = grid[nr][nc]
            if nval is not None:
                if op == '>' and not (val > nval):
                    return False
                if op == '<' and not (val < nval):
                    return False
        return True

    def get_possibilities(r, c):
        if grid[r][c] is not None:
            return [grid[r][c]]

        poss = []
        # Check row/col used values
        used = set()
        for j in range(N):
            if grid[r][j] is not None: used.add(grid[r][j])
        for i in range(N):
            if grid[i][c] is not None: used.add(grid[i][c])

        for val in range(1, N+1):
            if val in used:
                continue
            # Check inequalities
            valid = True
            for nr, nc, op in neighbors[r][c]:
                nval = grid[nr][nc]
                if nval is not None:
                    if op == '>' and not (val > nval):
                        valid = False; break
                    if op == '<' and not (val < nval):
                        valid = False; break
            if valid:
                poss.append(val)
        return poss

    def solve_backtrack():
        # Find unassigned cell with MRV
        min_poss = None
        min_len = N + 1
        best_cell = None

        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    poss = get_possibilities(r, c)
                    if len(poss) == 0:
                        return False # Dead end
                    if len(poss) < min_len:
                        min_len = len(poss)
                        min_poss = poss
                        best_cell = (r, c)
                    if min_len == 1:
                        break
            if min_len == 1:
                break

        if best_cell is None:
            return True # Solved

        r, c = best_cell
        # Try values
        # Heuristic: Try values that are least constraining? 
        # For now, just try in order.
        for val in min_poss:
            grid[r][c] = val
            if solve_backtrack():
                return True
            grid[r][c] = None

        return False

    if solve_backtrack():
        return grid
    else:
        return "No Solution"

