        parts = clean.split(',')
        r = int(parts[0].strip())
        c_float = float(parts[1].strip())
        c = int(c_float)

        if sym == '<':
            constraints.append((r, c, r, c + 1))
        elif sym == '>':
            constraints.append((r, c + 1, r, c))

    # Process Vertical Inequalities
    v_obs = observation.get('vertical', {})
    for key, sym in v_obs.items():
        # Format: '(row.5, col)'
        clean = key.strip('()')
        parts = clean.split(',')
        r_float = float(parts[0].strip())
        c = int(parts[1].strip())
        r = int(r_float)

        if sym == '^': # Bottom > Top => Top < Bottom
            constraints.append((r, c, r + 1, c))
        elif sym == 'v': # Top > Bottom => Bottom < Top
            constraints.append((r + 1, c, r, c))

    # Apply Givens to domains
    for r in range(N):
        for c in range(N):
            val = data[r][c]
