                    # Propagate Inequalities
                    for (r1, c1, r2, c2) in constraints:
                        if (r1, c1) == (r, c):
                            # val < board[r2][c2] => board[r2][c2] must be > val
                            to_remove = [x for x in domains[r2][c2] if x <= val]
                            for x in to_remove:
