            elif len(domains[r][c]) == 1:
                assignment[r][c] = list(domains[r][c])[0]

    def get_unassigned_variable(domains, assignment):
        # MRV Heuristic: Choose variable with fewest legal values
        min_len = N + 1
        best_var = None
        for r in range(N):
            for c in range(N):
                if assignment[r][c] is None:
                    length = len(domains[r][c])
                    if length < min_len:
                        min_len = length
                        best_var = (r, c)
                    if length == 1: # Optimization: return immediately
                        return (r, c)
        return best_var

    def is_consistent(r, c, val, assignment):
        # Check row/col uniqueness against currently assigned values
        for i in range(N):
            if assignment[r][i] == val: return False
            if assignment[i][c] == val: return False

        # Check inequalities against assigned neighbors
        for (r1, c1, r2, c2) in constraints:
            if (r1, c1) == (r, c):
                v2 = assignment[r2][c2]
                if v2 is not None and not (val < v2):
                    return False
            elif (r2, c2) == (r, c):
                v1 = assignment[r1][c1]
                if v1 is not None and not (v1 < val):
                    return False
        return True

    def propagate(r, c, val, domains, assignment):
        # Returns list of changes to revert, or False if failure
        changes = []

        # 1. Row/Col Uniqueness
        for j in range(N):
            if j != c and assignment[r][j] is None:
                if val in domains[r][j]:
                    domains[r][j].remove(val)
                    changes.append(('dom', r, j, val))
                    if len(domains[r][j]) == 0: return False
        for i in range(N):
            if i != r and assignment[i][c] is None:
                if val in domains[i][c]:
                    domains[i][c].remove(val)
                    changes.append(('dom', i, c, val))
                    if len(domains[i][c]) == 0: return False

        # 2. Inequalities
        for (r1, c1, r2, c2) in constraints:
            if (r1, c1) == (r, c):
                # val < board[r2][c2]
                if assignment[r2][c2] is None:
                    to_remove = [x for x in domains[r2][c2] if x <= val]
                    for x in to_remove:
                        domains[r2][c2].remove(x)
                        changes.append(('dom', r2, c2, x))
                        if len(domains[r2][c2]) == 0: return False
            elif (r2, c2) == (r, c):
                # board[r1][c1] < val
                if assignment[r1][c1] is None:
                    to_remove = [x for x in domains[r1][c1] if x >= val]
                    for x in to_remove:
                        domains[r1][c1].remove(x)
                        changes.append(('dom', r1, c1, x))
                        if len(domains[r1][c1]) == 0: return False
        return changes

    def backtrack(assignment, domains):
        unassigned = get_unassigned_variable(domains, assignment)
        if unassigned is None:
            return True # Solved

        r, c = unassigned
        # Try values in domain (sorted for determinism)
        possible_values = sorted(list(domains[r][c]))

        for val in possible_values:
            if is_consistent(r, c, val, assignment):
                # Assign
                assignment[r][c] = val
                old_domain = domains[r][c]
                domains[r][c] = {val} # Lock domain

                # Propagate
                changes = propagate(r, c, val, domains, assignment)

                if changes is not False:
                    if backtrack(assignment, domains):
                        return True

                # Backtrack (Undo)
                assignment[r][c] = None
                domains[r][c] = old_domain
                for change in changes:
                    if change[0] == 'dom':
                        _, rr, cc, vv = change
                        domains[rr][cc].add(vv)

        return False

    if backtrack(assignment, domains):
        return assignment
    else:
        return "No Solution"

