OBSERVATION = {'data': [[None, None, None, 9, None, None, None], [None, 5, None, None, None, None, 8], [None, None, None, 8, None, None, 10], [None, None, None, 9, None, None, None], [7, None, None, 9, None, None, None], [3, None, None, None, None, 3, None], [None, None, None, 4, None, None, None]]}

import sys
import copy

sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    clues = {}
    grid = [[0] * N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                clues[(r, c)] = val
                grid[r][c] = 1

    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def in_bounds(r, c):
        return 0 <= r < N and 0 <= c < N

    def propagate(g):
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if g[r][c] == 2:
                        for dr, dc in DIRS:
                            nr, nc = r + dr, c + dc
                            if in_bounds(nr, nc):
                                if g[nr][nc] == 0:
                                    g[nr][nc] = 1
                                    changed = True
                                elif g[nr][nc] == 2:
                                    return False

            for (r, c), val in clues.items():
                min_vis = 1
                max_vis = 1

                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    ray_min = 0
                    curr_r, curr_c = nr, nc
                    while in_bounds(curr_r, curr_c):
                        if g[curr_r][curr_c] == 1:
                            ray_min += 1
                        else:
                            break
                        curr_r += dr
                        curr_c += dc

                    ray_max = 0
                    curr_r, curr_c = nr, nc
                    while in_bounds(curr_r, curr_c):
                        if g[curr_r][curr_c] != 2:
                            ray_max += 1
                        else:
                            break
                        curr_r += dr
                        curr_c += dc

                    min_vis += ray_min
                    max_vis += ray_max

                if min_vis > val or max_vis < val:
                    return False

                if min_vis == val or max_vis == val:
                    for dr, dc in DIRS:
                        nr, nc = r + dr, c + dc
                        while in_bounds(nr, nc):
                            if g[nr][nc] == 2:
                                break
                            if g[nr][nc] == 0:
                                if max_vis == val:
                                    g[nr][nc] = 1
                                    changed = True
                                if min_vis == val:
                                    g[nr][nc] = 2
                                    changed = True
                            nr += dr
                            nc += dc
        return True

    def get_next_unknown(g):
        for r in range(N):
            for c in range(N):
                if g[r][c] == 0:
                    return r, c
        return None

    def is_connected(g):
        start = None
        count = 0
        for r in range(N):
            for c in range(N):
                if g[r][c] == 1:
                    if start is None: start = (r, c)
                    count += 1
        if count == 0: return True

        q = [start]
        vis = {start}
        while q:
            r, c = q.pop(0)
            for dr, dc in DIRS:
                nr, nc = r+dr, c+dc
                if in_bounds(nr, nc) and g[nr][nc] == 1 and (nr, nc) not in vis:
                    vis.add((nr, nc))
                    q.append((nr, nc))
        return len(vis) == count

    def backtrack(g):
        if not propagate(g):
            return None
        nxt = get_next_unknown(g)
        if nxt is None:
            if is_connected(g):
                return g
            return None

        r, c = nxt
        g1 = copy.deepcopy(g)
        g1[r][c] = 1
        res = backtrack(g1)
        if res: return res

        g2 = copy.deepcopy(g)
        g2[r][c] = 2
        res = backtrack(g2)
        if res: return res

        return None

    final_grid = backtrack(grid)
    if final_grid is None:
        return "No Solution"

    out = []
    for r in range(N):
        row = []
        for c in range(N):
            if final_grid[r][c] == 2:
                row.append('B')
            elif (r, c) in clues:
                row.append(clues[(r, c)])
            else:
                row.append(None)
        out.append(row)
    return out

