import sys
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    H_plus_1 = len(data)
    W_plus_1 = len(data[0])
    H = H_plus_1 - 1
    W = W_plus_1 - 1

    cell_grid = [[-1] * W for _ in range(H)]

    dot_target = [[None] * W_plus_1 for _ in range(H_plus_1)]
    for r in range(H_plus_1):
        for c in range(W_plus_1):
            dot_target[r][c] = data[r][c]

    dot_current = [[0] * W_plus_1 for _ in range(H_plus_1)]
    dot_available = [[0] * W_plus_1 for _ in range(H_plus_1)]

    incident_cells = {}
    for r in range(H_plus_1):
        for c in range(W_plus_1):
            incidents = []
            if r < H and c < W: incidents.append((r, c, 1))
            if r < H and c > 0: incidents.append((r, c-1, 0))
            if r > 0 and c < W: incidents.append((r-1, c, 0))
            if r > 0 and c > 0: incidents.append((r-1, c-1, 1))
            incident_cells[(r, c)] = incidents
            dot_available[r][c] = len(incidents)

    parent = list(range(H_plus_1 * W_plus_1))
    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path: parent[node] = i
        return i

    def dot_index(r, c): return r * W_plus_1 + c

    def get_unassigned_incidents(r, c):
        res = []
        for cr, cc, t in incident_cells[(r, c)]:
            if cell_grid[cr][cc] == -1:
                res.append((cr, cc, t))
        return res

    def apply_forced_moves(queue, changes):
        while queue:
            cr, cc, val = queue.pop(0)
            if cell_grid[cr][cc] != -1:
                if cell_grid[cr][cc] != val: return False
                continue

            cell_grid[cr][cc] = val
            changes.append(('cell', cr, cc))

            if val == 0:
                connected = [(cr+1, cc), (cr, cc+1)]
                non_connected = [(cr, cc), (cr+1, cc+1)]
            else:
                connected = [(cr, cc), (cr+1, cc+1)]
                non_connected = [(cr+1, cc), (cr, cc+1)]

            for dr, dc in connected:
                if dot_target[dr][dc] is not None:
                    dot_current[dr][dc] += 1
                    changes.append(('dot_curr', dr, dc))
                    if dot_current[dr][dc] > dot_target[dr][dc]: return False

            for dr, dc in non_connected:
                dot_available[dr][dc] -= 1
                changes.append(('dot_avail', dr, dc))
                if dot_target[dr][dc] is not None:
                    needed = dot_target[dr][dc] - dot_current[dr][dc]
                    if dot_available[dr][dc] < needed: return False

            d1, d2 = connected
            u, v = dot_index(d1[0], d1[1]), dot_index(d2[0], d2[1])
            root_u, root_v = find(u), find(v)
            if root_u == root_v: return False
            parent[root_u] = root_v
            changes.append(('dsu', root_u, root_v))

            dots_to_check = set()
            for dr, dc in connected: dots_to_check.add((dr, dc))
            for dr, dc in non_connected: dots_to_check.add((dr, dc))

            for dr, dc in dots_to_check:
                if dot_target[dr][dc] is None: continue
                target = dot_target[dr][dc]
                current = dot_current[dr][dc]
                available = dot_available[dr][dc]

                if current == target:
                    for icr, icc, itype in get_unassigned_incidents(dr, dc):
                        queue.append((icr, icc, 1 - itype))
                elif current + available == target:
                    for icr, icc, itype in get_unassigned_incidents(dr, dc):
                        queue.append((icr, icc, itype))
        return True

    def undo_changes(changes):
        for change in reversed(changes):
            ctype = change[0]
            if ctype == 'cell':
                cell_grid[change[1]][change[2]] = -1
            elif ctype == 'dot_curr':
                dot_current[change[1]][change[2]] -= 1
            elif ctype == 'dot_avail':
                dot_available[change[1]][change[2]] += 1
            elif ctype == 'dsu':
                parent[change[1]] = change[1]

    def backtrack():
        r_next, c_next = -1, -1
        for r in range(H):
            for c in range(W):
                if cell_grid[r][c] == -1:
                    r_next, c_next = r, c
                    break
            if r_next != -1: break

        if r_next == -1: return True

        for val in [0, 1]:
            changes = []
            queue = [(r_next, c_next, val)]
            if apply_forced_moves(queue, changes):
                if backtrack(): return True
            undo_changes(changes)
        return False

    if backtrack():
        res = []
        for r in range(H):
            row_strs = []
            for c in range(W):
                row_strs.append('/' if cell_grid[r][c] == 0 else '\\')
            res.append(row_strs)
        return res
    return "No Solution"

