def solve(observation):
    data = observation['data']
    H = len(data) - 1
    W = len(data[0]) - 1

    # Clues grid
    clues = data

    # Board: 0=empty, 1='/', 2='\'
    board = [[0] * W for _ in range(H)]

    # Pre-processing: Propagate constraints from 0 clues and max-degree clues
    # This mimics human deduction: "If a dot has 0, no lines connect to it."
