                if clue is None:
                    continue

                # Identify neighbors: (cell_r, cell_c, connects_if_type)
                # connects_if_type: 1 for '/', 2 for '\'
                neighbors = []
                # TL Cell (r-1, c-1): Dot is BR. Connects if '\' (2)
                if r > 0 and c > 0:
                    neighbors.append((r-1, c-1, 2))
                # TR Cell (r-1, c): Dot is BL. Connects if '/' (1)
                if r > 0 and c < W:
                    neighbors.append((r-1, c, 1))
                # BL Cell (r, c-1): Dot is TR. Connects if '/' (1)
                if r < H and c > 0:
                    neighbors.append((r, c-1, 1))
                # BR Cell (r, c): Dot is TL. Connects if '\' (2)
