                    val = board[cr][cc]
                    if val == req_type:
                        current_conn += 1
                    elif val == 0:
                        empty_neighbors.append((cr, cc, req_type))
                    # If val is the other type, it doesn't connect, which is fine.

                # Logic 1: Clue is 0 -> all empty neighbors must NOT connect
                if clue == 0:
                    for cr, cc, req_type in empty_neighbors:
                        opp_type = 1 if req_type == 2 else 2
                        if board[cr][cc] == 0:
                            board[cr][cc] = opp_type
                            changed = True
                        elif board[cr][cc] == req_type:
                            # Contradiction
                            return "No Solution"

                # Logic 2: Clue == current_conn + len(empty_neighbors) -> all must connect
                elif clue == current_conn + len(empty_neighbors):
                    for cr, cc, req_type in empty_neighbors:
                        if board[cr][cc] == 0:
                            board[cr][cc] = req_type
                            changed = True
                        elif board[cr][cc] != req_type:
                            # Contradiction
                            return "No Solution"

    # Initialize DSU and dot_degrees based on pre-processed board
    parent = list(range((H + 1) * (W + 1)))
    dot_degrees = [[0] * (W + 1) for _ in range(H + 1)]

    def get_dot_idx(r, c):
        return r * (W + 1) + c

    def find(i, p):
        path = []
        while p[i] != i:
            path.append(i)
            i = p[i]
        for node in path:
            p[node] = i
        return i

    def union(i, j, p):
        root_i = find(i, p)
        root_j = find(j, p)
        if root_i != root_j:
            p[root_i] = root_j
            return True
        return False

    # Apply pre-filled cells to DSU and degrees
    for r in range(H):
        for c in range(W):
            val = board[r][c]
            if val == 1: # '/' connects (r+1, c) and (r, c+1)
                dot_degrees[r+1][c] += 1
                dot_degrees[r][c+1] += 1
                union(get_dot_idx(r+1, c), get_dot_idx(r, c+1), parent)
            elif val == 2: # '\' connects (r, c) and (r+1, c+1)
                dot_degrees[r][c] += 1
                dot_degrees[r+1][c+1] += 1
                union(get_dot_idx(r, c), get_dot_idx(r+1, c+1), parent)

    # Check for initial contradictions in degrees
    for r in range(H + 1):
        for c in range(W + 1):
            clue = clues[r][c]
            if clue is not None:
                if dot_degrees[r][c] > clue:
                    return "No Solution"

    # Prepare for backtracking
    empty_cells = []
    for r in range(H):
        for c in range(W):
            if board[r][c] == 0:
                empty_cells.append((r, c))

    # Solver Class to encapsulate state
    class Solver:
        def __init__(self, H, W, clues, board, dot_degrees, parent, empty_cells):
            self.H = H
            self.W = W
            self.clues = clues
            self.board = board # Reference to list of lists
            self.dot_degrees = dot_degrees
            self.parent = parent
            self.empty_cells = empty_cells

        def get_dot_idx(self, r, c):
            return r * (self.W + 1) + c

        def find(self, i, p):
            path = []
            while p[i] != i:
                path.append(i)
                i = p[i]
            for node in path:
                p[node] = i
            return i

        def is_valid_move(self, r, c, diag_type, current_degrees, current_parent):
            # diag_type: 1 for '/', 2 for '\'

            if diag_type == 1: # '/' connects BL(r+1, c) and TR(r, c+1)
                dot1_r, dot1_c = r + 1, c
                dot2_r, dot2_c = r, c + 1
            else: # '\' connects TL(r, c) and BR(r+1, c+1)
                dot1_r, dot1_c = r, c
                dot2_r, dot2_c = r + 1, c + 1

            # 1. Check Loop
            idx1 = self.get_dot_idx(dot1_r, dot1_c)
            idx2 = self.get_dot_idx(dot2_r, dot2_c)
            if self.find(idx1, current_parent) == self.find(idx2, current_parent):
                return False

            # 2. Check Degrees
            clue1 = self.clues[dot1_r][dot1_c]
            if clue1 is not None and current_degrees[dot1_r][dot1_c] >= clue1:
                return False

            clue2 = self.clues[dot2_r][dot2_c]
            if clue2 is not None and current_degrees[dot2_r][dot2_c] >= clue2:
                return False

            return True

        def solve_recursive(self, cell_idx):
            if cell_idx == len(self.empty_cells):
                return True

            r, c = self.empty_cells[cell_idx]

            # Try '/' (1)
            if self.is_valid_move(r, c, 1, self.dot_degrees, self.parent):
                # Save state (deep copy degrees and parent)
                old_degrees = [row[:] for row in self.dot_degrees]
                old_parent = self.parent[:]

                # Apply
                self.board[r][c] = 1
                self.dot_degrees[r+1][c] += 1
                self.dot_degrees[r][c+1] += 1
                self.union(self.get_dot_idx(r+1, c), self.get_dot_idx(r, c+1), self.parent)

                # Lookahead
                if self.check_future_consistency():
                    if self.solve_recursive(cell_idx + 1):
                        return True

                # Backtrack
                self.dot_degrees = old_degrees
                self.parent = old_parent
                self.board[r][c] = 0

            # Try '\' (2)
            if self.is_valid_move(r, c, 2, self.dot_degrees, self.parent):
                old_degrees = [row[:] for row in self.dot_degrees]
                old_parent = self.parent[:]

                self.board[r][c] = 2
                self.dot_degrees[r][c] += 1
                self.dot_degrees[r+1][c+1] += 1
                self.union(self.get_dot_idx(r, c), self.get_dot_idx(r+1, c+1), self.parent)

                if self.check_future_consistency():
                    if self.solve_recursive(cell_idx + 1):
                        return True

                self.dot_degrees = old_degrees
                self.parent = old_parent
                self.board[r][c] = 0

            return False

        def union(self, i, j, p):
            root_i = self.find(i, p)
            root_j = self.find(j, p)
            if root_i != root_j:
                p[root_i] = root_j

        def check_future_consistency(self):
            # Check if any dot is over-satisfied or cannot be satisfied
            for r in range(self.H + 1):
                for c in range(self.W + 1):
                    clue = self.clues[r][c]
                    if clue is None:
                        continue

                    current = self.dot_degrees[r][c]
                    if current > clue:
                        return False

                    # Count remaining possible connections (upper bound)
                    remaining = 0
                    # TL
                    if r > 0 and c > 0:
                        if self.board[r-1][c-1] == 0: remaining += 1
                    # TR
                    if r > 0 and c < self.W:
                        if self.board[r-1][c] == 0: remaining += 1
                    # BL
                    if r < self.H and c > 0:
                        if self.board[r][c-1] == 0: remaining += 1
                    # BR
                    if r < self.H and c < self.W:
                        if self.board[r][c] == 0: remaining += 1

                    if current + remaining < clue:
                        return False
            return True

    solver = Solver(H, W, clues, board, dot_degrees, parent, empty_cells)
    if solver.solve_recursive(0):
        res = []
        for r in range(H):
            row_res = []
            for c in range(W):
                if solver.board[r][c] == 1:
                    row_res.append('/')
                else:
                    row_res.append('\\')
            res.append(row_res)
        return res
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
