import sys

# Increase recursion depth to be safe
sys.setrecursionlimit(2000)

def solve(observation):
    data = observation['data']
    H = len(data) - 1
    W = len(data[0]) - 1

    # Grid: 0=Unknown, 1='/', 2='\'
    grid = [[0] * W for _ in range(H)]

    # DSU for loop detection
    # Nodes are dots (r, c) -> index r*(W+1) + c
    parent = list(range((H + 1) * (W + 1)))

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    def get_dot_idx(r, c):
        return r * (W + 1) + c

    # Precompute dot neighbors
    # dot_cells[r][c] = list of (cell_r, cell_c, connects_if_val)
    # connects_if_val: 1 for '/', 2 for '\'
    dot_cells = [[[] for _ in range(W + 1)] for _ in range(H + 1)]
    for r in range(H + 1):
        for c in range(W + 1):
            # TL neighbor: cell (r-1, c-1), connects if '\' (2)
            if r > 0 and c > 0:
                dot_cells[r][c].append((r - 1, c - 1, 2))
            # TR neighbor: cell (r-1, c), connects if '/' (1)
            if r > 0 and c < W:
                dot_cells[r][c].append((r - 1, c, 1))
            # BL neighbor: cell (r, c-1), connects if '/' (1)
            if r < H and c > 0:
                dot_cells[r][c].append((r, c - 1, 1))
            # BR neighbor: cell (r, c), connects if '\' (2)
            if r < H and c < W:
                dot_cells[r][c].append((r, c, 2))

    # State tracking
    current_degree = [[0] * (W + 1) for _ in range(H + 1)]
    unknown_count = [[0] * (W + 1) for _ in range(H + 1)]
    for r in range(H + 1):
        for c in range(W + 1):
            unknown_count[r][c] = len(dot_cells[r][c])

    def apply_move(r, c, val):
        # val: 1 ('/'), 2 ('\')
        # Check loop constraint
        if val == 1:
            d1, d2 = get_dot_idx(r + 1, c), get_dot_idx(r, c + 1)
        else:
            d1, d2 = get_dot_idx(r, c), get_dot_idx(r + 1, c + 1)

        if find(d1) == find(d2):
            return False

        # Apply move
        grid[r][c] = val
        union(d1, d2)

        # Update degrees for surrounding dots
        # Dots: TL(r,c), TR(r,c+1), BL(r+1,c), BR(r+1,c+1)
        # TL connects if val==2
        # TR connects if val==1
        # BL connects if val==1
        # BR connects if val==2
        neighbors = [
            (r, c, 2), (r, c + 1, 1), (r + 1, c, 1), (r + 1, c + 1, 2)
        ]
        for dr, dc, conn_val in neighbors:
            if 0 <= dr <= H and 0 <= dc <= W:
                unknown_count[dr][dc] -= 1
                if val == conn_val:
                    current_degree[dr][dc] += 1
        return True

    def get_state():
        return {
            'grid': [row[:] for row in grid],
            'deg': [row[:] for row in current_degree],
            'unk': [row[:] for row in unknown_count],
            'parent': parent[:]
        }

    def set_state(state):
        for r in range(H):
            grid[r] = state['grid'][r][:]
        for r in range(H + 1):
            current_degree[r] = state['deg'][r][:]
            unknown_count[r] = state['unk'][r][:]
            for c in range(W + 1):
                parent[r * (W + 1) + c] = state['parent'][r * (W + 1) + c]

    def run_propagation():
        while True:
            changed = False
            move_found = None

            # 1. Check Clues (Degree Constraints)
            for r in range(H + 1):
                for c in range(W + 1):
                    clue = data[r][c]
                    if clue is None: continue
                    deg = current_degree[r][c]
                    unk = unknown_count[r][c]

                    # Contradiction check
                    if deg > clue or deg + unk < clue:
                        return False

                    # Rule: Satisfied (deg == clue) -> All unknowns must NOT connect
                    if deg == clue:
                        for cell_r, cell_c, conn_val in dot_cells[r][c]:
                            if grid[cell_r][cell_c] == 0:
                                # Must be the other value
                                move_found = (cell_r, cell_c, 1 if conn_val == 2 else 2)
                                break
                    # Rule: Desperate (deg + unk == clue) -> All unknowns MUST connect
                    elif deg + unk == clue:
                        for cell_r, cell_c, conn_val in dot_cells[r][c]:
                            if grid[cell_r][cell_c] == 0:
                                move_found = (cell_r, cell_c, conn_val)
                                break
                    if move_found: break
                if move_found: break

            # 2. Check Loops (Constraint Propagation)
            # If one option creates a loop, the other is forced
            if not move_found:
                for r in range(H):
                    for c in range(W):
                        if grid[r][c] == 0:
                            # Check '/' (1)
                            d1, d2 = get_dot_idx(r + 1, c), get_dot_idx(r, c + 1)
                            loop1 = (find(d1) == find(d2))
                            # Check '\' (2)
                            d3, d4 = get_dot_idx(r, c), get_dot_idx(r + 1, c + 1)
                            loop2 = (find(d3) == find(d4))

                            if loop1 and not loop2:
                                move_found = (r, c, 2)
                            elif loop2 and not loop1:
                                move_found = (r, c, 1)
                            elif loop1 and loop2:
                                return False # Both create loops -> Contradiction
                            if move_found: break
                    if move_found: break

            if move_found:
                mr, mc, mv = move_found
                if not apply_move(mr, mc, mv):
                    return False
                changed = True
            else:
                break # No more forced moves

        return True

    def backtrack():
        # Find first empty cell
        r_empty, c_empty = -1, -1
        for r in range(H):
            for c in range(W):
                if grid[r][c] == 0:
                    r_empty, c_empty = r, c
                    break
            if r_empty != -1: break

        if r_empty == -1:
            return True # Solved

        # Try values
        for val in [1, 2]:
            state = get_state()
            if apply_move(r_empty, c_empty, val):
                if run_propagation():
                    if backtrack():
                        return True
            set_state(state)

        return False

    # Initial Propagation
    if run_propagation():
        if backtrack():
            res = []
            for r in range(H):
                row_res = []
                for c in range(W):
                    row_res.append('/' if grid[r][c] == 1 else '\\')
                res.append(row_res)
            return res
    return "No Solution"

