import sys
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data)

    # State: 0=Unknown, 1=White, 2=Black
    state = [[0] * N for _ in range(N)]

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def propagate(current_state):
        changed = True
        while changed:
            changed = False

            # Pass 1: Black -> Neighbors White
            # If a cell is Black, all orthogonal neighbors must be White.
            # If a neighbor is already Black, conflict.
            for r in range(N):
                for c in range(N):
                    if current_state[r][c] == 2:
                        for nr, nc in get_neighbors(r, c):
                            if current_state[nr][nc] == 0:
                                current_state[nr][nc] = 1
                                changed = True
                            elif current_state[nr][nc] == 2:
                                return False # Adjacent Blacks

            # Pass 2: White -> Uniqueness (Same Value -> Black)
            # If a cell is White, any other cell in the same row/col with the same value must be Black.
            for r in range(N):
                for c in range(N):
                    if current_state[r][c] == 1:
                        val = data[r][c]
                        # Check Row
                        for cc in range(N):
                            if cc == c: continue
                            if data[r][cc] == val:
                                if current_state[r][cc] == 0:
                                    current_state[r][cc] = 2
                                    changed = True
                                elif current_state[r][cc] == 1:
                                    return False # Duplicate White in Row
                        # Check Col
                        for rr in range(N):
                            if rr == r: continue
                            if data[rr][c] == val:
                                if current_state[rr][c] == 0:
                                    current_state[rr][c] = 2
                                    changed = True
                                elif current_state[rr][c] == 1:
                                    return False # Duplicate White in Col

            # Pass 3: Connectivity Pruning (Isolated White Cells)
            # If a White cell has all neighbors Black (and no Unknowns), it is isolated.
            # If there are other White cells, this implies disconnection.
            white_count = 0
            isolated_count = 0
            for r in range(N):
                for c in range(N):
                    if current_state[r][c] == 1:
                        white_count += 1
                        is_isolated = True
                        has_unknown_neighbor = False
                        for nr, nc in get_neighbors(r, c):
                            if current_state[nr][nc] == 1:
                                is_isolated = False
                                break
                            if current_state[nr][nc] == 0:
                                has_unknown_neighbor = True
                        # If all neighbors are Black (state 2), it's isolated.
                        if is_isolated and not has_unknown_neighbor:
                            isolated_count += 1

            # If we have isolated white cells and more than 1 white cell total, it's disconnected.
            if white_count > 1 and isolated_count > 0:
                return False

        return True

    def check_connectivity(current_state):
        start = None
        white_count = 0
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == 1:
                    white_count += 1
                    if start is None:
                        start = (r, c)

        if white_count == 0:
            return False # Must have white cells

        visited = set()
        queue = [start]
        visited.add(start)

        while queue:
            r, c = queue.pop(0)
            for nr, nc in get_neighbors(r, c):
                if current_state[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == white_count

    def search(current_state):
        if not propagate(current_state):
            return None

        unknowns = []
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == 0:
                    unknowns.append((r, c))

        if not unknowns:
            if check_connectivity(current_state):
                return current_state
            else:
                return None

        # Heuristic: Pick cell with most constraints (duplicates in row/col)
        best_cell = None
        best_score = -1

        for r, c in unknowns:
            val = data[r][c]
            score = 0
            for cc in range(N):
                if cc != c and data[r][cc] == val:
                    score += 1
            for rr in range(N):
                if rr != r and data[rr][c] == val:
                    score += 1
            if score > best_score:
                best_score = score
                best_cell = (r, c)

        if best_cell is None:
            best_cell = unknowns[0]

        r, c = best_cell

        # Try Black
        s1 = [row[:] for row in current_state]
        s1[r][c] = 2
        res1 = search(s1)
        if res1:
            return res1

        # Try White
        s2 = [row[:] for row in current_state]
        s2[r][c] = 1
        res2 = search(s2)
        if res2:
            return res2

        return None

    final_state = search(state)

    if final_state is None:
        return "No Solution"

    result = []
    for r in range(N):
        row_res = []
        for c in range(N):
            if final_state[r][c] == 2:
                row_res.append('B')
            else:
                row_res.append(None)
        result.append(row_res)

    return result

