def solve(observation):
    import itertools

    region_grid = observation['region']
    data_grid = observation['data']
    N = len(region_grid)

    # Identify regions and their properties
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = {'cells': [], 'clue': None}
            regions[rid]['cells'].append((r, c))
            if data_grid[r][c] is not None:
                regions[rid]['clue'] = data_grid[r][c]

    # Determine fixed white cells and variable regions
    # Rule: Unnumbered regions have 0 black cells (implied by "A numbered region contains exactly that many...")
    # and standard puzzle logic where unnumbered areas are stream (white).
    fixed_white = set()
    variable_regions = []

    for rid, info in regions.items():
        if info['clue'] is None:
            # Unnumbered region -> 0 black cells -> All white
            for cell in info['cells']:
                fixed_white.add(cell)
        else:
            variable_regions.append(rid)

    # Also, numbered regions with clue 0 are all white
    for rid in variable_regions[:]:
        if regions[rid]['clue'] == 0:
            for cell in regions[rid]['cells']:
                fixed_white.add(cell)
            variable_regions.remove(rid)

    # Prepare combinations for each variable region
    # We need to choose exactly 'clue' black cells for each region
    region_combinations = {}
    for rid in variable_regions:
        cells = regions[rid]['cells']
        k = regions[rid]['clue']
        # Generate all combinations of k black cells from the region's cells
        combos = list(itertools.combinations(cells, k))
        region_combinations[rid] = combos

    # Order regions for DFS (smallest number of combinations first for pruning)
    variable_regions.sort(key=lambda rid: len(region_combinations[rid]))

    final_solution = None

    def is_valid_partial(black_cells):
        # Check orthogonal adjacency of black cells
        black_set = set(black_cells)
        for r, c in black_set:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in black_set:
                    return False
        return True

    def check_white_segment_rule(grid_state):
        # grid_state: dict (r,c) -> 'B' or 'W'
        # Rule: Any uninterrupted straight white segment (row/column) cannot pass through more than 2 regions.

        # Check rows
        for r in range(N):
            c = 0
            while c < N:
                if grid_state.get((r,c)) == 'B':
                    c += 1
                    continue
                # Start of white segment
