                        cc += 1

                    all_adj_regions = left_regions | right_regions | {region_map[r][c]}
                    if len(all_adj_regions) > 2:
                        # If setting this to White creates > 2 regions in the segment
                        # But only if the left/right parts are fully known whites?
                        # Yes, because if there was a black or unknown in between, the segment would be broken or uncertain.
                        # Wait, if left has unknown, we don't know if it's white.
                        # But here we scanned only '0's. So left_regions are definitely white.
                        # So if we set current to White, it connects to left whites and right whites.
                        # The segment becomes Left_Whites + Current + Right_Whites.
                        # If total regions > 2, then Current cannot be White.
                        grid[r][c] = 1
