                unknowns = [(r, c) for r, c in cells if grid[r][c] == -1]

                if current_blacks > clue: return False
                if current_blacks == clue:
                    for r, c in unknowns:
                        if grid[r][c] == -1:
                            grid[r][c] = 0
                            changed = True
                elif current_blacks + len(unknowns) == clue:
                    for r, c in unknowns:
                        if grid[r][c] == -1:
                            grid[r][c] = 1
                            changed = True

