        return True

    def search():
        # Find first unknown
        r, c = -1, -1
        for i in range(N):
            for j in range(N):
                if grid[i][j] == -1:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1:
            # All filled
            if check_connectivity():
                return True
            return False

        # Heuristic: Try Black first? Or White?
        # Usually Black is more constrained.
        # But let's try both.

        # Save state
        saved_grid = [row[:] for row in grid]

        # Try Black
        grid[r][c] = 1
        if propagate():
            if search():
                return True

        # Restore
        for i in range(N):
            grid[i] = saved_grid[i][:]

        # Try White
        grid[r][c] = 0
        if propagate():
            if search():
                return True

        return False

    if not propagate():
        return "No Solution"

    if search():
        # Format output
        res = []
        for r in range(N):
            row_res = []
            for c in range(N):
                if grid[r][c] == 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            res.append(row_res)
        return res
    else:
        return "No Solution"

