            # If a value can only go in one cell in a row/col, place it
            for r in range(N):
                for val in range(1, N + 1):
                    candidates = [c for c in range(N) if val in domains[r][c]]
                    if len(candidates) == 1:
                        c = candidates[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True
            for c in range(N):
                for val in range(1, N + 1):
                    candidates = [r for r in range(N) if val in domains[r][c]]
                    if len(candidates) == 1:
                        r = candidates[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

        return domains

    def is_valid(domains):
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) == 0:
                    return False
        return True

    def backtrack(domains):
        # Check if solved
        solved = True
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    solved = False
                    break
            if not solved: break

        if solved:
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        # MRV Heuristic: Pick cell with smallest domain > 1 to minimize branching
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                size = len(domains[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best_cell = (r, c)

        if best_cell is None:
            return None

        r, c = best_cell
        # Try values in sorted order (deterministic)
        for val in sorted(list(domains[r][c])):
            new_domains = copy.deepcopy(domains)
            new_domains[r][c] = {val}

            # Aggressive propagation after assignment
            propagated_domains = propagate(new_domains)

            if is_valid(propagated_domains):
                result = backtrack(propagated_domains)
                if result:
                    return result

        return None

    # Initial Propagation to reduce search space before backtracking
    domains = propagate(domains)

    if not is_valid(domains):
        return "No Solution"

    solution = backtrack(domains)
    return solution

if __name__ == "__main__":
    print(solve(OBSERVATION))
