def solve(observation):
    import sys
    sys.setrecursionlimit(20000)

    data = observation['data']
    region_map = observation['region']
    N = len(data)

    # Precompute peers for each cell (row, col)
    # Peers are cells in the same row, col, or region
    peers = {}
    regions = {} # region_id -> list of cells

    for r in range(N):
        for c in range(N):
            peers[(r, c)] = set()
            rid = region_map[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

