        for c in range(N):
            # Same row
            for cc in range(N):
                if cc != c:
                    peers[(r, c)].add((r, cc))
            # Same col
            for rr in range(N):
                if rr != r:
                    peers[(r, c)].add((rr, c))
            # Same region
            rid = region_map[r][c]
            for (rr, cc) in regions[rid]:
                if (rr, cc) != (r, c):
                    peers[(r, c)].add((rr, cc))

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    def propagate(domains):
        # AC-3 algorithm
        queue = list(domains.keys())
        while queue:
            cell = queue.pop(0)
            if len(domains[cell]) == 1:
                val = next(iter(domains[cell]))
                for peer in peers[cell]:
                    if val in domains[peer]:
                        domains[peer].remove(val)
                        if len(domains[peer]) == 0:
                            return None
                        if len(domains[peer]) == 1:
                            queue.append(peer)
        return domains

    def solve_backtrack(domains):
        # Check if solved
        if all(len(d) == 1 for d in domains.values()):
            return domains

        # MRV Heuristic: Choose cell with minimum remaining values
        unassigned = [(r, c) for r in range(N) for c in range(N) if len(domains[(r, c)]) > 1]
        if not unassigned:
            return domains

        cell = min(unassigned, key=lambda c: len(domains[c]))

        for val in list(domains[cell]):
            new_domains = {k: v.copy() for k, v in domains.items()}
            new_domains[cell] = {val}

            # Propagate
            # Remove val from peers
            consistent = True
            for peer in peers[cell]:
                if val in new_domains[peer]:
                    new_domains[peer].remove(val)
                    if len(new_domains[peer]) == 0:
                        consistent = False
                        break

            if consistent:
                # Further propagation (AC-3 light)
                # We can just recurse, but simple propagation helps
                res = solve_backtrack(new_domains)
                if res is not None:
                    return res
        return None

    # Initial propagation
    domains = propagate(domains)
    if domains is None:
        return "No Solution"

    final_domains = solve_backtrack(domains)

    if final_domains is None:
        return "No Solution"

    # Construct result grid
    result = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            result[r][c] = next(iter(final_domains[(r, c)]))

    return result

