                # Including current cell
                if current_black > region_clues[rid]:
                    return False
        else: # White
            pass # White constraints are more global (connectivity, segments)

        return True

    # Check white segment constraint
    # "Any uninterrupted straight white segment (row/column) cannot pass through more than 2 regions."
    def check_white_segments():
        # Check rows
        for r in range(N):
            c = 0
            while c < N:
