                        new_d2.add(v2)

                if new_d2 != d2:
                    domains[r2][c2] = new_d2
                    changed = True
                    if not new_d2: return False

            # 2. Propagate Latin Square (All-different)
            # Rows
            for r in range(N):
                # If a cell is singleton, remove from peers
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = list(domains[r][c])[0]
                        for other_c in range(N):
                            if other_c != c:
                                if val in domains[r][other_c]:
                                    domains[r][other_c].remove(val)
                                    changed = True
                                    if not domains[r][other_c]: return False

                # Hidden Singles: if a value can only go in one cell in this row
                for val in range(1, N+1):
                    positions = []
                    for c in range(N):
                        if val in domains[r][c]:
                            positions.append(c)
                    if len(positions) == 1:
                        c = positions[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

            # Cols
            for c in range(N):
                for r in range(N):
                    if len(domains[r][c]) == 1:
                        val = list(domains[r][c])[0]
                        for other_r in range(N):
                            if other_r != r:
                                if val in domains[other_r][c]:
                                    domains[other_r][c].remove(val)
                                    changed = True
                                    if not domains[other_r][c]: return False

                for val in range(1, N+1):
                    positions = []
                    for r in range(N):
                        if val in domains[r][c]:
                            positions.append(r)
                    if len(positions) == 1:
                        r = positions[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

        return True

    def solve_recursive(domains):
        if not is_consistent(domains):
            return None

        # Check if solved
        is_solved = True
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    is_solved = False
                    break
            if not is_solved: break

        if is_solved:
            # Construct result grid
            res = [[0]*N for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    res[r][c] = list(domains[r][c])[0]
            return res

        # MRV Heuristic: Pick cell with smallest domain > 1
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                size = len(domains[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best_cell = (r, c)

        if best_cell is None:
            # Should have been caught by is_solved, but safety check
            return None

        r, c = best_cell
        possible_values = sorted(list(domains[r][c]))

        for val in possible_values:
            new_domains = copy.deepcopy(domains)
            new_domains[r][c] = {val}
            if propagate(new_domains):
                result = solve_recursive(new_domains)
                if result:
                    return result

        return None

    # Initial propagation
    if propagate(domains):
        return solve_recursive(domains)
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
