import sys
sys.setrecursionlimit(2000)

def solve(observation):
    region_grid = observation['region']
    data_grid = observation['data']
    N = len(region_grid)

    # Identify regions and their constraints
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = {'cells': [], 'clue': None}
            regions[rid]['cells'].append((r, c))
            if data_grid[r][c] is not None:
                regions[rid]['clue'] = data_grid[r][c]

    # Precompute neighbors
    neighbors = {}
    for r in range(N):
        for c in range(N):
            neighs = []
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighs.append((nr, nc))
            neighbors[(r,c)] = neighs

    # State: 0=Unknown, 1=White, 2=Black
    # We use a flat list for speed, mapping (r,c) to index r*N+c
    state = [0] * (N * N)

    # Helper to get/set state
    def get_state(r, c):
        return state[r * N + c]
    def set_state(r, c, val):
        state[r * N + c] = val

    # Check if a move is valid locally
    def is_valid_move(r, c, color):
        # color: 1=White, 2=Black

        # Rule 2: Black cells cannot touch orthogonally
        if color == 2:
            for nr, nc in neighbors[(r,c)]:
                if get_state(nr, nc) == 2:
                    return False

        # Rule 3: White segment <= 2 regions
        if color == 1:
            # Check horizontal segment
            # Find left end
            c_left = c
            while c_left > 0 and get_state(r, c_left - 1) == 1:
                c_left -= 1
            # Find right end
            c_right = c
            while c_right < N - 1 and get_state(r, c_right + 1) == 1:
                c_right += 1

            # Count regions in this segment
            seg_regions = set()
            for k in range(c_left, c_right + 1):
                seg_regions.add(region_grid[r][k])
            if len(seg_regions) > 2:
                return False

            # Check vertical segment
            r_top = r
            while r_top > 0 and get_state(r_top - 1, c) == 1:
                r_top -= 1
            r_bottom = r
            while r_bottom < N - 1 and get_state(r_bottom + 1, c) == 1:
                r_bottom += 1

            seg_regions = set()
            for k in range(r_top, r_bottom + 1):
                seg_regions.add(region_grid[k][c])
            if len(seg_regions) > 2:
                return False

        return True

    # Check global constraints (connectivity, region counts)
    def is_global_valid():
        # 1. Region counts
        for rid, info in regions.items():
            if info['clue'] is not None:
                count = 0
                for r, c in info['cells']:
                    if get_state(r, c) == 2:
                        count += 1
                    elif get_state(r, c) == 0:
                        # If unknown, we can't be sure yet, but if count > clue, invalid
                        pass
                if count > info['clue']:
                    return False
                # Optimization: if all cells in region are decided, check exact count
                all_decided = True
                for r, c in info['cells']:
                    if get_state(r, c) == 0:
                        all_decided = False
                        break
                if all_decided and count != info['clue']:
                    return False

        # 2. Connectivity of White cells
        # Find first white cell
        start = None
        white_count = 0
        for r in range(N):
            for c in range(N):
                if get_state(r, c) == 1:
                    if start is None:
                        start = (r, c)
                    white_count += 1

        if white_count == 0:
            return True # No white cells is technically connected? Usually puzzle requires some white.
                        # But rule 4 says "All white cells are orthogonally connected".
                        # If 0 white cells, vacuously true.

        if start is None:
            return True

        # BFS
        visited = set()
        queue = [start]
        visited.add(start)
        while queue:
            curr = queue.pop(0)
            for nr, nc in neighbors[curr]:
                if get_state(nr, nc) == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        if len(visited) != white_count:
            return False

        return True

    # Heuristic: Pick next cell
    def get_next_cell():
        # Pick unknown cell with most constraints (e.g., in a region with tight clue)
        best_cell = None
        best_score = -1

        for r in range(N):
            for c in range(N):
                if get_state(r, c) == 0:
                    rid = region_grid[r][c]
                    clue = regions[rid]['clue']
                    current_black = sum(1 for rr, cc in regions[rid]['cells'] if get_state(rr, cc) == 2)
                    unknown_in_region = sum(1 for rr, cc in regions[rid]['cells'] if get_state(rr, cc) == 0)

                    score = 1000
                    if clue is not None:
                        remaining = clue - current_black
                        if remaining == 0:
                            score += 10000 # Must be white
                        elif remaining == unknown_in_region:
                            score += 10000 # Must be black

                    # Check neighbors for black adjacency constraint
                    black_neighbors = sum(1 for nr, nc in neighbors[(r,c)] if get_state(nr, nc) == 2)
                    if black_neighbors > 0:
                        score += 5000 # Must be white

                    if score > best_score:
                        best_score = score
                        best_cell = (r, c)
        return best_cell

    def backtrack():
        # Check global validity periodically
        if not is_global_valid():
            return False

        # Check if solved
        if all(s != 0 for s in state):
            return True

        cell = get_next_cell()
        if cell is None:
            return True

        r, c = cell

        # Try Black (2) then White (1)
        # Heuristic: If region needs blacks, try Black first?
        # Or if neighbor is black, must be White.

        forced_white = False
        for nr, nc in neighbors[(r,c)]:
            if get_state(nr, nc) == 2:
                forced_white = True
                break

        # Also check region clue
        rid = region_grid[r][c]
        clue = regions[rid]['clue']
        if clue is not None:
            current_black = sum(1 for rr, cc in regions[rid]['cells'] if get_state(rr, cc) == 2)
            if current_black >= clue:
                forced_white = True

        if forced_white:
            if is_valid_move(r, c, 1):
                set_state(r, c, 1)
                if backtrack():
                    return True
                set_state(r, c, 0)
            return False
        else:
            # Try Black
            if is_valid_move(r, c, 2):
                set_state(r, c, 2)
                if backtrack():
                    return True
                set_state(r, c, 0)

            # Try White
            if is_valid_move(r, c, 1):
                set_state(r, c, 1)
                if backtrack():
                    return True
                set_state(r, c, 0)

        return False

    if backtrack():
        # Convert state to output format
        result = []
        for r in range(N):
            row = []
            for c in range(N):
                if get_state(r, c) == 2:
                    row.append('B')
                else:
                    row.append(None)
            result.append(row)
        return result
    else:
        return "No Solution"

