OBSERVATION = {'U': [0, 0, 0, 0], 'D': [0, 0, 0, 0], 'L': [0, 0, 2, 0], 'R': [0, 1, 0, 3]}

import sys
import copy

# Increase recursion depth to be safe
sys.setrecursionlimit(5000)

def solve(observation):
    # Parse observation
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    N = len(U)

    # Grid state: 0 means empty
    grid = [[0] * N for _ in range(N)]

    # Domains: set of possible values for each cell
    # Initialize with {1..N}
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Helper to check if a value is consistent with row/col uniqueness
    def is_unique_consistent(r, c, val):
        # Check row
        for j in range(N):
            if j != c and grid[r][j] == val:
                return False
        # Check col
        for i in range(N):
            if i != r and grid[i][c] == val:
                return False
        return True

    # Helper to count visible buildings in a full line
    def count_visible_full(line):
        count = 0
        max_h = 0
        for h in line:
            if h > max_h:
                max_h = h
                count += 1
        return count

    # Helper to check visibility constraints for a specific line and clue
    # Returns True if consistent, False if violated
    def check_line_consistency(line, clue):
        if clue == 0:
            return True

        # If line is full
        if 0 not in line:
            cnt = count_visible_full(line)
            return cnt == clue

        # If line is partial, check bounds
        # Calculate min and max possible visible count

        # Current visible count among placed buildings
        current_cnt = 0
        current_max = 0
        empty_count = 0
        n_placed = False

        for h in line:
            if h == 0:
                empty_count += 1
            else:
                if h > current_max:
                    current_max = h
                    current_cnt += 1
                if h == N:
                    n_placed = True

        # Max possible visible:
        # We see current_cnt.
        # We can potentially see all empty cells if they are increasing and > current_max.
        max_possible = current_cnt + empty_count

        # Min possible visible:
        # We definitely see current_cnt.
        # If N is not placed yet, we will see N eventually (N is never hidden).
        min_possible = current_cnt
        if not n_placed:
            min_possible += 1

        # Special case: If N is placed, all cells after N are hidden.
        # So if N is placed at index k, and there are empty cells after k, they don't add to visibility.
        # But they must be filled with something < N.
        # This doesn't change the visibility count, which is fixed once N is seen?
        # No, empty cells *before* N can still add to visibility.
        if n_placed:
            # Find index of N
            n_idx = line.index(N)
            # Count visible up to N (including N) considering only placed buildings
            cnt_up_to_n = 0
            mx = 0
            empty_before_n = 0
            for i in range(n_idx + 1):
                if line[i] == 0:
                    empty_before_n += 1
                else:
                    if line[i] > mx:
                        mx = line[i]
                        cnt_up_to_n += 1

            # Min visible: cnt_up_to_n (placed) + (1 if empty_before_n > 0 and line[0] is empty? No)
            # Actually, if line[0] is empty, it MUST be visible (height >= 1).
            # So if line[0] is 0, min_visible increases by 1?
            # Let's stick to the loose bound: min_possible = cnt_up_to_n.
            # Because empty cells *could* be hidden (if not at index 0).
            # Wait, line[0] cannot be hidden.
            # So if line[0] == 0, min_possible should be at least cnt_up_to_n + 1?
            # Only if cnt_up_to_n doesn't already account for a visible building at 0.
            # Since line[0] is 0, it's not in cnt_up_to_n.
            # So yes, if line[0] == 0, min_possible += 1.
            if line[0] == 0:
                min_possible = cnt_up_to_n + 1
            else:
                min_possible = cnt_up_to_n

            max_possible = cnt_up_to_n + empty_before_n

        return min_possible <= clue <= max_possible

    # Propagation function
    def propagate():
        changed = True
        while changed:
            changed = False

            # 1. Naked Singles
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0 and len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        # Assign
                        grid[r][c] = val
                        # Remove from peers
                        for j in range(N):
                            if j != c:
                                if val in domains[r][j]:
                                    domains[r][j].remove(val)
                                    changed = True
                        for i in range(N):
                            if i != r:
                                if val in domains[i][c]:
                                    domains[i][c].remove(val)
                                    changed = True
                        # Check consistency
                        if not is_unique_consistent(r, c, val):
                            return False

            # 2. Hidden Singles (Row/Col)
            for r in range(N):
                for val in range(1, N + 1):
                    if val not in grid[r]: # If not already in row
                        possible_cols = [c for c in range(N) if grid[r][c] == 0 and val in domains[r][c]]
                        if len(possible_cols) == 1:
                            c = possible_cols[0]
                            grid[r][c] = val
                            domains[r][c] = {val}
                            # Remove from col peers
                            for i in range(N):
                                if i != r:
                                    if val in domains[i][c]:
                                        domains[i][c].remove(val)
                                        changed = True
                            changed = True

            for c in range(N):
                for val in range(1, N + 1):
                    col_vals = [grid[i][c] for i in range(N)]
                    if val not in col_vals:
                        possible_rows = [r for r in range(N) if grid[r][c] == 0 and val in domains[r][c]]
                        if len(possible_rows) == 1:
                            r = possible_rows[0]
                            grid[r][c] = val
                            domains[r][c] = {val}
                            # Remove from row peers
                            for j in range(N):
                                if j != c:
                                    if val in domains[r][j]:
                                        domains[r][j].remove(val)
                                        changed = True
                            changed = True

            # 3. Visibility Constraints Pruning (Specific Rules)
            # Rule: Clue 1 -> First cell must be N
            for r in range(N):
                if L[r] == 1:
                    if grid[r][0] == 0:
                        if domains[r][0] != {N}:
                            domains[r][0] = {N}
                            changed = True
                if R[r] == 1:
                    if grid[r][N-1] == 0:
                        if domains[r][N-1] != {N}:
                            domains[r][N-1] = {N}
                            changed = True

            for c in range(N):
                if U[c] == 1:
                    if grid[0][c] == 0:
                        if domains[0][c] != {N}:
                            domains[0][c] = {N}
                            changed = True
                if D[c] == 1:
                    if grid[N-1][c] == 0:
                        if domains[N-1][c] != {N}:
                            domains[N-1][c] = {N}
                            changed = True

            # Rule: Clue N -> 1, 2, ..., N
            for r in range(N):
                if L[r] == N:
                    for c in range(N):
                        val = c + 1
                        if grid[r][c] == 0:
                            if val not in domains[r][c]:
                                return False # Conflict
                            if domains[r][c] != {val}:
                                domains[r][c] = {val}
                                changed = True
                if R[r] == N:
                    for c in range(N):
                        val = N - c
                        if grid[r][c] == 0:
                            if val not in domains[r][c]:
                                return False
                            if domains[r][c] != {val}:
                                domains[r][c] = {val}
                                changed = True
            for c in range(N):
                if U[c] == N:
                    for r in range(N):
                        val = r + 1
                        if grid[r][c] == 0:
                            if val not in domains[r][c]:
                                return False
                            if domains[r][c] != {val}:
                                domains[r][c] = {val}
                                changed = True
                if D[c] == N:
                    for r in range(N):
                        val = N - r
                        if grid[r][c] == 0:
                            if val not in domains[r][c]:
                                return False
                            if domains[r][c] != {val}:
                                domains[r][c] = {val}
                                changed = True

            # 4. General Visibility Consistency Check
            # Check Rows
            for r in range(N):
                clue_l = L[r]
                if clue_l > 0:
                    line = grid[r]
                    if not check_line_consistency(line, clue_l):
                        return False
                clue_r = R[r]
                if clue_r > 0:
                    line = grid[r][::-1]
                    if not check_line_consistency(line, clue_r):
                        return False

            # Check Cols
            for c in range(N):
                clue_u = U[c]
                if clue_u > 0:
                    line = [grid[i][c] for i in range(N)]
                    if not check_line_consistency(line, clue_u):
                        return False
                clue_d = D[c]
                if clue_d > 0:
                    line = [grid[i][c] for i in range(N)][::-1]
                    if not check_line_consistency(line, clue_d):
                        return False

        return True

    # Backtracking
    def backtrack():
        # Check if solved
        if all(grid[r][c] != 0 for r in range(N) for c in range(N)):
            return True

        # MRV Heuristic
        min_domain_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    size = len(domains[r][c])
                    if size < min_domain_size:
                        min_domain_size = size
                        best_cell = (r, c)

        if best_cell is None:
            return False

        r, c = best_cell
        possible_vals = sorted(list(domains[r][c]))

        for val in possible_vals:
            # Try val
            grid[r][c] = val
            # Save state
            domains_snapshot = copy.deepcopy(domains)
            grid_snapshot = [row[:] for row in grid]

            # Update domain for this cell
            domains[r][c] = {val}

            # Propagate constraints
            if propagate():
                if backtrack():
                    return True

            # Revert
            domains[:] = domains_snapshot
            grid[:] = grid_snapshot
            grid[r][c] = 0

        return False

    # Initial propagation
    if propagate():
        if backtrack():
            return grid
        else:
            return "No Solution"
    else:
        return "No Solution"

if __name__ == "__main__":
    result = solve(OBSERVATION)
    print(result)
