OBSERVATION = {'data': [[3, 4, 3, 2, 3], [4, 3, 2, 3, 5], [1, 2, 3, 1, 4], [5, 3, 1, 4, 2], [2, 4, 4, 3, 3]]}

def solve(observation):
    grid = observation['data']
    N = len(grid)

    # State: 0 = White (Unshaded), 1 = Black (Shaded), 2 = Unknown
    state = [[2] * N for _ in range(N)]

    # Directions for neighbors
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def set_cell(r, c, val, changes):
        """
        Sets state[r][c] to val.
        Propagates constraints.
        Returns False if conflict detected.
        Appends changed coordinates to 'changes' list.
        """
        # Check conflict with existing state
        if state[r][c] != 2 and state[r][c] != val:
            return False

        # If already set to this value, no need to propagate again (unless we want to re-check, but logic holds)
        if state[r][c] == val:
            return True

        # Apply change
        state[r][c] = val
        changes.append((r, c))

        if val == 1:  # Black
            # Rule: Black cells cannot touch orthogonally -> Neighbors must be White
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if not set_cell(nr, nc, 0, changes):
                        return False
        else:  # White (val == 0)
            # Rule: Unshaded numbers appear at most once in row/col
            # So all other cells with same number in row/col must be Black
            v = grid[r][c]

            # Check Row
            for c2 in range(N):
                if c2 != c and grid[r][c2] == v:
                    if not set_cell(r, c2, 1, changes):
                        return False

            # Check Col
            for r2 in range(N):
                if r2 != r and grid[r2][c] == v:
                    if not set_cell(r2, c, 1, changes):
                        return False

        return True

    def undo(changes):
        """Reverts changes to Unknown (2)"""
        for r, c in reversed(changes):
            state[r][c] = 2

    def is_connected():
        """Checks if all White cells form a single connected component"""
        whites = []
        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    whites.append((r, c))

        if not whites:
            return True  # Vacuously true, though unlikely for valid puzzle

        # BFS
        start = whites[0]
        queue = [start]
        visited = set([start])

        while queue:
            r, c = queue.pop(0)
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if state[nr][nc] == 0 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        return len(visited) == len(whites)

    def get_next_cell():
        """Heuristic: Pick unknown cell involved in most constraints (duplicates)"""
        best_cell = None
        max_constraints = -1

        for r in range(N):
            for c in range(N):
                if state[r][c] == 2:
                    # Count same values in row/col
                    v = grid[r][c]
                    count = 0
                    for c2 in range(N):
                        if c2 != c and grid[r][c2] == v:
                            count += 1
                    for r2 in range(N):
                        if r2 != r and grid[r2][c] == v:
                            count += 1

                    # Also prioritize adjacent duplicates (tight constraints)
                    # Check neighbors for same value
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] == v:
                            count += 5 # High weight for adjacent duplicates

                    if count > max_constraints:
                        max_constraints = count
                        best_cell = (r, c)

        # Fallback to first unknown
        if best_cell is None:
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 2:
                        return (r, c)
        return best_cell

    def search():
        cell = get_next_cell()
        if cell is None:
            # All cells assigned
            if is_connected():
                return True
            return False

        r, c = cell

        # Try White (0) first - usually we want to keep cells white
        # But for efficiency, maybe try to resolve conflicts?
        # Let's stick to White first as a heuristic for "maximal" solution, 
        # though any valid solution is fine.

        # Branch 1: White
        changes = []
        if set_cell(r, c, 0, changes):
            if search():
                return True
        undo(changes)

        # Branch 2: Black
        changes = []
        if set_cell(r, c, 1, changes):
            if search():
                return True
        undo(changes)

        return False

    if search():
        # Format output
        result = []
        for r in range(N):
            row = []
            for c in range(N):
                if state[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            result.append(row)
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
