def solve(observation):
    import sys
    sys.setrecursionlimit(2000)

    N = 7
    regions = observation['region']
    data = observation['data']

    # Build region map: region_id -> list of (r, c)
    region_cells = {}
    for r in range(N):
        for c in range(N):
            rid = regions[r][c]
            if rid not in region_cells:
                region_cells[rid] = []
            region_cells[rid].append((r, c))

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Constraints
    def get_peers(r, c):
        peers = []
        # Row
        for cc in range(N):
            if cc != c:
                peers.append((r, cc))
        # Col
        for rr in range(N):
            if rr != r:
                peers.append((rr, c))
        # Region
        rid = regions[r][c]
        for rr, cc in region_cells[rid]:
            if (rr, cc) != (r, c):
                peers.append((rr, cc))
        return peers

    def is_consistent(var, value, assignment):
        r, c = var
        # Check row
        for cc in range(N):
            if cc != c and (r, cc) in assignment and assignment[(r, cc)] == value:
                return False
        # Check col
        for rr in range(N):
            if rr != r and (rr, c) in assignment and assignment[(rr, c)] == value:
                return False
        # Check region
        rid = regions[r][c]
        for rr, cc in region_cells[rid]:
            if (rr, cc) != (r, c) and (rr, cc) in assignment and assignment[(rr, cc)] == value:
                return False
        return True

    def select_unassigned_variable(assignment, domains):
        unassigned = [(r, c) for r in range(N) for c in range(N) if (r, c) not in assignment]
        # MRV: Minimum Remaining Values
        return min(unassigned, key=lambda var: len(domains[var]))

    def inference(var, value, assignment, domains):
        # Forward checking
        new_domains = {k: v.copy() for k, v in domains.items()}
        new_domains[var] = {value}

        for peer in get_peers(*var):
            if peer not in assignment:
                if value in new_domains[peer]:
                    new_domains[peer].remove(value)
                    if len(new_domains[peer]) == 0:
                        return None
        return new_domains

    def backtrack(assignment, domains):
        if len(assignment) == N * N:
            return assignment

        var = select_unassigned_variable(assignment, domains)
        r, c = var

        # Order values: least constraining value? Or just sorted.
        # Given N=7, sorted is fine.
        for value in sorted(list(domains[var])):
            if is_consistent(var, value, assignment):
                assignment[var] = value
                new_domains = inference(var, value, assignment, domains)
                if new_domains is not None:
                    result = backtrack(assignment, new_domains)
                    if result is not None:
                        return result
                del assignment[var]
        return None

    initial_assignment = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                initial_assignment[(r, c)] = data[r][c]

    # Check initial consistency
    for (r, c), val in initial_assignment.items():
        if not is_consistent((r, c), val, {k: v for k, v in initial_assignment.items() if (k, c) != (r, c) and (k, c) != (r, c)}): 
            # Simplified check, full check is in backtrack
            pass

    solution = backtrack(initial_assignment, domains)

    if solution is None:
        return "No Solution"

    # Format output as 2D list
    result_grid = [[0] * N for _ in range(N)]
    for (r, c), val in solution.items():
        result_grid[r][c] = val
    return result_grid

