                clues[(r, c)] = data[r][c]

    # Directions: Up, Down, Left, Right
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_line(r, c, dr, dc):
        """Returns list of (nr, nc) in direction (dr, dc) from (r, c)"""
        line = []
        nr, nc = r + dr, c + dc
        while 0 <= nr < N and 0 <= nc < N:
            line.append((nr, nc))
            nr += dr
            nc += dc
        return line

    def propagate(g):
        """Returns (success, changed)"""
        changed = True
        while changed:
            changed = False
            # 1. Black neighbors must be White
            for r in range(N):
                for c in range(N):
                    if g[r][c] == 1:
                        for dr, dc in DIRS:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if g[nr][nc] == 2:
                                    g[nr][nc] = 0
                                    changed = True
                                elif g[nr][nc] == 1:
                                    return False # Adjacent blacks

            # 2. Clue Constraints
            for (r, c), val in clues.items():
                min_visible = 1 # Self
                max_visible = 1

                # Calculate min/max visible for this clue
                # min: count consecutive 0s. Stop at 1 or 2 (assume 2 blocks for min)
                # max: count consecutive 0s and 2s. Stop at 1.

                line_info = [] # Store (min_count, max_count, line_cells)

                for dr, dc in DIRS:
                    line = get_line(r, c, dr, dc)
                    c_min = 0
                    c_max = 0
                    for nr, nc in line:
                        cell = g[nr][nc]
                        if cell == 0:
                            c_min += 1
                            c_max += 1
                        elif cell == 2:
                            c_max += 1
                            # c_min stops increasing
                            break # For min, we assume 2 is Black (blocker)
                        elif cell == 1:
                            break # Blocker for both

                    min_visible += c_min
                    max_visible += c_max
                    line_info.append((c_min, c_max, line))

                if min_visible > val or max_visible < val:
                    return False

                # If max_visible == val, all potential whites must be white
                if max_visible == val:
                    for c_min, c_max, line in line_info:
                        # We need to fill all 2s in the line that contributed to max
                        # But we must stop if we hit a 1 (which we didn't, since max counts them)
                        # Actually, max calculation stops at 1. So all cells in 'line' up to the break point are 0 or 2.
                        # We need to check which ones were counted.
                        # Re-scan to be safe
                        for nr, nc in line:
                            if g[nr][nc] == 2:
                                g[nr][nc] = 0
                                changed = True
                            elif g[nr][nc] == 1:
                                break # Should not happen if max logic is consistent, but safe guard

                # If min_visible == val, any 2 immediately following a sequence of 0s must be 1
                if min_visible == val:
                    for dr, dc in DIRS:
                        line = get_line(r, c, dr, dc)
                        # Count consecutive 0s
                        count_0 = 0
                        for nr, nc in line:
                            if g[nr][nc] == 0:
                                count_0 += 1
                            else:
                                # First non-0 cell
                                if g[nr][nc] == 2:
                                    g[nr][nc] = 1
                                    changed = True
                                break # Stop after first non-0 (whether it was 1 or became 1)

        return True

    def is_connected(g):
        """Check if all 0s are connected"""
        zeros = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == 0:
                    zeros.append((r, c))

        if not zeros:
            return True

        start = zeros[0]
        visited = set()
        queue = [start]
        visited.add(start)

        while queue:
            r, c = queue.pop(0)
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if g[nr][nc] == 0 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        return len(visited) == len(zeros)

    def check_clues_exact(g):
        for (r, c), val in clues.items():
            count = 1
            for dr, dc in DIRS:
                line = get_line(r, c, dr, dc)
                for nr, nc in line:
                    if g[nr][nc] == 0:
                        count += 1
                    else:
                        break
            if count != val:
                return False
        return True

    def search(g):
        # Propagate first
        if not propagate(g):
            return None

        # Find unknown
        r_pick, c_pick = -1, -1
        # Heuristic: pick cell adjacent to a clue or with most constraints?
        # Simple: first unknown
        for r in range(N):
            for c in range(N):
                if g[r][c] == 2:
                    r_pick, c_pick = r, c
                    break
            if r_pick != -1: break

        if r_pick == -1:
            # Solved? Check constraints
            if check_clues_exact(g) and is_connected(g):
                return g
            return None

        # Try White (0)
        g0 = copy.deepcopy(g)
        g0[r_pick][c_pick] = 0
        res = search(g0)
        if res: return res

        # Try Black (1)
        g1 = copy.deepcopy(g)
        g1[r_pick][c_pick] = 1
        res = search(g1)
        if res: return res

        return None

    final_grid = search(grid)

    if final_grid is None:
        return "No Solution"

    # Format output
    # Black -> 'B'
    # Clue -> Number
    # White (non-clue) -> None
    result = [[None for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if final_grid[r][c] == 1:
                result[r][c] = 'B'
            elif (r, c) in clues:
                result[r][c] = clues[(r, c)]
            else:
                result[r][c] = None

    return result

