sys.setrecursionlimit(2000)

def solve(observation):
    # 1. Parse Observation
    data = observation['data']
    N = len(data)

    # Domains: list of lists of sets
    # domains[r][c] contains possible values for cell (r, c)
    # Initialize with all possible values 1..N
    domains = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]

    # Apply Givens
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                val = data[r][c]
                domains[r][c] = {val}

    # Parse Constraints
    h_constraints = [] 
    for key, val in observation['horizontal'].items():
        # key is like '(0, 0.5)'
        key_clean = key.strip("()").split(", ")
        r = int(key_clean[0])
        c_float = float(key_clean[1])
        c1 = int(c_float)
        c2 = c1 + 1
        h_constraints.append((r, c1, c2, val))

    v_constraints = [] 
    for key, val in observation['vertical'].items():
        key_clean = key.strip("()").split(", ")
        r_float = float(key_clean[0])
        c = int(key_clean[1])
        r1 = int(r_float)
        r2 = r1 + 1
        v_constraints.append((r1, r2, c, val))

    def is_consistent(domains):
        # Check if any domain is empty
        for r in range(N):
            for c in range(N):
                if not domains[r][c]:
                    return False
        return True

    def propagate(domains):
        # Constraint Propagation Loop (AC-3 style + Hidden Singles)
        changed = True
        while changed:
            changed = False

            # 1. Apply Inequality Constraints (Arc Consistency)
            # Horizontal
            for r, c1, c2, op in h_constraints:
                d1 = domains[r][c1]
                d2 = domains[r][c2]
                if not d1 or not d2: continue

                if op == '>':
                    # d1 > d2: keep v1 in d1 if exists v2 in d2 s.t. v1 > v2
                    new_d1 = {v1 for v1 in d1 if any(v1 > v2 for v2 in d2)}
                    # keep v2 in d2 if exists v1 in d1 s.t. v2 < v1
                    new_d2 = {v2 for v2 in d2 if any(v2 < v1 for v1 in d1)}
                elif op == '<':
                    # d1 < d2
                    new_d1 = {v1 for v1 in d1 if any(v1 < v2 for v2 in d2)}
                    new_d2 = {v2 for v2 in d2 if any(v2 > v1 for v1 in d1)}
                else:
                    continue

                if new_d1 != d1:
                    domains[r][c1] = new_d1
                    changed = True
                if new_d2 != d2:
                    domains[r][c2] = new_d2
                    changed = True

            # Vertical
            for r1, r2, c, op in v_constraints:
                d1 = domains[r1][c]
                d2 = domains[r2][c]
                if not d1 or not d2: continue

                if op == 'v': # Top > Bottom (wide side up)
                    new_d1 = {v1 for v1 in d1 if any(v1 > v2 for v2 in d2)}
                    new_d2 = {v2 for v2 in d2 if any(v2 < v1 for v1 in d1)}
                elif op == '^': # Top < Bottom (wide side down)
                    new_d1 = {v1 for v1 in d1 if any(v1 < v2 for v2 in d2)}
                    new_d2 = {v2 for v2 in d2 if any(v2 > v1 for v1 in d1)}
                else:
                    continue

                if new_d1 != d1:
                    domains[r1][c] = new_d1
                    changed = True
                if new_d2 != d2:
                    domains[r2][c] = new_d2
                    changed = True

            # 2. Apply Latin Square Constraints (AllDifferent)
            # If a cell has a single value (Naked Single), remove it from row/col peers
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        # Row peers
                        for cc in range(N):
                            if cc != c:
                                if val in domains[r][cc]:
                                    domains[r][cc].remove(val)
                                    changed = True
                        # Col peers
                        for rr in range(N):
                            if rr != r:
                                if val in domains[rr][c]:
                                    domains[rr][c].remove(val)
                                    changed = True

            # 3. Hidden Singles
            # For each row, for each val, check if only one cell can take it
            for r in range(N):
                for val in range(1, N+1):
                    candidates = [c for c in range(N) if val in domains[r][c]]
                    if len(candidates) == 1:
                        c = candidates[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

            # For each col, for each val, check if only one cell can take it
            for c in range(N):
                for val in range(1, N+1):
                    candidates = [r for r in range(N) if val in domains[r][c]]
                    if len(candidates) == 1:
                        r = candidates[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

        return domains

    # Initial Propagation
    domains = propagate(domains)
    if not is_consistent(domains):
        return "No Solution"

    # Backtracking Search with MRV Heuristic
    def get_unassigned_variable(domains):
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    if len(domains[r][c]) < min_len:
                        min_len = len(domains[r][c])
                        best_cell = (r, c)
        return best_cell

    def solve_recursive(domains):
        # Check if solved (all domains size 1)
        is_solved = True
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) != 1:
                    is_solved = False
                    break
            if not is_solved:
                break

        if is_solved:
            sol = [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]
            return sol

        cell = get_unassigned_variable(domains)
        if cell is None:
            return None 

        r, c = cell
        # Order values (LCV heuristic could be added, but sorted is stable)
        possible_values = sorted(list(domains[r][c]))

        for val in possible_values:
            # Deep copy domains to avoid modifying current state
            domains_copy = [[s.copy() for s in row] for row in domains]
            domains_copy[r][c] = {val}

            # Propagate constraints after assignment
            domains_copy = propagate(domains_copy)

            if is_consistent(domains_copy):
                result = solve_recursive(domains_copy)
                if result:
                    return result

        return None

    final_solution = solve_recursive(domains)

    if final_solution:
        return final_solution
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
