                grid[r][c] = 2

    # Counts
    row_counts = [[0, 0, 0] for _ in range(N)] # [Unknown, B, W]
    col_counts = [[0, 0, 0] for _ in range(N)]

    for r in range(N):
        for c in range(N):
            val = grid[r][c]
            row_counts[r][val] += 1
            col_counts[c][val] += 1

    def get_opposite(val):
        return 2 if val == 1 else 1

    def set_cell(r, c, val, queue):
        if grid[r][c] != 0:
            return grid[r][c] == val

        grid[r][c] = val
        row_counts[r][0] -= 1
        row_counts[r][val] += 1
        col_counts[c][0] -= 1
        col_counts[c][val] += 1

        # Add to queue for propagation
        queue.append((r, c))
        return True

    def check_contradiction(r, c):
        val = grid[r][c]
        if val == 0: return False

        # Check counts
        if row_counts[r][val] > HALF: return True
        if col_counts[c][val] > HALF: return True

        # Check triplets
        # Row
        if c >= 2:
            if grid[r][c-1] == val and grid[r][c-2] == val: return True
        if c >= 1 and c < N-1:
            if grid[r][c-1] == val and grid[r][c+1] == val: return True
        if c < N-2:
            if grid[r][c+1] == val and grid[r][c+2] == val: return True

        # Col
        if r >= 2:
            if grid[r-1][c] == val and grid[r-2][c] == val: return True
        if r >= 1 and r < N-1:
            if grid[r-1][c] == val and grid[r+1][c] == val: return True
        if r < N-2:
            if grid[r+1][c] == val and grid[r+2][c] == val: return True

        return False

    def propagate():
        queue = []
        # Initial fill of known cells
        for r in range(N):
            for c in range(N):
                if grid[r][c] != 0:
                    queue.append((r, c))

        while queue:
            r, c = queue.pop(0)
            val = grid[r][c]
            opp = get_opposite(val)

            # 1. Check for immediate contradictions
            if check_contradiction(r, c):
                return False

            # 2. Apply Binary Constraints
            # Horizontal Right (r, c) -> (r, c+1)
            if (r, c) in h_constraints:
                constraint = h_constraints[(r, c)]
                nc = c + 1
                if nc < N:
                    if grid[r][nc] == 0:
                        target = val if constraint == '=' else opp
                        if not set_cell(r, nc, target, queue): return False

            # Horizontal Left (r, c-1) -> (r, c)
            if (r, c-1) in h_constraints:
                constraint = h_constraints[(r, c-1)]
                pc = c - 1
                if pc >= 0:
                    if grid[r][pc] == 0:
                        target = val if constraint == '=' else opp
                        if not set_cell(r, pc, target, queue): return False

            # Vertical Down (r, c) -> (r+1, c)
            if (r, c) in v_constraints:
                constraint = v_constraints[(r, c)]
                nr = r + 1
                if nr < N:
                    if grid[nr][c] == 0:
                        target = val if constraint == '=' else opp
                        if not set_cell(nr, c, target, queue): return False

            # Vertical Up (r-1, c) -> (r, c)
            if (r-1, c) in v_constraints:
                constraint = v_constraints[(r-1, c)]
                pr = r - 1
                if pr >= 0:
                    if grid[pr][c] == 0:
                        target = val if constraint == '=' else opp
                        if not set_cell(pr, c, target, queue): return False

            # 3. Apply Count Constraints (Fill rest if max reached)
            if row_counts[r][1] == HALF:
                for cc in range(N):
                    if grid[r][cc] == 0:
                        if not set_cell(r, cc, 2, queue): return False
            if row_counts[r][2] == HALF:
                for cc in range(N):
                    if grid[r][cc] == 0:
                        if not set_cell(r, cc, 1, queue): return False

            if col_counts[c][1] == HALF:
                for rr in range(N):
                    if grid[rr][c] == 0:
                        if not set_cell(rr, c, 2, queue): return False
            if col_counts[c][2] == HALF:
                for rr in range(N):
                    if grid[rr][c] == 0:
                        if not set_cell(rr, c, 1, queue): return False

            # 4. Apply Triplet Constraints (Deduction)
            # Row: XX -> !X neighbors
            # Check left neighbor
            if c >= 1 and grid[r][c-1] == val:
                # We have val, val at c-1, c.
                # Check c-2
                if c >= 2 and grid[r][c-2] == 0:
                    if not set_cell(r, c-2, opp, queue): return False
                # Check c+1
                if c < N-1 and grid[r][c+1] == 0:
                    if not set_cell(r, c+1, opp, queue): return False

            # Check right neighbor
            if c < N-1 and grid[r][c+1] == val:
                # We have val, val at c, c+1
                # Check c-1
                if c >= 1 and grid[r][c-1] == 0:
                    if not set_cell(r, c-1, opp, queue): return False
                # Check c+2
                if c < N-2 and grid[r][c+2] == 0:
                    if not set_cell(r, c+2, opp, queue): return False

            # Row: X_X -> middle !X
            if c >= 1 and c < N-1:
                if grid[r][c-1] == val and grid[r][c+1] == val:
                    if grid[r][c] == 0: # Should be val, but we are processing val at c. 
                        # Wait, if grid[r][c] is val, and neighbors are val, that's a triplet (contradiction).
                        # The rule is: if neighbors are SAME, middle must be DIFFERENT.
                        pass 
                    # Actually, if grid[r][c-1] == val and grid[r][c+1] == val, then grid[r][c] MUST be opp.
                    # But we are currently processing (r,c) which IS val. So this would be a contradiction.
                    # This is covered by check_contradiction.
                    # The deduction case is when grid[r][c] is 0.
                    # But we are in the loop for (r,c) where grid[r][c] != 0.
                    # So we look for patterns where (r,c) helps deduce others.
                    # Pattern: val, 0, val -> 0 must be opp.
                    # This is handled when we process the neighbors? 
                    # No, we need to scan the row/col for this pattern.

            # Let's do a explicit scan for X_X pattern in the affected row/col
            # Row scan
            for cc in range(N-2):
                if grid[r][cc] != 0 and grid[r][cc+2] != 0 and grid[r][cc] == grid[r][cc+2]:
                    if grid[r][cc+1] == 0:
                        if not set_cell(r, cc+1, get_opposite(grid[r][cc]), queue): return False

            # Col scan
            for rr in range(N-2):
                if grid[rr][c] != 0 and grid[rr+2][c] != 0 and grid[rr][c] == grid[rr+2][c]:
                    if grid[rr+1][c] == 0:
                        if not set_cell(rr+1, c, get_opposite(grid[rr][c]), queue): return False

        return True

    def is_solved():
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0: return False
        return True

    def search():
        if not propagate():
            return False

        if is_solved():
            return True

        # MRV Heuristic: Find cell with fewest options (always 2 for binary, but pick one that constrains most)
        # Or just first empty cell for simplicity in 10x10
        best_r, best_c = -1, -1
        # Simple heuristic: pick first empty
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    best_r, best_c = r, c
                    break
            if best_r != -1: break

        if best_r == -1: return True # Should be caught by is_solved

        # Try Black (1)
        # Save state
        # Since propagate modifies global state, we need to backtrack carefully.
        # Deep copy is expensive. Let's use a stack of changes or just copy grid/counts for small N.
        # For N=10, copying is fine.

        # Save state
        grid_snapshot = [row[:] for row in grid]
        row_counts_snapshot = [row[:] for row in row_counts]
        col_counts_snapshot = [col[:] for col in col_counts]

        if set_cell(best_r, best_c, 1, []):
            if search(): return True

        # Restore state
        for r in range(N):
            grid[r] = grid_snapshot[r][:]
            row_counts[r] = row_counts_snapshot[r][:]
            col_counts[r] = col_counts_snapshot[r][:] # Wait, col_counts is indexed by col

        # Fix restore for col_counts
        for c in range(N):
            col_counts[c] = col_counts_snapshot[c][:]

        # Try White (2)
        if set_cell(best_r, best_c, 2, []):
            if search(): return True

        # Restore state again (not strictly needed as we return False, but good for cleanliness)
        for r in range(N):
            grid[r] = grid_snapshot[r][:]
            row_counts[r] = row_counts_snapshot[r][:]
        for c in range(N):
            col_counts[c] = col_counts_snapshot[c][:]

        return False

    if search():
        # Convert back to B/W
        result = []
        for r in range(N):
            row_res = []
            for c in range(N):
                row_res.append('B' if grid[r][c] == 1 else 'W')
            result.append(row_res)
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
