OBSERVATION = {'data': [[5, 1, 2, 8, 7, 1, 4, 9, 8, 9], [8, 2, 10, 4, 9, 3, 6, 9, 1, 8], [1, 7, 7, 8, 4, 4, 9, 2, 9, 5], [4, 6, 9, 4, 8, 2, 9, 3, 6, 8], [6, 9, 1, 7, 9, 8, 2, 2, 5, 3], [1, 6, 3, 9, 1, 3, 8, 7, 8, 4], [9, 5, 7, 10, 5, 1, 4, 10, 4, 1], [8, 3, 1, 6, 2, 9, 5, 1, 5, 9], [9, 4, 5, 10, 8, 9, 10, 8, 3, 1], [3, 5, 10, 1, 4, 7, 10, 1, 9, 3]]}

def solve(observation):
    grid = observation['data']
    N = len(grid)

    # State: 0=Unknown, 1=White, 2=Black
    state = [[0] * N for _ in range(N)]

    # Precompute conflicts: for each cell, list of (r, c) with same value in row/col
    conflicts = [[[] for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            val = grid[r][c]
            for k in range(N):
                if k != c and grid[r][k] == val:
                    conflicts[r][c].append((r, k))
                if k != r and grid[k][c] == val:
                    conflicts[r][c].append((k, c))

    # Precompute initial neighbor counts (number of orthogonal neighbors within grid)
    # This tracks "potential connections" for connectivity check.
    # A cell is isolated if it is White and neighbor_counts becomes 0 (all neighbors Black).
    neighbor_counts = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            count = 0
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    count += 1
            neighbor_counts[r][c] = count

    total_white = 0
    queue = [] # Propagation queue: (r, c, type) where type 1=White, 2=Black

    # Snapshot management for backtracking
    def get_snapshot():
        return {
            'state': [row[:] for row in state],
            'neighbor_counts': [row[:] for row in neighbor_counts],
            'total_white': total_white,
            'queue': list(queue)
        }

    def restore_snapshot(snap):
        nonlocal state, neighbor_counts, total_white, queue
        state = snap['state']
        neighbor_counts = snap['neighbor_counts']
        total_white = snap['total_white']
        queue = snap['queue']

    def set_cell(r, c, val_type):
        # Returns True if successful, False if conflict detected
        if state[r][c] != 0:
            return state[r][c] == val_type

        state[r][c] = val_type
        queue.append((r, c, val_type))

        if val_type == 1: # White
            nonlocal total_white
            total_white += 1
            # Check for immediate isolation: if surrounded by Blacks already
            if neighbor_counts[r][c] == 0:
                if total_white > 1:
                    return False 
        return True

    def propagate():
        nonlocal total_white
        while queue:
            r, c, val_type = queue.pop()

            if val_type == 2: # Black
                # Rule: Black cells cannot touch orthogonally.
                # So all orthogonal neighbors MUST be White.
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        # Update neighbor count: this neighbor loses a non-black connection
                        neighbor_counts[nr][nc] -= 1

                        # If neighbor is already White, check if it became isolated
                        if state[nr][nc] == 1:
                            if neighbor_counts[nr][nc] == 0:
                                if total_white > 1:
                                    return False # Isolation detected

                        # If neighbor is Unknown, it MUST become White
                        if state[nr][nc] == 0:
                            if not set_cell(nr, nc, 1): 
                                return False

            elif val_type == 1: # White
                # Rule: Unshaded numbers appear at most once in row/col.
                # So all other cells with same value in row/col MUST be Black.
                for nr, nc in conflicts[r][c]:
                    if state[nr][nc] == 1:
                        return False # Duplicate White detected
                    if state[nr][nc] == 0:
                        if not set_cell(nr, nc, 2): 
                            return False
        return True

    def check_connectivity():
        # BFS to ensure all White cells are connected
        start = None
        count = 0
        for r in range(N):
            for c in range(N):
                if state[r][c] == 1:
                    if start is None: 
                        start = (r, c)
                    count += 1

        if count == 0: return True # No white cells (valid but unlikely)
        if start is None: return True

        visited = set([start])
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and state[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        return len(visited) == count

    def solve_dfs():
        # Find first Unknown cell (Simple heuristic)
        best_cell = None
        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    best_cell = (r, c)
                    break
            if best_cell: 
                break

        if best_cell is None:
            # All cells decided, check global connectivity
            return check_connectivity()

        r, c = best_cell
        snap = get_snapshot()

        # Heuristic: Try Black first? 
        # Black forces neighbors to White, which forces duplicates to Black.
        # This chain reaction is often good for pruning.

        # Try Black
        if set_cell(r, c, 2):
            if propagate():
                if solve_dfs():
                    return True

        restore_snapshot(snap)

        # Try White
        if set_cell(r, c, 1):
            if propagate():
                if solve_dfs():
                    return True

        return False

    # Start solving
    if solve_dfs():
        result = []
        for r in range(N):
            row_res = []
            for c in range(N):
                if state[r][c] == 2:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result.append(row_res)
        return result
    else:
        return "No Solution"

