import sys

# Increase recursion depth to handle backtracking safely for larger grids
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    H = len(data) - 1
    W = len(data[0]) - 1

    # Grid: 0=empty, 1='/', 2='\'
    grid = [[0] * W for _ in range(H)]

    # Dot degrees: tracks current number of connected lines for each dot
    dot_degree = [[0] * (W + 1) for _ in range(H + 1)]

    # DSU structures for loop detection
    # Nodes are mapped: (r, c) -> r * (W + 1) + c
    parent = list(range((H + 1) * (W + 1)))
    rank = [0] * ((H + 1) * (W + 1))
    dsu_stack = []  # Stack for rollback: stores ('parent', node, old_parent) or ('rank', node, old_rank)

    def find(x):
        # Path compression is omitted to facilitate easy rollback
        while parent[x] != x:
            x = parent[x]
        return x

    def union(x, y, stack):
        x_root = find(x)
        y_root = find(y)
        if x_root == y_root:
            return False  # Cycle detected

        # Union by rank
        if rank[x_root] < rank[y_root]:
            x_root, y_root = y_root, x_root

        parent[y_root] = x_root
        stack.append(('parent', y_root, y_root))  # y_root was its own parent

        if rank[x_root] == rank[y_root]:
            rank[x_root] += 1
            stack.append(('rank', x_root, rank[x_root] - 1))

        return True

    def dsu_rollback(stack, snapshot):
        while len(stack) > snapshot:
            op = stack.pop()
            if op[0] == 'parent':
                _, node, old_val = op
                parent[node] = old_val
            elif op[0] == 'rank':
                _, node, old_val = op
                rank[node] = old_val

    # Helper to force a cell value and record changes for undoing
    def force_cell(r, c, val, changes):
        if grid[r][c] != 0:
            return grid[r][c] == val

        # Determine endpoints for DSU
        if val == 1:  # '/' connects (r+1, c) and (r, c+1)
            u = (r + 1) * (W + 1) + c
            v = r * (W + 1) + (c + 1)
        else:  # '\' connects (r, c) and (r+1, c+1)
            u = r * (W + 1) + c
            v = (r + 1) * (W + 1) + (c + 1)

        if find(u) == find(v):
            return False  # Loop would be formed

        dsu_snap_before = len(dsu_stack)

        grid[r][c] = val
        union(u, v, dsu_stack)

        deg_changes = []
        if val == 1:
            dot_degree[r+1][c] += 1
            deg_changes.append((r+1, c))
            dot_degree[r][c+1] += 1
            deg_changes.append((r, c+1))
        else:
            dot_degree[r][c] += 1
            deg_changes.append((r, c))
            dot_degree[r+1][c+1] += 1
            deg_changes.append((r+1, c+1))

        changes.append({
            'type': 'cell_set',
            'r': r, 'c': c,
            'dsu_snap': dsu_snap_before,
            'deg_changes': deg_changes
        })
        return True

    def undo_propagation(changes):
        while changes:
            ch = changes.pop()
            if ch['type'] == 'cell_set':
                r, c = ch['r'], ch['c']
                grid[r][c] = 0
                dsu_rollback(dsu_stack, ch['dsu_snap'])
                for dr, dc in ch['deg_changes']:
                    dot_degree[dr][dc] -= 1

    def propagate(changes):
        changed = True
        while changed:
            changed = False
            for r in range(H + 1):
                for c in range(W + 1):
                    clue = data[r][c]
                    if clue is None:
                        continue

                    current_deg = dot_degree[r][c]
                    remaining_needed = clue - current_deg

                    if remaining_needed < 0:
                        return False

                    available = []
                    # Check 4 incident cells
                    # TL: (r-1, c-1), connects if '\' (2)
                    if r > 0 and c > 0:
                        val = grid[r-1][c-1]
                        if val == 0:
                            available.append((r-1, c-1, 2))
                        elif val == 2:
                            remaining_needed -= 1
                    # TR: (r-1, c), connects if '/' (1)
                    if r > 0 and c < W:
                        val = grid[r-1][c]
                        if val == 0:
                            available.append((r-1, c, 1))
                        elif val == 1:
                            remaining_needed -= 1
                    # BL: (r, c-1), connects if '/' (1)
                    if r < H and c > 0:
                        val = grid[r][c-1]
                        if val == 0:
                            available.append((r, c-1, 1))
                        elif val == 1:
                            remaining_needed -= 1
                    # BR: (r, c), connects if '\' (2)
                    if r < H and c < W:
                        val = grid[r][c]
                        if val == 0:
                            available.append((r, c, 2))
                        elif val == 2:
                            remaining_needed -= 1

                    if remaining_needed > len(available):
                        return False

                    if remaining_needed == 0:
                        # Force non-connecting (set to opposite of req_val)
                        for cr, cc, req_val in available:
                            other_val = 1 if req_val == 2 else 2
                            if grid[cr][cc] == 0:
                                if not force_cell(cr, cc, other_val, changes):
                                    return False
                                changed = True
                    elif remaining_needed == len(available):
                        # Force connecting (set to req_val)
                        for cr, cc, req_val in available:
                            if grid[cr][cc] == 0:
                                if not force_cell(cr, cc, req_val, changes):
                                    return False
                                changed = True
        return True

    def backtrack(r, c):
        # Find next empty cell
        while r < H and c < W:
            if grid[r][c] == 0:
                break
            c += 1
            if c == W:
                c = 0
                r += 1

        if r == H:
            return True

        # Try values 1 ('/') and 2 ('\')
        for val in [1, 2]:
            changes = []

            # Apply trial move
            if not force_cell(r, c, val, changes):
                undo_propagation(changes)
                continue

            # Propagate constraints
            if propagate(changes):
                if backtrack(r, c):
                    return True

            # Undo trial and propagation
            undo_propagation(changes)

        return False

    # Initial propagation from clues (e.g., 0s and 4s)
    init_changes = []
    if not propagate(init_changes):
        return "No Solution"
    # We do not undo init_changes; they are the starting state.

    if backtrack(0, 0):
        result = []
        for r in range(H):
            row = []
            for c in range(W):
                row.append('/' if grid[r][c] == 1 else '\\')
            result.append(row)
        return result
    else:
        return "No Solution"

OBSERVATION = {'data': [[None, None, None, 2, None, None, 1, None, None, None, 0], [None, 4, None, None, 1, 2, None, None, 1, None, None], [2, None, 3, None, 3, None, None, None, None, 3, None], [None, 2, None, None, 3, None, None, 4, None, 2, None], [None, None, None, 2, 2, None, 3, 2, 3, None, None], [2, None, None, 1, None, None, None, None, None, None, 1], [None, None, 1, 2, 2, 1, None, 2, 2, 2, None], [None, None, None, 2, 2, None, 2, None, 2, 3, None], [None, 2, None, None, None, None, 1, 2, 3, None, None], [0, None, 2, 1, None, 3, None, 3, 1, 1, None], [None, 1, None, 1, 0, None, None, None, 1, None, None]]}

if __name__ == "__main__":
    print(solve(OBSERVATION))
