import sys
sys.setrecursionlimit(5000)

def solve(observation):
    data = observation['data']
    N = len(data) - 1

    class Solver:
        def __init__(self, N, clues):
            self.N = N
            self.clues = clues
            # Grid: 0=unknown, 1='/', 2='\'
            self.grid = [[0] * N for _ in range(N)]
            # DSU for (N+1)*(N+1) dots to prevent loops
            self.parent = list(range((N + 1) * (N + 1)))
            # Degrees for each dot (number of incident lines)
            self.degrees = [[0] * (N + 1) for _ in range(N + 1)]

        def find(self, i):
            path = []
            while self.parent[i] != i:
                path.append(i)
                i = self.parent[i]
            for node in path:
                self.parent[node] = i
            return i

        def union(self, i, j):
            root_i = self.find(i)
            root_j = self.find(j)
            if root_i == root_j:
                return False # Loop detected
            self.parent[root_i] = root_j
            return True

        def get_dot_index(self, r, c):
            return r * (self.N + 1) + c

        def set_cell(self, r, c, val):
            # val: 1 ('/') or 2 ('\')
            self.grid[r][c] = val

            if val == 1: # '/' connects BL(r+1, c) and TR(r, c+1)
                self.degrees[r+1][c] += 1
                self.degrees[r][c+1] += 1
                u = self.get_dot_index(r+1, c)
                v = self.get_dot_index(r, c+1)
                if not self.union(u, v):
                    return False
            else: # '\' connects TL(r, c) and BR(r+1, c+1)
                self.degrees[r][c] += 1
                self.degrees[r+1][c+1] += 1
                u = self.get_dot_index(r, c)
                v = self.get_dot_index(r+1, c+1)
                if not self.union(u, v):
                    return False
            return True

        def propagate(self):
            # Apply logical deductions until no more changes or conflict
            changed = True
            while changed:
                changed = False
                for r in range(self.N + 1):
                    for c in range(self.N + 1):
                        clue = self.clues[r][c]
                        if clue is None:
                            continue

                        current = self.degrees[r][c]
                        if current > clue:
                            return False # Constraint violated

                        # Identify unknown neighbors that can still contribute to this dot
                        unknowns = []
                        # TL: cell (r-1, c-1) touches if '\' (2)
                        if r > 0 and c > 0 and self.grid[r-1][c-1] == 0:
                            unknowns.append(('TL', r-1, c-1))
                        # TR: cell (r-1, c) touches if '/' (1)
                        if r > 0 and c < self.N and self.grid[r-1][c] == 0:
                            unknowns.append(('TR', r-1, c))
                        # BL: cell (r, c-1) touches if '/' (1)
                        if r < self.N and c > 0 and self.grid[r][c-1] == 0:
                            unknowns.append(('BL', r, c-1))
                        # BR: cell (r, c) touches if '\' (2)
                        if r < self.N and c < self.N and self.grid[r][c] == 0:
                            unknowns.append(('BR', r, c))

                        needed = clue - current
                        count_unknowns = len(unknowns)

                        if needed == 0:
                            # Dot is satisfied; all unknown neighbors must NOT touch
                            for pos, cr, cc in unknowns:
                                if pos == 'TL': # TL touches if '\', so set '/' (1)
                                    if not self.set_cell(cr, cc, 1): return False
                                elif pos == 'TR': # TR touches if '/', so set '\' (2)
                                    if not self.set_cell(cr, cc, 2): return False
                                elif pos == 'BL': # BL touches if '/', so set '\' (2)
                                    if not self.set_cell(cr, cc, 2): return False
                                elif pos == 'BR': # BR touches if '\', so set '/' (1)
                                    if not self.set_cell(cr, cc, 1): return False
                                changed = True
                        elif needed == count_unknowns:
                            # Dot needs all remaining neighbors to touch
                            for pos, cr, cc in unknowns:
                                if pos == 'TL': # Set '\' (2)
                                    if not self.set_cell(cr, cc, 2): return False
                                elif pos == 'TR': # Set '/' (1)
                                    if not self.set_cell(cr, cc, 1): return False
                                elif pos == 'BL': # Set '/' (1)
                                    if not self.set_cell(cr, cc, 1): return False
                                elif pos == 'BR': # Set '\' (2)
                                    if not self.set_cell(cr, cc, 2): return False
                            changed = True
            return True

        def copy(self):
            # Create a deep copy of the solver state for backtracking
            new_solver = Solver(self.N, self.clues)
            new_solver.grid = [row[:] for row in self.grid]
            new_solver.parent = self.parent[:]
            new_solver.degrees = [row[:] for row in self.degrees]
            return new_solver

        def solve_recursive(self):
            # First, propagate all logical constraints
            if not self.propagate():
                return None

            # Find the first unknown cell
            r_unknown, c_unknown = -1, -1
            for r in range(self.N):
                for c in range(self.N):
                    if self.grid[r][c] == 0:
                        r_unknown, c_unknown = r, c
                        break
                if r_unknown != -1: break

            # If no unknown cells, check if solution is valid
            if r_unknown == -1:
                for r in range(self.N + 1):
                    for c in range(self.N + 1):
                        if self.clues[r][c] is not None:
                            if self.degrees[r][c] != self.clues[r][c]:
                                return None
                return [row[:] for row in self.grid]

            r, c = r_unknown, c_unknown

            # Try placing '/' (1)
            s1 = self.copy()
            if s1.set_cell(r, c, 1):
                res = s1.solve_recursive()
                if res: return res

            # Try placing '\' (2)
            s2 = self.copy()
            if s2.set_cell(r, c, 2):
                res = s2.solve_recursive()
                if res: return res

            return None

    solver = Solver(N, data)
    result = solver.solve_recursive()

    if result is None:
        return "No Solution"

    # Convert internal representation to output format
    output = []
    for r in range(N):
        row = []
        for c in range(N):
            if result[r][c] == 1:
                row.append('/')
            else:
                row.append('\\')
        output.append(row)
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
