        r = int(float(parts[0]) - 0.5) # r is the top cell index
        c = int(float(parts[1]))
        v_cons[(r, c)] = v

    def get_opposite(color):
        return 'W' if color == 'B' else 'B'

    def is_valid_state(grid):
        # Check basic constraints without full completion
        # 1. No 3 consecutive same
        for r in range(N):
            for c in range(N - 2):
                if grid[r][c] and grid[r][c+1] and grid[r][c+2]:
                    if grid[r][c] == grid[r][c+1] == grid[r][c+2]:
