        for (r, c), typ in h_cons.items():
            if grid[r][c] and grid[r][c+1]:
                if typ == '=' and grid[r][c] != grid[r][c+1]: return False
                if typ == 'x' and grid[r][c] == grid[r][c+1]: return False
        for (r, c), typ in v_cons.items():
            if grid[r][c] and grid[r+1][c]:
                if typ == '=' and grid[r][c] != grid[r+1][c]: return False
                if typ == 'x' and grid[r][c] == grid[r+1][c]: return False

