                    if typ == '=': grid[r][c+1] = grid[r][c]
                    else: grid[r][c+1] = get_opposite(grid[r][c])
                    changed = True
                elif not grid[r][c] and grid[r][c+1]:
                    if typ == '=': grid[r][c] = grid[r][c+1]
                    else: grid[r][c] = get_opposite(grid[r][c+1])
