                        grid[r+1][c] = get_opposite(grid[r][c])
                        changed = True

            # 3. Balance (N/2 of each)
            limit = N // 2
            for r in range(N):
                count_b = sum(1 for x in grid[r] if x == 'B')
                count_w = sum(1 for x in grid[r] if x == 'W')
                if count_b == limit:
                    for c in range(N):
                        if not grid[r][c]:
                            grid[r][c] = 'W'
                            changed = True
                if count_w == limit:
                    for c in range(N):
                        if not grid[r][c]:
                            grid[r][c] = 'B'
                            changed = True

            for c in range(N):
                col_vals = [grid[r][c] for r in range(N)]
                count_b = sum(1 for x in col_vals if x == 'B')
                count_w = sum(1 for x in col_vals if x == 'W')
                if count_b == limit:
                    for r in range(N):
                        if not grid[r][c]:
                            grid[r][c] = 'W'
                            changed = True
                if count_w == limit:
                    for r in range(N):
                        if not grid[r][c]:
                            grid[r][c] = 'B'
                            changed = True

        return is_valid_state(grid)

    def solve_backtrack(grid):
        # Find empty cell
        empty_cells = []
        for r in range(N):
            for c in range(N):
                if not grid[r][c]:
                    empty_cells.append((r, c))

        if not empty_cells:
