                for i in range(N - 1):
                    if col[i] != 0 and col[i] == col[i+1]:
                        if i + 2 < N and col[i+2] == 0:
                            grid[i+2][c] = -col[i]
                            changed = True
                        if i - 1 >= 0 and col[i-1] == 0:
                            grid[i-1][c] = -col[i]
                            changed = True
                    if i + 2 < N and col[i] != 0 and col[i] == col[i+2] and col[i+1] == 0:
                        grid[i+1][c] = -col[i]
                        changed = True

            # 4. Equality/Inequality propagation (simplified)
            # If one side is known, set the other
            for (r, c), constraint in horiz.items():
                v1 = grid[r][c]
                v2 = grid[r][c+1]
                if v1 != 0 and v2 == 0:
                    if constraint == '=':
                        grid[r][c+1] = v1
                        changed = True
                    else:
                        grid[r][c+1] = -v1
                        changed = True
                elif v2 != 0 and v1 == 0:
                    if constraint == '=':
                        grid[r][c] = v2
                        changed = True
                    else:
                        grid[r][c] = -v2
                        changed = True

            for (r, c), constraint in vert.items():
                v1 = grid[r][c]
                v2 = grid[r+1][c]
                if v1 != 0 and v2 == 0:
                    if constraint == '=':
                        grid[r+1][c] = v1
                        changed = True
                    else:
                        grid[r+1][c] = -v1
                        changed = True
                elif v2 != 0 and v1 == 0:
                    if constraint == '=':
                        grid[r][c] = v2
                        changed = True
                    else:
                        grid[r][c] = -v2
                        changed = True

        return is_valid()

    # Run initial propagation
    if not full_propagate():
        return "No Solution"

    # Backtracking with propagation at each step
    # Find first empty cell
    def solve_recursive():
        # Find empty cell with MRV (though domains are always size 2 initially, 
        # propagation might reduce effective options)
        # For simplicity, just pick first empty
        r, c = -1, -1
        for i in range(N):
            for j in range(N):
                if grid[i][j] == 0:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1:
            return True # Solved

        # Try values
        for val in [1, -1]:
            saved_grid = [row[:] for row in grid]
            grid[r][c] = val

            if full_propagate():
                if solve_recursive():
                    return True

            # Backtrack
            grid[:] = [row[:] for row in saved_grid]

        return False

    if solve_recursive():
        # Convert to output format
        result = []
        for r in range(N):
            row_str = []
            for c in range(N):
                if grid[r][c] == 1:
                    row_str.append('B')
                else:
                    row_str.append('W')
            result.append(row_str)
        return result
    else:
        return "No Solution"

